class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  final private[this] val MOD = 1000000007

  def solve(): Unit = {
    val n = ni()
    val (x, y) = na2(n)
    // red >= blue
    val red, blue = Array.ofDim[Int](n)
    REP(n) { i =>
      if (x(i) >= y(i)) {
        red(i) = x(i)
        blue(i) = y(i)
      } else {
        blue(i) = x(i)
        red(i) = y(i)
      }
    }

    val mx = red.max
    val ms = blue.min

    def calcMin: Int = {
      import java.util.Comparator
      val determined, ix = ArrayBuffer[Int]()
      REP(n) { i =>
        // red==mx && blue==msの場合は値を固定することができない
        if (red(i) == mx && blue(i) != ms) {
          determined += blue(i)
        } else if (blue(i) == ms && red(i) != mx) {
          determined += red(i)
        } else {
          ix += i
        }
      }

//      debug(determined.mkString(" "))
//      debug(ix.mkString(" "))
      val dms = determined.min
      val dmx = determined.max

      if (ix.isEmpty) {
        return dmx - dms
      }

      val nums = Array.ofDim[(Int, Int)](ix.length * 2)
      REP(ix.length) { i =>
        nums(i * 2) = (red(ix(i)), i)
        nums(i * 2 + 1) = (blue(ix(i)), i)
      }
      sort(nums, new Comparator[(Int, Int)] {
        override def compare(o1: (Int, Int), o2: (Int, Int)): Int = Integer.compare(o1._1, o2._1)
      })

      debug(s"dms:$dms dmx:$dmx")
      debug(nums.mkString(" "))

      var res = 1e9.toInt
      var r = -1
      var cnt = 0
      val flg = Array.ofDim[Int](n)
      REP(min(nums.length, ix.length + 1)) { l =>
        // [l, r] 最小になるようにする
        while(r + 1 < nums.length && cnt < ix.length) {
          r += 1
          if (flg(nums(r)._2) == 0) cnt += 1
          flg(nums(r)._2) += 1
        }
        debug(s"l:$l r:$r cnt:$cnt")
        debug(flg)

        if (cnt == ix.length) {
          res = min(res, max(nums(r)._1, dmx) - min(nums(l)._1, dms))
        }

        if (flg(nums(l)._2) == 1) cnt -= 1
        flg(nums(l)._2) -= 1
      }

      res
    }

    // red >= blue の状態ではri<->biを入れ替えても結果は悪くしかならない
    def diff = (red.max - red.min).toLong * (blue.max - blue.min)

    // r側でmin, maxを使うとして、b側が最小になる値
    def same = (mx - ms).toLong * calcMin
    out.println(min(same, diff))
  }
}

