        //printf("rmax: %lld rmin: %lld\n", ps[i].first, rmin);
        ans = min(ans, (ps[i].second-rmin)*bb);
      }
    }
  }

  LLI maxr = -1;
  LLI minb = 1000000001;
  for (int i=0; i<N; i++) {
    maxr = max(maxr, ps[i].second);
    minb = min(minb, ps[i].first);
  }
  ans = min(ans, (maxr-ps[mini].second) * (ps[maxi].first-minb));
  printf("%lld\n", ans);
}

