LL solve1(const vector<int> &x, const vector<int> &y){
    const int n = x.size();
    int min_a = 1<<30;
    int min_b = 1<<30;
    int max_a = 0;
    int max_b = 0;
    REP(i, n){
        int mn = min(x[i], y[i]);
        int mx = max(x[i], y[i]);
        min_a = min(min_a, mn);
        max_a = max(max_a, mn);
        min_b = min(min_b, mx);
        max_b = max(max_b, mx);
    }
    LL a = max_a - min_a;
    LL b = max_b - min_b;
    //cout << a*b << endl;
    return a * b;
}

LL solve2(const vector<int> &x, const vector<int> &y){
    const int n = x.size();
    int min_a = 1<<30;
    int max_a = 0;
    vector<pair<int, int> > z(n);
    REP(i, n){
        int mn = min(x[i], y[i]);
        int mx = max(x[i], y[i]);
        min_a = min(min_a, mn);
        max_a = max(max_a, mx);
        z[i].first = mn;
        z[i].second = mx;
    }
    sort(ALL(z));
    int b = z[n-1].first - z[0].first;
    int max_b = z[n-1].first;
    int min_b = z[n-1].second;
    REP(i, n-1){
        //cout << z[i].first << " " << z[i].second << endl;
        max_b = max(max_b, z[i].second);
        min_b = min(min_b, min(z[i+1].first, z[i].second));
        b = min(b, max_b - min_b);
        //cout << max_b << " " << z[i+1].first << " " << b << endl;
    }
    return (LL)(max_a-min_a) * (LL)b;
}

