void solve() {
  int n; cin >> n;
  vector<pii> g; g.reserve(n);
  rep(i,n) {
    int x, y; cin >> x >> y;
    if (x > y) swap(x, y);
    g.emplace_back(x, y);
  }

  sort(ALL(g));

  int Rmax = g[n-1].first, Rmin = g[0].first;
  int Bmax = 0, Bmin = 1e9;

  for (auto &p : g) {
    chmax(Bmax, p.second);
    chmin(Bmin, p.second);
  }

  ll ans = 1LL * (Rmax - Rmin) * (Bmax - Bmin);

  int MAX = 0;
  auto itr = g.begin();

  while (itr != g.end() && itr->first == Rmin) {
    chmax(MAX, itr->second);
    ++itr;
  }

  while (itr != g.end()) {
    if (itr->first > Bmin) {
      chmin(ans, 1LL * (max(MAX, Rmax) - Bmin) * (Bmax - Rmin));
      break;
    }

    if (MAX == Bmax) break;

    chmin(ans, 1LL * (max(MAX, Rmax) - itr->first) * (Bmax - Rmin));

    int tmp = itr->first;

    while (itr != g.end() && itr->first == tmp) {
      chmax(MAX, itr->second);
      ++itr;
    }
  }

  cout << ans << endl;
}


