    }
    bmax = bmin, rmin = rmax;
    for (int i = 1; i <= n; i++) {
        if (i == ida || i == idb) {
            if (ida == idb) continue;
            if (i == ida) {
                rmax = max(rmax, point[i].Se);
                rmin = min(rmin, point[i].Se);
            } else {
                bmax = max(bmax, point[i].Fi);
                bmin = min(bmin, point[i].Fi);
            }
        } else {
            rmax = max(rmax, point[i].Se);
            rmin = min(rmin, point[i].Se);
            bmax = max(bmax, point[i].Fi);
            bmin = min(bmin, point[i].Fi);
        }
    }
    ans = min(ans, (rmax - rmin) * (bmax - bmin));

    // Case II
    rmax = 0, rmin = LL_INF;
    bmax = 0, bmin = LL_INF;
    ida = 1, idb = 0;
    rmin = point[1].Fi;
    for (int i = n; i >= 1; i--) {
        if (point[i].Se > rmax) {
            rmax = point[i].Se;
            idb = i;
        } else if (point[i].Se == rmax) {
            if (i != ida) idb = i;
        }
    }
    if (ida != idb) {
        ll minvalue = LL_INF;
        for (int i = 1; i <= n; i++) {
            if (i == ida) {
                bmax = max(bmax, point[i].Se);
                bmin = min(bmin, point[i].Se);
            } else if (i == idb) {
                bmax = max(bmax, point[i].Fi);
                bmin = min(bmin, point[i].Fi);
            } else {
                ll newbmax = max(bmax, point[i].Fi);
                ll newbmin = min(bmin, point[i].Fi);
                ll oldbmax = max(bmax, point[i].Se);
                ll oldbmin = min(bmin, point[i].Se);;
                if (newbmax - newbmin < oldbmax - oldbmin) {
                    bmax = max(bmax, point[i].Fi);
                    bmin = min(bmin, point[i].Fi);
                } else {
                    bmax = max(bmax, point[i].Se);
                    bmin = min(bmin, point[i].Se);
                }
            }
        }
        ans = min(ans, (rmax - rmin) * (bmax - bmin));
    }
    printf("%lld\n", ans);

    //cout << "time: " << (long long)clock() * 1000 / CLOCKS_PER_SEC << " ms" << endl;
    return 0;
}

