const int maxn(2e5 + 5);

int n, x[maxn], y[maxn], mx, mn, bmx, bmn, rmx, rmn;
int sufmn[maxn], sufmx[maxn];
ll ans;
pair <int, int> vxy[maxn];

int main() {
	int i, p1, p2;
	scanf("%d", &n), mn = 1e9;
	for (i = 1; i <= n; ++i) {
		scanf("%d%d", &x[i], &y[i]);
		if (x[i] > y[i]) swap(x[i], y[i]);
		mx = max(mx, max(x[i], y[i]));
		mn = min(mn, min(x[i], y[i]));
	}
	for (i = 1; i <= n; ++i) if (y[i] == mx) p1 = i;
	for (i = n; i; --i) if (x[i] == mn) p2 = i;
	rmn = mn, bmx = mx, bmn = 1e9;
	for (i = 1; i <= n; ++i) {
		if (i != p2) rmx = max(rmx, x[i]);
		if (i != p1) bmn = min(bmn, y[i]);
	}
	ans = (ll)(bmx - bmn) * (rmx - rmn);
	if (p1 ^ p2) {
		swap(x[n], x[p1]), swap(x[n - 1], x[p2]);
		swap(y[n], y[p1]), swap(y[n - 1], y[p2]), p1 = n, p2 = n - 1;
		swap(y[p1], x[p1]);
		for (i = 1; i <= n; ++i) vxy[i] = make_pair(x[i], y[i]);
		bmx = mx, bmn = mn, sort(vxy + 1, vxy + n - 1), sufmn[n + 1] = 1e9;
		for (i = n; i; --i) {
			sufmx[i] = max(sufmx[i + 1], vxy[i].second);
			sufmn[i] = min(sufmn[i + 1], vxy[i].second);
		}
		for (i = 0; i < n - 1; ++i) {
			rmx = max(vxy[i].first, max(y[p1], y[p2])), rmn = min(sufmn[i + 1], rmx);
			if (sufmx[i + 1] <= rmx) ans = min(ans, (ll)(bmx - bmn) * (rmx - rmn));
		}
	}
	printf("%lld\n", ans);
	return 0;
}

