const int N = 2e5+5;
typedef long long LL;
multiset<int> s1, s2;

int a[N], b[N];

inline LL calc() {
	static set <int> :: iterator it;
	it = s1.end(); it --;
	LL tmp1 = *(s1.begin());
	LL tmp2 = *(it);
	it = s2.end(); it -- ;
	LL tmp3 = *(s2.begin());
	LL tmp4 = *(it);
	return (tmp2-tmp1)*(tmp4-tmp3);
}

int main() {
	int n;
	scanf("%d",&n);
	for(int i=1;i<=n;++i) {
		scanf("%d%d",&a[i], &b[i]);
		if(a[i] > b[i]) swap(a[i], b[i]);
		s1.insert(a[i]);
		s2.insert(b[i]);
	}
	LL nowans = calc();
	for(int i=1;i<=n;++i) {
		s1.erase(s1.find(a[i]));
		s1.insert(b[i]);
		s2.erase(s2.find(b[i]));
		s2.insert(a[i]);
		LL tmp = calc();
		if(tmp > nowans) {
			s1.erase(s1.find(b[i]));
			s1.insert(a[i]);
			s2.erase(s2.find(a[i]));
			s2.insert(b[i]);
		}
		else {
			nowans = tmp;
		}
	}
	cout << nowans << endl;
}

