	}
	sort(p, p + n);
	tmx = 0, tmn = MOD;
	for (int i = n - 1; i >= 0; i--) {
		if (tmx > p[i].ff) break;
		ans = min(ans, 1LL * val * (p[i].ff - min(p[0].ff, tmn)));
		tmn = min(tmn, p[i].ss);
		tmx = max(tmx, p[i].ss);
	}
	cout << ans;
