const int MAX_N = 200000;
ll N;
ll x[MAX_N], y[MAX_N];

int main() {
  cin >> N;
  rep(i,N) cin >> x[i] >> y[i];

  if (N == 1) {
    cout << 0 << endl;
    return 0;
  }

  vector<pll> vec;
  for (int i = 0; i < N; ++i) {
    vec.push_back(pll(x[i], i)); vec.push_back(pll(y[i], i));
  }

  sort(all(vec));

  ll inf = vec[0].fi, sup = vec[2*N-1].fi;

  ll ans = 0;

  if (vec[1].fi != inf && vec[2*N-2].fi != sup && vec[0].sc == vec[2*N-1].sc) {
    ll tsup = 0, tinf = 1e18;
    int id = vec[0].sc;
    for (int i = 0; i < N; ++i) {
      if (i != id) {
        if (x[i] > y[i]) {
          tinf = min(tinf, x[i]);
          tsup = max(tsup, y[i]);
        } else {
          tinf = min(tinf, y[i]);
          tsup = max(tsup, x[i]);
        }
      }
    }
    ans = (sup-tinf)*(tsup-inf);

  } else {
    ll infid = vec[0].sc, supid = vec[2*N-1].sc;
    if (supid == infid) {
      for (int i = 1; i < 2*N && vec[i].fi == inf; ++i) {
        infid = vec[i].sc;
        if (supid != infid) break;
      }
    }
    if (supid == infid) {
      for (int i = 2*N-2; i >= 0 && vec[i].fi == sup; --i) {
        supid = vec[i].sc;
        if (supid != infid) break;
      }
    }

    ll tsup = 0, tinf = 1e18;
    for (int i = 0; i < N; ++i) {
      if (i != supid && i != infid) {
        if (x[i] > y[i]) {
          tinf = min(tinf, x[i]);
          tsup = max(tsup, y[i]);
        } else {
          tinf = min(tinf, y[i]);
          tsup = max(tsup, x[i]);
        }
      } else if (i == supid) {
        if (x[i] > y[i]) {
          tsup = max(tsup, y[i]);
        } else {
          tsup = max(tsup, x[i]);
        }
      } else {
        if (x[i] > y[i]) {
          tinf = min(tinf, x[i]);
        } else {
          tinf = min(tinf, y[i]);
        }
      }
    }

    ans = (sup-tinf)*(tsup-inf);

    vector<pll> vec2;
    for (int i = 0; i < N; ++i) {
      if (i != infid) {
        vec2.push_back(pll(min(x[i], y[i]), i));
      } else {
        vec2.push_back(pll(max(x[i], y[i]), i));
      }
    }

    sort(all(vec2));
    tinf = vec2[0].fi; tsup = vec2[N-1].fi;
    ans = min(ans, (sup-inf)*(tsup-tinf));
    ll newinf = 1e18;
    for (int i = 0; i < N && i != infid && i != supid; ++i) {
      tinf = vec2[i+1].fi;
      tsup = max(tsup, max(x[vec2[i].sc], y[vec2[i].sc]));
      newinf = min(newinf, max(x[vec2[i].sc], y[vec2[i].sc]));
      if (tinf > newinf) {
        ans = min(ans, (sup-inf)*(tsup-newinf));
        break;
      }
      ans = min(ans, (sup-inf)*(tsup-tinf));
    }
  }

  cout << ans << endl;

  return 0;
}

