int idk[N];
int idkk[N];
int mxx = 0;
int mnn = 1e9+1;
vector<int> all;
int n;
int mxdiff = 0;
vector<int> hehe;
vector<int> haha;

bool check(int l1,int r1,int l2,int r2){
	//cout << l1 << " " << r1 << " " << l2 << " " << r2 << endl;
	// 1 6 2 5
	if(r1 > r2 or (r1 == r2 and l1 > l2) ){
		swap(l1,l2);
		swap(r1,r2);
	}
	//cout << l1 << " " << r1 << " " << l2 << " " << r2 << endl;
	if(l2 <= l1){
		//cout << "HERE" << endl;
		if(hehe[0] < l2 or haha[n-1] > r2)return 0;
		if(fuck[n-1].f > r1)return 0;
		if(fuck[n-1].f < l2){
			return idk[n-1] >= l1 and idkk[n-1] <= r1;
		}
		//cout << "HERE1" << endl;
		if(fuck[0].f >= l1){
			return 1;
		}
		int lo = 0;
		int hi = n-1;
		while(lo < hi){
			int mid = (lo+hi)/2;
			if(fuck[mid].f >= l1)hi = mid;
			else lo = mid+1;
		}
		return idk[lo-1] >= l1 and idkk[lo-1] <= r1;
	}
	return (hehe[0] >= l1 and hehe[n-1] <= r1 and haha[0] >= l2 and haha[n-1] <= r2);
}

void solve(){
  	cin >> n;
  	RE(i,n){
  		cin >> x[i] >> y[i];
  		if(x[i] > y[i])swap(x[i],y[i]);
  		fuck.pb({x[i],y[i]});
  		hehe.pb(x[i]);
  		haha.pb(y[i]);
  		all.pb(x[i]);
  		all.pb(y[i]);
  	}
  	sort(all(fuck));
  	idk[0] = fuck[0].s;
  	idkk[0] = fuck[0].s;
  	RE(i,n-1){
  		idk[i] = min(idk[i-1],fuck[i].s);
  		idkk[i] = max(idk[i-1],fuck[i].s);
  	}
  	//cout << check(1,6,2,5);
  	sort(all(all));
  	sort(all(hehe));
  	sort(all(haha));
  	mnn = all[0];
  	mxx = all[2*n-1];
  	int ans = INF;
  	REP(i,all.size()){
  		// [all[i],mxx] [mnn,binary]
  		// [mnn,mxx] [all[i],binary]
  		int lo = i;
  		int hi = all.size();hi--;
  		while(lo < hi){
  			int mid = (lo+hi)/2;
  			if(check(mnn,mxx,all[i],all[mid]))hi = mid;
  			else lo = mid+1;
  		}
  		if(check(mnn,mxx,all[i],all[lo])){
  			ans = min(ans,(mxx-mnn)*(all[lo]-all[i]));
  		}
  		lo = 0;
  		hi = all.size();hi--;
  		while(lo < hi){
  			int mid = (lo+hi)/2;
  			if(check(all[i],mxx,mnn,all[mid]))hi = mid;
  			else lo = mid+1;
  		}
  		if(check(all[i],mxx,mnn,all[lo])){
  			ans = min(ans,(mxx-all[i])*(all[lo]-mnn));
  		}
  	}
  	cout << ans;
}

