		ymin = min(ymin, y[i]);
		ymax = max(ymax, y[i]);
	}
	LL ans = (xmax - xmin) * (ymax - ymin);
	vector<pair<LL, LL>> xy;
	set<LL> sr, sb;
	LL d = ymax - xmin;
	REP(i, n) {
		if (x[i] == xmin) {
			sr.insert(x[i]);
			sb.insert(y[i]);
		}
		else if (y[i] == ymax) {
			sr.insert(y[i]);
			sb.insert(x[i]);
		}
		else {
			sb.insert(x[i]);
			sr.insert(y[i]);
			xy.push_back(MP(x[i], y[i]));
		}
	}
	SORT(xy);
	int k = xy.size();
	REP(i, k + 1) {
		ans = min(ans, ((*(--sb.end())) - (*sb.begin())) * d);
		if (i == k)break;
		sb.erase(xy[i].first);
		sb.insert(xy[i].second);
	}
	cout << ans << endl;
	return 0;
}

