const int MAXN = 2e5 + 5, inf = 1e9;
struct Cor {
	int x, y;
	bool operator < (const Cor &a) const {
		return x < a.x;
	}
} cor[MAXN];
int n, prefix[MAXN], suffix[MAXN];
bool flip[MAXN];
long long solve() {
	int min_x, min_y, max_x, max_y;
	min_x = min_y = inf;
	max_x = max_y = -inf;
	for(int i = 1; i <= n; i++) {
		min_x = std::min(min_x, cor[i].x);
		max_x = std::max(max_x, cor[i].x);
		min_y = std::min(min_y, cor[i].y);
		max_y = std::max(max_y, cor[i].y);
	}
	return (long long)(max_x - min_x) * (max_y - min_y);
}
int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n; i++) {
		scanf("%d%d", &cor[i].x, &cor[i].y);
		if(cor[i].x > cor[i].y) std::swap(cor[i].x, cor[i].y);
	}
	std::sort(cor + 1, cor + n + 1);
	prefix[0] = suffix[n + 1] = inf;
	for(int i = 1; i <= n; i++) prefix[i] = std::min(prefix[i - 1], cor[i].y);
	for(int i = n; i >= 1; i--) suffix[i] = std::min(suffix[i + 1], cor[i].x);
	int max_x = cor[n].x;
	int len = inf;
	int ilen;
	for(int i = 0; i <= n; i++) {
		int min_x = std::min(prefix[i], suffix[i + 1]);
		if(max_x - min_x < len) {
			ilen = i;
			len = max_x - min_x;
		}
		if(i + 1 <= n) max_x = std::max(max_x, cor[i + 1].y);
	}
	for(int i = 1; i <= ilen; i++) std::swap(cor[i].x, cor[i].y);
	printf("%lld\n", solve());
	return 0;
}

