    A.erase(A.begin());

    int64_t ans = 0;
    {
        vector<bool> used(n, false);
        used[imin] = true;
        int left = 0;
        int bmax = vmin;
        int rmin = vmax;
        while (left < SZ(A)) {
            if (!used[A[left].second]) {
                bmax = A[left].first;
            } else {
                rmin = min(rmin, A[left].first);
            }
            used[A[left].second] = true;
            left++;
