template
<class T>
struct heap
{
private:
	multiset<T, greater<T>>big;
	multiset<T, less<T>>sml;
public:
	void insert(T x)
	{
		big.insert(x);
		sml.insert(x);
	}
	void erase(T x)
	{
		big.erase(x);
		sml.erase(x);
	}
	T getMax()
	{
		assert(big.size() && sml.size());
		return *big.begin();
	}
	T getMin()
	{
		assert(big.size() && sml.size());
		return *sml.begin();
	}
};

LL difference(vector<pair<LL, LL>>&vec)
{
	LL v1 = vec.front().first;
	LL v2 = vec.back().first;
	sort(vec.begin() + 1, vec.end() - 1);
	heap<LL>S;
	S.insert(v1);
	S.insert(v2);
	for (int i = 1; i < vec.size() - 1; ++i)S.insert(vec[i].first);
	LL ans = S.getMax() - S.getMin();
	for (int i = 1; i < vec.size() - 1; ++i)
	{
		S.erase(vec[i].first);
		S.insert(vec[i].second);
		ans = min(ans, S.getMax() - S.getMin());
	}
	return ans;
}

int main(void)
{
	LL N;
	vector<pair<LL, LL>>vec;
	cin >> N;
	heap<LL> L, R;
	int sind, lind;
	LL minv = LLONG_MAX, maxv = 0;
	for (int i = 0; i < N; ++i)
	{
		LL x, y;
		cin >> x >> y;
		if (x > y)swap(x, y);
		vec.push_back({ x, y });
		L.insert(x);
		R.insert(y);
		if (minv > x)
		{
			minv = x;
			sind = i;
		}
		if (maxv < y)
		{
			maxv = y;
			lind = i;
		}
	}
	LL ans = (L.getMax() - L.getMin()) * (R.getMax() - R.getMin());
	if (sind == lind)
	{
		/*
		assert(vec[sind].first == sind && vec[sind].second == lind);
		vec.erase(vec.begin() + sind, vec.begin() + sind + 1);
		vec.insert(vec.begin(), make_pair(sind, lind));
		vec.push_back(vec[0]);
		*/
	}
	else
	{
		auto small = vec[sind];
		auto large = vec[lind];
		//sindとlindの2箇所を削除する(後ろから)
		vec.erase(vec.begin() + max(sind, lind), vec.begin() + max(sind, lind) + 1);
		vec.erase(vec.begin() + min(sind, lind), vec.begin() + min(sind, lind) + 1);
		swap(small.first, small.second);
		vec.insert(vec.begin(), small);
		vec.push_back(large);
		LL diff = difference(vec);
		LL can = diff * (large.second - small.second);
		ans = min(ans, can);
	}
	cout << ans << endl;
	return 0;
}

