const long long INF = 1e15;
using namespace std;

struct Ball{
    public:
        long long x, y;
        void swap(){
            long long temp = x;
            x = y;
            y = temp;
        }
        bool operator < ( const Ball &right ) const {
            return x <= right.x;
        }
};

int n;

long long solve(Ball b[200005]){
    long long xmax = 0, ymax = 0, xmin = INF, ymin = INF;
    rep(i,n){
        xmin = min(b[i].x, xmin);
        xmax = max(b[i].x, xmax);
        ymin = min(b[i].y, ymin);
        ymax = max(b[i].y, ymax);
    }
    return (xmax - xmin) * (ymax - ymin);
}

int main(){
    cin >> n;

    Ball b[200005];
    long long mini = INF, maxi = 0;
    rep(i,n){
        cin >> b[i].x >> b[i].y;
        mini = min( min(b[i].x, b[i].y), mini);
        maxi = max( max(b[i].x, b[i].y), maxi);
    }
    rep(i,n){
        if(b[i].x > b[i].y) b[i].swap();
    }
    long long ans = solve(b);
    sort(b, b + n);

    long long lowest = b[0].x;
    rep(i,n){
        if(b[i].y == maxi) continue;
        if(b[i].y > lowest){
            lowest = b[i].y;
            b[i].swap();
        }
    }
    cout << min(ans, solve(b)) << endl;
}

