  }

  int64_t MIN = *min_element(all(x));
  int64_t MAX = *max_element(all(y));

  int64_t ans = infll;
  {
    int64_t Rmin = MIN, Rmax = -infll;
    int64_t Bmin = infll, Bmax = MAX;

    for (int i = 0; i < n; ++i) {
      if (Rmin == x[i]) {
        chmin(Bmin, y[i]);
        continue;
      }
      if (Bmax == y[i]) {
        chmax(Rmax, x[i]);
        continue;
      }

      chmin(Bmin, y[i]);
      chmax(Rmax, x[i]);
    }

