	Rmin = X[0];
	Lmax = Y[0];
	Lmin = Y[0];
	for(int i=1;i<N;++i){
		LL _Rmax,_Rmin,_Lmax,_Lmin;
		_Rmax = max(Rmax,X[i]);
		_Rmin = min(Rmin,X[i]);
		_Lmax = max(Lmax,Y[i]);
		_Lmin = min(Lmin,Y[i]);
		LL res1 = (_Rmax-_Rmin)*(_Lmax-_Lmin);
		_Rmax = max(Rmax,Y[i]);
		_Rmin = min(Rmin,Y[i]);
		_Lmax = max(Lmax,X[i]);
		_Lmin = min(Lmin,X[i]);
		LL res2 = (_Rmax-_Rmin)*(_Lmax-_Lmin);
		if( res1 < res2 ){
			Rmax = max(Rmax,X[i]);
			Rmin = min(Rmin,X[i]);
			Lmax = max(Lmax,Y[i]);
			Lmin = min(Lmin,Y[i]);
		}else{
			Rmax = max(Rmax,Y[i]);
			Rmin = min(Rmin,Y[i]);
			Lmax = max(Lmax,X[i]);
			Lmin = min(Lmin,X[i]);
		}
	}
	cout << (Rmax-Rmin)*(Lmax-Lmin) << endl;
}

