LL solve0(){
	if(id0==id1) return 1e18;
	A0 = M0;
	A1 = M1;
	B0 = min(t0, t1);
	B1 = max(t0, t1);

	for(int i=1;i<=N;i++){
		if(i==id0 || i==id1) continue;
		if(B0<=x[i] && x[i]<=B1 || B0<=y[i] && y[i]<=B1) continue;

		t0 = min(x[i], y[i]);
		t1 = max(x[i], y[i]);
		if(t0 > B1){
			B1 = t0;
		}
		else if(t1 < B0){
			B0 = t1;
		}
		else{
			if(t1-B1 < B0-t0) B1 = t1;
			else B0 = t0;
		}
	}	

	return (LL)(A1-A0)*(B1-B0);
}

