	B0 = M0;
	A0 = t0;
	B1 = t1;

	for(int i=1;i<=N;i++){
		if(i==id0 || i==id1) continue;
		B1 = max(B1, min(x[i], y[i]));
		A0 = min(A0, max(x[i], y[i]));
