        fst_rmax = max(rmax, x);
        fst_rmin = min(rmin, x);
        fst_bmax = max(bmax, y);
        fst_bmin = min(bmin, y);
        fst_ans  = (fst_rmax - fst_rmin) * (fst_bmax - fst_bmin);

        snd_rmax = max(rmax, y);
        snd_rmin = min(rmin, y);
        snd_bmax = max(bmax, x);
        snd_bmin = min(bmin, x);
        snd_ans  = (snd_rmax - snd_rmin) * (snd_bmax - snd_bmin);

        if (fst_ans < snd_ans) {
            rmax = fst_rmax;
            rmin = fst_rmin;
            bmax = fst_bmax;
            bmin = fst_bmin;
            ans = fst_ans;
        }
        else {
            rmax = snd_rmax;
            rmin = snd_rmin;
            bmax = snd_bmax;
            bmin = snd_bmin;
            ans = snd_ans;
        }
        //dump(fst_rmax); dump(fst_rmin); dump(fst_bmax); dump(fst_bmin); dump(fst_ans); cout << endl;
        //dump(snd_rmax); dump(snd_rmin); dump(snd_bmax); dump(snd_bmin); dump(snd_ans); cout << endl;
        //dump(rmax); dump(rmin); dump(bmax); dump(bmin); dump(ans); cout << endl;
    }
    cout << ans << endl;
    return 0;
}

