struct Fenwick {
    vector<int> tree;
    void init() {
        tree = vector<int>(Xn + 1, 0);
    }
    void upd(int idx, int val) {
        for(int i = idx + 1; i <= Xn; i += (i & -i)) tree[i] += val;
    }
    int quer(int a) {
        int ret = 0;
        for(int i = a + 1; i >= 1; i -= (i & -i)) ret += tree[i];
        return ret;
    }
    int quer(int a, int b) {
        return quer(b) - quer(a - 1);
    }
    int kquer(int k) {
        int ret = 0;
        for(int i = 20; i >= 0; i--) {
            if(ret + (1 << i) > Xn) continue;
            if(tree[ ret + (1 << i) ] < k) {
                k -= tree[ ret + (1 << i) ];
                ret += (1 << i);
            }
        }
        return ret;
    }
} fw;

vector<pii> E[MN << 1];

int main() {
