using namespace std;
#define ll long long

void insert_to_sorted(vector<ll> &v, ll a) {
  auto it = upper_bound(v.begin(), v.end(), a);
  v.insert(it, a);
}

void delete_from_sorted(vector<ll> &v, ll a) {
  auto it = find(v.begin(), v.end(), a);
  v.erase(it);
}

inline ll get_current_range(vector<ll> &v) {
  return v.back() - v.front();
}

int main() {
  ll ans = 1000000000000000;
  ll N;
  cin >> N;
  vector<ll> x(N), y(N);
  for(ll i = 0; i < N; i++) {
    cin >> x[i] >> y[i];
  }

  ll min_among_all = x[0], max_among_all = x[0];

  for(ll i = 0; i < N; i++) {
    min_among_all = min(min_among_all, x[i]);
    max_among_all = max(max_among_all, x[i]);
    min_among_all = min(min_among_all, y[i]);
    max_among_all = max(max_among_all, y[i]);
  }

  // first case
  vector< pair<ll, ll> > v;

  for(ll i = 0; i < N; i++) {
    v.push_back(make_pair(x[i], y[i]));
  }

  for(ll i = 0; i < N; i++) {
    if(v[i].first > v[i].second) {
      swap(v[i].first, v[i].second);
    }
  }

  sort(v.begin(), v.end());

  vector<ll> current_members;

  for(ll i = 0; i < N; i++) {
    current_members.push_back(v[i].first);
  }

  ll min_range = get_current_range(current_members);

  for(ll i = 0; i < N; i++) {
    delete_from_sorted(current_members, v[i].first);
    insert_to_sorted(current_members, v[i].second);
    min_range = min(min_range, get_current_range(current_members));
  }


  ans = min(ans, min_range * (max_among_all - min_among_all) );

  // second case
  ll max_among_smaller, min_among_larger;
  max_among_smaller = v.front().first;
  min_among_larger = v.front().second;

  for(ll i = 0; i < N; i++) {
    max_among_smaller = max(max_among_smaller, v[i].first);
    min_among_larger = min(min_among_larger, v[i].second);
  }

  ans = min(ans, (max_among_smaller - min_among_all) * (max_among_all - min_among_larger) );

  cout << ans << endl;

