#include <bits/stdc++.h>
#define INF (0x3f3f3f3f)
#define INFLL (0x3f3f3f3f3f3f3f3fll)
using namespace std;
typedef long long ll;
mt19937 mtrd(time(0));

const int MAXN = 200055;

int A[MAXN], B[MAXN];

ll Ans = INFLL;
int N;

void f(int a, int b) {
	int mna = INF, mxa = -INF, mnb = INF, mxb = -INF;
	for(int i = 1; i <= N; i++) {
		ll xa = ll(A[i])*a, xb = ll(B[i])*b;
		if(xa < xb) {
			if(A[i] < mna) mna = A[i];
			if(mxa < A[i]) mxa = A[i];
			if(B[i] < mnb) mnb = B[i];
			if(mxb < B[i]) mxb = B[i];
		} else {
			if(B[i] < mna) mna = B[i];
			if(mxa < B[i]) mxa = B[i];
			if(A[i] < mnb) mnb = A[i];
			if(mxb < A[i]) mxb = A[i];
		}
	}
	ll ret = ll(mxa-mna) * (mxb-mnb);
		if(ret < Ans) Ans = ret;
}

int main() {
	ios::sync_with_stdio(false);

	cin >> N;
	for(int i = 1; i <= N; i++) cin >> A[i] >> B[i];

	f(0, 1); f(1, 0);
	for(int i = 0; i < 100; i++) { f(1, i); f(i, 1); }
	for(int t = 0; t < 1000; t++) {
		int a = mtrd() % INF, b = mtrd() % INF;
		f(a, b);
	}

	cout << Ans << endl;
	return 0;
}

