int n;
pii mas[200010];
int mn = 1000000000, mx = 0;
vector<pii> a;
set<int> blue, red;
struct Cmp{
    inline bool operator()(const int &lhs, const int &rhs){
        return lhs > rhs;
    }
};
set<int, Cmp> bmx, rmx;

ll solve(vector<pii> mas){
    blue.clear();
    red.clear();
    bmx.clear();
    rmx.clear();
    sort(mas.begin(), mas.end());
    if(n == 1){
        return 0;
    }
    for(int i = 0; i < n; i++){
        int l = mas[i].first, r = mas[i].second;
        if(i == 0){
            blue.pb(l);
            red.pb(r);
            bmx.pb(l);
            rmx.pb(r);
        }
        else{
            int mnb = *blue.begin();
            int mxb = *bmx.begin();
            int mnr = *red.begin();
            int mxr = *rmx.begin();
            ll a1 = (ll)(max(mxb, l) - min(mnb, l)) * (ll)(max(mxr, r) - min(mnr, r));
            ll a2 = (ll)(max(mxb, r) - min(mnb, r)) * (ll)(max(mxr, l) - min(mnr, l));
            if(a1 < a2){
                blue.pb(l);
                bmx.pb(l);
                red.pb(r);
                rmx.pb(r);
            }
            else{
                blue.pb(r);
                bmx.pb(r);
                red.pb(l);
                rmx.pb(l);
            }
        }
    }
    return ((ll)(*bmx.begin()) - (ll)(*blue.begin())) * ((ll)(*rmx.begin()) - (ll)(*red.begin()));
}

