        mn = min(mn, mas[i].first);
        mx = max(mx, mas[i].second);
    }
    for(int i = 0; i < n; i++){
        if(mas[i].first == mn){
            a.push_back(mas[i]);
        }
        else if(mas[i].second == mx){
            a.push_back(mas[i]);
        }
    }
    n = a.size();
    ll ans1 = solve(a);
    for(int i = 0; i < n; i++){
        swap(a[i].first, a[i].second);
    }
    ll ans2 = solve(a);
    cout << min(ans1, ans2) << endl;
    return 0;
}

