int mincollect(int k)
{
  //赤優先
  int l = k, r = 1 - k; //左　右
  int rmax, rmin, bmax, bmin; //赤　青
  // cout << k << endl;
  rmax = rmin = d[l][0]; //どっちにするか決めておく
  bmax = bmin = d[r][0];

  //cout << 0 << " " << rmax << " " << rmin << " " << bmax << " " << bmin << endl;
  for(int i = 1; i < N; i++) {
    int lmis = rmin - d[l][i], rmis = rmin - d[r][i];
    int lmas = d[l][i] - rmax, rmas = d[r][i] - rmax;

    int blmis = bmin - d[l][i], brmis = bmin - d[r][i];
    int blmas = d[l][i] - bmax, brmas = d[r][i] - bmax;

    if(lmas < 0) lmas = LLINF;
    if(rmas < 0) rmas = LLINF;
    if(lmis < 0) lmis = LLINF;
    if(rmis < 0) rmis = LLINF;
    if(blmas < 0) blmas = LLINF;
    if(brmas < 0) brmas = LLINF;
    if(blmis < 0) blmis = LLINF;
    if(brmis < 0) brmis = LLINF;


    int lsa = min(lmis, lmas), rsa = min(rmis, rmas);
    int blsa = min(blmis, blmas), brsa = min(brmis, brmas);

    //左側の処理
    if(rmin <= d[l][i] && d[l][i] <= rmax || lsa < rsa || lsa == rsa && (bmin <= d[l][i] && d[l][i] <= bmax || blsa < brsa)) {
      neew(rmax, rmin, bmax, bmin, l, r, i);
    } else {
      neew(rmax, rmin, bmax, bmin, r, l, i);
    }
    // cout << i << " " << rmax << " " << rmin << " " << bmax << " " << bmin << endl;
  }

  return ( (rmax - rmin) * (bmax - bmin) );
}

void neew(int &rmax, int &rmin, int &bmax, int &bmin, int l, int r, int i)
{
  rmax = max(rmax, d[l][i]); rmin = min(rmin, d[l][i]);
  bmax = max(bmax, d[r][i]); bmin = min(bmin, d[r][i]);
}

