    set<P> st; // blue candidate
    st.insert(P(v[0].second,-1LL)); 
    for(int i=1;i<n;i++) st.insert(P(v[i].second,i));
    while(true){
        ll dif=(*st.rbegin()).first-(*st.begin()).first;
        res=min(res,dif*(ma-mi));

        P p=(*st.rbegin());
        st.erase(p);
        if(p.second==-1) break;
        st.insert(P(v[p.second].first,-1LL));        
    }
    cout<<res<<endl;
}

