        chmax(mx,x[i]);
        s.insert(x[i]);
    }
    while(!hp.empty() && y[hp.top().second]<mx) {
        int idx=hp.top().second;
        auto itr=s.lower_bound(x[idx]);
        auto nitr=next(itr);
        s.erase(itr,nitr);
        s.insert(y[idx]);
        hp.pop();
    }
    int mn=*begin(s);
    chmin(ans,(MAX-MIN)*(mx-mn));
    cout<<ans<<endl;
    return 0;
}

