		scanf("%lld%lld",&a[i*2-1],&a[i*2]);
		if (a[i*2-1]<a[i*2])swap(a[i*2-1],a[i*2]);
	}
	Max=1,Min=2;
	for (int i=3;i<=n*2;i++){
		if (a[i]>a[Max])Max=i;
		if (a[i]<a[Min])Min=i;
	}
	ans=1e18;
	if ((Max-1)/2!=(Min-1)/2)solve1();
	solve2();
	printf("%lld\n",ans);
	return 0;
}

