		if(i.F>i.S){
			swap(i.F,i.S);
		}
		mn=min(mn,i.F);
		mx=max(mx,i.F);
		mn2=min(mn2,i.S);
		mx2=max(mx2,i.S);
	}
	ll ans=(mx2-mn2)*1ll*(mx-mn);
