// ---------------------- template ----------------------


void solve() {
	int N; cin >> N;
	vector<pii> xy;
	vector<int> v;
	int ma = 0;
	int mi = inf;
	REP(i, N) {
		int x, y; cin >> x >> y;
		if (x > y) swap(x, y);
		xy.emplace_back(x, y);
		ma = max(x, ma);
		ma = max(y, ma);
		mi = min(x, mi);
		mi = min(y, mi);
		v.push_back(x);
		v.push_back(y);
	}
	int lmax = 0;
	int lmin = inf;
	int res;
	{
		int rmax = 0;
		int rmin = inf;
		REP(i, N) {
			lmax = max(lmax, xy[i].first);
			lmin = min(lmin, xy[i].first);
			rmax = max(rmax, xy[i].second);
			rmin = min(rmin, xy[i].second);
		}
		res = (lmax - lmin) *(rmax - rmin);
	}
	{
		priority_queue<pii, vector<pii>, greater<pii> > que;
		multiset<int> se;
		vector<bool> ng(N);
		REP(i, N) {
			int x, y;
			tie(x, y) = xy[i];
			if (x == mi) {
				se.insert(y);
				ng[i] = true;
			}
			if (y == ma) {
				se.insert(x);
				if (ng[i]) {
					cout << res << endl;
					return;
				}
				ng[i] = true;
			}
			if (x != mi and y != ma) {
				se.insert(xy[i].first);
			}
		}
		REP(i,N) if(not ng[i]) que.emplace(xy[i].first, xy[i].second);
		int r  = inf;
		while (not que.empty()) {
			auto top = que.top(); que.pop();
			auto it = se.find(top.first);
			se.erase(it);
			se.insert(top.second);
			int a = *prev(se.end()) - *se.begin();
			r = min(r, a);
		}
		res = min(res, (ma - mi)*(r));
	}
	cout << res << endl;
}

