  using Pii = pair<int, int>;
  vector<Pii> A(N);
  const int INF = 1e9+1;
  int mi = INF, ma = 0;
  vector<int> all;  
  for ( int i = 0; i < N; i++ ) {
    int x, y;
    cin >> x >> y;
    all.push_back(x);
    all.push_back(y);
    if ( x > y ) swap(x, y);
    A[i] = Pii(x, y);
    mi = min(mi, x);
    ma = max(ma, y);
  }

  sort(all.begin(), all.end());
  all.erase(std::unique(all.begin(), all.end()), all.end());
  int mid = (mi+ma)/2;
  int ans = INF*INF;
  for ( int i: all ) {
    int rmax = 0, rmin = INF;
    int bmax = 0, bmin = INF;
    for ( int j = 0; j < N; j++ ) {
      if ( abs(i-A[j].first) < abs(i-A[j].second) ) {
	rmax = max(rmax, A[j].first);
	rmin = min(rmin, A[j].first);
	bmax = max(bmax, A[j].second);
	bmin = min(bmin, A[j].second);	
      } else {
	rmax = max(rmax, A[j].second);
	rmin = min(rmin, A[j].second);
	bmax = max(bmax, A[j].first);
	bmin = min(bmin, A[j].first);	
      }
    }
    ans = min(ans, (abs(rmax-rmin)*abs(bmax-bmin)));    
  }

  cout << ans << endl;

  return 0;
}

