int main()
{
    //ios::sync_with_stdio(false);
    //freopen("a.txt","r",stdin);
    //freopen("b.txt","w",stdout);

    int n;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%lld%lld", &point[i].Fi, &point[i].Se);
        if (point[i].Fi > point[i].Se) swap(point[i].Fi, point[i].Se);
    }
    sort(point + 1, point + 1 + n);
    ll ans = LL_INF;
    ll rmax = 0, rmin = LL_INF;
    ll bmax = 0, bmin = LL_INF;

    // Case I
    int ida = 0, idb = 0;
    for (int i = 1; i <= n; i++) {
        if (point[i].Fi < bmin) {
            bmin = point[i].Fi;
            ida = i;
        }
        if (point[i].Se > rmax) {
            rmax = point[i].Se;
            idb = i;
        }
    }
    bmax = bmin, rmin = rmax;
    for (int i = 1; i <= n; i++) {
        if (i == ida || i == idb) {
            if (ida == idb) continue;
            if (i == ida) {
                rmax = max(rmax, point[i].Se);
                rmin = min(rmin, point[i].Se);
            } else {
                bmax = max(bmax, point[i].Fi);
                bmin = min(bmin, point[i].Fi);
            }
        } else {
            rmax = max(rmax, point[i].Se);
            rmin = min(rmin, point[i].Se);
            bmax = max(bmax, point[i].Fi);
            bmin = min(bmin, point[i].Fi);
        }
    }
    ans = min(ans, (rmax - rmin) * (bmax - bmin));

    // Case II
    rmax = 0, rmin = LL_INF;
    bmax = 0, bmin = LL_INF;
    ida = 0, idb = 0;
    for (int i = 1; i <= n; i++) {
        if (point[i].Fi < rmin) {
            rmin = point[i].Fi;
            ida = i;
        }
        if (point[i].Se > rmax) {
            rmax = point[i].Se;
            idb = i;
        }
    }
    memset(suffix_min, 0x3f, sizeof(suffix_min));
    if (ida != idb) {
        for (int i = n; i >= 1; i--) {
            if (i == ida) {
                suffix_max[i] = max(suffix_max[i + 1], point[i].Se);
                suffix_min[i] = min(suffix_min[i + 1], point[i].Se);
            } else if (i == idb) {
                suffix_max[i] = max(suffix_max[i + 1], point[i].Fi);
                suffix_min[i] = min(suffix_min[i + 1], point[i].Fi);
            } else {
                suffix_max[i] = max(suffix_max[i + 1], point[i].Se);
                suffix_min[i] = min(suffix_min[i + 1], point[i].Se);
            }
        }
        ll minvalue = LL_INF;
        for (int i = 1; i <= n; i++) {
            if (i == ida) {
                bmax = max(bmax, point[i].Se);
                bmin = min(bmin, point[i].Se);
            } else if (i == idb) {
                bmax = max(bmax, point[i].Fi);
                bmin = min(bmin, point[i].Fi);
            } else {
                ll newbmax = max(bmax, point[i].Fi);
                ll newbmin = min(bmin, point[i].Fi);
                newbmax = max(suffix_max[i + 1], newbmax);
                newbmin = min(suffix_min[i + 1], newbmin);
                if (newbmax - newbmin < minvalue) {
                    minvalue = newbmax - newbmin;
                    bmax = max(bmax, point[i].Fi);
                    bmin = min(bmin, point[i].Fi);
                } else {
                    bmax = max(bmax, point[i].Se);
                    bmin = min(bmin, point[i].Se);
                }
            }
        }
        ans = min(ans, (rmax - rmin) * minvalue);
    }
    printf("%lld\n", ans);

    //cout << "time: " << (long long)clock() * 1000 / CLOCKS_PER_SEC << " ms" << endl;
    return 0;
}

