        if (!cnt[idd]) {
            j++;
            while (c[j].id != idd && j < o)j++;
        }

        if (j >= o) break;

    }


    ll ans2 = 1LL * (ma - mi) * gg;

    x = a[ss] + b[ss] - mi;
    y = a[tt] + b[tt] - ma;
    if (y < mi) swap(y, mi);
    int t1, t2;
    fr(i, 1, n)
        if (i != ss && i != tt) {
            t1 = max(a[i], b[i]);
            t2 = min(a[i], b[i]);
            if (t2 > y) y = t2;
            if (t1 < x) x = t1;
        }


    ll ans1 = 1LL * (ma - x) * (y - mi);

    return ans1 > ans2 ? ans2 : ans1;
}


int main(){
