    if (n==1){
        puts("0");
        return 0;
    }
    fr(i,1,n)
        scanf("%d%d",&a[i],&b[i]);
        ll ans1=doit1();
        ll ans2=doit2();
        printf("%lld\n",ans1>ans2?ans2:ans1);
    return 0;
}

