void solve(){
	int N;
	cin >> N;
	vector<LL> X(N),Y(N);
	for(int i=0;i<N;++i){
		cin >> X[i] >> Y[i];
	}
	LL Rmax,Rmin,Lmax,Lmin;
	Rmax = X[0];
	Rmin = X[0];
	Lmax = Y[0];
	Lmin = Y[0];
	vector< vector<LL> > AA;
	vector<LL> temp(4);
	temp[0] = X[0];
	temp[1] = X[0];
	temp[2] = Y[0];
	temp[3] = Y[0];
	AA.push_back(temp);
	for(int i=1;i<N;++i){
		vector< vector<LL> >::iterator itr,end;
		itr = AA.begin();
		end = AA.end();
		LL nowMin = LINF;
		vector< vector<LL> > next;
		for(;itr!=end;++itr){
			LL _Rmax,_Rmin,_Lmax,_Lmin;
			_Rmax = max((*itr)[0],X[i]);
			_Rmin = min((*itr)[1],X[i]);
			_Lmax = max((*itr)[2],Y[i]);
			_Lmin = min((*itr)[3],Y[i]);
			LL res1 = (_Rmax-_Rmin)*(_Lmax-_Lmin);
			_Rmax = max((*itr)[0],Y[i]);
			_Rmin = min((*itr)[1],Y[i]);
			_Lmax = max((*itr)[2],X[i]);
			_Lmin = min((*itr)[3],X[i]);
			LL res2 = (_Rmax-_Rmin)*(_Lmax-_Lmin);
			if( res1 < res2 ){
				if( res1 > nowMin ) continue;
				if( res1 < nowMin ){
					next.clear();
					nowMin = res1;
				}
				vector<LL> temp(4);
				temp[0] = max((*itr)[0],X[i]);
				temp[1] = min((*itr)[1],X[i]);
				temp[2] = max((*itr)[2],Y[i]);
				temp[3] = min((*itr)[3],Y[i]);
				next.push_back(temp);
			}else if(res2 < res1){
				if( res2 > nowMin ) continue;
				if( res2 < nowMin){
					nowMin = res2;
					next.clear();
				}
				vector<LL> temp(4);
				temp[0] = max((*itr)[0],Y[i]);
				temp[1] = min((*itr)[1],Y[i]);
				temp[2] = max((*itr)[2],X[i]);
				temp[3] = min((*itr)[3],X[i]);
				next.push_back(temp);
			}else{
				if( res1 > nowMin ) continue;
				if( res1 < nowMin ){
					nowMin = res1;
					next.clear();
				}
				vector<LL> temp(4);
				temp[0] = max((*itr)[0],X[i]);
				temp[1] = min((*itr)[1],X[i]);
				temp[2] = max((*itr)[2],Y[i]);
				temp[3] = min((*itr)[3],Y[i]);
				next.push_back(temp);
				temp[0] = max((*itr)[0],Y[i]);
				temp[1] = min((*itr)[1],Y[i]);
				temp[2] = max((*itr)[2],X[i]);
				temp[3] = min((*itr)[3],X[i]);
				next.push_back(temp);
			}
		}
		AA = next;
	}
	//cout << (Rmax-Rmin)*(Lmax-Lmin) << endl;
	LL ans = (AA[0][0]-AA[0][1])*(AA[0][2]-AA[0][3]);
	cout << ans << endl;
}

