long long solve(const vector<pair<int, int> >& v)
{
    int n = v.size();
    multiset<int> x;
    multiset<int> y;
    multiset<pair<int, int> > p;
    for(int i=0; i<n; ++i){
        x.insert(v[i].first);
        y.insert(v[i].second);
        p.insert(make_pair(v[i].second, v[i].first));
    }

    long long ans = LLONG_MAX;
    for(;;){
        long long tmp = *x.rbegin() - *x.begin();
        tmp *= *y.rbegin() - *y.begin();
        ans = min(ans, tmp);

        if(p.empty())
            break;

        int a, b;
        tie(a, b) = *p.begin();
        p.erase(p.begin());
        x.erase(x.find(b));
        x.insert(a);
        y.erase(y.find(a));
        y.insert(b);
    }

    return ans;
}

