    auto small = *min_element(begin(v), end(v), small_cmp);
    v.erase(min_element(begin(v), end(v), small_cmp));
    small = normalize(small);

    cout << solve_with_fixed_small_y(small.second, small.first, v) << endl;
    return 0; }

