signed main() {
	INIT;
	VAR(int, n);
	VEC_ROW(int, n, x, y);
	REP(i, n) {
		if (x[i] > y[i]) std::swap(x[i], y[i]);
	}
	int xmax = 0, xmin = INFINT;
	int ymax = 0, ymin = INFINT;
	REP(i, n) {
		CHMAX(xmax, x[i]);
		CHMIN(xmin, x[i]);
		CHMAX(ymax, y[i]);
		CHMIN(ymin, y[i]);
	}
	int ans = (xmax - xmin) * (ymax - ymin);
	//////////////////////////////////////////////////////////////////
	{
		std::vector<PAIR> v(n);
		REP(i, n) v[i] = PAIR(x[i], y[i]);
		std::sort(ALL(v));
		REP(i, n) {
			x[i] = v[i].first;
			y[i] = v[i].second;
		}
	}
	int len = std::max(xmax, ymax) - std::min(xmin, ymin);
	int ma = x[n - 1];
	std::priority_queue<PAIR, std::vector<PAIR>, std::greater<PAIR>> pq;
	REP(i, n) pq.push(PAIR(x[i], y[i]));
	while (true) {
		auto now = pq.top(); pq.pop();
		int nx = now.first, ny = now.second;
		CHMIN(ans, len * (ma - nx));
		if (nx < ny) {
			CHMAX(ma, ny);
			pq.push(PAIR(ny, nx));
		}
		else break;
	}
	OUT(ans)BR;
	return 0;
}

