        k=max(k,t[i].sc);
        l=min(l,t[i].sc);
    }
    if(temp==LINF) temp=t[N-1].sc-t[0].fs;
    cout << min(ans,(p[N-1]-q[0])*temp) << endl;
    return 0;
}

