inline long long read()
{
	long long x=0,f=1;
	char ch=getchar();
	while(ch<'0'||ch>'9')
	{
		if(ch=='-')
			f=-1;
		ch=getchar();
	}
	while(ch>='0'&&ch<='9')
	{
		x=(x<<1)+(x<<3)+(ch^48);
		ch=getchar();
	}
	return x*f;
}
int main()
{
	n=read();
	for(int i=1; i<=n; i++)
	{
		p[++cnt].bianhao=i;
		p[cnt].shuxing=read();
		p[++cnt].bianhao=i;
		p[cnt].shuxing=read();
	}
	sort(p+1,p+2*n+1);
	for(int i=2*n; i>=1; i--)
	{
		if(!vis[p[i].bianhao])
			tot_da++,vis[p[i].bianhao]=1,mark[i]=1;
		if(tot_da==n)
		{
			da=i;
			break;
		}
	}
	for(int i=2*n; i>=1; i--)
		if(!mark[i])
		{
			xiao=i;
			break;
		}
	ans=(p[2*n].shuxing-p[da].shuxing)*(p[xiao].shuxing-p[1].shuxing);
	if(p[1].bianhao!=p[2*n].bianhao)
	{
		memset(vis,0,sizeof(vis));
		memset(mark,0,sizeof(mark));
		for(int i=2; i<2*n-1; i++)
			chafen[i]=p[i+1].shuxing-p[i].shuxing;
		int head=2,tail=2*n-1;
		vis[p[1].bianhao]=vis[p[2*n].bianhao]=1;
		while(tot<n-2)
		{
			if(chafen[head]>=chafen[tail-1]&&!vis[p[head].bianhao])
				mark[head]=1,vis[p[head].bianhao]=1,head++,tot++;
			else if(chafen[tail-1]>=chafen[head]&&!vis[p[tail].bianhao])
				mark[tail]=1,vis[p[tail].bianhao]=1,tail--,tot++;
			else
				head++,tail--;
		}
		for(int i=2; i<=2*n-1; i++)
			if(!mark[i])
			{
				xiao=i;
				break;
			}
		for(int i=2*n-1;i>=2;i--)
			if(!mark[i])
			{
				da=i;
				break;
			}
		ans=min(ans,(p[2*n].shuxing-p[1].shuxing)*(p[da].shuxing-p[xiao].shuxing));
	}
	printf("%lld",ans);
	return 0;
}

