  ll mini = LLONG_MAX, maxi =- LLONG_MAX;
  rep(i,N) {
    cin >> x[i] >> y[i];
    mini = min(mini,min(x[i],y[i]));
    maxi = max(maxi,max(x[i],y[i]));
  }
  compute(mini,maxi);
  return 0;
}

