ll setflag(ll x,char u){
    if(u=='R'){
        flag[x]='R';
        flag[conn[x]]='B';
    }
    else{
        flag[x]='B';
        flag[conn[x]]='R';
    }
    return conn[x];
}
int main(){
    scanf("%lld",&N);
    for(ll i=0;i<N;i++){
        ll t1,t2;
        scanf("%lld%lld",&t1,&t2);
        val[i*2]=make_pair(t1,i),val[i*2+1]=make_pair(t2,i);
        chk[i*2]=-1,chk[i*2+1]=-1;
    }
    sort(val,val+2*N);
    for(ll i=0;i<2*N;i++){
        if(chk[val[i].second]==-1){
            chk[val[i].second]=i;
        }
        else{
            conn[chk[val[i].second]]=i;
            conn[i]=chk[val[i].second];
            chk[val[i].second]=-1;
        }
