inline int read() {
	int x = 0, f = 1;
	char ch = getchar();
	for(; !isdigit(ch); ch = getchar()) if(ch=='-') f=-1;
	for(; isdigit(ch); ch = getchar()) x = x*10 + ch-'0';
	return x * f;
}

inline ll calc(int x, int y) {
	ll d1 = max(Rmax-Rmin,max(x-Rmax, Rmin-x));
	ll d2 = max(Bmax-Bmin,max(y-Bmax, Bmax-y));
	return d1*d2;
}

int main() {
	int i;
	n = read();
	Rmin = Rmax = read();
	Bmin = Bmax = read();
	for(i = 2; i <= n; i++) {
		ll x = read(), y = read();
		ll c1 = calc(x, y), c2 = calc(y, x);
		if(c1 < c2) {
			Rmin = min(Rmin, x);
			Rmax = max(Rmax, x);
			Bmin = min(Bmin, y);
			Bmax = max(Bmax, y);
		}
		else {
			Rmin = min(Rmin, y);
			Rmax = max(Rmax, y);
			Bmin = min(Bmin, x);
			Bmax = max(Bmax, x);
		}
	}
	printf("%lld\n", (Rmax-Rmin)*(Bmax-Bmin));
	return 0;
}

