inline int Read()
{   rg int a=0,c=1;   rg char b=getchar();
	while(b!='-'&&(b<'0'||b>'9'))b=getchar();
	if(b=='-')c=-1,b=getchar();
	while(b>='0'&&b<='9')a=a*10+b-48,b=getchar();
	return a*c;
}
inline int Abs(rg int A){   return A>0?A:-A;   }
inline ll Max(rg ll A,rg ll B){   return A>B?A:B;   }
inline ll Min(rg ll A,rg ll B){   return A<B?A:B;   }
inline void Get_Ans1()
{   rg int Pos1=0,Pos2=0,Maxb=0,Minb=1e9;
	for(rg int i=1;i<=n&&!Pos1;i++) if(A[i]==Maxs||B[i]==Maxs) Pos1=i,Maxb=Min(A[i],B[i]);
	for(rg int i=1;i<=n;i++) if(A[i]==Mins||B[i]==Mins) Pos2=i,Minb=Max(A[i],B[i]);
	if(Pos1==Pos2) return ;   if(Maxb<Minb) swap(Maxb,Minb);
	for(rg int i=1;i<=n;i++)
	{	if((A[i]>=Minb&&A[i]<=Maxb)||(B[i]>=Minb||B[i]<=Maxb)) continue ;
		rg int Da=Min(Abs(A[i]-Maxb),Abs(A[i]-Minb)),Db=Min(Abs(B[i]-Maxb),Abs(B[i]-Minb)),S=Da<=Db?A[i]:B[i];
		Maxb=Max(Maxb,S),Minb=Min(Minb,S);
	}
	Ans=Min(Ans,1ll*(Maxs-Mins)*(Maxb-Minb));
}
inline void Get_Ans2()
{   rg int Minr=1e9,Maxb=0;
	for(rg int i=1;i<=n;i++) Minr=Min(Minr,Max(A[i],B[i])),Maxb=Max(Maxb,Min(A[i],B[i]));
	Ans=Min(Ans,1ll*(Maxs-Minr)*(Maxb-Mins));
}
