{   n=Read(),Mins=1e9;
	for(rg int i=1;i<=n;i++) A[i]=Read(),B[i]=Read(),Maxs=Max(Maxs,Max(A[i],B[i])),Mins=Min(Mins,Min(A[i],B[i]));
	Get_Ans1(),Get_Ans2(),printf("%lld\n",Ans);
}

