        } else {
          tinf = min(tinf, y[i]);
          tsup = max(tsup, x[i]);
        }
      } else if (i == supid) {
        if (x[i] > y[i]) {
          tsup = max(tsup, y[i]);
        } else {
          tsup = max(tsup, x[i]);
        }
      } else {
        if (x[i] > y[i]) {
          tinf = min(tinf, x[i]);
        } else {
          tinf = min(tinf, y[i]);
        }
      }
