	for(int i=1; i<=n; i++){
		if(d[i].x==totalMin && d[i].y!=totalMax)
			v.push_back(pii(d[i].y, d[i].y));
		else if(d[i].x!=totalMin && d[i].y==totalMax)
			v.push_back(pii(d[i].x, d[i].x));
		else v.push_back(pii(d[i].x, d[i].y));
	}
	int bmax=-1, bmin=1e9+7;
	for(auto elem : v){
        bmin=min(bmin, elem.y);
        bmax=max(bmax, elem.x);
	}
	for(auto elem : v){
        if(elem.x < bmin && bmax < elem.y)
			pp.push_back(elem);
	}
	if(pp.empty()){
		if(bmax<bmin) swap(bmax, bmin);
		return (totalMax-totalMin)*1ll*(bmax-bmin);
	}

	int mindiff=1e9+7;
	sort(pp.begin(), pp.end(), comp);
	for(auto elem : pp){
        if(stg.empty())
			stg.push_back(elem);
		else if(stg.back().x == elem.x){
			stg.back().y=elem.y;
		}
		else{
			if(elem.y <= stg.back().y) continue;
			stg.push_back(elem);
		}
	}
	for(auto elem : stg)
		mindiff=min(mindiff, elem.y-elem.x);
	for(unsigned int i=1; i<stg.size(); i++)
		mindiff=min(mindiff, stg[i-1].y-stg[i].x);
	return (totalMax-totalMin)*1ll*mindiff;
}

