	res=min(res,1LL*(Rx.first-Rn.first)*(Bx.first-Bn.first));
//	cerr<<Rx.first<<' '<<Rn.first<<' '<<Bx.first<<' '<<Bn.first<<'\n';
	cout<<res<<'\n';
