		seg.pb(mp(x[i], y[i]));
	}
	sort(all(seg));
	int X = seg.back().fi;
	int Y = INF;
	FOR(i, 0, sz(seg)) {
		chkmin(Y, seg[i].se);
	}
	return (long long) (x[0] - x[1]) * max(0, X - Y);
}

long long work2() {
	int mnx = y[1];
	int mxy = y[0];
	FOR(i, 2, n) {
		if (x[i] < y[i]) swap(x[i], y[i]);
		chkmin(mnx, x[i]);
		chkmax(mxy, y[i]);
	}
	return (long long) (x[0] - mnx) * (mxy - x[1]);
}

void solve() {
	cin >> n;
	int mxx = 0, mxy = 0;
	FOR(i, 0, n) {
		cin >> x[i] >> y[i];
		chkmax(mxx, x[i]);
		chkmax(mxy, y[i]);
	}
