		cout << 0 << "\n";
		return;
	}
	if (mxx < mxy) {
		FOR(i, 0, n) {
			swap(x[i], y[i]);
		}
	}
	pi best;
	FOR(i, 0, n) chkmax(best, mp(x[i], i));
	int ix = best.se;
	swap(x[ix], x[0]);
	swap(y[ix], y[0]);
	int mnxy = INF;
	FOR(i, 1, n) chkmin(mnxy, x[i]), chkmin(mnxy, y[i]);
	if (mnxy == y[0]) {
		int mxy = y[0], mnx = x[0];
		FOR(i, 1, n) {
			if (x[i] < y[i]) swap(x[i], y[i]);
			chkmin(mnx, x[i]);
			chkmax(mxy, y[i]);
		}
		cout << (long long) (x[0] - mnx) * (mxy - y[0]) << "\n";
		return;
	}
	best = mp(INF + 1, INF + 1);
	FOR(i, 1, n) chkmin(best, mp(x[i], i)), chkmin(best, mp(y[i], i));
	ix = best.se;
	swap(x[ix], x[1]);
	swap(y[ix], y[1]);
	if (x[1] > y[1]) swap (x[1], y[1]);
	cout << min(work1(), work2()) << "\n";
}

