    {
        cin >> nums[i][0] >> nums[i][1];
        sorted[2 * i] = {nums[i][0], {i, 0}};
        sorted[2 * i + 1] = {nums[i][1], {i, 1}};
    }
    sort(sorted.begin(), sorted.end());
    vector<LL> ls, rs;
    ls.reserve(N);
    rs.reserve(N);
    for (int i = 0, j = 0; i < 2 * N; ++i)
    {
        int myi = sorted[i].second.first;
        int myg = sorted[i].second.second;
        int heg = myg == 0 ? 1 : 0;
        if ((nums[myi][heg] > sorted[i].first) ||
            (nums[myi][heg] == sorted[i].first && myg == 0))
            ls.push_back(sorted[i].first);
        else
            rs.push_back(sorted[i].first);
    }
    LL ll = ls[0], lr = ls[N - 1], rl = rs[0], rr = rs[N - 1];
    LL res = (lr - ll) * (rr - rl);
    lr = rr;
    int last_i = sorted[2 * N - 1].second.first;
    int last_g = sorted[2 * N - 1].second.second;
    int other_g = last_g == 0 ? 1 : 0;
    LL other = nums[last_i][other_g];
    rs.pop_back();
    if (rs.empty())
    {
        rl = other;
        rr = other;
    }
    else
    {
        rl = min(other, rl);
        rr = max(other, rs.back());
    }
    res = min(res, (lr - ll) * (rr - rl));
