		for (ll R = m - 1; R >= maxi; R--) {
			for (int num: r[R + 1])
				st.insert(num);
			ans = min(ans, (help[m - 1] - help[0]) * max(0LL, (help[R] - help[*st.begin()])));
		}
	}
