		Lmax=std::max(x[i],Lmax);
		Rmin=std::min(y[i],Rmin);
		Rmax=std::max(y[i],Rmax);
	}
	ans=std::min(ans,1ll*(Lmax-Lmin)*(Rmax-Rmin));
	printf("%lld\n",ans);
	return 0;
}

