	for(rg int i=1;i<=n;i++) Maxs=Max(Maxs,A[i]),Mins=Min(Mins,B[i]),Lsh[++Ls]=A[i],Lsh[++Ls]=B[i];
	sort(Lsh+1,Lsh+Ls+1),Ls=unique(Lsh+1,Lsh+Ls+1)-Lsh-1;
