        if (xs[i].second == rmin) {
            rminc++;
        }
        if (xs[i].second == rmax) {
            rmaxc++;
        }
        if (xs[i].first == rmin && xs[i].second == rmax) {
            pairc++;
        }
    }

    li ans = abs(rmax - bmin) * abs(bmax - rmin);
    if (rminc > 1 || rmaxc > 1 || pairc > 1) {
        ans = min(ans, abs(rmax - rmin) * abs(bmax - bmin));
    }
    cout << ans << endl;
    return 0;
}

