			swap(v[i].x, v[i].y);
		mx = max(mx, v[i].y);
	}
	sort(v, v + n);
	ll res = calc(mn, mx);
	res = min(res, (mxmn - mn)*(ll)(mx - mnmx));
	printf("%lld\n", res);
	return 0;
}

