inline void up(int &x,const int &y){if(x<y)x=y;}
inline void down(int &x,const int &y){if(x>y)x=y;}
const int maxn = 410000;

int n;
int li[maxn],ri[maxn];
struct node{int x,i,p;}a[maxn<<1]; int m;
inline bool cmp(const node x,const node y){return x.x==y.x?x.i<y.i:x.x<y.x;}


int main()
{
	scanf("%d",&n); if(n==1) return puts("0"),0;
	for(int i=1;i<=n;i++)
	{
		int x,y; scanf("%d%d",&x,&y); if(x>y) swap(x,y);
		li[i]=x,ri[i]=y;
		a[++m]=(node){x,i,0};
		a[++m]=(node){y,i,1};
	}sort(a+1,a+m+1,cmp);

	ll ans=LLONG_MAX;
	if(a[1].i!=a[m].i)
	{
		int l=2;for(;l<m&&a[l].p!=1;l++); l=a[l].x;
		int mn=a[m-1].x-l;
		if(a[m-1].p!=0)
		{
			for(int i=m-2;i>=2;)
			{
				down(l,li[a[i+1].i]);
				down(mn,a[i].x-l);
				if(a[i].p==0) break;
				int nex=i;
				for(;a[nex].p!=0&&a[nex].x==a[i].x;nex--);
				i=nex; if(a[i].p==0) break;
			}
		}
		ans=(ll)(a[m].x-a[1].x)*(ll)mn;
	}
	int u1=0,d2=inf;
	for(int i=1;i<=n;i++)
	{
		up(u1,li[i]);
		down(d2,ri[i]);
	}
	ans=min(ans,(ll)(u1-a[1].x)*(ll)(a[m].x-d2));
	printf("%lld\n",ans);

	return 0;
}

