struct bags {
    int v1,v2;

    bags() {}

    bags(int _v1,int _v2) {
        v1=_v1,v2=_v2;
    }

    bool operator<(const bags &a)const {
        return v1<a.v1;
    }
}p[maxn];

ll calc() {
    return 1ll*(*R.rbegin()-*R.begin())*(*B.rbegin()-*B.begin());
}

