        p[i]=bags(x,y);
        R.insert(x),B.insert(y);
    }
    sort(p+1,p+n+1);
    ans=calc();
    for(int i=1;i<=n;i++) {
        int x=p[i].v1,y=p[i].v2;
        R.erase(R.find(x)),B.insert(x);
        B.erase(B.find(y)),R.insert(y);
        ans=min(ans,calc());
