	PII maxX = PII(-INF, 0), maxY = PII(-INF, 0), ma, minX = PII(INF, 0), minY = PII(INF, 0), mi;
	cin >> N;
	x.resize(N); y.resize(N);
	for (int i = 0; i < N; i++)
	{
		cin >> x[i] >> y[i];
		maxX = max(maxX, PII(x[i], i));
		maxY = max(maxY, PII(y[i], i));
		minX = min(minX, PII(x[i], i));
		minY = min(minY, PII(y[i], i));
	}
	if (maxX < maxY)
	{
		swap(maxX, maxY);
		swap(minX, minY);
		swap(x, y);
	}
	mi = min(minX, minY);
	ma = max(maxX, maxY);
	int ans = INF;
	int a = y[ma.second], b = (minX < minY) ? y[mi.second] : x[mi.second];
	{
		vector<PII> v;
		v.reserve(N);
		for (int i = 0; i < N; i++)
		{
			if (mi.second == i || ma.second == i) continue;
			v.push_back(PII(min(x[i], y[i]), max(x[i], y[i])));
		}
		v.push_back(PII(INF, 0));
		sort(v.begin(), v.end());
		int bMax = max(v[v.size() - 2].first, max(a, b));
		ans = (ma.first - mi.first)*(bMax - min(min(a, b), v[0].first));
		for (int i = 0; i < v.size() - 1; i++)
		{
			bMax = max(bMax, v[i].second);
			ans = min(ans, (ma.first - mi.first)*(bMax - min(min(a, b), v[i + 1].first)));
		}
	}
	{
		int bMax = a, rMin = b;
		for (int i = 0; i < N; i++)
		{
			if (mi.second == i || ma.second == i) continue;
			bMax = max(bMax, min(x[i], y[i]));
			rMin = min(rMin, max(x[i], y[i]));
		}
		ans = min(ans, (ma.first - rMin)*(bMax - mi.first));
	}
	printf("%lld\n", ans);
	return 0;
}

