}

int mincollect(int k)
{
  //赤優先
  int l = k, r = 1 - k; //左　右
  int rmax, rmin, bmax, bmin; //赤　青

  rmax = rmin = d[l][0];
  bmax = bmin = d[r][0];

  for(int i = 1; i < N; i++) {
    int lmis = rmin - d[l][i], rmis = rmin - d[r][i];
    int lmas = d[l][i] - rmax, rmas = d[r][i] - rmax;

    if(lmas < 0) lmas = LLINF;
    if(rmas < 0) rmas = LLINF;
    if(lmis < 0) lmis = LLINF;
    if(rmis < 0) rmis = LLINF;

    //左側の処理
    if(rmin <= d[l][i] && d[l][i] <= rmax || min(lmis, lmas) < min(rmis, rmas)) {
      rmax = max(rmax, d[l][i]); rmin = min(rmin, d[l][i]);
      bmax = max(bmax, d[r][i]); bmin = min(bmin, d[r][i]);
    } else {
      rmax = max(rmax, d[r][i]); rmin = min(rmin, d[r][i]);
      bmax = max(bmax, d[l][i]); bmin = min(bmin, d[l][i]);
    }
  }

  return ( (rmax - rmin) * (bmax - bmin) );
}

