	  bm = z[i].first;
	}
	else {
	  bM = z[i].second;
	}
      }
    }
    ans = (RM - Rm) * (bM - bm);
    //cout << ans << endl;
    RM = xM.second;
    bm = xm.first;
    Rm = xm.second;
    bM = xM.first;
    for (i = 0; i < n; i++) {
      if (i == im || i == iM) {
	continue;
      }
      if (z[i].first > bM) {
	bM = z[i].first;
      }
      else if (z[i].second < Rm) {
	Rm = z[i].second;
      }
    }
    ans = min(ans, (RM - Rm) * (bM - bm));
    return ans;
  }
  else {
    ll RM = xM.second;
    ll bm = xm.first;
    ll Rm = INF;
    ll bM = -1;
    for (i = 0; i < n; i++) {
      if (i == im) {
	continue;
      }
      Rm = min(Rm, z[i].second);
      bM = max(bM, z[i].first);
    }
    return (RM - Rm) * (bM - bm);
  }
}

