using i64=int64_t;

void solve(){
    int N;
    cin >> N;
    vector<i64> x(N),y(N);
    rep(i,0,N){
        cin >> x[i] >> y[i];
        if(x[i]>y[i]) swap(x[i],y[i]);
    }

    int min_index=min_element(x.begin(),x.end())-x.begin(),max_index=max_element(y.begin(),y.end())-y.begin();
    if(min_index==max_index){
        i64 l1=x[min_index],r2=y[max_index];
        i64 r1=l1,l2=r2;
        rep(i,0,N){
            r1=max(r1,x[i]);
            l2=min(l2,y[i]);
        }
        cout << (r1-l1)*(r2-l2) << endl;
        return;
    }

    i64 ans1,ans2;
    {
        i64 l1=x[min_index],r1=x[max_index],l2=y[min_index],r2=y[max_index];
        rep(i,0,N){
            r1=max(r1,x[i]);
            l2=min(l2,y[i]);
        }
        ans1=(r1-l1)*(r2-l2);
    }
    {
        i64 l1=x[min_index],r1=y[max_index];
        map<tuple<int,int,int>,int> memo;
        function<i64(int,int,int)> rec=[&](int i,int l2,int r2){
            auto state=make_tuple(i,l2,r2);
            if(memo.find(state)!=memo.end()) return memo[state];
            if(i==N) return memo[state]=r2-l2;
            int x_=x[i],y_=y[i];
            if(l2<=x_ and x_<=r2) return memo[state]=rec(i+1,l2,r2);
            if(l2<=y_ and y_<=r2) return memo[state]=rec(i+1,l2,r2);
            if(y_<=l2) return memo[state]=rec(i+1,y_,r2);
            if(r2<=x_) return memo[state]=rec(i+1,l2,x_);
            int res1=rec(i+1,min(l2,x_),max(r2,x_)),res2=rec(i+1,min(l2,y_),max(r2,y_));
            return memo[state]=min(res1,res2);
        };
        ans2=(r1-l1)*i64(rec(0,min(y[min_index],x[max_index]),max(y[min_index],x[max_index])));
    }
    cout << min(ans1,ans2) << endl;
}

