  multiset<int> st;
  vector<Node> bv;
  for (int i = 0; i < N; ++i) {
    if (i != imin && i != imax) {
      bv.push_back(v[i]);
      st.insert(v[i].x);
    }
  }
  st.insert(v[imin].y);
  st.insert(v[imax].x);

  bmin = *st.begin();
  bmax = *st.rbegin();
  ll bmin_low = bmax;
  ret = min(ret, (rmax - rmin) * (bmax - bmin));
  for (int i = 0; i + 1 < bv.size(); ++i) {
    auto const& c = bv[i];
    if (c.x > bmin_low) break;
    bmin = min(bv[i + 1].x, bmin_low);
    bmax = max(c.y, bmax);
    bmin_low = min(bmin_low, c.y);
    ret = min(ret, (rmax - rmin) * (bmax - bmin));
  }

  bmin = v[0].y;
  bmax = v[imax].x;
  for (auto& n : bv) {
    bmin = min(bmin, n.y);
    bmax = max(bmax, n.y);
  }
  ret = min(ret, (rmax - rmin) * (bmax - bmin));
  cout << ret << endl;
}

