    ll Left=rangemin;
    rep(i,s){
        ll Right=outofrange[i+1].first,y=-outofrange[i].second;
        chmin(Left,y);
        chmin(ans,(uppermax-lowermin)*(Right-Left));
    }
    cout << ans << endl;
}

