        v.emplace_back(xs[i], ys[i], i);
        v.emplace_back(ys[i], xs[i], i);
    }

    sort(v.begin(), v.end());

    for(int i=0;i<2*N;++i){
        int a, b, index;
        tie(a, b, index) = v[i];

        thd(v[i]) = lower_bound(v.begin(), v.end(), std::make_tuple(b, a, index)) - v.begin();
    }

    ll res = compute1();
    if(thd(v[0]) != 2 * N - 1){
        res = min(res, compute2());
    }
    std::cout << res << std::endl;
}

