void calc2()
{
	static int smn[MAXN], smx[MAXN];
	smn[0] = INF, smx[0] = -INF;
	for(int i = 1; i <= n; i++)
		smn[i] = min(smn[i - 1], s[i].second), smx[i] = max(smx[i - 1], s[i].second);
	for(int i = 2; i <= n; i++)
		ans = min(ans, (long long)(mx - mn) * (max(s[n].first, smx[i - 1]) - min(s[i].first, smn[i - 1])));
}

