typedef pair<LL,LL> P;
vector<P>v;
LL case1(LL r_min,LL r_max,LL b_min,LL b_max){
   LL ans=(r_max-r_min)*(b_max-b_min);
   //b_maxの最低値を求める
   LL b_lb=0;
   REP(i,v.size()){
      b_lb=max(b_lb,v[i].second);
   }
   //xの大きさでソートした列の用意
   vector<P>w;
   REP(i,v.size()){
       w.push_back(P(v[i].second,v[i].first));
   }
   sort(w.begin(),w.end());
   w.push_back(P(10e10,0));//番兵
   //z[i]=i番目までのyの最大値
   vector<LL>z;
   if(w.size()!=0){
      z.push_back(w[0].second);
   }
   REP(i,w.size()){
      if(i==0){
         continue;
      }
      z.push_back(max(z[i-1],w[i].second));
   }
   //
   vector<LL>vv;
   REP(i,v.size()){
       vv.push_back(v[i].first);
       vv.push_back(v[i].second);
   }
   sort(vv.begin(),vv.end());
   REP(i,vv.size()){
       LL mi=min(vv[i],b_min);
       LL index=lower_bound(w.begin(),w.end(),P(mi,-1))-w.begin();
       LL ma=max(z[index],b_lb);
       ma=max(ma,b_max);
       ans=min(ans,(ma-mi)*(r_max-r_min));
   }
   return ans;
}

LL case2(LL r_min,LL r_max,LL b_min,LL b_max){
   LL ans=(r_max-r_min)*(b_max-b_min);
   LL mi=10e10;
   LL ma=0;
   REP(i,v.size()){
       mi=min(mi,v[i].first);
       ma=max(ma,v[i].second);
   }
   mi=min(b_min,mi);
   ma=max(ma,r_max);
   return (ma-r_min)*(b_max-mi);
}

