func diff(a, b int) int {
	c := a - b
	if c < 0 {
		return -c
	}
	return c
}

func maxOfTwo(min, min2, max, max2 int) int {
	a := diff(max, min) * diff(max2, min2)
	b := diff(max, min2) * diff(max2, min)
	if a < b {
		return a
	}
	return b
}

