#define SORT(v) sort((v).begin(), (v).end())
#define RSORT(v) sort((v).rbegin(), (v).rend())
#define ARY_SORT(a, size) sort((a), (a)+(size))
#define MAX(a,b) (((a) > (b)) ? (a) : (b))
#define MIN(a,b) (((a) < (b)) ? (a) : (b))
using namespace std;

struct St
{
	int small;
	int big;
	bool operator < (const St &st) const
	{
		if (st.small == small)
		{
			return st.big > big;
		}
		return st.small > small;
	}
};

St st[200000];


signed main()
{
	int N;
	cin >> N;
	for (int i = 0; i < N; i++)
	{
		int x, y;
		cin >> x >> y;
		int max = MAX(x, y);
		int min = MIN(x, y);
		st[i].small = min;
		st[i].big = max;
	}

	ARY_SORT(st, N);

	int max_i = -1;
	int max_n = INT_MIN;
	int min_i = -1;
	int min_n = INT_MAX;
	for (int i = 0; i < N; i++)
	{
		int max = st[i].big;
		int min = st[i].small;
		if (max > max_n)
		{
			max_n = max;
			max_i = i;
		}
		if (min < min_n)
		{
			min_n = min;
			min_i = i;
		}
	}

	//pt1 r_max=MAX r_min=MIN
	int max2 = MAX(st[min_i].big, st[max_i].small);
	int min2 = MIN(st[min_i].big, st[max_i].small);
	int init_min2 = min2;
	for (int i = 0; i < N; i++)
	{
		if (i == max_i || i == min_i) continue;
		max2 = MAX(max2, st[i].small);
		min2 = MIN(min2, st[i].small);
	}

	int min_val = (max_n - min_n) * (max2 - min2);
	for (int i = 0; i < N; i++)
	{
		if (st[i].big >= init_min2) break;
		if (i == N - 1)
		{
			//last
			min2 = MIN(MIN(st[min_i].big, st[max_i].small), st[i].big);
		}
		else
		{
			min2 = st[i + 1].small;
		}
		max2 = MAX(max2, st[i].big);
		int val = (max_n - min_n) * (max2 - min2);
		min_val = MIN(val, min_val);
	}

	//pt2 r_max=MAX b_min=MIN
	int min_r = st[min_i].big;
	int max_b = st[max_i].small;
	for (int i = 0; i < N; i++)
	{
		if (i == max_i || i == min_i) continue;
		min_r = MIN(st[i].big, min_r);
		max_b = MAX(st[i].small, max_b);
	}
	int val = (max_n - min_r) * (max_b - min_n);
	min_val = MIN(val, min_val);

	cout << min_val << endl;
}

