    {
        dp[1].X.X = max(x[0] , x[1]);
        dp[1].X.Y = min(x[0] , x[1]);
        dp[1].Y.X = max(y[0] , y[1]);
        dp[1].Y.Y = min(y[0] , y[1]);
    }
    else
    {
        dp[1].X.X = max(x[0] , y[1]);
        dp[1].X.Y = min(x[0] , y[1]);
        dp[1].Y.X = max(y[0] , x[1]);
        dp[1].Y.Y = min(y[0] , x[1]);
    }
