	for(int i=1; i<=N; i++) {
		scanf("%d%d", &x[i], &y[i]);
		if(x[i] > y[i]) swap(x[i], y[i]);
		mn = min(mn, x[i]);
		mx = max(mx, y[i]);
	}
	int mni = -1, mxi = -1;
	for(int i=1; i<=N; i++) {
        if(x[i] == mn && y[i] == mx) {
            if(mni == -1) mni = i, mxi = i;
            else mxi = i;
        }
    }
	for(int i=1; i<=N; i++) {
		if(x[i] != mn || y[i] != mx) {
			if(x[i] == mn) mni = i;
			if(y[i] == mx) mxi = i;
		}
	}

	int rmn = 1e9, rmx = -1e9, bmn = 1e9, bmx = -1e9;
	for(int i=1; i<=N; i++) {
		rmn = min(rmn, x[i]);
		rmx = max(rmx, x[i]);
		bmn = min(bmn, y[i]);
		bmx = max(bmx, y[i]);
	}
	long long ans = 1LL * (rmx - rmn) * (bmx - bmn);
	if(mni != mxi) {
		int omn = x[mxi], omx = y[mni];
		int Ll = min({bmn, omn, omx}), Rr = max({rmx, omn, omx});
		int L = min(Ll, Rr), R = max(Ll, Rr);
		vector<int> S;
		for(int i=1; i<=N; i++) {
			if(i == mni || i == mxi) continue;
			if(x[i] <= L && R <= y[i]) S.push_back(i);
		}
		int lmn = 1e9, lmx = -1e9, rmn = 1e9, mnx = -1e9;
		for(auto& it: S) {
			lmn = min(x[it], lmn);
			lmx = max(x[it], lmx);
			rmn = min(y[it], rmn);
			rmx = max(y[it], rmx);
		}
		int LL = min({lmn, omn, omx, L, R});
		int RR = max({lmx, omn, omx, L, R});
		ans = min(ans, 1LL * (mx - mn) * (RR - LL));
		LL = min({rmn, omn, omx, L, R});
		RR = max({rmx, omn, omx, L, R});
		ans = min(ans, 1LL * (mx - mn) * (RR - LL));
	}
	printf("%lld", max(0LL, ans));
	return 0;
}

