int add(int i){
    cnt[data[i].second]++;
    if(cnt[data[i].second] == 1)return 1;
    return 0;
}
int remove(int i){
    cnt[data[i].second]--;
    if(cnt[data[i].second] == 0)return -1;
    return 0;
}
int check(){
    memset(cnt, 0, sizeof cnt);
    int ans = 0;
    int i = 1;
    ans += add(i);
    int j = 1;
    i++;
    int len = 1e18;
    if(ans == n)len= min(len, data[i-1].first - data[j].first);
    while(i < data.size() -1){
        ans += add(i);
        while(ans > n){
            ans += remove(j);
            j++;
        }
        i++;
        if(ans == n)len= min(len, data[i-1].first - data[j].first);
    }
    return len;
}
