void build(int ver,int tl,int tr)
{
    if(tl>tr)
            return ;
    else if(tl==tr)
        seg[ver]=min(p[tl].first,p[tl].second);
    else
    {
        int tm=(tl+tr)/2;
        build(2*ver,tl,tm);
        build(2*ver+1,tm+1,tr);
        seg[ver]=max(seg[2*ver],seg[2*ver+1]);
