void upd(int ver,int tl,int tr,int pos,int val)
{
    if(tl>tr)
            return;
    else if(tl==tr)
            seg[ver]=val;
    else
    {
        int tm=(tl+tr)/2;
        if(tm>=pos)
            upd(2*ver,tl,tm,pos,val);
        else
            upd(2*ver+1,tm+1,tr,pos,val);
        seg[ver]=max(seg[2*ver],seg[2*ver+1]);
    }
}


