unordered_map<ll,ll> dp[101];
ll dfs(int pos,ll cost){
  if(pos == -1) return 0;
  if(dp[pos].count(cost)) return dp[pos][cost];

  ll res =  dfs(pos-1,cost);
  if(cost+w[pos]<=W) res=max(res,v[pos]+dfs(pos-1,cost+w[pos]));
  return res;
}

