			a = y[i], b = x[i];
		}
		xmin = min(xmin, a);
		xmax = max(xmax, a);
		ymin = min(ymin, b);
		ymax = max(ymax, b);
	}
	//printf("%d %d %d %d\n", xmin, xmax, ymin, ymax);
	return static_cast<long long>(xmax - xmin) * static_cast<long long>(ymax - ymin);
}
