void Calc() {

  int n = in;

  vector<pair<int, int>> v(n);
  for (auto& i : v) {
    in, i.first, i.second;
  }

  const int INF = 1e9 - 1;

  int rmin = INF, rmax = -INF, bmin = INF, bmax = -INF;

  struct Data {
    pair<int, int> r, b;
  };
  queue<Data>q;
  q.push({ {v[0].first,v[0].first},{v[0].second,v[0].second} });
  auto score = [](pair<int, int> r, pair<int, int> b) {
    return (ll)(r.second - r.first)*(b.second - b.first);
  };
  rep(i, n) {
    auto p = q.front();
    q.pop();
    ll s = INF;
    auto r = p.r, b = p.b;
    amax(r.second, max(v[i].first, v[i].second));
    amin(r.first, max(v[i].first, v[i].second));
    amax(b.second, min(v[i].first, v[i].second));
    amin(b.first, min(v[i].first, v[i].second));
    s = score(r, b);
    auto ra = p.r, ba = p.b;
    amax(ra.second, min(v[i].first, v[i].second));
    amin(ra.first, min(v[i].first, v[i].second));
    amax(ba.second, max(v[i].first, v[i].second));
    amin(ba.first, max(v[i].first, v[i].second));

    if (s > score(ra, ba)) {
      q.push({ ra,ba });
    }
    else {
      q.push({ r,b });
    }
  }

  auto p = q.front();
  cout << score(p.r, p.b) << endl;


}

