        }
        if (point[i].Se > rmax) {
            rmax = point[i].Se;
            idb = i;
        }
    }
    bmax = bmin, rmin = rmax;
    for (int i = 1; i <= n; i++) {
        if (i == ida || i == idb) {
            if (ida == idb) continue;
            if (i == ida) {
                rmax = max(rmax, point[i].Se);
                rmin = min(rmin, point[i].Se);
            } else {
                bmax = max(bmax, point[i].Fi);
                bmin = min(bmin, point[i].Fi);
