            rmax = max(rmax, point[i].Se);
            rmin = min(rmin, point[i].Se);
            bmax = max(bmax, point[i].Fi);
            bmin = min(bmin, point[i].Fi);
        }
    }
    ans = min(ans, (rmax - rmin) * (bmax - bmin));

    // Case II
    rmax = 0, rmin = LL_INF;
    bmax = 0, bmin = LL_INF;
    ida = 0, idb = 0;
    for (int i = 1; i <= n; i++) {
