			std::swap(p[i].first, p[i].second);
		}
		nowmax = std::max(nowmax, p[i].first);
		nowmin = std::min(nowmin, p[i].first);
	}
	return printf("%lld\n", std::min(calc(), LLONG_MAX)), 0;
}

