		if(A [i + N] == A [allMax] && A [i] != A [allMin]){
			flag = true;
			break;
		}
		if(A [i] == A [allMin] && A [i + N] != A [allMax]){
			flag = true;
			break;
		}
		if(A [i + N] == A [allMin] && A [i] != A [allMax]){
			flag = true;
		}
	}

	ll ans = INF;
	if(flag){
		ll rMax = A [allMax],rMin = A [allMin];
		double lo = 0.0,hi = 1e18,mid1,mid2;
		FOR(i,0,200){
			mid1 = (lo + lo + hi) / 3;
			mid2 = (lo + hi + hi) / 3;
			if(f(mid1) <= f(mid2)){
				hi = mid2;
			}
			else{
				lo = mid1;
			}
		}
		chmin(ans,(rMax - rMin) * f((lo + hi) / 2));
	}
	{
		ll rMax = A [allMax],rMin = INF;
		ll bMax = -INF,bMin = A [allMin];
		FOR(i,0,N){
			if(A [i] >= A [i + N]){
				chmax(rMax,A [i]);
				chmin(rMin,A [i]);
				chmax(bMax,A [i + N]);
				chmin(bMin,A [i + N]);
			}
			else{
				chmax(rMax,A [i + N]);
				chmin(rMin,A [i + N]);
				chmax(bMax,A [i]);
				chmin(bMin,A [i]);
			}
		}
		chmin(ans,(rMax - rMin) * (bMax - bMin));
	}

	printf("%lld\n",ans);

	return 0;
}

