template<typename A, typename B> inline bool chmax(A &a, B b) { if (a<b) { a=b; return 1; } return 0; }
template<typename A, typename B> inline bool chmin(A &a, B b) { if (a>b) { a=b; return 1; } return 0; }

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
typedef pair<int, pii> P;

const ll INF = 1ll<<30;
const ll MOD = 1000000007;
const double EPS  = 1e-10;

int N;
int x[212345], y[212345];

int main() {
	cin >> N;
	REP(i, N) scanf("%lld %lld", x + i, y + i);

	vector<pii> v;
	REP(i, N) {
		v.push_back(pii(x[i], i + 1));
		v.push_back(pii(y[i], -i - 1));
	}

	sort(ALL(v));

	ll ans = 1ll<<60;

	if (N == 1) {
		ans = 0;
	}
	else {
		// Rmax, Bmaxが違う袋の場合
		REP(i, N) {
			ll rmax = x[i], rmaxp = i + 1;

			ll bmax = -1, bmaxp;
			for (int j = v.size() - 1; j >= 0; j--) {
				if (abs(v[j].se) == abs(rmaxp)) continue;
				bmax = v[j].fi;
				bmaxp = v[j].se;
				break;
			}

			ll rmin, bmin = y[i];
			if (bmaxp > 0) rmin = y[bmaxp - 1];
			else rmin = x[-bmaxp - 1];

			ll min1 = INF, min2 = INF;
			REP(j, v.size()) {
				if (abs(v[j].se) == abs(rmaxp) || abs(v[j].se) == abs(bmaxp)) continue;

				if (min1 == INF) min1 = v[j].fi; 
				else { min2 = v[j].fi; break; }
			}

			ll tmp = ( max(rmax, max(rmin, min1)) - min(rmax, min(rmin, min1)) ) * ( max(bmax, max(bmin, min2)) - min(bmax, min(bmin, min2)) );
			if (tmp >= 0) chmin(ans, tmp);
			tmp = ( max(rmax, max(rmin, min2)) - min(rmax, min(rmin, min2)) ) * ( max(bmax, max(bmin, min1)) - min(bmax, min(bmin, min1)) );
			if (tmp >= 0) chmin(ans, tmp);
		}

		// Rmax, Bmaxが同じ袋の場合
		REP(i, N) {
			ll rmax = x[i], bmax = y[i];
			if (v[v.size() - 1].fi > max(rmax, bmax) || v[v.size() - 2].fi > min(rmax, bmax)) continue;

			ll min1 = INF, min2 = INF;
			REP(j, v.size()) {
				if (abs(v[j].se) == i + 1) continue;

				if (min1 == INF) min1 = v[j].fi; 
				else { min2 = v[j].fi; break; }
			}
			if (rmax >= min1 && bmax >= min2) chmin(ans, (rmax - min1) * (bmax - min2));
			if (rmax >= min2 && bmax >= min1) chmin(ans, (rmax - min2) * (bmax - min1));
		}
	}

	cout << ans << endl;

	return 0;
}

