	for(int i = 1; i <= n; i ++)
	{
		P[++ tot].x = read(), P[tot].id = i;
		P[++ tot].x = read(), P[tot].id = i; 
	}
	sort(P + 1, P + 1 + tot);

	for(int i = 1; i <= N; i ++)
	{
		if(mark[P[i].id]) P[i].rec = mark[P[i].id], P[P[i].rec].rec = i;
		else mark[P[i].id] = i;
	}
	LL = 0, RR = N + 1;
	for(int i = 1; i <= N; i ++) if(P[i].rec < i) { LL = i; break; }
	for(int i = N; i >= 1; i --) if(P[i].rec > i) { RR = i; break; } 

