int mnn = 1e9+1;
vector<int> all;
int n;

bool check(int l1,int r1,int l2,int r2){
	//cout << l1 << " " << r1 << " " << l2 << " " << r2 << endl;
	RE(i,n){
		if(x[i] >= l1 and x[i] <= r1 and y[i] >= l2 and y[i] <= r2)continue;
		swap(x[i],y[i]);
		if(x[i] >= l1 and x[i] <= r1 and y[i] >= l2 and y[i] <= r2)continue;
		return 0;
	}
	return 1;
}

void solve(){
  	cin >> n;
  	RE(i,n){
  		cin >> x[i] >> y[i];
  		all.pb(x[i]);
  		all.pb(y[i]);
  	}
  	//cout << check(1,6,2,5);
  	sort(all(all));
  	mnn = all[0];
  	mxx = all[2*n-1];
  	int ans = INF;
  	REP(i,all.size()){
  		// [all[i],mxx] [mnn,binary]
  		// [mnn,mxx] [all[i],binary]
  		int lo = i;
  		int hi = all.size();hi--;
  		while(lo < hi){
  			int mid = (lo+hi)/2;
  			if(check(mnn,mxx,all[i],all[mid]))hi = mid;
  			else lo = mid+1;
  		}
  		if(check(mnn,mxx,all[i],all[lo])){
  			ans = min(ans,(mxx-mnn)*(all[lo]-all[i]));
  		}
  		lo = 0;
  		hi = all.size();hi--;
  		while(lo < hi){
  			int mid = (lo+hi)/2;
  			if(check(all[i],mxx,mnn,all[mid]))hi = mid;
  			else lo = mid+1;
  		}
  		if(check(all[i],mxx,mnn,all[lo])){
  			ans = min(ans,(mxx-all[i])*(all[lo]-mnn));
  		}
  	}
  	cout << ans;
}

