    int sz = srt.size ( ) ;
    int en = -1 ;
    int sm = 0 ;
    long long mnint = -1 ;
    for ( int i = 0 ; i < sz ; ++ i ) {
        if ( en < i ) {
            ++ cnt[ srt[ i ].second ] ;
            ++ sm ;
            en = i ;
        }
        while ( en < sz - 1 && sm < n ) {
            ++ en ;
            ++ cnt[ srt[ en ].second ] ;
            if ( cnt[ srt[ en ].second ] == 1 ) { ++ sm ; }
        }
        if ( sm == n ) {
