            if ( mnint < 0 || mnint > sr ) { mnint = sr ; }
        }
        -- cnt[ srt[ i ].second ] ;
        if ( cnt[ srt[ i ].second ] == 0 ) { -- sm ; }
    }
    return mnint * ( srt[ sz - 1 ].first - srt[ 0 ].first ) ;
}

long long obtain ( ) {
    for ( int i = 1 ; i <= n ; ++ i ) {
        cnt[ i ] = 0 ;
    }
    int sz = srt.size ( ) ;
    long long fst = -1 ;
    long long lst = -1 ;
    int sm = 0 ;
