#include <cstdio>
#include <algorithm>
#include <utility>
#include <vector>
typedef long long int64;
static const int MAXN = 200004;
static const int   INF32 = 0x7fff0fff;
static const int64 INF64 = 0x7fffffffffffffffLL;

int n;
std::pair<int, int> p[MAXN];

int64 brute(std::vector<std::pair<int, int>> &candidates)
{
    int n = candidates.size();
    int64 ans = INF64, cur;
    for (int i = 0; i < (1 << n); ++i) {
        int max[2] = { -1, -1 }, min[2] = { INF32, INF32 };
        for (int j = 0; j < n; ++j) {
            max[(i >> j) & 1] = std::max(max[(i >> j) & 1], p[j].first);
            min[(i >> j) & 1] = std::min(min[(i >> j) & 1], p[j].first);
            max[((i >> j) & 1) ^ 1] = std::max(max[((i >> j) & 1) ^ 1], p[j].second);
            min[((i >> j) & 1) ^ 1] = std::min(min[((i >> j) & 1) ^ 1], p[j].second);
        }
        cur = (int64)(max[0] - min[0]) * (max[1] - min[1]);
        ans = std::min(ans, cur);
    }
    return ans;
}

int main()
{
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", &p[i].first, &p[i].second);
        if (p[i].first > p[i].second) std::swap(p[i].first, p[i].second);
    }

    std::vector<std::pair<int, int>> candidates;
    if (n <= 8) {
        for (int i = 0; i < n; ++i) candidates.push_back(p[i]);
    } else {
        std::sort(p, p + n);
        for (int i = 0; i < 4; ++i) candidates.push_back(p[i]);
        for (int i = 0; i < n; ++i) std::swap(p[i].first, p[i].second);
        std::sort(p, p + n);
        for (int i = 0; i < 4; ++i) candidates.push_back(p[i]);
    }

    printf("%lld\n", brute(candidates));
    return 0;
}

