    for (int i = 0; i < N; i++) {
        int x, y; cin >> x >> y;
        A[i] = make_pair(min(x, y), max(x, y));
        B[i] = make_pair(max(x, y), min(x, y));
    }
    sort(begin(A), end(A));
    sort(begin(B), end(B));
    set<pair<int, int>> C;
    C.insert(A.front());
    C.insert(A.back());
    C.insert(B.front());
    C.insert(B.back());
    Int ans = LLONG_MAX;
    for (int i = 0; i < (1 << C.size()); i++) {
        int Rmax = 0, Rmin = 1e9, Bmax = 0, Bmin = 1e9;
        auto it = C.begin();
        for (int j = 0; j < C.size(); j++, it++) {
            if ((i >> j) & 1) {
                Rmax = max(Rmax, it->first);
                Rmin = min(Rmin, it->first);
                Bmax = max(Bmax, it->second);
                Bmin = min(Bmin, it->second);
            } else {
                Rmax = max(Rmax, it->second);
                Rmin = min(Rmin, it->second);
                Bmax = max(Bmax, it->first);
                Bmin = min(Bmin, it->first);
            }
        }
        ans = min(ans, (Int)(Rmax - Rmin) * (Bmax - Bmin));
    }
    cout << ans << endl;
