    }
    if(y[id_ymax]<y[i]){
      id_ymax = i;
    }
  }
  ll Rmax = y[id_ymax];
  ll Rmin = y[id_xmin];
  ll Bmax = x[id_ymax];
  ll Bmin = x[id_xmin];
  ll ans=0;
  repeat(i,N){
    if(i==id_xmin || i==id_ymax) continue;
    if(Rmin > y[i]){
      Rmin = y[i];
    }
    if(Bmax < x[i]){
      Bmax = x[i];
    }
  }
  ans = (Rmax-Rmin)*(Bmax-Bmin);
  if(id_xmin != id_ymax){
    Rmax = y[id_ymax];
    Rmin = x[id_xmin];
    Bmax = max(x[id_ymax],y[id_xmin]);
    Bmin = min(x[id_ymax],y[id_xmin]);
    repeat(i,N){
      if(i==id_xmin || i==id_ymax) continue;
      if((Bmin <= x[i] && x[i] <= Bmax)||(Bmin <= y[i] && y[i] <= Bmax)) continue;
      if(Bmax<x[i]) Bmax = x[i];
      else if(y[i]<Bmin) Bmin = y[i];
      else{
        if(Bmin-x[i] < y[i]-Bmax) Bmin = x[i];
        else Bmax = y[i];
      }
    }
    ans = min(ans,(Rmax-Rmin)*(Bmax-Bmin));
  }
  cout << ans << endl;
  return 0;
}

