#define MOD 1000000007
struct st{
	long long int pol[22];
	st(){
		memset(pol, 0, sizeof(pol));
	}
};
st merge(st a, st b){
	for (int i = 0; i < 21; i++){
		a.pol[i] += b.pol[i];
		if (a.pol[i] >= MOD)a.pol[i] %= MOD;
	}
	return a;
}

st ty1[200002];
st ty2[200002];

st sum[200002];

inline void dfs2(int b,st up){
	up = merge(up, ty1[b]);
	sum[b] = merge(sum[b], up);
	for (int i = 0; i < v[b].size(); i++){
		dfs2(v[b][i], up);
	}
}
inline st dfs3(int b){
	st R = ty2[b];
	for (int i = 0; i < v[b].size(); i++){
		R = merge(R, dfs3(v[b][i]));
	}
	sum[b] = merge(sum[b], R);
	return R;
}

