  for(int i=0;i<N;i++){
      if(X[mit]>X[i]) mit=i;
      if(Y[mat]<Y[i]) mat=i;
  }

  ll ans=INF;
  if(mit!=mat){
      ll R=Y[mat]-X[mit];
