      if(v.size()==0) ans=min(ans,R*abs(Y[mit]-X[mat]));
      else{
          ll ma=max(Y[mit],X[mat]);
          ll mi=min(Y[mit],X[mat]);
          for(int i=0;i<v.size();i++){
              ll s=min(mi,v[i].first);
              if(i==0) ma=max(ma,v.back().first);
