  bmax = -INF, bmin = INF;
  rep (i, n) {
    if (x[i] == mi && y[i] == ma) {
      //cout << ans << endl;
      return ans;
    }
    if (x[i] == mi) {
      bmax = max(bmax, y[i]);
      bmin = min(bmin, y[i]);
    }
    if (y[i] == ma) {
      bmax = max(bmax, x[i]);
      bmin = min(bmin, x[i]);
    }
  }
  //DEBUG(bmax); DEBUG(bmin);

  ll ans2 = INF;
  vector<bool> used(n);
  vector<pll> xy;
  int cnt = 0;
  rep (i, n) {
    if (x[i] == mi || y[i] == ma) {
      cnt++;
      continue;
    }
    if (in(x[i], bmin, bmax + 1) || in(y[i], bmin, bmax + 1)) {
      cnt++;
      continue;
    }
    else {
      if (bmax < x[i]) {
	cnt++;
	bmax = x[i];
      }
      else if (y[i] < bmin) {
	cnt++;
	bmin = y[i];
      }
      else if (x[i] < bmin && bmax < y[i]) {
	xy.push_back(pll(x[i], y[i]));
      }
    }
  }

  assert(cnt + xy.size() == n);
  sort(all(xy));
  rep (i, xy.size()) {
    ans2 = min(ans2, (rmax - rmin) * (bmax - xy[i].first));
    bmax = max(bmax, xy[i].second);
  }
