ll solve2() {
  int i;
  vector<pll> z(n);
  for (i = 0; i < n; i++) {
    z[i] = pll(x[i], y[i]);
  }
  if (n == 1) {
    cout << 0 << endl;
    return 0;
  }

  pll xM, xm;
  ll m = INF, M = -1;
  int im, iM;
  for (i = 0; i < n; i++) {
    if (z[i].second > M) {
      M = z[i].second;
      xM = z[i];
      iM = i;
    }
    if (z[i].first < m) {
      m = z[i].first;
      xm = z[i];
      im = i;
    }
  }
  if(im != iM) {
    ll ans = INF;
    ll RM = xM.second;
    ll Rm = xm.first;
    ll bm = min(xM.first, xm.second);
    ll bM = max(xM.first, xm.second);
    for (i = 0; i < n; i++) {
      if (i == im || i == iM) {
	continue;
      }
      if (z[i].first > bM) {
	bM = z[i].first;
      }
      else if (z[i].second < bm) {
	bm = z[i].second;
      }
      else if (z[i].second > bM && z[i].first < bm) {
	if (bm - z[i].first < z[i].second - bM) {
	  bm = z[i].first;
	}
	else {
	  bM = z[i].second;
	}
      }
    }
    ans = (RM - Rm) * (bM - bm);
    //cout << ans << endl;
    RM = xM.second;
    bm = xm.first;
    Rm = xm.second;
    bM = xM.first;
    for (i = 0; i < n; i++) {
      if (i == im || i == iM) {
	continue;
      }
      if (z[i].first > bM) {
	bM = z[i].first;
      }
      else if (z[i].second < Rm) {
	Rm = z[i].second;
      }
    }
    ans = min(ans, (RM - Rm) * (bM - bm));
    return ans;
  }
  else {
    ll RM = xM.second;
    ll bm = xm.first;
    ll Rm = INF;
    ll bM = -1;
    for (i = 0; i < n; i++) {
      if (i == im) {
	continue;
      }
      Rm = min(Rm, z[i].second);
      bM = max(bM, z[i].first);
    }
    return (RM - Rm) * (bM - bm);
  }
}

