    for(int i=0; i<N; i++){
        cin >> A[i] >> B[i];
        if(A[i] < B[i]) swap(A[i], B[i]);
        BA[i] = {B[i], A[i]};
    }
    int64_t Amax = *max_element(A.begin(), A.end());
