using namespace std;
typedef long long li;
typedef pair <li, li> pi;
#define rep(i, n) for(int i = 0; i < (int)(n); ++i)

int main() {
    li n;
    cin >> n;

    vector<pi> xs;
    rep(i, n) {
        li x, y;
        cin >> x >> y;
        xs.emplace_back(min(x, y), max(x, y));
    }
    sort(xs.begin(), xs.end());
    li rmin = 1e10, rmax = -1;
    li bmin = 1e10, bmax = -1;
    rep(i, n) {
        rmin = min(rmin, xs[i].first);
        rmax = max(rmax, xs[i].second);
        bmax = max(bmax, xs[i].first);
        bmin = min(bmin, xs[i].second);
    }

    li rminc = 0, rmaxc = 0, pairc = 0;
    rep(i, n) {
        if (xs[i].first == rmin) {
            rminc++;
        }
        if (xs[i].first == rmax) {
            rmaxc++;
        }
        if (xs[i].second == rmin) {
            rminc++;
        }
        if (xs[i].second == rmax) {
            rmaxc++;
        }
        if (xs[i].first == rmin && xs[i].second == rmax) {
            pairc++;
        }
    }

    li ans = abs(rmax - bmin) * abs(bmax - rmin);
    if (rminc > 1 || rmaxc > 1 || pairc != 1) {
        vector<li> tmax(n, -1), tmin(n, 1e10);
        rep(i, n) {
            if (i) {
                tmax[i] = max(tmax[i - 1], xs[i].second);
                tmin[i] = min(tmin[i - 1], xs[i].second);
            } else {
                tmax[i] = xs[i].second;
                tmin[i] = xs[i].second;
            }
        }
        vector<li> mins;
        rep(i, n) {
            mins.push_back(xs[i].first);
            mins.push_back(xs[i].second);
        }
        sort(mins.begin(), mins.end());
        rep(i, 2 * n) {
            li bbmin = mins[i];
            li p = 0, q = n;
            while (q - p > 1) {
                li m = (p + q) / 2;
                if (xs[m].first < bbmin) {
                    q = m;
                } else {
                    p = m;
                }
            }
            li bbmax;
            if (q == 0) {
                bbmax = bmax;
            } else {
                if (tmax[p] < bbmin) {
                    continue;
                } else {
                    bbmax = max(tmax[p], bmax);
                }
            }
            ans = min(ans, abs(rmax - rmin) * abs(bbmax - bbmin));
        }
    }
    cout << ans << endl;
    return 0;
}

