    solve(i + 1,
          min(a, pr.first), max(b, pr.first),
          min(c, pr.second), max(d, pr.second),
          xs, out);

    solve(i + 1,
          min(a, pr.second), max(b, pr.second),
          min(c, pr.first), max(d, pr.first),
          xs, out);
  }
}


int main(const int argc, char * argv [])
{
  ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

  size_t n;
  cin >> n;
  vector<pair<int64_t, int64_t>> xs(n);
  cin >> xs;

  for(auto & pr: xs)
    if(pr.second < pr.first)
      swap(pr.first, pr.second);

  const int64_t inf = numeric_limits<int64_t>::max();
  typedef pair<int64_t, int64_t> value_t;

  int64_t out = inf;

  {
    value_t a(xs.front().first, xs.front().first);
    value_t b(xs.front().second, xs.front().second);

    for(const auto & pr: xs)
    {
      a.first = min(a.first, pr.first);
      a.second = max(a.second, pr.first);

      b.first = min(b.first, pr.second);
      b.second = max(b.second, pr.second);
    }

    DEBUG(a);
    DEBUG(b);

    out = (a.second - a.first) * (b.second - b.first);
  }

  if(20 < xs.size())
  {
    // min of mins
    partial_sort(begin(xs), begin(xs) + 5, end(xs),
                 [](const value_t & a, const value_t & b) {
                   return a.first < b.first;
                 });

    // max of mins
    partial_sort(begin(xs) + 5, begin(xs) + 10, end(xs),
                 [](const value_t & a, const value_t & b) {
                   return a.first > b.first;
                 });

    // min of maxs
    partial_sort(begin(xs) + 10, begin(xs) + 15, end(xs),
                 [](const value_t & a, const value_t & b) {
                  return a.second < b.second;
                 });

    // max of max
    partial_sort(begin(xs) + 15, begin(xs) + 20, end(xs),
                 [](const value_t & a, const value_t & b) {
                  return a.second > b.second;
                 });

    xs.erase(xs.begin() + 20, end(xs));
  }

  solve(0, inf, -inf, inf, -inf, xs, out);
  cout << out;

  return EXIT_SUCCESS;
}

