void solve(){
		int N;
	cin >> N;
	vector< pair<LL,LL> > XY(N);
	for(int i=0;i<N;++i){
		cin >> XY[i].first >> XY[i].second;
		if( XY[i].first > XY[i].second ){
			swap(XY[i].first,XY[i].second);
		}
	}
	sort( XY.begin(), XY.end() );
	LL Rmax,Rmin,Lmax,Lmin;
	Rmax = XY[0].first;
	Rmin = XY[0].first;
	Lmax = XY[0].second;
	Lmin = XY[0].second;
	for(int i=1;i<N;++i){
		LL _Rmax,_Rmin,_Lmax,_Lmin;
		_Rmax = max(Rmax,XY[i].first);
		_Rmin = min(Rmin,XY[i].first);
		_Lmax = max(Lmax,XY[i].second);
		_Lmin = min(Lmin,XY[i].second);
		LL res1 = (_Rmax-_Rmin)*(_Lmax-_Lmin);
		_Rmax = max(Rmax,XY[i].second);
		_Rmin = min(Rmin,XY[i].second);
		_Lmax = max(Lmax,XY[i].first);
		_Lmin = min(Lmin,XY[i].first);
		LL res2 = (_Rmax-_Rmin)*(_Lmax-_Lmin);
		if( res1 < res2 ){
			Rmax = max(Rmax,XY[i].first);
			Rmin = min(Rmin,XY[i].first);
			Lmax = max(Lmax,XY[i].second);
			Lmin = min(Lmin,XY[i].second);
		}else{
			Rmax = max(Rmax,XY[i].second);
			Rmin = min(Rmin,XY[i].second);
			Lmax = max(Lmax,XY[i].first);
			Lmin = min(Lmin,XY[i].first);
		}
	}
	cout << (Rmax-Rmin)*(Lmax-Lmin) << endl;
}

