			sb.insert(y);
			bal[i*2]=P(x,y);
			bal[i*2+1]=P(y,0);
		}
		ll rmi,rma,bmi,bma;
		auto ite=sr.begin();
		rmi=*ite;
		ite=sr.end();
		ite--;
		rma=*ite;
		ite=sb.begin();
		bmi=*ite;
		ite=sb.end();
		ite--;
		bma=*ite;
		ans=min(ans,(rma-rmi)*(bma-bmi));
		mi=rmi;
		ma=bma;
	}
	sort(bal,bal+N*2);
	{
		priority_queue<ll> pque;
		REP(i,N*2){
			if (bal[i].second!=0){
				pque.push(bal[i].first);
			}
		}
		REP(i,N*2){
			ans=min(ans,(ma-mi)*(pque.top()-bal[i].first));
			if (bal[i].second!=0){
				pque.push(bal[i].second);
			}else{
				break;
			}
		}
	}
	cout<<ans<<endl;
	return 0;
}

