#define mod 1000000007

int main()
{
	int n;
	cin >> n;
	long long int maxofall = 0, minofall = mod;
	int maxindex = 0, minindex = 0;
	long long int x[200001], y[200001];
	for(int i = 0; i < n; i++){
		cin >> x[i] >> y[i];
		if(x[i] > y[i]) swap(x[i], y[i]);
		if(y[i] > maxofall){
			maxindex = i;
			maxofall = y[i];
		}
		if(x[i] < minofall){
			minindex = i;
			minofall = x[i];
		}
	}
	long long int amax = maxofall, amin = y[minindex];
	long long int bmax = x[maxindex], bmin = minofall;
	for(int i = 0; i < n; i++){
		amin = min(amin, y[i]);
		bmax = max(bmax, x[i]);
	}
	long long int ans = (amax - amin) * (bmax - bmin);
	if(maxindex == minindex){
		cout << ans << endl;
		return 0;
	}
	amax = maxofall;
	amin = minofall;
	bmax = max(x[maxindex], y[minindex]);
	bmin = min(x[maxindex], y[minindex]);
	for(int i = 0; i < n; i++){
		if(max(bmax, x[i]) - min(bmin, x[i]) < max(bmax, y[i]) - min(bmin, y[i])){
			bmax = max(bmax, x[i]);
			bmin = min(bmin, x[i]);
		} else {
			bmax = max(bmax, y[i]);
			bmin = min(bmin, y[i]);
		}
	}
	ans = min(ans, (amax - amin) * (bmax - bmin));
	cout << ans << endl;
	return 0;
}

