		int tmp1_red_small = min(xy[i].first, red_small);
		int tmp1_red_large = max(xy[i].first, red_large);
		int tmp1_blue_small = min(xy[i].second, blue_small);
		int tmp1_blue_large = max(xy[i].second, blue_large);
		ll tmp1 = (tmp1_red_large - tmp1_red_small) * (tmp1_blue_large - tmp1_blue_small);

		int tmp2_red_small = min(xy[i].second, red_small);
		int tmp2_red_large = max(xy[i].second, red_large);
		int tmp2_blue_small = min(xy[i].first, blue_small);
		int tmp2_blue_large = max(xy[i].first, blue_large);
		ll tmp2 = (tmp2_red_large - tmp2_red_small) * (tmp2_blue_large - tmp2_blue_small);

		if (tmp1 < tmp2) {
			red_small = tmp1_red_small;
			red_large = tmp1_red_large ;
			blue_small = tmp1_blue_small;
			blue_large = tmp1_blue_large;
		}else {
			red_small = tmp2_red_small;
			red_large = tmp2_red_large;
			blue_small = tmp2_blue_small;
			blue_large = tmp2_blue_large;
		}
	}
	cout << (long long)(red_large - red_small) * (blue_large - blue_small);
	return 0;
}

