bool cmp1(data a,data b){return a.b<b.b;}

bool cmp2(kry a,kry b){return a.x<b.x;}

void solve1(){
	int tmn;
	mn1=a[2].b; mx2=max(a[1].b,a[2].a); tmn=min(a[1].b,a[2].a);
	//printf("%lld %lld %lld %lld\n",mx1,mn1,mx2,tmn);
	cnt=0;
	rep(i,3,n){
		c[++cnt].x=a[i].a; c[cnt].i=i;
		c[++cnt].x=a[i].b; c[cnt].i=i;
	}
	sort(c+1,c+cnt+1,cmp2);
	mn2=c[1].x;
	rep(i,1,cnt){
		if(d[c[i].i]){
			p[d[c[i].i]]=i;
			p[i]=d[c[i].i];
		} else{
			d[c[i].i]=i;
			mx2=max(mx2,c[i].x);
		}
	}
	//puts("---"); rep(i,1,cnt) printf("%d %d\n",c[i].x,c[i].i);
	//puts("---"); rep(i,1,cnt) printf("%d\n",p[i]);

	ans1=(LL)(mx1-mn1)*(mx2-min(mn2,tmn));
	rep(i,1,cnt){
		if(p[i]<c[i].i) break;
		mn2=c[i+1].x;
		mx2=max(mx2,c[p[i]].x);
		ans1=min(ans1,(LL)(mx1-mn1)*(mx2-min(mn2,tmn)));
	}
}

