int n,a[Maxn],b[Maxn],mn,mx,mn1,mx1;
bool check1(long long val)
{
	bool r=true;
	int c1=a[mx1]+b[mx1]-mx;
	int c2=a[mn1]+b[mn1]-mn;
	if (c1<c2) swap(c1,c2);
	if (1LL*(mx-mn)*(c1-c2)>val) return false;
	for (int i=1;i<=n;i++)
		if (i!=mn1&&i!=mx1)
		{
			bool ch=true;
			if (1LL*(mx-mn)*(max(c1,a[i])-min(c2,b[i]))<=val) ch=false;
			if (1LL*(mx-mn)*(max(c1,b[i])-min(c2,a[i]))<=val) ch=false;
			if (ch) return false;
		}
	return true;
}
bool check2(long long val)
{
	bool r=true;
	int rmax=a[mx1]+b[mx1]-mx;
	int bmin=a[mn1]+b[mn1]-mn;
	if (1LL*(mx-bmin)*(rmax-mn)>val) return false;
	for (int i=1;i<=n;i++)
		if (i!=mn1&&i!=mx1)
		{
			bool ch=true;
			if (1LL*(mx-min(bmin,a[i]))*(max(rmax,b[i])-mn)<=val) ch=false;
			if (1LL*(mx-min(bmin,b[i]))*(max(rmax,a[i])-mn)<=val) ch=false;
			if (ch) return false;
		}
	return true;
}
int main()
{
	n=read();
	mx=0,mn=1e10;
	mx1,mn1=0;
	for (int i=1;i<=n;i++)
	{
		a[i]=read(),b[i]=read();
		if (max(a[i],b[i])>mx)
		{
			mx1=i;
			mx=max(a[i],b[i]);
		}
		if (min(a[i],b[i])<mn)
		{
			mn=min(a[i],b[i]);
			mn1=i;
		}
	}
	long long ans;
	if (mx1!=mn1)
	{
		long long left=0,right=1e20;
		while (right-left>1)
		{
			long long mid=(left+right)/2;
			if (check1(mid)) right=mid; else left=mid;
		}
		if (check1(left)) ans=left; else ans=right;
	}
	long long left=0,right=1e20;
	while (right-left>1)
	{
		long long mid=(left+right)/2;
		if (check2(mid)) right=mid; else left=mid;
	}
	if (check2(left)) ans=min(ans,left); else ans=min(ans,right);
	cout << ans << endl;
	return 0;
}

