const int MAXN = 4e5 + 5;

int N;
pair<LL, LL> A[MAXN];

void input()
{
    read(N);
    for (int i = 0; i < N * 2; ++i) {
        read(A[i].x);
        A[i].y = i;
    }
}

void solve()
{
    static LL val[MAXN];

    for (int i = 0; i < N * 2; i += 2) {
        if (A[i].x > A[i+1].x)
            std::swap(A[i].x, A[i+1].x);
        val[i] = A[i].x;
        val[i+1] = A[i+1].x;
    }

    LL x0 = +oo, x1 = -oo, y0 = +oo, y1 = -oo;
    for (int i = 0; i < N * 2; i += 2) {
        chkmin(x0, A[i].x); chkmax(x1, A[i].x);
        chkmin(y0, A[i+1].x); chkmax(y1, A[i+1].x);
    }
    LL ans = (x1 - x0) * (y1 - y0);

    if (N > 1) {
        std::sort(A, A + N * 2);
        LL curmax = x1;
        for (int i = 0; i < N * 2; ++i) {
            chkmin(ans, (A[N*2-1].x - A[0].x) * (curmax - A[i].x));
            if (A[i].y & 1) break;
            chkmax(curmax, val[A[i].y^1]);
        }
    }

    printf("%lld\n", ans);
}

