		ord[i << 1 | 1] = {y[i], i};
	}
	sort(ord, ord + 2 * N);

	LL ans = test2();
	if (ord[0].id != ord[2 * N - 1].id) {
		ans = min(ans, test1());
	}

	cout << ans << '\n';

	return 0;
}

