  }
  inline int Qmin(int s, int t, int ans = inf) {
    for(s += M - 1, t += M + 1; s ^ t ^ 1; s >>= 1, t >>= 1) {
      if(~s & 1) ans = min(ans, Min[s ^ 1]);
      if(t & 1) ans = min(ans, Min[t ^ 1]);
    }return ans;
  }

  inline int Qmax(int s, int t, int ans = 0) {
    for(s += M - 1, t += M + 1; s ^ t ^ 1; s >>= 1, t >>= 1) {
      if(~s & 1) ans = max(ans, Max[s ^ 1]);
      if(t & 1) ans = max(ans, Max[t ^ 1]);
