const int N = 200005;
const int inf = 1e9 + 10;

int n;
int x[N], y[N];
int tmpX[N], tmpY[N];
int MIN[2], MAX[2];
int mn[2], mx[2];
long long ans = 1LL * inf * inf;

void solve(int mask) {
	// mn[0] and mx[0] for x-coordinate
	// mn[1] and mx[1] for y-coordinate

	// assign values for all mn, mx, X, Y
	mn[0] = MIN[0], mx[0] = MAX[0];
	mn[1] = MIN[1], mx[1] = MAX[1];
	if (mask >> 0 & 1) swap(mn[0], mn[1]);
	if (mask >> 1 & 1) swap(mx[0], mx[1]);
	for (int i = 1; i <= n; ++i) {
		tmpX[i] = x[i], tmpY[i] = y[i];
	}

	// check for validity
	if (mn[0] > mx[0] || mn[1] > mx[1]) return;
	for (int i = 1; i <= n; ++i) {
		if (tmpX[i] < mn[0] || tmpX[i] > mx[0]) swap(tmpX[i], tmpY[i]);
		if (tmpY[i] < mn[1] || tmpY[i] > mx[1]) swap(tmpX[i], tmpY[i]);
		if (tmpX[i] < mn[0] || tmpX[i] > mx[0] || tmpY[i] < mn[1] || tmpY[i] > mx[1]) return;
	}

	ans = min(ans, 1LL * (mx[0] - mn[0]) * (mx[1] - mn[1]));
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		cin >> x[i] >> y[i];
	}

	// find MIN, MAX
	MIN[0] = MIN[1] = inf;
	MAX[0] = MAX[1] = -inf;
	for (int i = 1; i <= n; ++i) {
		MIN[0] = min(MIN[0], min(x[i], y[i]));
		MAX[0] = max(MAX[0], max(x[i], y[i]));
		MIN[1] = min(MIN[1], max(x[i], y[i]));
		MAX[1] = max(MAX[1], min(x[i], y[i]));
	}

	for (int mask = 0; mask < 4; ++mask) {
		solve(mask);
	}

	cout << ans << endl;
}

