	REP(i, n) pq.push(PAIR(x[i], y[i]));
	while (true) {
		auto now = pq.top(); pq.pop();
		int nx = now.first, ny = now.second;
		CHMIN(ans, len * (ma - nx));
		if (nx < ny) {
			CHMAX(ma, ny);
			pq.push(PAIR(ny, nx));
		}
		else break;
	}
	OUT(ans)BR;
	return 0;
}

