typedef double db;

// const int inf = 0x3f3f3f3f;
const ll inf = 0x3f3f3f3f3f3f3f3f;
const db pi = 3.14159265358979323846264338327950288L;
const db eps = 1e-6;
const int mo = 1e9+7;

typedef pair<ll, ll> pll;

int n;
vector<pll> v;
int mxi, mni;
bool used[200005];
vector<ll> r,b;

ll getMin(pll &p) {
    return min(p.fi,p.se);
}

ll getMax(pll &p) {
    return max(p.fi,p.se);
}

ll get3Min(ll a, ll b, ll c) {
    return min(a, min(b, c));
}

ll get3Max(ll a, ll b, ll c) {
    return max(a, max(b, c));
}

int main() {
    ll x, y;
    ll mx = -inf, mn = inf;
    R(n);
    if (n == 1) {
        W(0);
        return 0;
    }
    rep(i,0,n-1) {
        R(x,y), v.pb(pll(x,y));
        if (max(x,y) > mx) mx = max(x,y), mxi = i;
        if (min(x,y) < mn) mn = min(x,y), mni = i;
        if (max(x,y) == mx && mxi == mni) max(x,y), mxi = i;
        if (min(x,y) == mn && mxi == mni) min(x,y), mni = i;
    }
    // same bag
    if (mxi != mni) r.pb(getMin(v[mxi])), b.pb(getMax(v[mni]));
    memset(used, false, sizeof used);
    used[mxi] = used[mni] = true;
    rep(i,0,n-1) {
        if (!used[i]) {
            r.pb(getMin(v[i]));
            b.pb(getMax(v[i]));
        }
    }
    sort(r.begin(),r.end());
    sort(b.begin(),b.end());
    ll ans = (getMax(v[mxi]) - b[0]) * (r[sz(r)-1] - getMin(v[mni]));
    // diff bags
    if (mxi != mni) {
        ll r1 = min(getMin(v[mxi]), getMax(v[mni])), r2 = max(getMin(v[mxi]), getMax(v[mni]));
        memset(used, false, sizeof used);
        used[mxi] = used[mni] = true;
        rep(i,0,n-1) {
            if (!used[i]) {
                ll a = getMin(v[i]), b = getMax(v[i]), ra, rb;
                ra = get3Max(a,r1,r2) - get3Min(a,r1,r2);
                ra = get3Max(b,r1,r2) - get3Min(b,r1,r2);
                ll add = (ra < rb) ? a : b;
                r1 = get3Min(add,r1,r2), r2 = get3Max(add,r1,r2);
            }
        }
        ans = min(ans, (getMax(v[mxi]) - getMin(v[mni])) * (r2 - r1));
    }
    W(ans);
    return 0;
}

