inline void init()
{
	n=read();
	REP(i,1,n)x[i]=read(),y[i]=read(),a[i*2-1]=mkr(x[i],i),a[i*2]=mkr(y[i],i);
	REP(i,1,n)if(x[i]>y[i])swap(x[i],y[i]);
