inline void doing()
{
	// 1
	if(a[1].se!=a[n*2].se)
	{
		memset(vis,0,sizeof(vis));
		ll L,R;
		vis[a[n*2].se]++;
		REP(i,1,n*2-1)
		{
			if(!vis[a[i].se])vis[a[i].se]++;
			else { L=i;break;}
		}
		memset(vis,0,sizeof(vis));
		vis[a[1].se]++;
		DREP(i,n*2,1)
		{
			if(!vis[a[i].se])vis[a[i].se]++;
			else {R=a[i].fi; break;}
 		}
		memset(vis,0,sizeof(vis));
		REP(i,2,L)
		{
			chkmin(Ans,1ll*(a[n*2].fi-a[1].fi)*(R-a[i].fi));
			chkmax(R,(ll)y[a[i].se]);
		}
		//chkmin(Ans,1ll*(a[n*2].fi-a[1].fi)*(R-L));
	}

	//2
