const ll INF = 2e18;

ll f(double m)
{
	ll mx = -INF,mn = INF;
	FOR(i,0,N){
		if(allMin == i){
			chmax(mx,A [i + N]);
			chmin(mn,A [i + N]);
			continue;
		}
		if(allMin == i + N){
			chmax(mx,A [i]);
			chmin(mn,A [i]);
			continue;
		}
		if(allMax == i){
			chmax(mx,A [i + N]);
			chmin(mn,A [i + N]);
			continue;
		}
		if(allMax == i + N){
			chmax(mx,A [i]);
			chmin(mn,A [i]);
			continue;
		}
		if(abs(A [i] - m) <= abs(A [i + N] - m)){
			chmax(mx,A [i]);
			chmin(mn,A [i]);
		}
		else{
			chmax(mx,A [i + N]);
			chmin(mn,A [i + N]);
		}
	}
	return abs(mx - mn);
}

