#define MAX_N 200000
#define INF ((ll)1e10)
using namespace std;
typedef long long int ll;
typedef pair<ll, int> PLI;


int N;
PLI xy[MAX_N * 2];
ll ans;

bool can(ll d) {
  int cnt;
  int used[MAX_N];
  int i, j;

  cnt = 0;
  memset(used, 0, sizeof(0));
  i = 1;
  j = 1;
  for (; i < 2 * N - 1; i++) {
    for (; (j < 2 * N - 1) && (xy[j].first - xy[i].first <= d); j++) {
      if (used[xy[j].second] == 0) {
        cnt++;
        if (cnt == N) {
          // printf("can %2lld true\n", d);
          return true;
        }
      }
      used[xy[j].second]++;
    }
    used[xy[i].second]--;
    if (used[xy[i].second] == 0) {
      cnt--;
    }
  }
  // printf("can %2lld false\n", d);
  return false;
}

int main() {

  ll cnt_s_s, cnt_l_l;
  ll s_s, s_l, l_s, l_l, s_p, l_p;
  ll min_x, max_x;
  ll l, m, r;

  scanf("%d", &N);
  cnt_s_s = cnt_l_l = 0;
  s_s = s_l = INF;
  l_s = l_l = 0;
  for (int i = 0; i < N; i++) {
    scanf("%lld%lld", &xy[2 * i].first, &xy[2 * i + 1].first);
    xy[2 * i].second = i;
    xy[2 * i + 1].second = i;
    min_x = min(xy[2 * i].first, xy[2 * i + 1].first);
    max_x = max(xy[2 * i].first, xy[2 * i + 1].first);
    s_l = min(s_l, max_x);
    l_s = max(l_s, min_x);
    if (s_s >= min_x) {
      if (s_s == min_x) {
        cnt_s_s++;
      } else {
        cnt_s_s = 1;
      }
      s_s = min_x;
    }
    if (l_l <= max_x) {
      if (l_l == max_x) {
        cnt_l_l++;
      } else {
        cnt_l_l = 1;
      }
      l_l = max_x;
    }
  }
  sort(xy, xy + 2 * N);
  s_s = xy[0].first;
  l_l = xy[2 * N - 1].first;
  // printf("%lld, %lld, %lld, %lld\n", s_s, s_l, l_s, l_l);

  ans = (l_s - s_s) * (l_l - s_l);

  // printf("%lld\n", ans);

  if (xy[0].second != xy[2 * N - 1].second || cnt_s_s * cnt_l_l > 1) {
    r = ans / (l_l - s_s) + 1;
    l = 0;
    while (r - l > 1) {
      m = (r + l + 1) / 2;
      if (can(m)) {
        r = m;
      } else {
        l = m;
      }
    }
    m = (r + l + 1) / 2;
    ans = min(ans, (l_l - s_s) * m);
  }

  printf("%lld\n", ans);

  return 0;

}

