struct Fenwick {
    vector<int> tree;
    void init() {
        tree = vector<int>(Xn + 1, 0);
    }
    void upd(int idx, int val) {
        for(int i = idx + 1; i <= Xn; i += (i & -i)) tree[i] += val;
    }
    int kquer(int k) {
        int ret = 0;
        for(int i = 20; i >= 0; i--) {
            if(ret + (1 << i) > Xn) continue;
            if(tree[ ret + (1 << i) ] < k) {
                k -= tree[ ret + (1 << i) ];
                ret += (1 << i);
            }
        }
        return ret;
    }
} fw;

