class Segment_MAX{
    public :
        int n;
        void init(int n_){
            n=1;
            while(n<n_)n*=2;
            for(int i=0;i<n*2-1;++i)dat_max[i]=-INT_MAX;
        }

        void update(int k,int a){
            k+=n-1;
            dat_max[k]=a;
            while(k>0){
                k=(k-1)/2;
                dat_max[k]=max(dat_max[k*2+1],dat_max[k*2+2]);
            }
        }

        int query(int a,int b,int k,int l,int r){
            if(a<=l&&r<=b)return dat_max[k];
            if(r<=a||b<=l)return -INT_MAX;
            else {
                int vl=query(a,b,k*2+1,l,(l+r)/2);
                int vr=query(a,b,k*2+2,(l+r)/2,r);
                return max(vl,vr);
            }
        }
};

class Segment_MIN{
    public :
        int n;
        void init(int n_){
            n=1;
            while(n<n_)n*=2;
            for(int i=0;i<n*2-1;++i)dat_min[i]=INT_MAX;
        }

        void update(int k,int a){
            k+=n-1;
            dat_min[k]=a;
            while(k>0){
                k=(k-1)/2;
                dat_min[k]=min(dat_min[k*2+1],dat_min[k*2+2]);
            }
        }

        int query(int a,int b,int k,int l,int r){
            if(a<=l&&r<=b)return dat_min[k];
            if(r<=a||b<=l)return INT_MAX;
            else {
                int vl=query(a,b,k*2+1,l,(l+r)/2);
                int vr=query(a,b,k*2+2,(l+r)/2,r);
                return min(vl,vr);
            }
        }
};

