    }
    for (auto it : s)
        if (it.x > it.y)
            swap(it.x,it.y);
    for (auto it : s)
    {
        smin(Rmin,it.x);
        smax(Rmax,it.x);
        smin(Bmin,it.y);
        smax(Bmax,it.y);
    }
    ll ans = 1ll * (Bmax - Bmin) * (Rmax - Rmin);
    sort(s.begin(),s.end());
    multiset < int > s1,s2;
    for (auto it : s)
        s1.insert(it.x),s2.insert(it.y);
    auto f = [&](void)
    {
        return 1ll * (*s1.rbegin() - *s1.begin()) * (*s2.rbegin() - *s2.begin());
    };
    smin(ans,f());
    for (auto it : s)
    {
        s1.erase(s1.find(it.x));
        s1.insert(it.y);
        s2.erase(s2.find(it.y));
        s2.insert(it.x);
        smin(ans,f());
    }
    fo << ans << '\n';
    cerr << "Time elapsed :" << clock() * 1000.0 / CLOCKS_PER_SEC << " ms" << '\n';
    return 0;
}

