map<int,int> m;

void solve(){
	int xmin = 1e18, xmax = -1, ymin = 1e18, ymax = -1;
	int n;
	cin >> n;
	int c = 0;
	fr(i, 1, n) {
		int x, y;
		cin >> x >> y;
		lol[++c] = {x, i};
		lol[++c] = {y, i};
		if(x > y) swap(x, y);
		xmin = min(xmin, x);
		xmax = max(xmax, x);
		ymin = min(ymin, y);
		ymax = max(ymax, y);
	}
	int ans = (xmax - xmin) * (ymax - ymin);
	sort(lol + 1, lol + c + 1);
	if(lol[1].se != lol[c].se) {
		int pt = 0, dist = 0;
		fr(i, 1, c - 1) {
			while(pt + 1 < c && dist != n) {
				pt++;
				m[lol[pt].se]++;
				if(m[lol[pt].se] == 1) dist++;
			}
			if(dist == n) {
				ans = min(ans, (lol[c].fi - lol[1].fi) * (lol[pt].fi - lol[i].fi));
			}
			m[lol[i].se]--;
			if(!m[lol[i].se]) {
				dist--;
			}
		}
	}
	cout << ans;
}

