    xy.resize(N);
    FOR(i,N) cin >> xy[i].first >> xy[i].second;
    FOR(i,N) {
        uint _max=max(xy[i].first, xy[i].second),
            _min=min(xy[i].first, xy[i].second);
        if (_max > Max) {
            Max = _max;
            interval.second = _min;
        }
        if (_min < Min) {
            Min = _min;
            interval.first = _max;
        }
        if (_max < minmax)
            minmax = _max;
        if (_min > maxmin)
            maxmin = _min;
    }
    cand1 = (ull)(Max - minmax) * (maxmin - Min);

    if (interval.first > interval.second) {
        uint tmp = interval.first;
        interval.first = interval.second;
        interval.second = tmp;
    }

    while (true) {
        bool flag = false;
        while (flag) {
            flag = false;
            FOR(i,N) {
                uint _max=max(xy[i].first, xy[i].second),
                    _min=min(xy[i].first, xy[i].second);
                if (interval.first <= _min)
                    interval.second = max(interval.second, _min);
                else if (_max <= interval.second)
                    interval.first = min(interval.first, _max);
                else {
                    intervals.push_back(make_pair(_min, _max));
                    flag = true;
                }
            }
        }

        if (intervals.size() == 0)
            break;

        pairUInt _max=make_pair(0,0), _min=make_pair(MAXX+1, MAXX+1);
        for (auto p : intervals) {
            if (p.first < _min.first)
                _min = p;
            if (p.second > _max.second)
                _max = p;
        }
        if (_max.second - interval.second > interval.first - _min.first)
            interval.first = _max.first;
        else
            interval.second = _min.second;
    }
    cand2 = (ull)(Max - Min) * (interval.second - interval.first);

    cout << min(cand1, cand2) << endl;

