				int nex=i; for(;a[nex].p!=0&&a[nex].x==a[i].x;nex--) down(l,li[a[nex].i]);
				if(a[nex].x==a[i].x) break;
				i=nex;
			}
		}
		ans=(ll)(a[m].x-a[1].x)*(ll)mn;
	}
	int u1=0,d2=inf;
	for(int i=1;i<=n;i++)
	{
		up(u1,li[i]);
		down(d2,ri[i]);
	}
	ans=min(ans,(ll)(u1-a[1].x)*(ll)(a[m].x-d2));
	printf("%lld\n",ans);

	return 0;
}

