void solve() {
	int N; cin >> N;
	vector<pii> xy;
	vector<int> v;
	int ma = 0;
	int mi = inf;
	REP(i, N) {
		int x, y; cin >> x >> y;
		if (x > y) swap(x, y);
		xy.emplace_back(x, y);
		ma = max(x, ma);
		ma = max(y, ma);
		mi = min(x, mi);
		mi = min(y, mi);
		v.push_back(x);
		v.push_back(y);
	}
	int res;
	{
		int lmax = 0;
		int lmin = inf;
		int rmax = 0;
		int rmin = inf;
		REP(i, N) {
			lmax = max(lmax, xy[i].first);
			lmin = min(lmin, xy[i].first);
			rmax = max(rmax, xy[i].second);
			rmin = min(rmin, xy[i].second);
		}
		res = (lmax - lmin) *(rmax - rmin);
	}
	{
		int rma = 0;
		int rmi = inf;
		for (auto &a : xy) {
			if (a.first == mi and a.second == ma) {
				cout << res << endl;
				return;
			}
		}
		int rma = 0;
		int rmi = inf;
		for (auto &a : v) {
			if (a != ma and a != mi) {
				rma = max(a, rma);
				rmi = min(a, rmi);
			}
		}
		res = min(res, (ma - mi)*(rma - rmi));
	}
	cout << res << endl;
}

