    F0R (i, N) {
        auto& e = b[i];
        if (e.f > e.s) swap(e.f, e.s);

        every.pb(e.f);
        every.pb(e.s);

        ckmin(lo, {e.f, i});
        ckmax(hi, {e.s, i});
    }
    dedup(every);

    ll ans = LLONG_MAX;

    int lm = 0, hm = INT_MAX;
    F0R (i, N) {
        ckmax(lm, b[i].f);
        ckmin(hm, b[i].s);
    }
    ckmin(ans, ll(lm - lo.f) * (hi.f - hm));

    if (lo.s != hi.s) {
        set<pii> other;
        other.insert({ b[lo.s].s, lo.s });
        other.insert({ b[hi.s].f, hi.s });

        priority_queue<pii> rest;
        F0R (i, N) if (i != lo.s && i != hi.s) {
            rest.push({ -b[i].f, i });
            other.insert({ b[i].f, i });
        }
        ckmin(ans, ll(hi.f - lo.f) * (other.rbegin()->f - other.begin()->f));

        int fmin = INT_MAX;
        trav (v, every) {
            if (fmin < v) break;
            bool fix = true;
            while (!rest.empty() && -rest.top().f < v) {
                int sw = rest.top().s;
                rest.pop();
                if (b[sw].s < v) { fix = false; break; }
                other.erase({ b[sw].f, sw });
                other.insert({ b[sw].s, sw });
                ckmin(fmin, b[sw].s);
            }

            if (fix) ckmin(ans, ll(hi.f - lo.f) * (other.rbegin()->f - other.begin()->f));
            else break;
        }
    }

    ps(ans);

    return 0;
}

