	if(a<=l && r<=b){
		dat[k].lazy=max(dat[k].lazy,v);
		lazy_evaluate(k);
		return;
	}
	update(a,b,v,k*2+1,l,(l+r)/2);
	update(a,b,v,k*2+2,(l+r)/2,r);
	lazy_update(k);
