    REP(i, n)
    {
        if (ma < p[i].first)
        {
            ma = p[i].first;
            mai = i;
            mat = 0;
        }
        if (ma < p[i].second)
        {
            ma = p[i].second;
            mai = i;
            mat = 1;
        }
        if (mi > p[i].first)
        {
            mi = p[i].first;
            mii = i;
            mit = 0;
        }
        if (mi > p[i].second)
        {
            mi = p[i].second;
            mii = i;
            mit = 1;
        }
    }

    //MAXとMINを分ける
    ll rma = ma;
    ll rmi = LLONG_MAX;
    ll bma = 0;
    ll bmi = mi;
    REP(i, n)
    {
        if (mai == i && mii == i)
            continue;

        if (mai != i && mii != i)
        {
            rmi = min(rmi, max(p[i].first, p[i].second));
            bma = max(bma, min(p[i].first, p[i].second));
        }

        if (mai == i)
            bma = max(bma, mat == 0 ? p[i].second : p[i].first);

        if (mii == i)
            rmi = min(rmi, mit == 0 ? p[i].second : p[i].first);
    }

    res = min(res, (rma - rmi) * (bma - bmi));

    //MAXとMINが同じ
    if (mai != mii)
    {
        rma = ma;
        rmi = mi;

        priority_queue<ll> qma;
        priority_queue<ll, vector<ll>, greater<ll>> qmi;

        pair<ll, ll> a[212345];

        REP(i, n)
        {
            if (mai == i)
            {
                a[i] = {mat == 0 ? p[i].second : p[i].first, 1e18};

                qma.push(a[i].first);
                qmi.push(a[i].first);

                continue;
            }
            if (mii == i)
            {
                a[i] = {mit == 0 ? p[i].second : p[i].first, 1e18};

                qma.push(a[i].first);
                qmi.push(a[i].first);

