int add(int i){
    cnt[data[i].second]++;
    if(cnt[data[i].second] == 1)return 1;
    return 0;
}
int remove(int i){
    cnt[data[i].second]--;
    if(cnt[data[i].second] == 0)return -1;
    return 0;
}
int check(){
    memset(cnt, 0, sizeof cnt);
    int ans = 0;
    int i = 1;
    ans += add(i);
    int j = 1;
    i++;
    int len = 1e18;
    if(ans == n)len= min(len, data[i-1].first - data[j].first);
    while(i < data.size() -1){
        ans += add(i);
        while(ans > n){
            ans += remove(j);
            j++;
        }
        while(ans == n && i > j && cnt[data[j].second] > 1){
           ans += remove(j); 
           j++;
        }
        i++;
        if(ans == n)len= min(len, data[i-1].first - data[j].first);
    }
//    debug(len);
    return len;
}
signed main(){
    ios_base::sync_with_stdio(false);cin.tie(NULL);
    cin >> n;
    int x, y;
    FOR(i, n){
        cin >> x >> y;
        if(y < x)swap(x, y);
        data.pb(mp(x, i));
        data.pb(mp(y, i));
    }
    sort(data.rbegin(), data.rend());
    map<int, bool> found;
    int ans = 1e18;
    int start =-1;
    FOR(i, data.size()){
        //debug(data[i].first);
        if(found[data[i].second] && start == -1){
            start = data[i].first;
        } 
        found[data[i].second] = true;
        if(found.size() == n){
            ans =min(ans, (data[0].first - data[i].first)*((start == -1 ? data[i+1].first : start)- data.back().first)); 
            break;
        }
    }
    if(data[0].second == data.back().second){
        cout << ans;
        return 0;
    }
    int len = data[0].first - data.back().first;

    //debug("here");
//    debug(len);
    reverse(data.begin(), data.end());
    //debug(len);
    ans = min(ans, len * check());
    cout << ans;

}

