void Dfs(LL dep){
	if(dep==cnt+1){
		LL Rmax=-Inf,Rmin=Inf;
		LL Bmax=-Inf,Bmin=Inf;
		for(LL i=1;i<=cnt;i++) {
			Rmax=max(Rmax,R[i]);
			Rmin=min(Rmin,R[i]);
			Bmax=max(Bmax,B[i]);
			Bmin=min(Bmin,B[i]);
		}
		ans=min(ans,(Rmax-Rmin)*(Bmax-Bmin));
		return;
	}
	R[dep]=b[dep].x;
	B[dep]=b[dep].y;
	Dfs(dep+1);
	swap(R[dep],B[dep]);
	Dfs(dep+1);
}
