		if (dat[i].x > dat[i].y) swap(dat[i].x, dat[i].y);
	}

	int maxidx = 0;
	for (int i = 1; i < n; i++)
		if (dat[maxidx].y < dat[i].y) maxidx = i;

	swap(dat[maxidx], dat[n - 1]);
	sort(dat, dat + n - 1);

	printf("%lld\n", min(solve1(), solve2()));
}

