int main(){
    int n;
    cin >> n;

    vector<long long int> xb(n), yb(n);
    vector<pair<long long int, long long int>> ball(n);
    long long int amax = 0, amin = 1e9 + 1;

    for(int i=0; i<n; i++){
        long long int x, y;
        cin >> x >> y;
        if(x < y) swap(x,y);
        xb[i] = x;
        yb[i] = y;
        ball[i] = {y, x};

        amax = max(amax, x);
        amin = min(amin, y);
    }

    if(n == 1){
        cout << 0 << endl;
        return 0;
    }

    long long int ans = 1e18;
    sort(xb.begin(),xb.end());
    sort(yb.begin(),yb.end());
    sort(ball.begin(), ball.end());

    // case(1) amax = Rmax, amin = Rmin
    long long int rmax = amax;
    long long int rmin = amin;

    long long int bmax = max(ball[0].second, ball[n-1].first);
    long long int bmin = min(ball[0].second, ball[1].first);
    long long int blue = bmax - bmin;

    for(int i=1; i<n-1; i++){
        if(ball[0].second < ball[i].first) break;
        if(ball[i].second > xb[n-2]) break;
        bmax = max(bmax, ball[i].second);
        bmin = min(ball[0].second, ball[i+1].first);
        blue = min(blue, bmax - bmin);
    }
    ans = (rmax - rmin) * blue;

    // case(2) amax = Rmax, amin = Bmin
    ans = min(ans, (xb[n-1]-xb[0]) * (yb[n-1]-yb[0]));

    cout << ans << endl;
    return 0;
}

