int main()
{
	int n;
	cin >> n;
	long long int maxofall = 0, minofall = mod;
	int maxindex = 0, minindex = 0;
	vector<pair<long long int, long long int> > v;
	for(int i = 0; i < n; i++){
		long long int x, y;
		cin >> x >> y;
		if(x > y) swap(x, y);
		v.push_back(make_pair(x, y));
	}
	sort(v.begin(), v.end());
	for(int i = 0; i < n; i++){
		long long int x = v[i].first;
		long long int y = v[i].second;
		if(y > maxofall){
			maxindex = i;
			maxofall = y;
		}
		if(x < minofall){
			minindex = i;
			minofall = x;
		}
	}
	long long int amax = maxofall, amin = v[minindex].second;
	long long int bmax = v[maxindex].first, bmin = minofall;
	for(int i = 0; i < n; i++){
		long long int x = v[i].first;
		long long int y = v[i].second;
		if(i == maxindex || i == minindex) continue;
		amin = min(amin, y);
		bmax = max(bmax, x);
	}
	long long int ans = (amax - amin) * (bmax - bmin);
	if(maxindex == minindex){
		cout << ans << endl;
		return 0;
	}
	amax = maxofall;
	amin = minofall;
	bmax = max(v[maxindex].first, v[minindex].second);
	bmin = min(v[maxindex].first, v[minindex].second);
	for(int i = 0; i < n; i++){
		if(i == maxindex || i == minindex) continue;
		long long int x = v[i].first;
		long long int y = v[i].second;
		if(max(bmax, x) - min(bmin, x) < max(bmax, y) - min(bmin, y)){
			bmax = max(bmax, x);
			bmin = min(bmin, x);
		} else {
			bmax = max(bmax, y);
			bmin = min(bmin, y);
		}
	}
	ans = min(ans, (amax - amin) * (bmax - bmin));
	cout << ans << endl;
	return 0;
}

