inline void solve () {
        scanf ("%d", &n);
        m = f = mp (0, mod);
        for (int i = 1; i <= n; i++) {
                scanf ("%d%d", &a[i].f, &a[i].s);
                if (a[i].f > a[i].s) {
                        swap (a[i].f, a[i].s);
                }
                m.f = max (m.f, a[i].s);
                m.s = min (m.s, a[i].f);
                f.f = max (f.f, a[i].f);
                f.s = min (f.s, a[i].s);
                b[i] = mp (a[i].f, i);
                b[n + i] = mp (a[i].s, i);
        }
        ans = (f.f - m.s) * 1LL * (m.f - f.s);
        x = max (f.f, m.f) - min (f.s, m.s);
        sort (b + 1, b + n + n + 1);
        for (int i = 1, r = 0, cr = 0; i <= n + n; i++) {
                while (r < n + n && cr < n) {
                        q[b[++r].s]++;
                        if (q[b[r].s] == 1) {
                                cr++;
                        }
                }
                if (cr < n) {
                        break;
