        int c = idx[i];
        B_max = max(B_max, y[c]);
        y_min = min(y_min, y[c]);
        B_min = min(y_min, x[c + 1]);
        ans = min(ans, (R_max - R_min) * (B_max - B_min));
    }

    cout << ans << endl;
}

