const int maxn = 2e5 + 5;
int n;
int x[maxn];
int y[maxn];

long long work1(int lo, int hi) {
	vii seg;
	FOR(i, 0, n) {
		if (x[i] > y[i]) swap(x[i], y[i]);
		seg.pb(mp(x[i], y[i]));
	}
	sort(all(seg));
	int X = seg.back().fi;
	int Y = INF;
	FOR(i, 0, sz(seg)) {
		if (seg[i].se <= X) {
			chkmin(Y, seg[i].se);
		}
		else {
			chkmin(Y, seg[i].fi);
		}
	}
	return (long long) (hi - lo) * max(0, X - Y);
}

long long work2(int lo, int hi) {
	int mnx = INF, mxy = 0;
	FOR(i, 0, n) {
		if (x[i] < y[i]) swap(x[i], y[i]);
		chkmin(mnx, x[i]);
		chkmax(mxy, y[i]);
	}
	return (long long) (hi - mnx) * (mxy - lo);
}

void solve() {
	cin >> n;
	int mn = INF, mx = 0;
	FOR(i, 0, n) {
		cin >> x[i] >> y[i];
		chkmin(mn, x[i]);
		chkmin(mn, y[i]);
		chkmax(mx, x[i]);
		chkmax(mx, y[i]);
	}
	cout << min(work1(mn, mx), work2(mn, mx)) << "\n";
}

