			r2 = i;
		}
	}
	ans = dif(n);
	if(r1 + 1 != r2 && r2 + 1 != r1)
		ans = min(ans, same(n, r1, r2) * (mmax - mmin));
	printf("%lld\n", ans);
	return 0;
}

