ll sol1() {
	ll ret = INF * INF;
	vector<bool> used(n, false);
	vector<bool> min_ok(m, false);
	REP(i, m - 1) {
		if(used[v[i].second]) break;
		used[v[i].second] = true;
		min_ok[i + 1] = true;
	}
	used.assign(n, false);
	ll mx = -1;
	for(int i = m - 1; i > 0; i--) {
		if(used[v[i].second] && mx == -1) {
			mx = v[i].first;
		} else used[v[i].second] = true;
		if(!min_ok[i]) continue;
		if(mx == -1) {
			ret = min(ret, (v[m - 1].first - v[i].first) * (v[i - 1].first - v[0].first));
		} else {
			ret = min(ret, (v[m - 1].first - v[i].first) * (mx - v[0].first));
		}
	}
	return ret;
}

ll sol2() {
	ll ret = INF * INF;
	ll d = (v[m - 1].first - v[0].first);
	vector<int> used(n, 0);
	ll bk = 1, c = 1;
	used[v[1].second] = true;
	FOR(i, 1, m - 1) {
		while(c != n && bk < m - 2) {
			bk++;
			used[v[bk].second]++;
			if(used[v[bk].second] == 1) c++;
		}
		if(c == n) ret = min(ret, d * (v[bk].first - v[i].first));
		used[v[i].second]--;
		if(used[v[i].second] == 0) c--;
	}
	return ret;
}

