        rep(i,n){
            int r=x[i],b=y[i];
            if(r>b)swap(r,b);
            chmin(Rmi,r);
            chmax(Rma,r);
            chmin(Bmi,b);
            chmax(Bma,b);
        }
        chmin(ans,(Rma-Rmi)*(Bma-Bmi));
    }
    {
        //(MAX-MIN)
        int ma=-INF;
        priority_queue<P,vector<P>,greater<P>>q;
        rep(i,n){
            int r=x[i],b=y[i];
            if(r>b)swap(r,b);
            q.push({r,b});
