ll div_minmax(const V<t2> &val_idx_list, ll n)
{
    ll minval = get<0>(val_idx_list[0]);
    ll minidx = get<1>(val_idx_list[0]);

    bool checked[n];
    memset(checked, 0, sizeof(checked));
    ll count = 0LL;
    ll min_pair = minval;

    checked[minidx] = true;
    count++;
    rep (i, 2LL * n) {
        ll val = get<0>(val_idx_list[i]);
        ll idx = get<1>(val_idx_list[i]);

        debug_printf("x1 val=%lld idx=%lld\n", val, idx);
        if (checked[idx]) continue;
        debug_printf("x1 pass val=%lld idx=%lld\n", val, idx);

        checked[idx] = true;
        count++;
        min_pair = val;
        if (count >= n) break;
    }

    ll maxval = get<0>(val_idx_list[2 * n - 1]);
    ll maxidx = get<1>(val_idx_list[2 * n - 1]);

    memset(checked, 0, sizeof(checked));
    count = 0LL;
    ll max_pair = maxval;

    checked[maxidx] = true;
    count++;
    rrep (i, 2LL * n) {
        ll val = get<0>(val_idx_list[i]);
        ll idx = get<1>(val_idx_list[i]);

        debug_printf("x2 val=%lld idx=%lld\n", val, idx);
        if (checked[idx]) continue;
        debug_printf("x2 pass val=%lld idx=%lld\n", val, idx);

        checked[idx] = true;
        count++;
        max_pair = val;
        if (count >= n) break;
    }

    return (min_pair - minval) * (maxval - max_pair);
}

ll same_minmax(const V<t2> &val_idx_list, ll n)
{
    ll minval = get<0>(val_idx_list[0]);
    ll minidx = get<1>(val_idx_list[0]);
    ll maxval = get<0>(val_idx_list[2 * n - 1]);
    ll maxidx = get<1>(val_idx_list[2 * n - 1]);
    if (minidx == maxidx) return 2LL * ((ll)pow(10LL, 18LL));

    ll leftval = 0LL;
    ll leftidx = -1LL;
    ll rightval = 0LL;
    ll rightidx = -1LL;

    ll left_out_val = get<0>(val_idx_list[1]);
    ll left_out_idx = get<1>(val_idx_list[1]);
    ll left_out_listidx = 1LL;
    ll right_out_val = 0LL;
    ll right_out_idx = -1LL;
    ll right_out_listidx = -1LL;

    int checkcount[n];
    memset(checkcount, 0, sizeof(checkcount));
    ll count = 0LL;

    srep (i, 1, n * 2LL - 1LL) {
        ll val = get<0>(val_idx_list[i]);
        ll idx = get<1>(val_idx_list[i]);

        if (idx == minidx || idx == maxidx) {
            if (leftidx < 0LL) {
                leftval = val;
                leftidx = idx;
            }
            else if (rightidx < 0LL) {
                rightval = val;
                rightidx = idx;
            }
        }

        if (checkcount[idx] == 0) count++;
        checkcount[idx]++;
        right_out_val = val;
        right_out_idx = idx;
        right_out_listidx = i;

        if (count >= n) break;
    }

    assert(leftidx >= 0LL);
    assert(rightidx >= 0LL);

    ll ret = (maxval - minval) * (right_out_val - left_out_val);

    srep (i, 1LL, n * 2LL - 2LL) {
        ll val = get<0>(val_idx_list[i]);
        ll idx = get<1>(val_idx_list[i]);
        left_out_val = get<0>(val_idx_list[i+1]);
        left_out_idx = get<1>(val_idx_list[i+1]);

        checkcount[idx]--;

        if (checkcount[idx] <= 0) {
            count--;
            srep (j, right_out_listidx+1LL, n * 2LL - 1LL) {
                ll rval = get<0>(val_idx_list[j]);
                ll ridx = get<1>(val_idx_list[j]);
                right_out_val = rval;
                right_out_idx = ridx;
                right_out_listidx = j;
                if (checkcount[ridx] == 0) count++;
                checkcount[ridx]++;
                if (count >= n) break;
            }
            if (count < n) return ret;
        }

        ret = (maxval - minval) * (right_out_val - left_out_val);
    }

    return ret;
}


int _main()
{
    ll n;
    llin(n);

    V<t2> xylist;
    llinl2(xylist, n);

    V<t2> val_idx_list;
    rep (i, n) {
        ll x = get<0>(xylist[i]);
        ll y = get<1>(xylist[i]);
        val_idx_list.pb(t2(x, i));
        val_idx_list.pb(t2(y, i));
