    sort(val_idx_list);
    debug_printf("---- val_idx_list\n");
    debug_print(val_idx_list);

    ll ans = 2LL * ((ll)pow(10LL, 18LL));

    ans = min(ans, div_minmax(val_idx_list, n));
    ans = min(ans, same_minmax(val_idx_list, n));

    cout << ans;

    return 0;
}

