		ans = min(ans, 1ll * (a[s.rbegin()->first][s.rbegin()->second] - a[s.begin()->first][s.begin()->second]) * (ymax - a[b[i].first][0]));
		s.erase(mp(i, 1));
		s.insert(mp(i, 0));
	}
	printf("%lld\n", ans);
	return 0;
}
