	int pmin=1,pmax=1;
	rep(i,2,n) {
		if(A[i].xx<A[pmin].xx) pmin=i;
		if(A[i].yy>=A[pmax].yy) pmax=i;
	}
	ll ans=inf;
	//ans=min(ans,solve2(pmin,pmax));
	if(pmin!=pmax) ans=min(ans,solve1(pmin,pmax));
	printf("%lld\n",ans);
	return 0;
}

