ll greedy1(int n, vector<int>& x, vector<int>& y) {
    vector<int> I(n);
    iota(I.begin(), I.end(), 0);
    sort(I.begin(), I.end(), [&](int i, int j) {
        return make_pair(x[i], -y[i]) < make_pair(x[j], -y[j]);
    });
    int b1 = I[0], B_min = x[b1], R_min = y[b1];
    sort(I.begin(), I.end(), [&](int i, int j) {
        return make_pair(y[i], -x[i]) > make_pair(y[j], -x[j]);
    });
    int b2 = I[0], B_max = x[b2], R_max = y[b2];
    for(int i : I) {
        if(i != b1 and i != b2) {
            B_max = max(B_max, x[i]);
            R_min = min(R_min, y[i]);
        }
    }
    return ll(R_max - R_min) * (B_max - B_min);
}
ll greedy2(int n, vector<int>& x, vector<int>& y) {
    vector<int> I(n);
    iota(I.begin(), I.end(), 0);

    sort(I.begin(), I.end(), [&](int i, int j) { return x[i] > x[j]; });
    int R_min = x[I.back()];
    sort(I.begin(), I.end(), [&](int i, int j) { return y[i] < y[j]; });
    int R_max = y[I.back()];

    vector<int> always_B;
    sort(I.begin(), I.end(), [&](int i, int j) { return x[i] > x[j]; });
    while(not I.empty() and x[I.back()] == R_min) {
        always_B.push_back(y[I.back()]);
        I.pop_back();
    }
    sort(I.begin(), I.end(), [&](int i, int j) { return y[i] < y[j]; });
    while(not I.empty() and y[I.back()] == R_max) {
        always_B.push_back(x[I.back()]);
        I.pop_back();
    }

    if(I.empty()) {
        int B_min = lim<int>::max(), B_max = lim<int>::min();
        for(int x : always_B) {
            B_min = min(B_min, x);
            B_max = max(B_max, x);
        }
        return ll(R_max - R_min) * (B_max - B_min);
    } else {
        sort(I.begin(), I.end(), [&](int i, int j) {
            return make_pair(x[i], y[i]) < make_pair(x[j], y[j]);
        });
        int B_min = x[I[0]], B_max = x[I.back()];
        for(int x : always_B) {
            B_min = min(B_min, x);
            B_max = max(B_max, x);
        }
        ll ans = ll(R_max - R_min) * (B_max - B_min);
        for(auto it = I.begin(); it + 1 != I.end(); it++) {
            B_min = min({B_min, x[I[*(it + 1)]], y[I[*it]]});
            B_max = max(B_max, y[I[*it]]);
            ans = min(ans, ll(R_max - R_min) * (B_max - B_min));
        }
        sort(I.begin(), I.end(), [&](int i, int j) { return y[i] < y[j]; });
        B_min = y[I[0]], B_max = y[I.back()];
        for(int x : always_B) {
            B_min = min(B_min, x);
            B_max = max(B_max, x);
        }
        return min(ans, ll(R_max - R_min) * (B_max - B_min));
    }
}
