    color[0] = Red;
    color[pair_pos[2 * N - 1]] = Red;
    color[pair_pos[0]] = Blue;
    color[2 * N - 1] = Blue;
    ll cnt = 2;
    REP(i, 2 * N) {
        if(color[i] == Suspend) {
            color[i] = Red;
            color[pair_pos[i]] = Blue;
            r_max = max(r_max, XY[i].first);
            b_min = min(b_min, XY[pair_pos[i]].first);
            cnt++;
        }
    }
    assert(cnt == N);
    ll ans = (r_max - r_min) * (b_max - b_min);

    // パターン 2
    // 最小の値も最大の値も赤にする場合
    // → 青が取る区間を最小にするのが最善
    if(pair_pos[0] == 2 * N - 1) {
        // 最大と最小が同じ袋
        printf("%lld\n", ans);
        return 0;
    }

    ll l, r;
    auto Init = [&](ll pos1, ll pos2) {
        ll l = min(pair_pos[pos1], pair_pos[pos2]);
        ll r = max(pair_pos[pos1], pair_pos[pos2]);
        r_min = XY[pos1].first;
        r_max = XY[pos2].first;
        b_min = min(XY[pair_pos[pos1]].first, XY[pair_pos[pos2]].first);
        b_max = max(XY[pair_pos[pos1]].first, XY[pair_pos[pos2]].first);
        color.assign(2 * N, Suspend);
        color[pos1] = Red;
        color[pos2] = Red;
        color[pair_pos[pos2]] = Blue;
        color[pair_pos[pos1]] = Blue;
        cnt = 2;
    };

    Init(0, 2 * N - 1);
    // パターン 2-1
    // まず [b_min, b_max] の中でまだ色が決まっていないやつを手当たり次第に取る
    if(cnt < N) {
        // とりあえずなるべく左側のもので充填してみる
        REP(i, 2 * N) {
            if(color[i] == Suspend) {
                color[i] = Blue;
                color[pair_pos[i]] = Red;
                cnt++;
                l = min(l, i);
                r = max(r, i);
                if(cnt == N) { break; }
            }
        }
    }
    assert(cnt == N);
    // 左から見て [l, r] を小さくできそうならそうする
    REP(i, 2 * N) {
        assert(color[i] != Suspend);
        if(color[i] == Blue) {
            l = i;
            if(l < pair_pos[i] && pair_pos[i] < r) { swap(color[i], color[pair_pos[i]]); }
            else { break; }
        }
    }
    // 右から見て [l, r] を小さくできそうならそうする
    for(ll i = 2 * N - 1; i >= 0; --i) {
        assert(color[i] != Suspend);
        if(color[i] == Blue) {
            r = i;
            if(l < pair_pos[i] && pair_pos[i] < r) { swap(color[i], color[pair_pos[i]]); }
            else { break; }
        }
    }

    b_max = XY[r].first;
    b_min = XY[l].first;
    ans = min(ans, (r_max - r_min) * (b_max - b_min));

    // パターン 2-2
    // 一応両端を広げるパターンもやっておく
    Init(0, 2 * N - 1);
    ll base_l = l;
    ll base_r = r;
    // まず [b_min, b_max] の中でまだ色が決まっていないやつを手当たり次第に取る
    for(ll i = base_l + 1; i < base_r; ++i) {
        if(color[i] == Suspend) {
            color[i] = Blue;
            color[pair_pos[i]] = Red;
            cnt++;
        }
        if(cnt == N) { break; }
    }
    // まだ色がついていない場所があるなら、なるべく青の max - min が
    // 大きくならないような範囲を探す
    while(cnt < N) {
        ll next_l = l;
        while(next_l >= 0) {
            if(color[next_l] == Suspend) { break; }
            next_l--;
        }
        ll next_r = r;
        while(next_r < 2 * N) {
            if(color[next_r] == Suspend) { break; }
            next_r++;
        }
        if(next_l >= 0 && next_r < 2 * N) {
            // どちらか近い方をとる
            ll sub_l = abs(XY[base_l].first - XY[next_l].first);
            ll sub_r = abs(XY[base_r].first - XY[next_r].first);
            if(sub_l < sub_r) {
                color[next_l] = Blue;
                color[pair_pos[next_l]] = Red;
                l = next_l;
            }
            else {
                color[next_r] = Blue;
                color[pair_pos[next_r]] = Red;
                r = next_r;
            }
            cnt++;
        }
        else if(next_l >= 0 && next_r >= 2 * N) {
            // l をとる
            color[next_l] = Blue;
            color[pair_pos[next_l]] = Red;
            l = next_l;
            cnt++;
        }
        else if(next_l < 0 && next_r < 2 * N) {
            // r をとる
            color[next_r] = Blue;
            color[pair_pos[next_r]] = Red;
            r = next_r;
            cnt++;
        }
        else {
            assert(false);
        }
    }
    assert(cnt == N);

    b_max = XY[r].first;
    b_min = XY[l].first;
    ans = min(ans, (r_max - r_min) * (b_max - b_min));

    printf("%lld\n", ans);

    return 0;
}

