using namespace std;

#define MAX_N 200005
int N;
LL X[MAX_N], Y[MAX_N];

using pLL = pair<LL, LL>;

int dist[MAX_N];
LL solve(int pos, vector<pLL> v)
{
  if(pos == v.size()){
    LL Lmi = 1145141919, Lma = 0;
    LL Rmi = 1145141919, Rma = 0;
    for (int i = 0; i < v.size(); i++) {
      if(dist[i] == 0){
        Lmi = min(Lmi, v[i].first); Rmi = min(Rmi, v[i].second);
        Lma = max(Lma, v[i].first); Rma = max(Rma, v[i].second);
      }
      else{
        Lmi = min(Lmi, v[i].second); Rmi = min(Rmi, v[i].first);
        Lma = max(Lma, v[i].second); Rma = max(Rma, v[i].first);
      }
    }
    return (Lma - Lmi) * (Rma - Rmi);
  }
  else{
    LL ret = INF_LL_MAX;
    dist[pos] = 0;
    ret = min(ret, solve(pos+1, v));
    dist[pos] = 1;
    ret = min(ret, solve(pos+1, v));
    dist[pos] = 0;
    return ret;
  }
}

