  lvec.push_back(vec[0]);
  lvec.push_back(vec[N-1]);
  LL t = vec[N-1].first;
  for (int i = N-2; 0 <= i; i--) {
    if(t < vec[i].first && t < vec[i].second){
      lvec.push_back(vec[i]);
      break;
    }
  }

  t = vec[0].second;
  for (int i = 1; i < N; i++) {
