  set<P> RB;

  auto top=[](set<P>&S){return *S.begin();};
  auto back=[](set<P> &S){return *(--S.end());};
  auto toptop=[](set<P> &S){return *(++S.begin());};
  auto backback=[](set<P>&S){return *(--(--S.end()));};
  auto calc=[](int a,int b,int c,int d){return (a-b)*(c-d);};

