void init(){
    width = 1;
    while(width<n) width*=2;
    REP(i,2*width-1) dat[i] = INF;
    REP(i,2*width-1) dat2[i] = -INF;
}

void update(int i, int x){
    i += width-1;
    dat[i] = x;
    dat2[i] = x;
    while (i>0){
        i = (i-1)/2;
        dat[i] = min(dat[i*2+1],dat[i*2+2]);
        dat2[i] = max(dat2[i*2+1],dat2[i*2+2]);
    }
}

int query(int a, int b, int k, int l, int r){
    if (r<=a || b<=l) return INF;
    if (a<=l && r<=b) return dat[k];
    int vl = query(a,b,k*2+1,l,(l+r)/2);
    int vr = query(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
}

int query2(int a, int b, int k, int l, int r){
    if (r<=a || b<=l) return -INF;
    if (a<=l && r<=b) return dat2[k];
    int vl = query2(a,b,k*2+1,l,(l+r)/2);
    int vr = query2(a,b,k*2+2,(l+r)/2,r);
    return max(vl,vr);
}

