inline LL calc() {
	static set <int> :: iterator it;
	it = s1.end(); it --;
	LL tmp1 = *(s1.begin());
	LL tmp2 = *(it);
	it = s2.end(); it -- ;
	LL tmp3 = *(s2.begin());
	LL tmp4 = *(it);
