#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef pair<ll, int> P;

const ll INF = 100000000000;

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<ll> x(n), y(n);
	ll rmax = 0, rmin = INF, bmax = 0, bmin = INF;
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> y[i];
		if (x[i] > y[i]) swap(x[i], y[i]);
		rmax = max(rmax, x[i]);
		rmin = min(rmin, x[i]);
		bmax = max(bmax, y[i]);
		bmin = min(bmin, y[i]);
	}

	ll ans = (rmax - rmin) * (bmax - bmin);
	ll vmin = rmin, vmax = bmax;
	rmax = vmax, rmin = vmin, bmax = 0, bmin = INF;
	vector<bool> used(n, false);
	for (int i = 0; i < n; i++) {
		bool flag1 = (x[i] == vmin);
		bool flag2 = (y[i] == vmax);
		if (flag1 && flag2) {
			cout << ans << endl;
			return 0;
		}
		if (flag1) {
			bmin = min(bmin, y[i]);
			bmax = max(bmax, y[i]);
			used[i] = true;
		} else if (flag2) {
			bmax = max(bmax, x[i]);
			bmin = min(bmin, x[i]);
			used[i] = true;
		}
	}

	vector<P> hoge;
	for (int i = 0; i < n; i++) {
		if (used[i]) continue;
		if (bmin <= x[i] || bmax >= y[i]) {
			used[i] = true;
			continue;
		}
		hoge.emplace_back(x[i], i);
	}

	sort(hoge.begin(), hoge.end());
	int m = hoge.size();
	ll d = INF;
	ll v1 = bmax, v2 = bmin;
	for (int i = 0; i < m; i++) {
		ll tmp1 = min(v1, hoge[i].first);
		ll tmp2 = max(v2, hoge.back().first);
		d = min(d, tmp2 - tmp1);
		v1 = min(v1, y[hoge[i].second]);
		v2 = max(v2, y[hoge[i].second]);
	}
	v1 = min(v1, bmin);
	v2 = max(v2, bmax);
	d = min(d, v2 - v1);
	ans = min(ans, (rmax - rmin) * d);
	cout << ans << endl;
	return 0;
}

