  r = min(r,x),R = max(R,x);
  b = min(b,y),B = max(B,y);
  return (R-r)*(B-b);
}

void update(ll &r,ll &R,ll &b,ll &B,ll x,ll y){
  r = min(r,x),R = max(R,x);
  b = min(b,y),B = max(B,y);
}

