int main() {
    cin.sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    ll x[n], y[n];
    ll mn = 1e9, mx = 0;
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
        mn = min({mn, x[i], y[i]});
        mx = max({mx, x[i], y[i]});
    }

    // Rmax = mx, Bmin = mn の時
    ll Bmax = 0, Rmin = 1e9;
    for (int i = 0; i < n; i++) {
        if (x[i] > y[i]) {
            Rmin = min(Rmin, x[i]);
            Bmax = max(Bmax, y[i]);
        } else {
            Rmin = min(Rmin, y[i]);
            Bmax = max(Bmax, x[i]);
        }
    }
    ll ans = (mx - Rmin) * (Bmax - mn);

    // Rmax = mx, Rmin = mn の時
    priority_queue <P, vector<P>, greater<P>> q;
    for (int i = 0; i < n; i++) {
        q.push({min(x[i], y[i]), i});
    }

    while (true) {
        P p = q.top();
        q.pop();

        if (p.first < max(x[p.second], y[p.second])) {
            q.push(P(max(x[p.second], y[p.second]), p.second));
        } else {
            q.push(P(p.first, p.second));
            break;
        }
    }

    ll Bmin = q.top().first;
    while (q.size() > 1) q.pop();
    Bmax = q.top().first;

    ans = min(ans, (mx - mn) * (Bmax - Bmin));

    cout << ans << "\n";
    return 0;
}

