    int b;

    int a_gidx;
    int b_gidx;

    friend ostream& operator<<(ostream& os, const bag& b) {
        os << "{" << b.a << ", " << b.a << ", " << b.a_gidx << ", " << b.b_gidx << "}";
        return os;
