		xy.emplace_back(x, y);
		ma = max(x, ma);
		ma = max(y, ma);
		mi = min(x, mi);
		mi = min(y, mi);
	}
	int res;
	{
		int lmax = 0;
		int lmin = inf;
		int rmax = 0;
		int rmin = inf;
		REP(i, N) {
			lmax = max(lmax, xy[i].first);
			lmin = min(lmin, xy[i].first);
			rmax = max(rmax, xy[i].second);
			rmin = min(rmin, xy[i].second);
		}
		res = (lmax - lmin) *(rmax - rmin);
	}
	{
		int rma = 0;
		int rmi = inf;
		for (auto &a : xy) {
			if (a.first == ma and a.second == mi) {
				cout << res << endl;
				return;
			}
			else if (a.second == ma || a.second == mi){
				swap(a.first, a.second);
			}
			rma = max(rma, a.second);
			rmi = min(rmi, a.second);
		}
		res = min(res, (ma - mi)*(rma - rmi));
	}
	cout << res << endl;
}

