			}
			min1 = std::min(p[i].second, min1);
			max1 = std::max(p[i].first, max1);
		}
	}
	else{
		max1 = p[sit1].first, min1 = p[sit2].second;
		for (int i = 0; i < n; ++ i){
			if (i == sit1 || i == sit2){
				continue;
			}
			min1 = std::min(p[i].second, min1);
			max1 = std::max(p[i].first, max1);
		}
	}
	long long ans = 1ll * (max - min1) * (max1 - min);
	std::sort(p, p + n);
