        while(l < M){
            int loop_n = 0;
            for(int to : G[l]){
                if(to == l){
                    ++loop_n;
                    continue;
                }

                if(to < l){
                    --single_n;
                    ++double_n;
                }else{
                    ++single_n;
                }
            }

            loop_n /= 2;
            double_n += loop_n;

            if(double_n > 0){
                break;
            }

            ++l;
        }
    }

    {
        int single_n = 0, double_n = 0;
        while(r >= 0){
            int loop_n = 0;
            for(int to : G[r]){
                if(to == r){
                    ++loop_n;
                    continue;
                }

                if(r < to){
                    --single_n;
                    ++double_n;
                }else{
                    ++single_n;
                }
            }

            loop_n /= 2;
            double_n += loop_n;

            if(double_n > 0){
                break;
            }

            --r;
        }
    }

    if(l > r){swap(l, r);}

    int hr = upper_bound(G[0].begin(), G[0].end(), r) - G[0].begin() - 1,
        lr = upper_bound(G[M-1].begin(), G[M-1].end(), r) - G[M-1].begin() - 1,
        hl = lower_bound(G[0].begin(), G[0].end(), l) - G[0].begin(),
        lll = lower_bound(G[M-1].begin(), G[M-1].end(), l) - G[M-1].begin();
    hr = hr >= 0 ? G[0][hr] : 252521;
    lr = lr >= 0 ? G[M-1][lr] : 252521;
    hl = hl < G[0].size() ? G[0][hl] : 252521;
    lll = lll < G[M-1].size() ? G[M-1][lll] : 252521;

    int ls[4] = {0, hr, lr, max(hr, lr) < 252521 ? min(hr, lr) : 252521}, rs[4] = {0, hl, lll, max(hl, lll) < 252521 ? max(hl, lll) : 252521};

    ll res = std::numeric_limits<ll>::max() / 2;
    for(int i=1;i<4;++i){
        for(int j=1;j<4;++j){
            int _l = min(l, ls[i]), _r = max(r, rs[j]);
            if(_l == 252521 || _r == 252521 || (i | j) != 3){
                continue;
            }

            int edge_in_lr_n = 0, blue_n = 0;
            for(int k=_l;k<=_r;++k){
                for(int to : G[k]){
                    if(_l <= to && to <= _r){
                        ++edge_in_lr_n;
                    }else{
                        ++blue_n;
                    }
                }               
            }

            edge_in_lr_n /= 2;
            blue_n += edge_in_lr_n;

            int cl = 0, cr = 0;
            if(_l - 1 >= 0){
                cl = _count(_l - 1, _l, _r);
            }
            if(_r + 1 < M){
                cr = _count(_r + 1, _l, _r);
            }

            while(blue_n < N){
                if(cl > cr){
                    blue_n += cl;
                    --_l;
                    if(_l - 1 >= 0){
                        cl = _count(_l - 1, _l, _r);
                    }else{
                        cl = 0;
                    }
                }else{
                    blue_n += cr;
                    ++_r;
                    if(_r + 1 < M){
                        cr = _count(_r + 1, _l, _r);
                    }else{
                        cr = 0;
                    }
                }
            }

            res = min(res, 1ll * (v[M-1] - v[0]) * (v[_r] - v[_l]));
        }
    }

    return res;
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

