		Rmin = min( Rmin, v[i].second );//大きい方をRへ
		Bmax = max( Bmax, v[i].first );//小さい方をBへ
	}
	ans1 = (Rmax-Rmin) * (Bmax-Bmin);

	/*
	Rmax = MAX, Rmin = MIN
	*/
	Rmin = MIN;
	Rmax = MAX;
	Bmin = LINF;
	Bmax = 0;
	LL ans2 = LINF;

	vector< pair<LL,LL> > rui(N);
	for(int i=N-1;i>=0;--i){
