			rui[i].first = min( rui[i+1].first,v[i].first);
			rui[i].second = max( rui[i+1].second, v[i].first );
		}
	}

	LL BminPre = LINF;
	LL BmaxPre = 0;
	for(int i=0;i<=N;++i){//大きい方をBにする個数。
		if( i < N ){
			Bmin = rui[i].first;
			Bmax = rui[i].second;
		}else{
			Bmin = LINF;
