void solve(int test) {
    int n = nxt();
    if (n == 1) {
        cout << "0\n";
        return;
    }
    vector <pii> t(n);
    int mx = INT_MIN;
    int mu = INT_MAX;
    forn(i, n) {
        int x = nxt();
        int y = nxt();
        if (x > y) swap(x, y);
        t[i] = {x, y};
        mx = max(mx, y);
        mu = min(mu, x);
    }

    ll ans = LLONG_MAX;

    {
        int Mx = INT_MIN;
        int My = INT_MAX;
        forn(i, n) {
            Mx = max(Mx, t[i].x);
            My = min(My, t[i].y);
        }
        ans = (Mx - mu) * 1ll * (mx - My);
    }

    cerr << mx << " " << mu << endl;
    {
        multiset<pii> e(all(t));
        auto q = *e.begin();
        e.erase(e.begin());

        int mi = q.y;
        int ma = q.y;

        while (!e.empty()) {
            auto q = *e.begin();
            e.erase(e.begin());

            {
                int nmi = min(mi, q.x);
                int nma = max(ma, q.x);
                if (!e.empty()) {
                    nma = max(nma, e.rbegin()->x);
                }
                ans = min(ans, (mx - mu) * 1ll * (nma - nmi));
            }

            mi = min(mi, q.y);
            ma = max(ma, q.y);
        }
    }

    cerr << ans << endl;

    {
        forn(i, n) t[i].y = -t[i].y;

        multiset<pii> e(all(t));
        auto q = *e.begin();
        e.erase(e.begin());

        int mi = -q.y;
        int ma = -q.y;

        while (!e.empty()) {
            auto q = *e.begin();
            e.erase(e.begin());

            {
                int nmi = min(mi, q.x);
                int nma = max(mu, -q.y);
                if (!e.empty()) {
                    nma = max(nma, e.rbegin()->x);
                }
                ans = min(ans, (nma - mu) * 1ll * (mx - nmi));
            }

            mi = min(mi, -q.y);
            ma = max(ma, -q.y);
        }
    }

    cout << ans << "\n";
}

