	f[0]=1;
	for(int i=1;i<=n;i++){
		for(int j=i;j>=0;j--){
			f[j]=f[j+1];
			if(j){
				(f[j]+=(lint)f[j-1]*C((i-1)*(k-1)+(i-j)+(k-2),k-2)%O*(n-i+1))%=O;
			}
		}
	}
	printf("%lld\n",f[0]);
	return 0;
}

