	while (left != right) {
		long long d = (right - left) / 3;
		long long l = f(left + d);
		long long r = f(right - d);
		if (d == 0) {
			if (l > r)left++;
			else right--;
		}
		else {
			if (l > r)left = left + d;
			else right = right - d;
		}
	}
	printf("%lld\n",f(left));
	return 0;
}

