	while(c < '0' || c > '9') { if(c == '-') k = -1; c = getchar(); }
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x * k;
}

struct node
{
	int x, rec, id;
	friend bool operator <(const node& a, const node& b)
	{ return a.x < b.x; }
}P[maxn];

void Work1(int LL, int RR)
{
	for(int i = N - 1, t = INF, l = LL; i >= RR; i --)
	{
		t = min(t, P[i].rec);
		while(l > t) l --; int k = l;
		if(P[l].id == P[i].id) k = l - 1;
		if(k <= 1) continue;
		ans = min(ans, (P[i].x - P[k].x) * (P[N].x - P[1].x));
	} 
}

void Work2(int LL, int RR)
{
	for(int i = N - 1; i >= RR; i --)
	{
		int t = min(LL, P[i].rec);
		if(t <= 1) continue;
		ans = min(ans, (P[i].x - P[1].x) * (P[N].x - P[t].x));
	}
}

