		else mark[P[i].id] = i;
	}
	LL = 0, RR = N + 1;
	for(int i = 1; i <= N; i ++) if(P[i].rec < i) { LL = i; break; }
	for(int i = N; i >= 1; i --) if(P[i].rec > i) { RR = i; break; } 

	if(P[N].id != P[1].id) Work1(LL, RR);
