    pq.push(another);
    if (st.count(num) == 1) {
      pp.push(max(x[num], y[num]));
    } else {
      st.insert(num);
      counter++;
    }
    while (!pp.empty() && pp.top() == pq.top()) pp.pop(), pq.pop();
    if (counter == n) ans = min(ans, (mx - dt) * (pq.top() - mn));
