    //when min B max R
    int Bmini  = min(in[0].first,maxIn.first), Bmaxi = maxIn.first;
    int Rmaxi = maxIn.second,Rmini = in[0].second;
    for(int i=1;i<n;++i) {
        Bmaxi = max(Bmaxi,in[i].first);
        Rmini = min(Rmini,in[i].second);
    }
    ret = min(ret, (ll)(Bmaxi - Bmini)*(Rmaxi - Rmini));
