ll calc(ll r,ll R,ll b,ll B,ll x,ll y){
  r = min(r,x),R = max(R,x);
  b = min(b,y),B = max(B,y);
  return (R-r)*(B-b);
}

void update(ll &r,ll &R,ll &b,ll &B,ll x,ll y){
  r = min(r,x),R = max(R,x);
  b = min(b,y),B = max(B,y);
}

int n;
ll calc(ll r,ll R,ll b,ll B){
  ll res = (R-r)*(B-b);
  for(int i=0;i<n-1;i++){
    ll x = A[i].first;
    ll y = A[i].second;
    ll p = calc(r,R,b,B,x,y);
    ll q = calc(r,R,b,B,y,x);
    if(p<=q) update(r,R,b,B,x,y);
    else update(r,R,b,B,y,x);
    res = min(p,q);
  }
  return res;
}

