#include <bits/stdc++.h>

using namespace std;

#define fst(t) std::get<0>(t)
#define snd(t) std::get<1>(t)
#define thd(t) std::get<2>(t)
#define unless(p) if(!(p))
#define until(p) while(!(p))

using ll = long long;
using P = std::tuple<int,int>;

const int dx[8] = {-1, 1, 0, 0, -1, -1, 1, 1}, dy[8] = {0, 0, -1, 1, -1, 1, -1, 1};

int N;
vector<tuple<int, int, int> > v;
int xs[200100], ys[200100];
bool used[400100];

// R .. R B .. B pattern
ll compute1(){
    int mx = 0; // [0, mx]には組をなす2整数がないような最大の添字
    while(mx < 2 * N && mx < thd(v[mx])){
        ++mx;
    }
    --mx;

    int mx_blue = -1;
    for(int i=2*N-1;i>mx;--i){
        if(i < thd(v[i]) && mx_blue == -1){
            mx_blue = fst(v[i]);
        }
    }

    ll res = 1001001001001001001ll;
    // b..b (i+1 個) .. の場合
    for(int i=mx;i>=0;--i){
        int b_diff = max(mx_blue != -1 ? mx_blue : fst(v[i]), i < mx ? fst(v[thd(v[i+1])]) : fst(v[i])) - fst(v[0]),
            r_diff = fst(v[2*N-1]) - fst(v[i+1]);
        res = min(res, 1ll * b_diff * r_diff);

        if(i < mx && mx_blue == -1){
            mx_blue = fst(v[i+1]);
        }
    }

    return res;
}

// R .. B .. B .. R pattern
ll compute2(){
    int l = min(thd(v[0]), thd(v[2*N-1])), r = max(thd(v[0]), thd(v[2*N-1]));

    int blue_n = 2;
    used[thd(v[l])] = true;
    used[thd(v[r])] = true;
    {
        for(int i=l+1;i<r;++i){
            if(!used[i]){
                ++blue_n;
                used[thd(v[i])] = true;
            }
        }
    }

    int _l = l - 1, _r = r + 1;
    while(blue_n < N){
        while(_l >= 0 && used[_l]){--_l;}
        while(_r < 2 * N && used[_r]){++_r;}

        int diff_l = _l >= 0 ? fst(v[l]) - fst(v[_l]) : 1001001001,
            diff_r = r < 2 * N ? fst(v[_r]) - fst(v[r]) : 1001001001;

        if(diff_l < diff_r){
            used[thd(v[_l])] = true;
            l = _l;
        }else{
            used[thd(v[_r])] = true;
            r = _r;
        }

        ++blue_n;
    }

    return 1ll * (fst(v[2*N-1]) - fst(v[0])) * (fst(v[r]) - fst(v[l]));
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N;

    for(int i=0;i<N;++i){
        std::cin >> xs[i] >> ys[i];

        v.emplace_back(xs[i], ys[i], i);
        v.emplace_back(ys[i], xs[i], i);
    }

    sort(v.begin(), v.end());

    for(int i=0;i<2*N;++i){
        int a, b, index;
        tie(a, b, index) = v[i];

        thd(v[i]) = lower_bound(v.begin(), v.end(), std::make_tuple(b, a, index)) - v.begin();
    }

    ll res = compute1();
    if(snd(v[0]) != 2 * N - 1){
        res = min(res, compute2());
    }
    std::cout << res << std::endl;
}

