ll x[MAX], y[MAX];
int main()
{
	int N;
	std::cin >> N;
	ll m =INF, M = 0;
	for (int i = 0; i < N; i++) { 
		std::cin >> x[i] >> y[i];
		m = std::min({ m, x[i] ,y[i] }), M = std::max({M, x[i],y[i]});
	}
	ll rmin = INF, bmin = INF, rmax = 0, bmax = 0;
	for (int i = 0; i < N; i++) {
		rmin = std::min(rmin, std::min(x[i], y[i]));
		bmin = std::min(bmin, std::max(x[i], y[i]));
		rmax = std::max(rmax, std::min(x[i], y[i]));
		bmax = std::max(bmax, std::max(x[i], y[i]));
	}
	ll ans = (rmax - rmin)*(bmax - bmin);
	using P = std::pair<ll, int>;
	std::set<P> st;
	for (int i = 0; i < N; i++) {
		const ll min = std::min(x[i], y[i]);
		if (min == m) {
			st.insert({std::max(x[i], y[i]), i});
		}	else {
			st.insert({ min,i });
		}
	}
	for (int i = 0; i < N; i++) {
		const ll min = st.cbegin()->first;
		const ll max = st.crbegin()->first;
		ans = std::min(ans, (max - min)*(M - m));
		const int mind = st.cbegin()->second;
		if (min == std::min(x[mind], y[mind])) { break; }
		st.erase(st.begin());
		st.insert({ std::max(x[mind],y[mind]), mind });
	}
	std::cout << ans << std::endl;
}

