const int MAX_N = 200050;
const long long MAX_L = (long long)1000000009;
int N;
long long x[MAX_N], y[MAX_N];

bool can(long long Rmax, long long Rmin, long long Bmax, long long Bmin) {
    for (int i = 1; i <= N; i++) {
        if ((Rmin <= x[i] && x[i] <= Rmax && Bmin <= y[i] && y[i] <= Bmax) ||
            (Rmin <= y[i] && y[i] <= Rmax && Bmin <= x[i] && x[i] <= Bmax)
        ) {
            continue;
        } else {
            return false;
        }
    }
    return true;
}

int main(int argc, char **argv) {
    std::cin >> N;

    for (int i = 1; i <= N; i++) {
        std::cin >> x[i] >> y[i];
    }

    long long all_max = 0;
    long long all_min = MAX_L;

    std::vector<long long> all;

    for (int i = 1; i <= N; i++) {
        all_max = std::max(all_max, std::max(x[i], y[i]));
        all_min = std::min(all_min, std::min(x[i], y[i]));
        all.push_back(x[i]);
        all.push_back(y[i]);
    }

    std::sort(all.begin(), all.end());

    long long ret = MAX_L * MAX_L;
    for (int i = 1; i < all.size(); i++) {
        if (can(all_max, all_min, all[i], all[i])) {
            ret = 0;
        } else if (can(all_max, all_min, all[all.size() - 1], all[i])) {
            int lb = i;
            int ub = all.size() - 1;
            while (lb + 1 < ub) {
                int mid = (lb + ub) / 2;
                if (can(all_max, all_min, all[mid], all[i])) {
                    ub = mid;
                } else {
                    lb = mid;
                }
            }
            ret = std::min(ret, (all_max - all_min) * (all[ub] - all[i]));
        }
    }

    for (int i = 1; i < all.size(); i++) {
        if (can(all_max, all[0], all[i], all_min)) {
            if (can(all_max, all_max, all[i], all_min)) {
                ret = 0;
            } else {
                int lb = 0;
                int ub = all.size() - 1;
                while (lb + 1 < ub) {
                    int mid = (lb + ub) / 2;
                    if (can(all_max, all[mid], all[i], all_min)) {
                        lb = mid;
                    } else {
                        ub = mid;
                    }
                }
                ret = std::min(ret, (all_max - all[lb]) * (all[i] - all_min));
            }
        }
    }
    std::cout << ret << std::endl;

    return 0;
}

