LLI query(int wishl, int wishr, int k, int watchl, int watchr) {
  int mid;
  LLI lval, rval;

  if (wishr <= watchl || watchr <= wishl) return INF;
  if (wishl <= watchl && watchr <= wishr) return seg[k];

