  if (wishr <= watchl || watchr <= wishl) return -INF;
  if (wishl <= watchl && watchr <= wishr) return seg2[k];

  mid = (watchl+watchr)/2;
  lval = query2(wishl, wishr, k*2+1, watchl, mid);
  rval = query2(wishl, wishr, k*2+2, mid, watchr);
  return max(lval, rval);
}

