int64 solve1() {
    int64 hi1, low1, hi2, low2;

    hi1 = low1 = max(X[0], Y[0]);
    hi2 = low2 = min(X[0], Y[0]);
    for (int j = 1; j < N; ++j) {
        hi1 = max(hi1, max(X[j], Y[j]));
        low1 = min(low1, max(X[j], Y[j]));

        hi2 = max(hi2, min(X[j], Y[j]));
        low2 = min(low2, min(X[j], Y[j]));
