    if (low1 == hi2) {
        int v = low1;
        bool zero = true;
        for (int j = 0; j < N; ++j) {
            if (v != X[j] && v != Y[j]) {
                zero = false;
                break;
            }
        }
        if (zero) {
            return 0;
        }
    }

    return (hi1 - low1) * (hi2 - low2);
}

int64 solve2() {
    int64 lowest, highest;
    int64 lv, hv;
    lv = highest = max(X[0], Y[0]);
    hv = lowest = min(X[0], Y[0]);
