	//----------------------------パターン１：最大と最小それぞれを赤と青でカバーする---------------------------
	long long r1 = (1LL << 30), r2 = -(1LL << 30), r3 = (1LL << 30), r4 = -(1LL << 30);
	for (int i = 0; i < n; i++) {
