/*
 <url:https://arc073.contest.atcoder.jp/tasks/arc073_c>
 問題文============================================================
 2 個の白いボールが入った袋が N 個あります。
 i 個目の袋にはそれぞれ整数 xi と yi が書かれたボールが 1 個ずつ入っています。

 あなたはこの袋それぞれについて、片方のボールを赤く塗り、もう片方を青く塗ります。

 そのあと 2N 個のボールを、塗られた色で分類します。

 そして

 赤く塗られたボールに書かれた整数の最大値を Rmax
 赤く塗られたボールに書かれた整数の最小値を Rmin
 青く塗られたボールに書かれた整数の最大値を Bmax
 青く塗られたボールに書かれた整数の最小値を Bmin

 としたときに、(Rmax−Rmin)×(Bmax−Bmin) の最小値を求めてください。

 =================================================================
 解説=============================================================
 ================================================================
 */

ll solve(){
    ll res = LLONG_MAX;
    ll N; cin >> N;
    vector<ll> x(N),y(N);
    for(int i = 0; i < N;i++) cin >> x[i] >> y[i];

    srand((unsigned int)time(NULL));
    for(int _ = 0; _ < 100; _++){
        pll l = {x[0],x[0]}, r = {y[0],y[0]};
        for(int i = 1; i < N;i++){
            pll tl[2];
            pll tr[2];
            ll val[2];
            for(int j = 0; j < 2;j++){
                tl[j] = {min(l.first,x[i]),max(l.second,x[i])};
                tr[j] = {min(r.first,y[i]),max(r.second,y[i])};
                val[j] = (tl[j].second-tl[j].first)*(tr[j].second-tr[j].first);
                swap(x[i],y[i]);
            }

            if(val[0] < val[1]){
                l = tl[0]; r = tr[0];
            }else if(val[0] > val[1]){
                l = tl[1]; r = tr[1];
            }else{
                int k = rand()%2;
                l = tl[k]; r = tr[k];
            }
        }
        res = (l.second-l.first)*(r.second-r.first);
    }
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    cout << solve() << endl;
    return 0;
}

