signed main() {
	read(n);
	for (int i = 1; i <= n; ++i) {
		read(x[i], y[i]);
		if (x[i] > y[i]) swap(x[i], y[i]);
		a[i] = make_pair(x[i], y[i]);
	}

	long long ans = inf;
	int minx = inf, maxx = 0, miny = inf, maxy = 0;

	for (int i = 1; i <= n; ++i) {
		chkmin(minx, x[i]);
		chkmax(maxx, x[i]);
		chkmin(miny, y[i]);
		chkmax(maxy, y[i]);
	}

	chkmin(ans, 1ll * (maxx - minx) * (maxy - miny));

	sort(a + 1, a + n + 1);
	long long D = maxy - minx;

	minx = inf;
	for (int i = 1; i <= n; ++i) {
		chkmax(maxx, a[i].se);
		chkmin(minx, a[i].se);
		if (a[i + 1].fi >= minx) {
			chkmin(ans, D * (maxx - minx));
			break;
		}
		chkmin(ans, D * (maxx - a[i + 1].fi));
	}

	printf("%lld\n", ans);
	return 0;
}

