    {
        if (y == ot.y)
            return x < ot.x;
        return y < ot.y;
    }
} v[maxN];
/* ------------------------------------------------------- */
int vmin, vmax, rmin, rmax, bmin, bmax, minMax, Min[maxN];
/* ------------------------------------------------------- */
long long ans;
/* ------------------------------------------------------- */
void RmaxBminCase()
{
    rmax = rmin = vmax;
    bmin = bmax = vmin;
    for (int i = 1; i <= n; ++ i)
    {
        rmin = min(rmin, v[i].y);
        bmax = max(bmax, v[i].x);
    }
    ans = (long long)(rmax - rmin) * (bmax - bmin);
}
void RmaxRminCase()
{
    bmin = rmax = vmax;
    rmin = vmin;
    int i = 1;
    Min[n] = v[n].x;
    for (int i = n - 1; i >= 1; -- i)
        Min[i] = min(Min[i + 1], v[i].x);
    for (bmax = minMax; bmax <= rmax; ++ bmax)
    {
        while (v[i].y <= bmax && i <= n)
        {
            bmin = min(bmin, v[i].y);
            ++ i;
        }

        if (i <= n)
            bmin = min(bmin, Min[i]);
        ans = min(ans, (long long)(rmax - rmin) * (bmax - bmin));
    }
}
