    int N;
    while (cin >> N) {
        LL minn = inf, maxx = 0;
        vector<PLL> A;
        FOR(i,0,N) {
            LL x,y; cin >> x >> y;
            if (x > y)
                swap(x,y);
            A.push_back(PLL(x,y));
            minn = min(minn,x);
            maxx = max(maxx,y);
        }
        sort(ALL(A));
        LL ans = inf;
        {
            const LL rmin = minn, bmax = maxx;
            LL rmax = rmin, bmin = bmax;
