                const LL x = A[i].first;
                const LL y = A[i].second;
                rmax = max(rmax,x);
                bmin = min(bmin,y);
            }
            const LL res = (rmax-rmin) * (bmax-bmin);
            ans = min(ans,res);
        }
        {
            LL rmin = maxx, rmax = minn;
            LL bmin = maxx, bmax = minn;
            VI vis(N);
            FOR(i,0,N) {
                const LL x = A[i].first;
