                    rmin = minn;
                    bmin = min(bmin,y);
                    bmax = max(bmax,y);
                }
                else if (y == maxx) {
                    vis[i]++;
                    rmax = maxx;
                    bmin = min(bmin,x);
                    bmax = max(bmax,x);
