ll mainmain(int n, vector<pll> v){
	sort(ALL(v));
	if(n==1){
		return 0;
	}
	ll mn = INFL, mx = 0;
	int pmn = -1, pmx = -1;
	rep(i,n){
		if(mn > v[i].fi){
			mn = v[i].fi;
			pmn = i;
		}
		if(mx < v[i].se){
			mx = v[i].se;
			pmx = i;
		}
	}
	// cout<<mx<<" "<<pmx<<endl;
	// cout<<mn<<" "<<pmn<<endl;
	ll a = 0;
	ll b = INFL;
	if(pmn==pmx){
		v.erase(v.begin()+pmn);
	}
	else{
		a = v[pmx].fi;
		b = v[pmn].se;
		v.erase(v.begin()+max(pmn,pmx));
		v.erase(v.begin()+min(pmn,pmx));
	}
	sort(ALL(v));
	// cout<<v.size()<<endl;
	// ll aa = max(a,b), bb = min(a,b);
	ll aa = a, bb = b;
	a = aa;
	b = bb;
	// cout<<"ab "<<a<<" "<<b<<endl;
	rep(i,v.size()){
		maxs(a, v[i].fi);
		mins(b, v[i].se);
	}
	// cout<<"ab "<<a<<" "<<b<<endl;
	ll ans = (a-mn)*(mx-b);
	// cout<<"ans "<<ans<<endl;
	if(pmn == pmx || v.size()==0){
		return ans;
	}
	// cout<<a<<" "<<b<<endl;
	// aa = max(a,b), bb = min(a,b);

	a = max(aa,bb);
	b = min(aa,bb);
	// cout<<"ab "<<a<<" "<<b<<endl;
	vll wfi(v.size());
	ll tmx = 0;
	for(int i=wfi.size()-1; i>=0; i--){
		maxs(tmx, v[i].fi);
		wfi[i] = tmx;
	}
	rep(i,v.size()){
		ll l = min(b, v[i].fi);
		ll r = max(a, wfi[i]);
		// cout<<"r l "<<r<<" "<<l<<endl;
		mins(ans, (mx-mn)*(r-l));
		mins(b, v[i].se);
		maxs(a, v[i].se);
	}
	a = max(aa,bb);
	b = min(aa,bb);
	vll wse(v.size());
	rep(i,n) swap(v[i].fi, v[i].se);
	sort(ALL(v));
	rep(i,n) swap(v[i].fi, v[i].se);
	ll tmn = INFL;
	rep(i,wfi.size()){
		mins(tmn, v[i].se);
		wse[i] = tmn;
	}
	for(int i=wfi.size()-1; i>=0; i--){
		ll l = min(b, wse[i]);
		ll r = max(a, v[i].se);
		// cout<<"r l "<<r<<" "<<l<<endl;
		// cout<<"v[i] "<<v[i].fi<<" "<<v[i].se<<endl;
		mins(ans, (mx-mn)*(r-l));
		mins(b, v[i].fi);
		maxs(a, v[i].fi);
	}
	return ans;
}

ll solve(int n, vector<pll> v){
	ll ans = INFL;
	rep(i,1<<n){
		ll rmx = 0, rmn = INFL;
		ll bmx = 0, bmn = INFL;
		rep(j,n){
			ll a = v[j].fi, b = v[j].se;
			if(i&(1<<j)){
				swap(a,b);
			}
			maxs(rmx, a);
			mins(rmn, a);
			maxs(bmx, b);
			mins(bmn, b);
		}
		mins(ans, (rmx-rmn)*(bmx-bmn));
	}
	return ans;
}

