ll div_minmax(const V<t2> &val_idx_list, ll n)
{
    ll minval = get<0>(val_idx_list[0]);
    ll minidx = get<1>(val_idx_list[0]);

    bool checked[n];
    memset(checked, 0, sizeof(checked));
    ll count = 0LL;
    ll min_pair = minval;

    checked[minidx] = true;
    count++;
    rep (i, 2LL * n) {
        ll val = get<0>(val_idx_list[i]);
        ll idx = get<1>(val_idx_list[i]);

        debug_printf("x1 val=%lld idx=%lld\n", val, idx);
        if (checked[idx]) continue;
        debug_printf("x1 pass val=%lld idx=%lld\n", val, idx);

        checked[idx] = true;
        count++;
        min_pair = val;
        if (count >= n) break;
    }

    ll maxval = get<0>(val_idx_list[2 * n - 1]);
    ll maxidx = get<1>(val_idx_list[2 * n - 1]);

    memset(checked, 0, sizeof(checked));
    count = 0LL;
    ll max_pair = maxval;

    checked[maxidx] = true;
    count++;
    rrep (i, 2LL * n) {
        ll val = get<0>(val_idx_list[i]);
        ll idx = get<1>(val_idx_list[i]);

        debug_printf("x2 val=%lld idx=%lld\n", val, idx);
        if (checked[idx]) continue;
        debug_printf("x2 pass val=%lld idx=%lld\n", val, idx);

        checked[idx] = true;
        count++;
        max_pair = val;
        if (count >= n) break;
    }

    return (min_pair - minval) * (maxval - max_pair);
}

ll same_minmax(const V<t2> &val_idx_list, ll n)
{
    ll minval = get<0>(val_idx_list[0]);
    ll minidx = get<1>(val_idx_list[0]);
    ll maxval = get<0>(val_idx_list[2 * n - 1]);
    ll maxidx = get<1>(val_idx_list[2 * n - 1]);
    if (minidx == maxidx) return 2LL * ((ll)pow(10LL, 18LL));

    ll leftval = get<0>(val_idx_list[1]);
    ll leftidx = get<1>(val_idx_list[1]);
    ll rightval = 0LL;
    ll rightidx = -1LL;
    ll right_listidx = -1LL;

    int checkcount[n];
    memset(checkcount, 0, sizeof(checkcount));
    ll count = 0LL;

    srep (i, 1, n * 2LL - 1LL) {
        ll val = get<0>(val_idx_list[i]);
        ll idx = get<1>(val_idx_list[i]);

        if (checkcount[idx] == 0) count++;
        checkcount[idx]++;
        rightval = val;
        rightidx = idx;
        right_listidx = i;

        if (count >= n) break;
    }

    ll ret = (maxval - minval) * (rightval - leftval);

    srep (i, 1LL, n * 2LL - 2LL) {
        ll rem_val = get<0>(val_idx_list[i]);
        ll rem_idx = get<1>(val_idx_list[i]);

        checkcount[rem_idx]--;

        if (checkcount[rem_idx] <= 0) {
            count--;
            srep (j, right_listidx+1LL, n * 2LL - 1LL) {
                ll add_val = get<0>(val_idx_list[j]);
                ll add_idx = get<1>(val_idx_list[j]);
                rightval = add_val;
                rightidx = add_idx;
                right_listidx = j;
                if (checkcount[add_idx] == 0) count++;
                checkcount[add_idx]++;
                if (count >= n) break;
            }
            if (count < n) return ret;
        }

        leftval = get<0>(val_idx_list[i+1]);
        leftidx = get<1>(val_idx_list[i+1]);

        ret = min(ret, (maxval - minval) * (rightval - leftval));
    }

    return ret;
}


