	int l1=A[pmin].xx,r1=A[pmax].xx,l2=A[pmin].yy,r2=A[pmax].yy;
	rep(i,1,n) if(i!=pmin&&i!=pmax) {
		r1=max(r1,A[i].xx);
		l2=min(l2,A[i].yy);
	}
	return (ll)(r1-l1)*(r2-l2);
}
