void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    S V<t2> xylist; llinl2(xylist, n);

    if (n == 1) {
        cout << 0 << endl;
        return;
    }

    S V<t2> xyslist;
    for (auto xy : xylist) {
        ll x = get<0>(xy);
        ll y = get<1>(xy);
        xyslist.pb(t2(min(x, y), max(x, y)));
    }
    sort(xyslist);

    S V<ll> floor_list;
    S V<ll> ceil_list;
    for (auto xy : xyslist) {
        ll x = get<0>(xy);
        ll y = get<1>(xy);
        floor_list.pb(x);
        ceil_list.pb(y);
    }
    sort(floor_list);
    sort(ceil_list);
    ll ans1 = (floor_list[n-1] - floor_list[0]) * (ceil_list[n-1] - ceil_list[0]);

    ll all_max = -1e18;
    ll all_min = 1e18;
    for (auto xy : xyslist) {
        ll x = get<0>(xy);
        ll y = get<1>(xy);
        all_max = max(all_max, y);
        all_min = min(all_min, x);
    }

    ll x_min = get<0>(xyslist[0]);
    ll x_max = get<0>(xyslist[n-1]);
    ll y_min = 1e18;
    ll y_max = -1e18;
    ll range_min = x_max - x_min;

    xyslist.pb(t2(1e18, 1e18));

    rep (i, n) {
        ll x = get<0>(xyslist[i]);
        ll y = get<1>(xyslist[i]);
        ll nx = get<0>(xyslist[i+1]);
        ll ny = get<1>(xyslist[i+1]);
        x_min = nx;
        y_min = min(y_min, y);
        y_max = max(y_max, y);
        ll minval = min(x_min, y_min);
        ll maxval = max(x_max, y_max);
        range_min = min(range_min, maxval - minval);
    }

    ll ans2 = (all_max - all_min) * range_min;

    cout << min(ans1, ans2) << endl;
}

