using namespace std;

int n, totalMax=-1, totalMin=1e9+7;
struct pii{
	int x, y;
	pii(){x=y=0;}
	pii(int x, int y){
		this->x=x;
		this->y=y;
	}
};
pii d[200001];

long long type1(){
	int bmax=-1, rmin=1e9+7;
	for(int i=1; i<=n; i++){
		bmax=max(bmax, d[i].x);
		rmin=min(rmin, d[i].y);
	}
	return (totalMax-rmin)*1ll*(bmax-totalMin);
}

vector<pii> v;
vector<pii> pp;
bool comp(pii a, pii b){
	if(a.x==b.x) return a.y<b.y;
	else return a.x<b.x;
}
vector<pii> stg;
long long type2(){
	for(int i=1; i<=n; i++)
		v.push_back(pii(d[i].x, d[i].y));
	int bmax=-1, bmin=1e9+7;
	for(auto elem : v){
        bmin=min(bmin, elem.y);
        bmax=max(bmax, elem.x);
	}
	for(auto elem : v){
        if(elem.x < bmin && bmax < elem.y)
			pp.push_back(elem);
	}
	if(pp.empty()){
		if(bmax<bmin) swap(bmax, bmin);
		return (totalMax-totalMin)*1ll*(bmax-bmin);
	}

	int mindiff=1e9+7;
	sort(pp.begin(), pp.end(), comp);
	for(auto elem : pp){
        if(stg.empty())
			stg.push_back(elem);
		else if(stg.back().x == elem.x){
			stg.back().y=elem.y;
		}
		else{
			if(elem.y <= stg.back().y) continue;
			stg.push_back(elem);
		}
	}
	for(auto elem : stg)
		mindiff=min(mindiff, elem.y-elem.x);
	for(unsigned int i=1; i<stg.size(); i++)
		mindiff=min(mindiff, stg[i-1].y-stg[i].x);
	return (totalMax-totalMin)*1ll*mindiff;
}

int main(){
	scanf("%d", &n);
	for(int i=1; i<=n; i++){
		scanf("%d %d", &d[i].x, &d[i].y);
		if(d[i].x > d[i].y) swap(d[i].x, d[i].y);
		totalMin=min(totalMin, d[i].x);
		totalMax=max(totalMax, d[i].y);
	}
	long long t1res = type1();
	long long t2res = type2();
	printf("%lld", min(t1res, t2res));
	return 0;
}

