const int INF = 1 << 30;

int main() {
  int n;
  scanf("%d", &n);
  vector<ii> a(n);
  int minv = INF, maxv = -INF;
  for (int i = 0; i < n; ++i) {
    scanf("%d%d", &a[i].first, &a[i].second);
    if (a[i].first > a[i].second) swap(a[i].first, a[i].second);
    minv = min(minv, a[i].first);
    maxv = max(maxv, a[i].second);
  }
  int L = -INF, R = INF;
  for (int i = 0; i < n; ++i) {
    L = max(L, a[i].first);
    R = min(R, a[i].second);
  }
  int64 ret = (int64)(L - minv) * (maxv - R);
  sort(a.begin(), a.end(), [](const ii& a, const ii& b) {
      return a.first < b.first;
    });
  int u = a[0].second, v = a[0].second;
  for (int i = 0; i < n; ++i) {
    u = min(u, a[i].second);
    v = max(v, a[i].second);
    if (i < n - 1) {
      L = min(u, a[i + 1].first);
      R = max(v, a[n - 1].first);
      ret = min(ret, (int64)(maxv - minv) * (R - L));
    } else {
      ret = min(ret, (int64)(maxv - minv) * (v - u));
    }
  }
  printf("%lld\n", ret);
  return 0;
}

#include <cstdio>
#include <algorithm>

#define INF 1000000000

#define MAXN 200000

int ind[MAXN+1];
int x[MAXN+1], y[MAXN+1];

bool cmp(const int &a, const int &b){
    return y[a]-x[a]>y[b]-x[b];
}

inline long long cost(int n){
    int a=0, b=0, c=INF, d=INF;
    for(int i=0; i<n; i++){
        a=std::max(a, x[i]);
        b=std::max(b, y[i]);
        c=std::min(c, x[i]);
        d=std::min(d, y[i]);
    }
    return 1LL*(c-a)*(d-b);
}

int main(){
    int n;
    scanf("%d", &n);

    for(int i=0; i<n; i++){
        scanf("%d%d", &x[i], &y[i]);
        ind[i]=i;
        if(x[i]>y[i]) std::swap(x[i], y[i]);
    }

    std::sort(ind, ind+n, cmp);

    long long ans=cost(n);
    for(int i=0; i<n; i++){
        std::swap(x[ind[i]], y[ind[i]]);
        ans=std::min(ans, cost(n));
    }

    printf("%lld\n", ans);

    return 0;
}

