int mark[maxn];

int read()
{
	int x = 0, k = 1;
	char c; c = getchar();
	while(c < '0' || c > '9') { if(c == '-') k = -1; c = getchar(); }
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x * k;
}

struct node
{
	int x, rec, id;
	friend bool operator <(const node& a, const node& b)
	{ return a.x < b.x; }
}P[maxn];

void Work1(int LL, int RR)
{
	for(int i = N - 1, t = INF, l = LL; i >= RR; i --)
	{
		t = min(t, P[i].rec);
		while(l > t) l --; int k = l;
		if(P[l].id == P[i].id) k = l - 1;
		if(k <= 1) continue;
		ans = min(ans, (P[i].x - P[k].x) * (P[N].x - P[1].x));
	} 
}

void Work2(int LL, int RR)
{
	if(P[LL].id == P[N].id) LL --;
	if(P[RR].id == P[1].id) RR ++;
	if(LL <= 1 || RR >= N) return;
	ans = min(ans, (P[N].x - P[LL].x) * (P[RR].x - P[1].x));
}

signed main()
{
	n = read(); N = 2 * n;
	for(int i = 1; i <= n; i ++)
	{
		P[++ tot].x = read(), P[tot].id = i;
		P[++ tot].x = read(), P[tot].id = i; 
	}
	sort(P + 1, P + 1 + tot);

	for(int i = 1; i <= N; i ++)
	{
		if(mark[P[i].id]) P[i].rec = mark[P[i].id], P[P[i].rec].rec = i;
		else mark[P[i].id] = i;
	}
	LL = 0, RR = N + 1;
	for(int i = 1; i <= N; i ++) if(P[i].rec < i) { LL = i; break; }
	for(int i = N; i >= 1; i --) if(P[i].rec > i) { RR = i; break; } 

	if(P[N].id != P[1].id) Work1(LL, RR);
	Work2(LL, RR);
	if(LL - 1 >= n && RR + 1 <= n + 1) ans = min(ans, (P[n].x - P[1].x) * (P[N].x - P[n + 1].x));
	printf("%lld\n", ans);
	return 0;
}

