		if (p[i].a > p[i].b) std::swap(p[i].a, p[i].b);
	}
	std::sort(p + 1, p + 1 + n);
	for (int i = 1; i <= n; ++i) {
		if (i != 1) min = std::max(min, std::min(p[i].a, p[i].b));
		if (i != n) max = std::min(max, std::max(p[i].a, p[i].b));
	}
	ans = (min - std::min(p[1].a, p[1].b)) * 1LL * (std::max(p[n].a, p[n].b) - max);


	printf("%lld\n", ans);
	return 0;
}

