using PAIR = std::pair<int, int>;
using PAIRLL = std::pair<ll, ll>;
constexpr int INFINT = 1 << 30;                          // 1.07x10^ 9
constexpr int INFINT_LIM = (1LL << 31) - 1;              // 2.15x10^ 9
constexpr ll INFLL = 1LL << 60;                          // 1.15x10^18
constexpr ll INFLL_LIM = (1LL << 62) - 1 + (1LL << 62);  // 9.22x10^18
constexpr double EPS = 1e-7;
constexpr int MOD = 1000000007;
constexpr double PI = 3.141592653589793238462643383279;

signed main() {
	INIT;
	VAR(int, n);
	VEC_ROW(int, n, x, y);
	std::vector<PAIR> v(n);
	REP(i, n) {
		if (x[i] > y[i]) std::swap(x[i], y[i]);
		v[i] = PAIR(x[i], y[i]);
	}
	std::sort(ALL(v));
	int xmin = v[0].first;
	int ymax = 0, ymin = INFINT;
	REP(i, n) {
		CHMAX(ymax, v[i].second);
		CHMIN(ymin, v[i].second);
	}
	int ans = (v[n - 1].first - xmin) * (ymax - ymin);
	int xmax = ymax;
	int ma = xmax;
	std::priority_queue<PAIR> pq;
	REP(i, n) {
		pq.push(PAIR(y[i], i));
	}
	while (true) {
		PAIR now = pq.top(); pq.pop();
		int i = now.second;
		if (x[i] < y[i]) {
			std::swap(x[i], y[i]);
			pq.push(PAIR(y[i], i));
		}
		else {
			break;
		}
	}
	ymax = 0; ymin = INFINT;
	REP(i, n) {
		CHMAX(ymax, y[i]);
		CHMIN(ymin, y[i]);
	}
	CHMIN(ans, (xmax - xmin) * (ymax - ymin));
	OUT(ans)BR;
	return 0;
}

