ll cut(ll x) { return x & 1 ? x - 1 : x; }
ll put(ll x) { return x & 1 ? x - 1 : x + 1; }

ll N, res;
signed main() {
    cin >> N;
    ll A[2 * N];
    rep(i, 2 * N) cin >> A[i];

    ll MI = max_element(A, A + 2 * N) - A, mi = min_element(A, A + 2 * N) - A;

    if (cut(MI) != cut(mi)) {
        ll MAX1 = A[MI], MAX2 = A[put(MI)], MIN1 = A[put(mi)], MIN2 = A[mi];
        rep(i, N) {
            if (i == mi / 2 || i == MI / 2) continue;
            MAX2 = max(MAX2, min(A[2 * i], A[2 * i + 1]));
            MIN1 = min(MIN1, max(A[2 * i], A[2 * i + 1]));
        }
        res = (MAX1 - MIN1) * (MAX2 - MIN2);

        ll M, m;
        vector<pair<ll, ll>> B;
        rep(i, N) {
            if (i == mi / 2 || i == MI / 2) continue;
            B.pb({min(A[2 * i], A[2 * i + 1]), max(A[2 * i], A[2 * i + 1])});
        }
        sort(all(B));
        ll MAX = max(A[put(MI)], A[put(mi)]), MIN = min(A[put(MI)], A[put(mi)]);
        M = max(MAX, B.back().fi), m = min(MIN, B.front().fi);
        rep(i, N - 2) {
            M = max(MAX, B[i].se);
            if (i == N - 3) {
                m = B[0].se;
                rep(i, N - 2) m = min(m, min(MIN, B[i].se));
            } else {
                m = min(MIN, B[i + 1].se);
            }
            res = min(res, (MI - mi) * (M - m));
        }
    } else {
        ll M, m;
        vector<pair<ll, ll>> B;
        rep(i, N) {
            if (i == mi / 2 || i == MI / 2) continue;
            B.pb({min(A[2 * i], A[2 * i + 1]), max(A[2 * i], A[2 * i + 1])});
        }
        sort(all(B));
        M = max(A[put(MI)], B.back().fi), m = min(A[put(mi)], B.front().fi);
        rep(i, N - 1) {
            M = max(A[put(MI)], B[i].se);
            if (i == N - 2) {
                m = B[0].se;
                rep(i, N - 1) m = min(m, min(A[put(mi)], B[i].se));
            } else {
                m = min(A[put(mi)], B[i + 1].se);
            }
            res = min(res, (MI - mi) * (M - m));
        }
    }

    cout << res << endl;
}

