#include "bits/stdc++.h"
using namespace std;
typedef long long ll;
#define int ll
typedef pair<int,int> pii;
#define rep(i,n) for(ll i=0;i<(ll)(n);i++)
#define all(a) (a).begin(),(a).end()
#define pb emplace_back
#define INF (1LL<<60)

signed main(){
    int n;
    cin>>n;

    vector<int> x(n), y(n);
    rep(i,n)cin>>x[i]>>y[i];

    rep(i,n){
        if(x[i]>y[i]){
            swap(x[i],y[i]);
        }
    }

    int maxi = max( *max_element( all(x) ), *max_element( all(y) ) );
    int mini = min( *min_element( all(x) ), *min_element( all(y) ) );

    set<int> minset, maxset;
    rep(i,y.size()){
        if( y[i] == maxi ) maxset.insert( i );
    }
    rep(i,x.size()){
        if( x[i] == mini ) minset.insert( i );
    }

    ll ans = (  *max_element( all(x) ) - *min_element( all(x) ) )
            *(  *max_element( all(y) ) - *min_element( all(y) ) );

    bool f = true;
    rep(i,n)if(x[i]==mini && y[i] == maxi)f = false;
    if( f ){
        int x_use = -INF, y_use = INF;
        int x_ind, y_ind;

        for( auto e: maxset ){
            if(x[e]>x_use){
                x_use = x[e];
                x_ind = e;
            }
        }
        for( auto e: minset ){
            if( e == x_ind )continue;
            if(y[e]<y_use){
                y_use = y[e];
                y_ind = e;
            }
        }

        assert( x_ind != y_ind);

        priority_queue<pii,vector<pii>,greater<pii>> pq;
        int cur_max = max( x_use, y_use );
        rep(i,n){
            if( i==x_ind || i==y_ind )continue;
            pq.push( pii(x[i],y[i]) );
            cur_max = max( cur_max, x[i] );
        }

        while( pq.size() ){
            int x, y;
            tie(x,y) = pq.top();
            pq.pop();
            ans = min<ll>( ans, (maxi-mini) * (cur_max - min(x, min(x_use, y_use))) );
            cur_max = max(cur_max, y);
        }
    }
    cout<<ans<<endl;
}

