int mn = 1e9 + 123, mx = -1;

long long calc1() {
    long long red = mx - mn;
    long long blueFrom = v[0].first;
    long long blueTo = v[0].first;

    for (int i = 0; i < sz(v); i++) {
        long long from = v[i].second, to = v[i].first;
        if (from >= blueFrom) {
            blueTo = max(blueTo, from);
        } else {
            blueTo = max(blueTo, to);
        }
    }

    return 1ll * red * (blueTo - blueFrom);
}

long long f(long long r) {
    long long redFrom = mn, redTo = r;
    long long blueFrom = mx, blueTo = mx;

    for (int i = 0; i < sz(v); i++) {
        long long from = v[i].second, to = v[i].first;
        if (from >= redFrom && from <= redTo) {
            blueFrom = min(blueFrom, to);
        } else {
            blueFrom = min(blueFrom, from);
        }
    }

    return 1ll * (redTo - redFrom) * (blueTo - blueFrom);
}

long long calc2() {
    long long l = mn, r = mx;

    for (int i = 0; i < sz(v); i++) {
        long long from = v[i].second, to = v[i].first;
        if (from == mn) {
            continue;
        }
        l = max(l, from);
    }

    while (r - l > 5) {
        long long mid1 = l + (r - l) / 3;
        long long mid2 = r - (r - l) / 3;
        if (f(mid1) < f(mid2)) {
            r = mid2;
        } else {
            l = mid1;
        }
    }

    long long result = f(l);
    while (l != r) {
        result = min(result, f(l));
        l++;
    }
    return result;
}

