typedef long long ll;
typedef pair<ll, int> P;

const ll INF = 100000000000;

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<ll> x(n), y(n);
	ll rmax = 0, rmin = INF, bmax = 0, bmin = INF;
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> y[i];
		if (x[i] > y[i]) swap(x[i], y[i]);
		rmax = max(rmax, x[i]);
		rmin = min(rmin, x[i]);
		bmax = max(bmax, y[i]);
		bmin = min(bmin, y[i]);
	}

	ll ans = (rmax - rmin) * (bmax - bmin);
	ll vmin = rmin, vmax = bmax;
	rmax = vmax, rmin = vmin, bmax = 0, bmin = INF;
	vector<bool> used(n, false);
	for (int i = 0; i < n; i++) {
		bool flag1 = (x[i] == vmin);
		bool flag2 = (y[i] == vmax);
		if (flag1 && flag2) {
			cout << ans << endl;
			return 0;
		}
		if (flag1) {
			bmin = min(bmin, y[i]);
			bmax = max(bmax, y[i]);
			used[i] = true;
		} else if (flag2) {
			bmax = max(bmax, x[i]);
			bmin = min(bmin, x[i]);
			used[i] = true;
		}
	}

	vector<P> hoge;
	for (int i = 0; i < n; i++) {
		if (used[i]) continue;
		if (bmin <= x[i] || bmax >= y[i]) {
			used[i] = true;
			continue;
		}
		hoge.emplace_back(bmin - x[i], -(i + 1));
		hoge.emplace_back(y[i] - bmax, i);
	}

	sort(hoge.begin(), hoge.end());
	ll dmin = 0, dmax = 0;
	for (P p : hoge) {
		if (p.second < 0) {
			if (used[-p.second - 1]) continue;
			dmin = p.first;
			used[-p.second - 1] = true;
		} else {
			if (used[p.second]) continue;
			dmax = p.first;
			used[p.second] = true;
		}
	}
	bmin -= dmin;
	bmax += dmax;
	ans = min(ans, (rmax - rmin) * (bmax - bmin));
	cout << ans << endl;
	return 0;
}

