#define rep(i,a,b) for(auto i=a;i<b;++i)
typedef long long ll;

int const N = 4e5 + 41;
int n;
ll a[N][2];
int p[N];
int col[N], w[N];

int getVal(int i){
	return (i < n ? a[i][0] : a[i-n][1]);
}

int const INF = 1e9 + 41;

void remin(int &a, int b){
	a = min(a, b);
}

void remax(int &a, int b){
	a = max(a, b);
}

ll solve1(){
	int cnt = 0;
	rep(i, 0, n * 2){
		++w[p[i] % n];
		col[p[i]] = w[p[i] % n];
		if(col[p[i]] == 1) ++cnt;
		if(cnt == n) break;
	}
	ll ret = 0;
	int miniR = INF, maxiR = -INF, miniB = INF, maxiB = -INF;
	rep(i, 0, n * 2){
		if(col[i] == 1){
			remin(miniR, getVal(i));
			remax(maxiR, getVal(i));
		}else{
			remin(miniB, getVal(i));
			remax(maxiB, getVal(i));
		}
	}

	ret = (maxiR - miniR) * 1LL * (maxiB - miniB);

	return ret;
}

ll solve2(){
	ll ret = INF * 1LL * INF;
	rep(i, 0, n * 2) w[i] = 0, col[i] = 0;
	int cnt = 0;
	rep(i, 1, n * 2){
		++w[p[i] % n];
		if(w[p[i] % n] == 1) col[p[i]] = 1, ++cnt;
		else col[p[i]] = 2;
		if(cnt == n) break;
	}
	assert(cnt == n);
	int maxiB = -INF, miniB = INF, maxiR = -INF, miniR = INF;
	rep(i, 0, n * 2){
		if(col[i] == 1){
			remax(maxiB, getVal(i));
			remin(miniB, getVal(i));
		}else{
			remax(maxiR, getVal(i));
			remin(miniR, getVal(i));
		}
	}

	ret = (maxiB - miniB) * 1LL * (maxiR - miniR);

	return ret;
}

bool comp(int i, int j){
	return getVal(i) < getVal(j);
}

void solve(){
	cin >> n;
	rep(i, 0, n) cin >> a[i][0] >> a[i][1];
	rep(i, 0, n * 2) p[i] = i;
	sort(p, p + n * 2, comp);
	ll ans = solve1();
	if(n > 1) ans = min(ans, solve2());

	cout << ans << endl;
}

int main(){
#ifdef _DEBUG
	freopen("input.txt","r",stdin);
	freopen("output.txt","w",stdout);
#endif

	solve();

	return 0;
}

