		a[++cnt]=node(x,i,y);
		a[++cnt]=node(y,i,x);
	}
	sort(a+1,a+1+cnt);
	if(a[1].bel==a[cnt].bel)
	{
		if(a[1].v==a[2].v)
			swap(a[1],a[2]);
	}
	ans=1ll<<60;
	if(a[1].bel!=a[cnt].bel)
	{
		use[a[1].bel]=use[a[cnt].bel]=1;
		int v1=a[1].opt,v2=a[cnt].opt;
		for(int i=2,j=i-1,sum=0;i<cnt;i++)
		{
