		if (max < st[i].big)
		{
			max = st[i].big;
			max_i = i;
		}
	}
	int min_r = st[0].big;
	int max_b = st[max_i].small;
	for (int i = 1; i < N; i++)
	{
		if (i == max_i) continue;
		min_r = MIN(st[i].big, min_r);
		max_b = MAX(st[i].small, max_b);
	}
	return (max - min_r) * (max_b - min);
}

signed main()
{
	cin >> N;
	for (int i = 0; i < N; i++)
	{
		int x, y;
		cin >> x >> y;
		int max = MAX(x, y);
		int min = MIN(x, y);
		st[i].small = min;
		st[i].big = max;
	}
	ARY_SORT(st, N);

	if (N == 1)
	{
		return 0;
	}

	int val = MIN(func1(), func2());

	cout << val << endl;
}

