typedef long long ll;
const int N = 200000;
struct point {
	int x, y;
	void read() {
		scanf("%d%d", &x, &y);
	}
	bool operator<(const point &p)const {
		if (x != p.x)
			return x < p.x;
		return y < p.y;
	}
}v[N];
int n;
ll calc(ll l, ll r) {
	int mn = 1e9 + 1, mx = -1;
	set<point> s;
	vector<int> ans;
	for (int i = 0; i < n; ++i) {
		if (v[i].x >= l && v[i].x <= r && v[i].y >= l && v[i].y <= r) {
			s.insert(v[i]);
			ans.push_back(v[i].x);
			ans.push_back(v[i].y);
			continue;
		}
		if (v[i].x >= l && v[i].x <= r) {
			mn = min(mn, v[i].y);
			mx = max(mx, v[i].y);
		}
		else {
			mn = min(mn, v[i].x);
			mx = max(mx, v[i].x);
		}
	}
	sort(ans.begin(), ans.end());
	ans.resize(unique(ans.begin(), ans.end()) - ans.begin());
	ll res = (r - l)*max(0, (mx - mn));
	if (!ans.empty())
		res = 2e18;
	for (int i = 0; i < ans.size(); ++i) {
		if (ans[i] > mn)
			break;
		while (s.begin()->x<ans[i]) {
			auto x = *s.begin();
			s.erase(s.begin());
			if (x.y <= x.x)
				return res;
			swap(x.x, x.y);
			s.insert(x);
		}
		int L = ans[i];
		int R = max(mx, (--s.end())->x);
		R = max(R, L);
		res = min(res, (r - l)*(R - L));
	}
	return res;
}
int main()
{
	scanf("%d", &n);
	int mn = 1e9, mxmn = -1e9;
	for (int i = 0; i < n; ++i) {
		v[i].read();
		mn = min(mn, min(v[i].x, v[i].y));
		mxmn = max(mxmn, min(v[i].x, v[i].y));
		if (v[i].x > v[i].y)
			swap(v[i].x, v[i].y);
	}
	ll l1, l2, r1, r2, l = mxmn - mn, r = 1e9 - mn + 1, res = 2e18;
	while (l <= r) {
		l1 = (2 * l + r) / 3;
		l2 = (l + 2 * r) / 3;
		r1 = calc(mn, mn+l1);
		r2 = calc(mn, mn+l2);
		res = min(res, min(r1, r2));
		if (r1 > r2)
			l = l1 + 1;
		else
			r = l2 - 1;
	}
	printf("%lld\n", res);
	return 0;
}

