			Rmin=min(min(card[i].y,premin),card[i+1].x);
			premin=min(premin,card[i].y);
			if(Rmax-Rmin<tmp) tmp=Rmax-Rmin;
		}
		ans=min(ans,1ll*tmp*(Bmax-Bmin));
	}
