struct Solver {
  long n;
  std::vector<std::array<long, 2>> xs;
  Solver() {
    S002 reader;
    reader >= n >n>= xs;
  }
  void solve() {
    for(auto& x : xs) {
      if( x[0] > x[1] ) std::swap(x[0], x[1]);
    }
    long lMinI, lMaxI, rMinI, rMaxI;
    lMinI = lMaxI = rMinI = rMaxI = 0;
    for(long i = 0; i < n; ++i) {
      if( xs[lMinI][0] > xs[i][0] ) {
        lMinI = i;
      }
      if( xs[lMaxI][0] < xs[i][0] ) {
        lMaxI = i;
      }
      if( xs[lMinI][1] > xs[i][1] ) {
        rMinI = i;
      }
      if( xs[lMaxI][1] < xs[i][1] ) {
        rMaxI = i;
      }
    }
    long res = (1LL << 62);
    for(long k1 = 0; k1 < 2; std::swap(xs[lMinI][0], xs[lMinI][1]), ++k1) {
      for(long k2 = 0; k2 < 2; std::swap(xs[lMaxI][0], xs[lMaxI][1]), ++k2) {
        for(long k3 = 0; k3 < 2; std::swap(xs[rMinI][0], xs[rMinI][1]), ++k3) {
          for(long k4 = 0; k4 < 2; std::swap(xs[rMaxI][0], xs[rMaxI][1]), ++k4) {
            long lMin, lMax, rMin, rMax;
            lMin = lMax = xs[0][0];
            rMin = rMax = xs[0][1];
            for(long i = 0; i < n; ++i) {
