              rMin = std::min(rMin, xs[i][1]);
              rMax = std::max(rMax, xs[i][1]);
            }
            res = std::min(res, (lMax - lMin) * (rMax - rMin));
          }
        }
      }
    }
    printf("%ld\n", res);
  }    
  ~Solver() { fprintf(stderr, "--end--\n"); }
};


