			if(i == min_idx) {
				y = arr[i].y;
			}
			if(i == max_idx) {
				x = arr[i].x;
			}
		}
		if(y < x) swap(x, y);
		assert(x != -1 && y != -1);
		for(int i = 1; i <= n; i++) {
			if(arr[i].x <= y && arr[i].x >= x) {
			} else if(arr[i].y <= y && arr[i].y >= x) {
			} else if(i != min_idx && i != max_idx) {
				pts.push_back(arr[i]);
			}
		}
		if(pts.size()) {
			sort(pts.begin(), pts.end());
