using namespace std;

/** whole range */
#define whole(xs) (xs).begin(), (xs).end()

namespace {
    /** output whole vector. ex) vector<int>{1, 2, 3} -> '1 2 3'. */
    template<typename T>
    ostream& operator<<(ostream& os, const vector<T>& xs) {
       if (xs.empty()) return os;
       os << xs[0];
       for (auto i = 1; i < xs.size(); i++) os << ' ' << xs[i];
       return os;
    }
    int N;
    vector<int> xs, ys;
    void input() {
        cin >> N;
        for (int i = 0; i < N; i++) {
            int x, y; cin >> x >> y;
            xs.push_back(x);
            ys.push_back(y);
        }
    }

    void solve() {
        using ll = long long;
        const int INF = numeric_limits<int>::max() / 2;
        const ll INFLL = numeric_limits<ll>::max() / 2;
        ll ans = INFLL;
        int gmin = min(*min_element(whole(xs)), *min_element(whole(ys)));
        int gmax = max(*max_element(whole(xs)), *max_element(whole(ys)));
        vector<int> ps, qs;
        int r = gmin, R = -INF;
        int b = INF, B = -INF;
        bool b_pos = false;
        for (int i = 0; i < N; i++) {
            int x = xs[i], y = ys[i];
            if (x > y) swap(x, y);
            if (x == gmin) {
                b = min(b, y);
                B = max(B, y);
            } else {
                if (y == gmax) { b_pos = true; }
                ps.push_back(x);
                qs.push_back(y);
            }
        }
        auto pattern_a = [&](int r, int R, int b, int B) {
            B = gmax;
            for (int i = 0; i < ps.size(); i++) {
                int p = ps[i], q = qs[i];
                if (q == gmax) {
                    R = max(R, p);
                } else {
                    R = max(R, p);
                    b = min(b, q);
                }
            }
            return ll(R - r) * ll(B - b);
        };
        auto pattern_b = [&](int r, int R, int b, int B) {
            R = gmax;
            vector<int> ss, ts;
            for (int i = 0; i < ps.size(); i++) {
                int p = ps[i], q = qs[i];
                if (q == gmax) {
                    b = min(b, p);
                    B = max(B, p);
                }
            }
            for (int i = 0; i < ps.size(); i++) {
                int p = ps[i], q = qs[i];
                if (q == gmax) continue;
                if ( (b <= p and p <= B) or (b <= q and q <= B) ) ;
                else {
                    ss.push_back(p);
                    ts.push_back(q);
                }
            }
            if (ss.size() >= 2) {
                //cout << "ss: " << ss << endl;
                //cout << "ts: " << ts << endl;
                int m = *min_element(whole(ts));
                int M = *max_element(whole(ss));
                if (m > M) swap(m, M);
                b = min(b, m);
                B = max(B, M);
            } else if (ss.size() == 1) {
                int x = ss[0];
                int y = ts[0];
                if ( (b <= x and x <= B) or (b <= y and y <= B) ) ;
                else {
                    if (b - x >= x - B) b = x;
                    else B = x;
                }
            }
            return ll(R - r) * ll(B - b);
        };
        ans = min(pattern_a(r, R, b, B), pattern_b(r, R, b, B));
        cout << ans << endl;
    }
}

int main() {
    input(); solve();
    return 0;
}

