    while(mx < 2 * N && mx < another[mx]){
        ++mx;
    }
    --mx;

    int mx_blue = -1;
    for(int i=2*N-1;i>mx;--i){
        if(i < another[i] && mx_blue == -1){
            mx_blue = fst(v[i]);
        }
    }

    ll res = 1001001001001001001ll;
    // b..b (i+1 個) .. の場合
    for(int i=mx;i>=0;--i){
        int b_diff = max(abs(mx_blue != -1 ? mx_blue - fst(v[0]) : fst(v[i]) - fst(v[0])), abs(i < mx ? snd(v[i+1]) - fst(v[0]) : fst(v[i]) - fst(v[0]))),
            r_diff = abs(fst(v[2*N-1]) - fst(v[i+1]));
        std::cout << b_diff << ", " << r_diff << std::endl;
        res = min(res, 1ll * b_diff * r_diff);

        if(i < mx && mx_blue == -1){
            mx_blue = fst(v[i+1]);
        }
    }

    return res;
}

// R .. B .. B .. R pattern
ll compute2(){
    int l = min(another[0], another[2*N-1]), r = max(another[0], another[2*N-1]);

    int blue_n = 2;
    used[another[l]] = true;
    used[another[r]] = true;
    {
        for(int i=l+1;i<r;++i){
            if(!used[i]){
                ++blue_n;
                used[another[i]] = true;
            }
        }
    }

    int _l = l - 1, _r = r + 1;
    while(blue_n < N){
        while(_l > 0 && used[_l]){--_l;}
        while(_r < 2 * N - 1 && used[_r]){++_r;}

        int diff_l = _l > 0 ? fst(v[l]) - fst(v[_l]) : 1001001001,
            diff_r = _r < 2 * N - 1 ? fst(v[_r]) - fst(v[r]) : 1001001001;

        if(diff_l < diff_r){
            used[another[_l]] = true;
            l = _l;
            --_l;
        }else{
            used[another[_r]] = true;
            r = _r;
            ++_r;
        }

        ++blue_n;
    }

    return 1ll * (fst(v[2*N-1]) - fst(v[0])) * (fst(v[r]) - fst(v[l]));
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N;

    for(int i=0;i<N;++i){
        std::cin >> xs[i] >> ys[i];

        v.emplace_back(xs[i], ys[i], i);
        v.emplace_back(ys[i], xs[i], 2 * N - 1 - i);
    }

    sort(v.begin(), v.end());

    for(int i=0;i<2*N;++i){
        int a, b, index;
        tie(a, b, index) = v[i];

        another[i] = lower_bound(v.begin(), v.end(), std::make_tuple(b, a, 2 * N - 1 - index)) - v.begin();
    }

    ll res = compute1();
    if(another[0] != 2 * N - 1){
        // 端をもつものからどれを選ぶかで答えが変わりそう．
        res = min(res, compute2());
    }
    reverse(v.begin(), v.end());
    reverse(another, another+2*N);
    for(int i=0;i<2*N;++i){
        another[i] = 2 * N - 1 - another[i];
    }
    res = min(res, compute1());
    std::cout << res << std::endl;
}

