//2N個のボールのうち最大のものを赤、最小のものを青で塗った場合
int RMBm() {
    int RMax = -INF, Rmin = INF;
    int BMax = -INF, Bmin = INF;
    rep(i, N) {
        int r = max(XY[i].first, XY[i].second);
        int b = min(XY[i].first, XY[i].second);
        RMax = max(RMax, r);
        Rmin = min(Rmin, r);
        BMax = max(BMax, b);
        Bmin = min(Bmin, b);
    }
    return (RMax - Rmin) * (BMax - Bmin);
}

//2N個のボールのうち最大、最小のものを赤でぬる
pii blue[200200];

int RMrm1() {
    int maxv = -INF, maxi, minv = INF, mini;
    rep(i, N) {
        int M = max(XY[i].first, XY[i].second);
        int m = min(XY[i].first, XY[i].second);
        blue[i] = pii(m, M);
        if (M > maxv) {
            maxv = M;
            maxi = i;
        } else if (M == maxv) {
            maxi = -1;
        }
        if (m < minv) {
            minv = m;
            mini = i;
        } else if (m == minv) {
            mini = -1;
        }
    }
    if (maxi == mini)return INF;
    sort(blue, blue + N);
