{
	scanf("%lld",&n);
	for(int i=1;i<=n;i++)
	{
		scanf("%lld%lld",&x[i],&y[i]);
	}
	Rmax=Rmin=x[1],Lmax=Lmin=y[1];
	for(int i=2;i<=n;i++)
	{
		LL rmax=Rmax,rmin=Rmin,lmax=Lmax,lmin=Lmin,ans=0;
		rmax=max(rmax,x[i]),rmin=min(rmin,x[i]);
		lmax=max(lmax,y[i]),lmin=min(lmin,y[i]);
