ll cul_dis(multiset<ll> &s){
    return *s.rbegin() - *s.begin();
}

ll solve(){
	ll res = INFLL;
	multiset<ll> mins;
	multiset<ll> maxs;
    foreach(i,line){
        if(i[0]>i[1])swap(i[0],i[1]);
        mins.insert(i[0]);
        maxs.insert(i[1]);
    }
    sort(all(line));
    res = cul_dis(maxs) * cul_dis(mins);
    foreach(i,line){
        mins.erase(mins.find(i[0]));
        maxs.insert(i[0]);
        mins.insert(i[1]);
        maxs.erase(maxs.find(i[1]));
        chmin(res,cul_dis(maxs)*cul_dis(mins));
    }
    return res;
}

