int64 maxOfTwo(int64 min1, int64 min2, int64 max1, int64 max2) {
    int64 t = abs(max1 - min1);
    int64 t2 = abs(max2 - min2);
	int64 a = abs(max1 - min1) * abs(max2 - min2);
	int64 b = abs(max1 - min2) * abs(max2 - min1);
	a = t*t2;
	return min(a, b);
}

