ll dist(ll a, ll b, ll c) {
    if (a <= c && c <= b) return 0;
    return min(abs(a-c), abs(b-c));
}

ll solve() {
    ll X[n], Y[n];
    for (int i = 0; i < n; i++) {
        if (x[i] > y[i])
            swap(x[i], y[i]);
        X[i] = x[i];
        Y[i] = y[i];
    }
    sort(X, X+n);
    sort(Y, Y+n);
    ll res = (X[n-1] - X[0]) * (Y[n-1] - Y[0]);
    ll v[2] = {inf, 0};
    for (int i = 0; i < n; i++) {
        if (x[i] == X[0]) {
            v[0] = min(v[0], y[i]);
            v[1] = max(v[1], y[i]);
        }
        if (y[i] == Y[n-1]) {
            v[0] = min(v[0], x[i]);
            v[1] = max(v[1], x[i]);
        }
    }
    for (int i = 0; i < n; i++) {
        ll w = (dist(v[0], v[1], x[i]) < dist(v[0], v[1], y[i]) ? x[i] : y[i]);
        v[0] = min(v[0], w);
        v[1] = max(v[1], w);
    }
    res = min(res, (Y[n-1] - X[0]) * (v[1] - v[0]));

    return res;
}

