const ll LLINF = (1LL<<60);
const int INF = (1LL<<30);
const double DINF = std::numeric_limits<double>::infinity();
const int MOD = 1000000007;
#define MAX_N 200010

ll N;
vector<ll> X, Y;

enum State { Suspend = 0, Red = 1, Blue = 2 };
vector< pair<ll, ll> > XY;  // first: val, second: index
vector<ll> pair_pos;    // XY[i] の、相方の XY での位置

signed main()
{
    cin >> N;
    X.resize(N);
    Y.resize(N);
    REP(i, N) {
        cin >> X[i] >> Y[i];
        // 小さい方を X にしておく
        if(X[i] > Y[i]) { swap(X[i], Y[i]); }
        XY.push_back(make_pair(X[i], i));
        XY.push_back(make_pair(Y[i], i));
    }
    SORT(XY);

    // pair_pos の作成
    pair_pos.assign(2 * N, 0);
    {
        vector< vector<ll> > table(N, vector<ll>());    // X or Y で位置 i にいるものの、 XY での位置
        REP(i, 2 * N) {
            table[XY[i].second].push_back(i);
        }
        REP(i, N) {
            pair_pos[table[i][0]] = table[i][1];
            pair_pos[table[i][1]] = table[i][0];
        }
    }

    // パターン 1
    // 最小の値を赤に、最大の値を青にする場合
    // → 赤にできるだけ小さい値を、青にできるだけ大きい値を入れるのが最善
    ll r_min = XY[0].first;
    ll r_max = XY[pair_pos[2 * N - 1]].first;
    ll b_min = XY[pair_pos[0]].first;
    ll b_max = XY[2 * N - 1].first;
    // r_max/b_min を求める
    vector<ll> color(2 * N, Suspend);   // XY[i] はどっちの色か
    color[0] = Red;
    color[pair_pos[2 * N - 1]] = Red;
    color[pair_pos[0]] = Blue;
    color[2 * N - 1] = Blue;
    ll cnt = 2;
    REP(i, 2 * N) {
        if(color[i] == Suspend) {
            color[i] = Red;
            color[pair_pos[i]] = Blue;
            r_max = max(r_max, XY[i].first);
            b_min = min(b_min, XY[pair_pos[i]].first);
            cnt++;
        }
    }
    assert(cnt == N);
    ll ans = (r_max - r_min) * (b_max - b_min);

    // パターン 2
    // 最小の値も最大の値も赤にする場合
    // → 青が取る区間を最小にするのが最善
    if(pair_pos[0] == 2 * N - 1 && XY[0].first != XY[1].first && XY[2 * N - 1] != XY[2 * N - 2]) {
        // 最大と最小が同じ袋
        printf("%lld\n", ans);
        return 0;
    }

    ll pos1 = 0;
    ll pos2 = 2 * N - 1;
    if(pair_pos[0] == 2 * N - 1) {
        // 同じ袋の玉を選ぼうとしてしまっているので避ける
        if(XY[0].first == XY[1].first) { pos1 = 1; }
        else if(XY[2 * N - 1].first == XY[2 * N - 2].first) { pos2 = 2 * N - 2; }
        else { assert(false); }
    }
    r_min = XY[pos1].first;
    r_max = XY[pos2].first;
    b_min = min(XY[pair_pos[pos1]].first, XY[pair_pos[pos2]].first);
    b_max = max(XY[pair_pos[pos1]].first, XY[pair_pos[pos2]].first);
    color.assign(2 * N, Suspend);
    color[pos1] = Red;
    color[pos2] = Red;
    color[pair_pos[pos2]] = Blue;
    color[pair_pos[pos1]] = Blue;

    cnt = 2;
    ll l = min(pair_pos[pos1], pair_pos[pos2]);
    ll r = max(pair_pos[pos1], pair_pos[pos2]);
    ll base_l = l;
    ll base_r = r;
    // まず [b_min, b_max] の中でまだ色が決まっていないやつを手当たり次第に取る
    for(ll i = base_l + 1; i < base_r; ++i) {
        if(color[i] == Suspend) {
            color[i] = Red;
            color[pair_pos[i]] = Blue;
            cnt++;
        }
        if(cnt == N) { break; }
    }
    // まだ色がついていない場所があるなら、なるべく青の max - min が
    // 大きくならないような範囲を探す
    while(cnt < N) {
        ll next_l = (l > 0) ? l - 1 : 0;
        ll next_r = (r < N - 1) ? r + 1 : N - 1;
        if(color[next_l] == Suspend && color[next_r] == Suspend) {
            // どちらか近い方をとる
            ll sub_l = abs(XY[base_l].first - XY[next_l].first);
            ll sub_r = abs(XY[base_r].first - XY[next_r].first);
            if(sub_l < sub_r) {
                color[next_l] = Blue;
                color[pair_pos[next_l]] = Red;
                l = next_l;
            }
            else {
                color[next_r] = Blue;
                color[pair_pos[next_r]] = Red;
                l = next_l;
            }
            cnt++;
        }
        else if(color[next_l] == Suspend && color[next_r] != Suspend) {
            // l をとる
            color[next_l] = Blue;
            color[pair_pos[next_l]] = Red;
            l = next_l;
            r = next_r;
            cnt++;
        }
        else if(color[next_l] != Suspend && color[next_r] == Suspend) {
            // r をとる
            color[next_r] = Blue;
            color[pair_pos[next_r]] = Red;
            l = next_l;
            r = next_r;
            cnt++;
        }
        else {
            assert(l != next_l || r != next_r);
            l = next_l;
            r = next_r;
        }
    }
    assert(cnt == N);

    b_max = XY[r].first;
    b_min = XY[l].first;
    ans = min(ans, (r_max - r_min) * (b_max - b_min));

    printf("%lld\n", ans);

    return 0;
}

