    if(cnt < N) {
        // とりあえずなるべく左側のもので充填してみる
        REP(i, 2 * N) {
            if(color[i] == Suspend) {
                color[i] = Blue;
                color[pair_pos[i]] = Red;
                cnt++;
                l = min(l, i);
                r = max(r, i);
                if(cnt == N) { break; }
            }
        }
    }
    assert(cnt == N);
    // 左から見て [l, r] を小さくできそうならそうする
    REP(i, 2 * N) {
        assert(color[i] != Suspend);
        if(color[i] == Blue) {
            l = i;
            if(l < pair_pos[i] && pair_pos[i] < r) { swap(color[i], color[pair_pos[i]]); }
            else { break; }
        }
    }
    // 右から見て [l, r] を小さくできそうならそうする
    for(ll i = 2 * N - 1; i >= 0; --i) {
        assert(color[i] != Suspend);
        if(color[i] == Blue) {
            r = i;
            if(l < pair_pos[i] && pair_pos[i] < r) { swap(color[i], color[pair_pos[i]]); }
            else { break; }
        }
    }

    b_max = XY[r].first;
    b_min = XY[l].first;
    ans = min(ans, (r_max - r_min) * (b_max - b_min));

    // 一応両端を広げるパターンもやっておく
    // まず [b_min, b_max] の中でまだ色が決まっていないやつを手当たり次第に取る
    for(ll i = base_l + 1; i < base_r; ++i) {
        if(color[i] == Suspend) {
            color[i] = Blue;
            color[pair_pos[i]] = Red;
            cnt++;
        }
        if(cnt == N) { break; }
    }
    // まだ色がついていない場所があるなら、なるべく青の max - min が
    // 大きくならないような範囲を探す
    while(cnt < N) {
        ll next_l = l;
        while(next_l >= 0) {
            if(color[next_l] == Suspend) { break; }
            next_l--;
        }
        ll next_r = r;
        while(next_r < 2 * N) {
            if(color[next_r] == Suspend) { break; }
            next_r++;
        }
        if(next_l >= 0 && next_r < 2 * N) {
            // どちらか近い方をとる
            ll sub_l = abs(XY[base_l].first - XY[next_l].first);
            ll sub_r = abs(XY[base_r].first - XY[next_r].first);
            if(sub_l < sub_r) {
                color[next_l] = Blue;
                color[pair_pos[next_l]] = Red;
                l = next_l;
            }
            else {
                color[next_r] = Blue;
                color[pair_pos[next_r]] = Red;
                r = next_r;
            }
            cnt++;
        }
        else if(next_l >= 0 && next_r >= 2 * N) {
            // l をとる
            color[next_l] = Blue;
            color[pair_pos[next_l]] = Red;
            l = next_l;
            cnt++;
        }
        else if(next_l < 0 && next_r < 2 * N) {
            // r をとる
            color[next_r] = Blue;
            color[pair_pos[next_r]] = Red;
            r = next_r;
            cnt++;
        }
        else {
            assert(false);
        }
    }
    assert(cnt == N);

    b_max = XY[r].first;
    b_min = XY[l].first;
    ans = min(ans, (r_max - r_min) * (b_max - b_min));

    printf("%lld\n", ans);

    return 0;
}

