int main() {
	in(n);
	if(n == 1) {
		puts("0");
		return 0;
	}
	int min_idx = -1, max_idx = -1;
	LL minim, maxim;
	for(int i = 1; i <= n; i++) {
		in(arr[i].x), in(arr[i].y);
		if(arr[i].x > arr[i].y) swap(arr[i].x, arr[i].y);
		if(i == 1) {
			minim = arr[1].x, maxim = arr[1].y;
		} else {
			minim = min(minim, arr[i].x), maxim = max(maxim, arr[i].y);
		}
	}
	for(int i = 1; i <= n; i++) {
		if(arr[i].x == minim && min_idx == -1) {
			min_idx = i;
		}
		if(arr[i].y == maxim) {
			max_idx = i;
		}
	}
	assert(max_idx != -1 && min_idx != -1);
	LL res = INF, x = -INF, y = INF;
	for(int i = 1; i <= n; i++) {
		if(max_idx == min_idx && i == min_idx) {
		} else if(max_idx == i) {
			x = max(x, arr[i].x);
		} else if(min_idx == i) {
			y = min(y, arr[i].y);
		} else {
			x = max(x, arr[i].x);
			y = min(y, arr[i].y);
		}
	}
	assert(x != -INF && y != INF);
	res = (maxim - y) * (x - minim);
	if(min_idx != max_idx) {
		y = arr[min_idx].y;
		x = arr[max_idx].x;
		if(y < x) swap(x, y);
		vector<point> pts;
		for(int i = 1; i <= n; i++) {
			if(arr[i].x >= x && arr[i].x <= y) {
			} else if(arr[i].y >= x && arr[i].y <= y) {
			} else if(arr[i].x > y) {
				y = arr[i].x;
			} else if(arr[i].y < x) {
				x = arr[i].y;
			} else {
				assert(i != min_idx && i != max_idx);
				pts.push_back(arr[i]);
			}
		}
		sort(pts.begin(), pts.end());
		LL a = maxim - minim, b = INF;
		if(pts.size()) {
			multiset<LL> yss;
			for(auto &elem: pts) {
				yss.insert(elem.y);
			}
			yss.insert(y);
			b = min(b, (*yss.rbegin()) - x);
			for(int i = 0; i < pts.size(); i++) {
				yss.erase(yss.find(pts[i].y));
				b = min(b, (*yss.rbegin()) - pts[i].x);
			}
		} else {
			b = y - x;
		}
		res = min(res, a * b);
	}
	printf("%lld\n", res);
	return 0;
}

