ll ri(){ll l;cin>>l;return l;} string rs(){string s;cin>>s;return s;}

ll calc(const vpii &P) {
	const int n = sz(P);
	ll xmi = P[0].fst;
	ll ymi = P[0].snd;
	ll xma = xmi;
	ll yma = ymi;

	rep(i, 1, n) {
		ll a, b;
		tie(a, b) = P[i];
		{
			ll xabi = min(xmi, a);
			ll xaba = max(xma, a);
			ll yabi = min(ymi, b);
			ll yaba = max(yma, b);
			ll cab = (xaba - xabi) * (yaba - yabi);
			ll xbai = min(xmi, b);
			ll xbaa = max(xma, b);
			ll ybai = min(ymi, a);
			ll ybaa = max(yma, a);
			ll cba = (xbaa - xbai) * (ybaa - ybai);
			if (cab <= cba) {
				xmi = xabi;
				xma = xaba;
				ymi = yabi;
				yma = yaba;
			}
			else {
				xmi = xbai;
				xma = xbaa;
				ymi = ybai;
				yma = ybaa;
			}
		}
	}
	return (xma-xmi) * (yma-ymi);
}

ll solve() {
	int n = ri();

	vpii P(n);
	rep(i, n) {
		int x = ri();
		int y = ri();
		P[i].fst = min(x, y);
		P[i].snd = max(x, y);
	}

	sort(all(P));
	ll cand1 = calc(P);

	forr(xy, P) swap(xy.fst, xy.snd);
	sort(all(P), greater<decltype(P)::value_type>());

	ll cand2 = calc(P);

	out(cand1, cand2);

	return min(cand1, cand2);
}

void Main() {
	cout << solve() << endl;
}
