        if(u.second >= u.first) break;
        Rmax = max(Rmax, u.first);
        Bmin = min(Bmin, u.second);
        swap(u.first, u.second);
        pq.push(u);
        ans = min(ans, 1LL * (Rmax - Rmin) * (pq.top().first - Bmin));
    }
    printf("%lld\n", ans);
    return 0 ;
}

