        Lma = max(Lma, v[i].first); Rma = max(Rma, v[i].second);
      }
      else{
        Lmi = min(Lmi, v[i].second); Rmi = min(Rmi, v[i].first);
        Lma = max(Lma, v[i].second); Rma = max(Rma, v[i].first);
      }
    }
    return (Lma - Lmi) * (Rma - Rmi);
  }
  else{
    LL ret = INF_LL_MAX;
    dist[pos] = 0;
    ret = min(ret, solve(pos+1, v));
    dist[pos] = 1;
    ret = min(ret, solve(pos+1, v));
    dist[pos] = 0;
    return ret;
  }
}

