int main() {
    ll x, y;
    ll mx = -inf, mn = inf;
    R(n);
    if (n == 1) {
        W(0);
        return 0;
    }
    rep(i,0,n-1) {
        R(x,y), v.pb(pll(x,y));
        if (max(x,y) > mx) mx = max(x,y), mxi = i;
        if (min(x,y) < mn) mn = min(x,y), mni = i;
        if (max(x,y) == mx && mxi == mni) mxi = i;
        if (min(x,y) == mn && mxi == mni) mni = i;
    }
    // set mx, mn to different colors
    if (mxi != mni) r.pb(getMin(v[mxi])), b.pb(getMax(v[mni]));
    rep(i,0,n-1) {
        if (i != mxi && i != mni) {
            r.pb(getMin(v[i]));
            b.pb(getMax(v[i]));
        }
    }
    ll ans = (getMax(v[mxi]) - *min_element(b.begin(), b.end())) * (*max_element(r.begin(),r.end()) - getMin(v[mni]));
    // set mx, mn to the same color
    if (mxi != mni) {
