        eval();
        for(ll i=max_B;i>max(k1,k2);){
            min_B=min(min_B,setflag(i,'R'));
            do{i--;}while(i>max(k1,k2)&&flag[i]=='B');
            max_B=i;
            eval();
        }
    }
    for(ll i=0;i<2*N;i++) flag[i]=0;
    min_R=0,max_B=2*N-1;
    min_B=INF,max_R=-INF;
