template <typename T, int n>
class BIT{
public:
    BIT(){
        bit.fill(0);
    }
    // add v to k-th
    void add(int k, T v, T modulo = -1){
        while(k <= n){
            if(modulo > 0){
                bit[k] = (bit[k] + v) % modulo;
                bit[k] = (bit[k] + modulo) % modulo;
            }else{
                bit[k] += v;
            }
            k += k & -k;
        }
    }
    // the sum of [1, k] (閉区間!!!)
    T sum(int k, T modulo = -1){
        T res = 0;
        while(k > 0){
            if(modulo > 0){
                res = (res + bit[k]) % modulo;
                res = (res + modulo) % modulo;
            }else{
                res += bit[k];
            }
            k -= k & -k;
        }
        return res;
    }
    std::array<T,n+1> bit;
};

// 0-based
template <typename T, int n>
class imosBIT{
public:
    void add(int l, int r, T v){
        _add(l + 1, r + 1, v);
    }
    // add v to [l, r)
    void _add(int l, int r, T v, T modulo = -1){
        bit.add(l, v, modulo);
        bit.add(r, -v, modulo);
    }
    T at(int k){
        return _at(k + 1);
    }
    // k-th value
    T _at(int k){
        return bit.sum(k);
    }
    BIT<T,n> bit;
};

imosBIT<int, 400100> bit;
bool used[400100];

// R .. R B .. B pattern
ll compute1(){
    int mx = 0; // [0, mx]には組をなす2整数がないような最大の添字
    while(mx < 2 * N && mx < snd(v[mx])){
        ++mx;
    }
    --mx;

    vector<int> w;
    for(int i=2*N-1;i>mx;--i){
        if(i < snd(v[i])){
            w.emplace_back(fst(v[i]));
        }
    }

    ll res = 1001001001001001001ll;
    // b..b (i+1 個) .. の場合
    for(int i=mx;i>=0;--i){
        int leftBlue_n = i + 1,
            rest_n = N - leftBlue_n;
        int b_diff = (w.size() > 0 && rest_n <= w.size() ? w[w.size()-rest_n] : fst(v[i])) - fst(v[0]),
            r_diff = fst(v[2*N-1]) - fst(v[i+1]);
        res = min(res, 1ll * b_diff * r_diff);
        w.emplace_back(fst(v[i]));
    }

    return res;
}

// R .. B .. B .. R pattern
ll compute2(){
    int l = min(snd(v[0]), snd(v[2*N-1])), r = max(snd(v[0]), snd(v[2*N-1]));

    int blue_n = 2;
    used[snd(v[l])] = true;
    used[snd(v[r])] = true;
    {
        for(int i=l+1;i<r;++i){
            if(!used[i]){
                ++blue_n;
                used[snd(v[i])] = true;
            }
        }
    }

    int _l = l - 1, _r = r + 1;
    while(blue_n < N){
        while(_l >= 0 && used[_l]){--_l;}
        while(_r < 2 * N && used[_r]){++_r;}

        int diff_l = _l >= 0 ? fst(v[l]) - fst(v[_l]) : 1001001001,
            diff_r = r < 2 * N ? fst(v[_r]) - fst(v[r]) : 1001001001;

        if(diff_l < diff_r){
            used[snd(v[_l])] = true;
            l = _l;
        }else{
            used[snd(v[_r])] = true;
            r = _r;
        }

        ++blue_n;
    }

    return 1ll * (fst(v[2*N-1]) - fst(v[0])) * (fst(v[r]) - fst(v[l]));
}

