    rep(i, 0, n)
        cin >> a[i][0] >> a[i][1];
    ll ma = max(a[0][0], a[0][1]), mi = min(a[0][0], a[0][1]);
    rep(i, 1, n)
    {
        ma = max(ma, max(a[i][0], a[i][1]));
        mi = min(mi, min(a[i][0], a[i][1]));
    }
    ll ans = big;
    vector<pair<ll, ll> > b(n * 2);
    rep(i, 0, n)
    {
        b[i * 2] = {a[i][0], i};
        b[i * 2 + 1] = {a[i][1], i};
    }
    sort(b.begin(), b.end());
    int cnt[n], curr = 0;
    fill(cnt, cnt + n, 0);
    for (int l = 0, r = -1; l < n * 2; l++)
    {
        while (curr < n)
        {
            if (r == n * 2 - 1)
                break;
            r++;
            cnt[b[r].se]++;
            if (cnt[b[r].se] == 1)
                curr++;
        }
        if (curr == n)
            ans = min(ans, (ma - mi) * (b[r].fi - b[l].fi));
        cnt[b[l].se]--;
        if (cnt[b[l].se] == 0)
            curr--;
    }
    ll t1 = ma, t2 = mi;
    rep(i, 0, n)
    {
        if (a[i][0] < a[i][1])
            swap(a[i][0], a[i][1]);
        t1 = min(t1, a[i][0]);
        t2 = max(t2, a[i][1]);
    }
    ans = min(ans, (ma - t1) * (t2 - mi));
    cout << ans << endl;
}

