using LL = long long;

LL solve(int N, vector<pair<LL, LL>> &xys);

int main() {
    int N;
    cin >> N;
    vector<pair<LL, LL>> xys(N);
    for (auto & xy : xys){
        cin >> xy.first >> xy.second;
        if (xy.first > xy.second) swap(xy.first, xy.second);
    }
