#include <bits/stdc++.h>

#define MAXN (200010)
#define ll long long

int n, m;
std::pair<ll, ll> bag[MAXN];
std::vector<std::pair<ll, ll> > vec;

ll solve(){
	ll min1 = bag[1].first, min2 = bag[1].second;
	ll max1 = bag[1].first, max2 = bag[1].second;
	for(int i = 2; i <= n; ++ i){
		ll tmp1, tmp2;
		tmp1 = (std::max(max1, bag[i].first) - std::min(min1, bag[i].first)) * 
		       (std::max(max2, bag[i].second) - std::min(min2, bag[i].second));
		tmp2 = (std::max(max1, bag[i].second) - std::min(min1, bag[i].second)) * 
		       (std::max(max2, bag[i].first) - std::min(min2, bag[i].first));
		if(tmp1 < tmp2){
			max1 = std::max(max1, bag[i].first);
			min1 = std::min(min1, bag[i].first);
			max2 = std::max(max2, bag[i].second);
			min2 = std::min(min2, bag[i].second);
		}
		else{
			max1 = std::max(max1, bag[i].second);
			min1 = std::min(min1, bag[i].second);
			max2 = std::max(max2, bag[i].first);
			min2 = std::min(min2, bag[i].first);
		}
	}
	return (max1 - min1) * (max2 - min2);
}

ll solve2(){
	ll ret = LLONG_MAX;
	for(int s = 0; s < (1 << m); ++ s){
		ll max1 = LLONG_MIN, max2 = LLONG_MIN;
		ll min1 = LLONG_MAX, min2 = LLONG_MAX;
		for(int i = 0; i < m; ++ i){
			if((s >> i) & 1){
				max1 = std::max(max1, vec[i].first);
				min1 = std::min(min1, vec[i].first);
				max2 = std::max(max2, vec[i].second);
				min2 = std::min(min2, vec[i].second);
			}
			else{
				max1 = std::max(max1, vec[i].second);
				min1 = std::min(min1, vec[i].second);
				max2 = std::max(max2, vec[i].first);
				min2 = std::min(min2, vec[i].first);
			}
		}
		ret = std::min(ret, (max1 - min1) * (max2 - min2));
	}
	return ret;
}

int main(){
	scanf("%d", &n);
	for(int i = 1; i <= n; ++ i){
		scanf("%lld%lld", &bag[i].first, &bag[i].second);
	}
	std::sort(bag + 1, n + bag + 1);
	ll ans = solve();
	for(int i = 1; i <= n; ++ i){
		std::swap(bag[i].first, bag[i].second);
	}
	std::sort(bag + 1, n + bag + 1);
	ans = std::min(ans, solve());

	if(n <= 20){
		m = n;
		for(int i = 1; i <= n; ++ i){
			vec.push_back(bag[i]);
		}
	}
	else{
		m = 20;
	    for(int i = 1; i <= n; ++ i){
	    	if(bag[i].first > bag[i].second){
			    std::swap(bag[i].first, bag[i].second);
		    }
	    }
	    std::sort(bag + 1, n + bag + 1);
	    for(int i = 1; i <= 5; ++ i){
	    	vec.push_back(bag[i]);
	    }
	    for(int i = n; i >= n - 4; -- i){
	    	vec.push_back(bag[i]);
	    }
	    for(int i = 1; i <= n - 10; ++ i){
	    	bag[i] = {bag[i + 5].second, bag[i + 5].first};
