    ll x_min = 10e+10, y_min = 10e+10;
    ll x_max = 0, y_max = 0;
    cin >> N;
    ll que_max = 0;
    for(int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
        if(x[i] > y[i]) swap(x[i], y[i]);
        p[i] = P(x[i], y[i]);
        que_max = max(que_max, y[i]);
        x_max = max(x_max, x[i]);
        x_min = min(x_min, x[i]);
        y_max = max(y_max, y[i]);
        y_min = min(y_min, y[i]);
    }
    ll ans = (x_max-x_min)*(y_max-y_min);
    sort(p, p+N);
