int n;
pi b[N];

int main(){
	scanf("%d", &n); int mx = 1, mn = 1;
	for (int i = 1; i <= n; ++i) {
		scanf("%d %d", &b[i].fi, &b[i].se);
		if(b[i].fi > b[i].se) swap(b[i].fi, b[i].se);
		if(b[i].se > b[mx].se) mx = i;
		if(b[i].fi < b[mn].fi) mn = i;
	}
	//Case1 mx -> R, mn -> R
	//Case2 mx -> R, mn -> B
	long long ans1 = b[mx].se - b[mn].fi, ans2 = oo;
	int r1 = max(b[mx].fi, b[mn].se), l1 = min(b[mx].fi, b[mn].se);
	int l2 = b[mn].se, r2 = b[mx].fi;
	for (int i = 1; i <= n; ++i) {
		if(i == mx || i == mn) continue;
		if(b[i].fi < l1 && b[i].se > r1) {
			int tmp1 = l1 - b[i].fi, tmp2 = b[i].se - r1;
			if(tmp1 < tmp2) l1 = b[i].fi;
			else r1 = b[i].se;
		}
		if(r1 < b[i].fi) r1 = b[i].fi;
		if(l1 > b[i].se) l1 = b[i].se;
		if(b[i].fi > l2) r2 = max(r2, b[i].fi);
		if(b[i].se < r2) l2 = min(l2, b[i].se);
		if(r2 < b[i].fi && b[i].fi < l2 && l2 < b[i].se) r2 = b[i].fi;
		if(b[i].fi < r2 && r2 < b[i].se && b[i].se < l2) l2 = b[i].se;
	}
	ans1 *= r1 - l1; ans2 = 1ll * (r2 - b[mn].fi) * (b[mx].se - l2);
	if(mx == mn) cout << ans2 << endl;
	else cout << min(ans1, ans2) << endl;
	return 0;
}

