bool cmp(const ii &a, const ii &b)
{
	if(max(a.fi,a.se)!=max(b.fi,b.se)) return max(a.fi,a.se)<max(b.fi,b.se);
	return a.fi<b.fi;
}

bool cmp2(const ii &a, const ii &b)
{
	if(min(a.fi,a.se)!=min(b.fi,b.se)) return min(a.fi,a.se)<min(b.fi,b.se);
	return a.fi<b.fi;
}
