		ll bmin=x[i];
		while(!vec.empty()&&min(vec.front().fi,vec.front().se)<x[i])
		{
			tmp=max(tmp,max(vec.front().fi,vec.front().se));
			vec.pop_front();
		}
		ans=min(ans,(tmp-bmin)*rrange);
	}
