                                st1 = dp[i - 1].mx1 - dp[i - 1].mn1;
                }
                ////y[i] and x[i]
                if (dp[i - 1].mx < y[i])
                        stt = y[i] - dp[i - 1].mn;
                else {
                        if (dp[i - 1].mn > y[i])
                                stt = dp[i - 1].mx - y[i];
                        else
                                stt = dp[i - 1].mx - dp[i - 1].mn;
                }
                if (dp[i - 1].mx1 < x[i])
                        stt1 = x[i] - dp[i - 1].mn1;
                else {
                        if (dp[i - 1].mn1 > x[i])
                                stt1 = dp[i - 1].mx1 - x[i];
                        else
                                stt1 = dp[i - 1].mx1 - dp[i - 1].mn1;
                }
                if (st *1ll* st1 > stt * 1ll* stt1) {
                        dp[i].ans = stt * 1ll * stt1;
                        dp[i].mn = min(dp[i - 1].mn,y[i]);
                        dp[i].mn1 = min(dp[i - 1].mn1,x[i]);
                        dp[i].mx = max(dp[i - 1].mx,y[i]);
                        dp[i].mx1 = max(dp[i - 1].mx1,x[i]);
                }
                else {
                        dp[i].ans = st * 1ll * st1;
                        dp[i].mn = min(dp[i - 1].mn,x[i]);
                        dp[i].mn1 = min(dp[i - 1].mn1,y[i]);
                        dp[i].mx = max(dp[i - 1].mx,x[i]);
                        dp[i].mx1 = max(dp[i - 1].mx1,y[i]);
                }
        }
        cout << dp[n].ans << endl;
        return 0;
}

