using namespace std;
typedef long long ll;
typedef pair<int,int> PII;
typedef vector<int> VI;

const int INF = 1e9 + 100;

int main() {
	int N;
	scanf("%d", &N);
	priority_queue<PII> pq;
	int Xs = INF, Xm = 0;
	int Ys = INF, Ym = 0;
	for(int i = 0; i < N; i++) {
		int x, y;
		scanf("%d%d", &x, &y);
		if(x > y) swap(x, y);
		pq.push(MP(y, x));
		Xs = min(Xs, x);
		Ys = min(Ys, y);
		Xm = max(Xm, x);
		Ym = max(Ym, y);
	}
	ll ans = 1ll * (Xm - Xs) * (Ym - Ys);
	while(!pq.empty()) {
		PII u = pq.top(); pq.pop();
		if(u.S >= u.F) break;
		Xm = max(Xm, u.F);
		Ys = min(Ys, u.S);
		swap(u.F, u.S);
		pq.push(u);
		debug("%lld %lld -- %lld %lld\n", Xm, Xs, pq.top().F, Ys);
		ans = min(ans, 1ll * (Xm - Xs) * (pq.top().F - Ys));
	}
	cout << ans << endl;
	return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;
#define int ll

#define REP(i,n) for(int i=0;i<n;++i)
#define SORT(name) sort(name.begin(), name.end())
#define ZERO(p) memset(p, 0, sizeof(p))
#define MINUS(p) memset(p, -1, sizeof(p))
