	sort(sa+1,sa+n+n+1,cmp);
	for (int i=1;i<=n+n;i++) pos[i]=(sa[i]>n?sa[i]-n:sa[i]);
	Min=x[sa[1]];Max=x[sa[n+n]];
	solve1();solve2();
	printf("%lld\n",ans);
	return 0;
}

