int N;
struct node {
    int x,y,id;
}pos[MAXN * 2];
int64 ans = 1e18;
int st[2][MAXN][20],len[MAXN];
int cnt[MAXN],all;
int getmax(int l,int r) {
    int t = len[r - l + 1];
    return max(st[0][l][t],st[0][r - (1 << t) + 1][t]);
}
int getmin(int l,int r) {
    int t = len[r - l + 1];
    return min(st[1][l][t],st[1][r - (1 << t) + 1][t]);
}
void Solve_x() {
    sort(pos + 1,pos + 2 * N + 1,[](node a,node b){return a.x < b.x;});
    for(int i = 1 ; i <= 2 * N ; ++i) {
        st[0][i][0] = st[1][i][0] = pos[i].y;
    }

    for(int j = 1 ; j <= 19 ; ++j) {
        for(int i = 1 ; i <= 2 * N ; ++i) {
            if(i + (1 << j) - 1 > 2 * N) break;
            st[0][i][j] = max(st[0][i][j - 1],st[0][i + (1 << j - 1)][j - 1]);
            st[1][i][j] = min(st[1][i][j - 1],st[1][i + (1 << j - 1)][j - 1]);
        }
    }
    memset(cnt,0,sizeof(cnt));
    int p = 1,q = 0;all = 0;
    for(int i = 1 ; i <= 2 * N ; ++i) {
        while(all < N) {
            if(q == 2 * N) break;
            ++q;
            cnt[pos[q].id]++;
            if(cnt[pos[q].id] == 1) all++;
        }
        if(all < N) break;
        ans = min(1LL * (pos[q].x - pos[p].x) * (getmax(p,q) - getmin(p,q)),ans);
        --cnt[pos[p].id];
        if(cnt[pos[p].id] == 0) all--;
        ++p;
    }
}
void Solve_y() {
    sort(pos + 1,pos + 2 * N,[](node a,node b){return a.y < b.y;});
    for(int i = 1 ; i <= 2 * N ; ++i) {
        st[0][i][0] = st[1][i][0] = pos[i].x;
    }
    for(int j = 1 ; j <= 19 ; ++j) {
        for(int i = 1 ; i <= 2 * N ; ++i) {
            if(i + (1 << j) - 1 > 2 * N) break;
            st[0][i][j] = max(st[0][i][j - 1],st[0][i + (1 << j - 1)][j - 1]);
            st[1][i][j] = min(st[1][i][j - 1],st[1][i + (1 << j - 1)][j - 1]);
        }
    }
    memset(cnt,0,sizeof(cnt));
    int p = 1,q = 0;all = 0;
    for(int i = 1 ; i <= 2 * N ; ++i) {
        while(all < N) {
            if(q == 2 * N) break;
            ++q;
            ++cnt[pos[q].id];
            if(cnt[pos[q].id] == 1) ++all;
        }
        if(all < N) break;
        ans = min(ans,1LL * (pos[q].y - pos[p].y) * (getmax(p,q) - getmin(p,q)));
        --cnt[pos[p].id];
        if(cnt[pos[p].id] == 0) --all;
        ++p;
    }
}
void Solve() {
    read(N);
    int x,y;
    for(int i = 1 ; i <= N ; ++i) {
        read(x);read(y);
        pos[2 * i - 1] = (node){x,y,i};
        pos[2 * i] = (node){y,x,i};
    }
    for(int i = 2 ; i <= 2 * N ; ++i) len[i] = len[i / 2] + 1;
    Solve_x();Solve_y();
    out(ans);enter;
}
