ll N;
vector<P> balls;
vector<P> bags;
const ll INF = 5e15;

ll check1(){
    ll rmax, rmaxb;
    tie(rmax, rmaxb) = balls[balls.size() - 1];
    ll rmin, rminb;
    ll idx;
    for(idx = 0; idx < balls.size(); idx++){
        if(balls[idx].second != rmaxb){
            tie(rmin, rminb) = balls[idx];
            break;
        }
    }
    ll bmin = INF, bmax = 0;
    vector<bool> used(N, 0);
    used[rmaxb] = 1;
    used[rminb] = 1;
    for(ll i = 0; i < balls.size() - 1; i++){
        if(i == idx) continue;
        ll v, bn;
        tie(v, bn) = balls[i];
        if(used[bn]){
            bmin = min(bmin, v);
            bmax = max(bmax, v);
        }else{
            used[bn] = 1;
        }
    }
    return (rmax - rmin) * (bmax - bmin);
}

ll check2(){
    ll rmax, rmaxb, bmin, bminb;
    tie(rmax, rmaxb) = balls[balls.size() - 1];
    tie(bmin, bminb) = balls[0];
    ll bmax = 0, rmin = INF;
    for(ll i = 0; i < N; i++){
        if(i == rmaxb && i == bminb){
            continue;
        }else if(i == rmaxb){
            bmax = max(bmax, bags[i].first);
        }else if(i == bminb){
            rmin = min(rmin, bags[i].second);
        }else{
            bmax = max(bmax, bags[i].first);
            rmin = min(rmin, bags[i].second);
        }
    }
    return (rmax - rmin) * (bmax - bmin);
}

