        balls.push_back(P(x, i));
        balls.push_back(P(y, i));
        bags.push_back(P(x, y));
    }
    if(N == 1){
        cout << 0 << endl;
        return 0;
    }
    sort(balls.begin(), balls.end());
    cout << min(check1(), check2()) << endl;
