    {
        rmin = min(rmin, v[i].y);
        bmax = max(bmax, v[i].x);
    }
    ans = (long long)(rmax - rmin) * (bmax - bmin);
}
void RmaxRminCase()
{
    bmin = rmax = vmax;
    rmin = vmin;

    Min[n] = v[n].x;
    for (int i = n - 1; i >= 1; -- i)
        Min[i] = min(Min[i + 1], v[i].x);
