    {
        while (v[i].y <= bmax && i <= n)
        {
            bmin = min(bmin, v[i].y);
            ++ i;
        }

        if (i <= n)
            bmin = min(bmin, Min[i]);
        ans = min(ans, (long long)(rmax - rmin) * (bmax - bmin));
    }
}
