int main(){
    ll N;
    cin >> N;
    vector<Pll> ball(N);
    ll uppermax=0,uppermin=INF,lowermax=0,lowermin=INF;
    ll maxid,minid;
    rep(i,N){
        ll x,y;
        cin >> x >> y;
        if (x<y) swap(x,y);
        if (chmax(uppermax,x)) maxid=i;
        chmin(uppermin,x);
        chmax(lowermax,y);
        chmin(lowermin,y);
        ball[i]=Pll(x,y);
    }
    ll ans=(uppermax-uppermin)*(lowermax-lowermin);
    ll restmin=INF;
    rep(i,N){
