//Base class for Segment Trees
template <class T>
class segtree_base
{
protected:
	size_t width;
	vector<T> vec;
	T def;
	virtual T query_raw(int l_, int r_, int a_, int b_, int k_) = 0;
public:
	segtree_base(size_t size_, const T& def_ = T()) : def(def_)
	{
		width = 1;
		while (width < size_)width *= 2;
		vec.resize(width * 2 - 1, def);
	}
	T query(int left, int right)
	{
		return query_raw(left, right, 0, width, 0);
	}
	virtual ~segtree_base() {}
};

//Range Minimum Tree
template <class T>
class rmq_tree : public segtree_base<T>
{
public:
	rmq_tree(size_t size_, const T& def) : segtree_base<T>(size_, def)
	{}
	void update(int index, T val)
	{
		auto &vec = this->vec;
		index += (this->width - 1);
		vec[index] = val;
		while (index > 0)
		{
			index = (index - 1) / 2;
			vec[index] = min(vec[index * 2 + 1], vec[index * 2 + 2]);
		}
	}
private:
	T query_raw(int l_, int r_, int a_, int b_, int k_)override
	{
		const auto &vec = this->vec;
		if (l_ <= a_ && b_ <= r_)
		{
			return vec[k_];
		}
		if (b_ <= l_ || r_ <= a_)
		{
			return this->def;
		}
		int m = (a_ + b_) / 2;
		return min(
			query_raw(l_, r_, a_, m, k_ + k_ + 1),
			query_raw(l_, r_, m, b_, k_ + k_ + 2));
	}
};

LL n;
LL x[234567], y[234567];
vector<pair<LL, LL>>vec;
int main(void)
{
	cin >> n;
	LL sml = INT_MAX;
	for (int i = 0; i < n; ++i)
	{
		cin >> x[i] >> y[i];
		sml = min(sml, x[i]);
		sml = min(sml, y[i]);
	}
	rmq_tree<LL> rmq(n, LLONG_MAX), lrmq(n, LLONG_MAX);
	rmq_tree<LL> rev(n, 12345678901234567ll), lrev(n, 12345678901234567ll);//maximumをとるので-1倍する
	vector<pair<LL, LL>>lim;
	LL nowt = 0;
	for (int i = 0; i < n; ++i)
	{
		vec.push_back({ x[i] - sml,y[i] - sml });
		if (vec.back().first > vec.back().second)
		{
			swap(vec.back().first, vec.back().second);
		}
		nowt = max(nowt, vec.back().first);
	}
	sort(vec.begin(), vec.end());
	LL kij = vec[0].second;
	for (int i = 0; i < n; ++i)
	{
		if (vec[i].second <= nowt)
		{
			if (abs(kij - vec[i].second) > abs(kij - vec[i].first))
			{
				swap(vec[i].first, vec[i].second);
			}
		}
		lim.push_back({ vec[i].second,i });
		lrmq.update(i, vec[i].first);
		lrev.update(i, -vec[i].first);
		rmq.update(i, vec[i].second);
		rev.update(i, -vec[i].second);
	}
	sort(lim.begin(), lim.end());
	LL ans = (-rev.query(0, n) - rmq.query(0, n)) * nowt;
	auto itr = lim.begin();
	while (itr != lim.end() && itr->first <= nowt)
	{
		++itr;
	}
	while (itr != lim.end())
	{
		nowt = itr->first;
		int index = itr->second;
		if (abs(kij - vec[index].second) > abs(kij - vec[index].first))
		{
			swap(vec[index].first, vec[index].second);
			lrmq.update(index, vec[index].first);
			lrev.update(index, -vec[index].first);
			rmq.update(index, vec[index].second);
			rev.update(index, -vec[index].second);
		}
		LL can = (-rev.query(0, n) - rmq.query(0, n)) * /*nowt*/(-lrev.query(0, n) - lrmq.query(0, n));
		ans = min(ans, can);
		++itr;
	}
	cout << ans << endl;
	return 0;
}

