int cal(int r_min, int r_max, int x) {
    if (x < r_min) r_min = x;
    else if (x > r_max) r_max = x;
    return (r_max - r_min);
}

void alter(int& v_min, int& v_max, int v) {
    if (v < v_min) v_min = v;
    else if (v > v_max) v_max = v;
}

int main()
{
    int N;
