        cin >> x >> y;
        if (i == 0) {
            r_min = r_max = x;
            b_min = b_max = y;
            ans = 0;
        } else {
            LL a1 = 1LL * cal(r_min, r_max, x) * 1LL * cal(b_min, b_max, y);
            LL a2 = 1LL * cal(r_min, r_max, y) * 1LL * cal(b_min, b_max, x);
            if (a1 <= a2) {
                alter(r_min, r_max, x);
                alter(b_min, b_max, y);
                ans = a1;
            } else {
                alter(r_min, r_max, y);
                alter(b_min, b_max, x);
                ans = a2;
            }
        }
    }
    cout << ans << endl;
    return 0;;
}

