    // 最小の値も最大の値も赤にする場合
    // → 青が取る区間を最小にするのが最善
    if(pair_pos[0] == 2 * N - 1 && XY[0].first != XY[1].first && XY[2 * N - 1] != XY[2 * N - 2]) {
        // 最大と最小が同じ袋
        printf("%lld\n", ans);
        return 0;
    }

    ll pos1 = 0;
    ll pos2 = 2 * N - 1;
    if(pair_pos[0] == 2 * N - 1) {
        // 同じ袋の玉を選ぼうとしてしまっているので避ける
        if(XY[0].first == XY[1].first) { pos1 = 1; }
        else if(XY[2 * N - 1].first == XY[2 * N - 2].first) { pos2 = 2 * N - 2; }
        else { assert(false); }
    }
    r_min = XY[pos1].first;
    r_max = XY[pos2].first;
    b_min = min(XY[pair_pos[pos1]].first, XY[pair_pos[pos2]].first);
    b_max = max(XY[pair_pos[pos1]].first, XY[pair_pos[pos2]].first);
    color.assign(2 * N, Suspend);
    color[pos1] = Red;
    color[pos2] = Red;
    color[pair_pos[pos2]] = Blue;
    color[pair_pos[pos1]] = Blue;

    cnt = 2;
    ll l = min(pair_pos[pos1], pair_pos[pos2]);
    ll r = max(pair_pos[pos1], pair_pos[pos2]);
    ll base_l = l;
    ll base_r = r;
    // まず [b_min, b_max] の中でまだ色が決まっていないやつを手当たり次第に取る
    for(ll i = base_l + 1; i < base_r; ++i) {
        if(color[i] == Suspend) {
            color[i] = Blue;
            color[pair_pos[i]] = Red;
            cnt++;
        }
        if(cnt == N) { break; }
    }
    // まだ色がついていない場所があるなら、なるべく青の max - min が
    // 大きくならないような範囲を探す
    while(cnt < N) {
        ll next_l = (l > 0) ? l - 1 : 0;
        ll next_r = (r < N - 1) ? r + 1 : N - 1;
        if(color[next_l] == Suspend && color[next_r] == Suspend) {
            // どちらか近い方をとる
            ll sub_l = abs(XY[base_l].first - XY[next_l].first);
            ll sub_r = abs(XY[base_r].first - XY[next_r].first);
            if(sub_l < sub_r) {
                color[next_l] = Blue;
                color[pair_pos[next_l]] = Red;
                l = next_l;
            }
            else {
                color[next_r] = Blue;
                color[pair_pos[next_r]] = Red;
                r = next_r;
            }
            cnt++;
        }
        else if(color[next_l] == Suspend && color[next_r] != Suspend) {
            // l をとる
            color[next_l] = Blue;
            color[pair_pos[next_l]] = Red;
            l = next_l;
            r = next_r;
            cnt++;
        }
        else if(color[next_l] != Suspend && color[next_r] == Suspend) {
            // r をとる
            color[next_r] = Blue;
            color[pair_pos[next_r]] = Red;
            l = next_l;
            r = next_r;
            cnt++;
        }
        else {
            assert(l != next_l || r != next_r);
            l = next_l;
            r = next_r;
        }
    }
    assert(cnt == N);

    b_max = XY[r].first;
    b_min = XY[l].first;
    ans = min(ans, (r_max - r_min) * (b_max - b_min));

    printf("%lld\n", ans);

    return 0;
}

