};


struct Solver {
  long n;
  std::vector<std::array<long, 2>> xs;
  Solver() {
    S002 reader;
    reader >= n >n>= xs;
  }
  void solve() {
    for(auto& x : xs) {
      if( x[0] > x[1] ) std::swap(x[0], x[1]);
    }
    long lMin, lMax, rMin, rMax;
    lMin = lMax = xs[0][0];
    rMin = rMax = xs[0][1];
    for(long i = 1; i < n; ++i) {
      long t, s;
      {
        long nlMin = std::min(lMin, xs[i][0]);
        long nlMax = std::max(lMax, xs[i][0]);
        long nrMin = std::min(rMin, xs[i][1]);
        long nrMax = std::max(rMax, xs[i][1]);
        t = (nlMax - nlMin) * (nrMax - nrMin);
      }
      {
        long nlMin = std::min(lMin, xs[i][1]);
        long nlMax = std::max(lMax, xs[i][1]);
        long nrMin = std::min(rMin, xs[i][0]);
        long nrMax = std::max(rMax, xs[i][0]);
        s = (nlMax - nlMin) * (nrMax - nrMin);
      }
      if( t <= s ) {
        lMin = std::min(lMin, xs[i][0]);
        lMax = std::max(lMax, xs[i][0]);
        rMin = std::min(rMin, xs[i][1]);
