typedef long long ll;
typedef pair<ll, ll> pii;

const int N = 200005;
const long long oo = 1e9;

int n;
vector<pii>bags;

long long solve(){

	int minpos, maxpos;
	int mn=oo, mx=-oo;
	for(int i=0;i<bags.size();i++){
		pii u = bags[i];
		if(u.f < mn) mn = u.f, minpos = i;
		if(u.s > mx) mx = u.s, maxpos = i;
	}

	if(minpos == maxpos) return ll(1e18);

	long long rmin = mn, rmax = mx;
	long long bmin = oo, bmax = -oo;

	set<pii>maxset, minset;

	for(int i=0;i<bags.size();i++){
		if(i == minpos) bmin = min(bmin, bags[i].s);
		else if(i == maxpos) bmax = max(bmax, bags[i].f);
		else{
			maxset.insert({bags[i].s, i});
			minset.insert({bags[i].f, i});
		}
	}

	long long ret = 1e18;

	for(int i=0;i<bags.size();i++){
		if(i == minpos) continue;
		if(i == maxpos) continue;

		long long fmin = bmin;
		long long fmax = bmax;

		if(!maxset.empty()){
			auto u = maxset.begin();
			if((*u).f < bags[i].f) return ret;
		}

		while(!minset.empty()){
			auto u = minset.begin();

			if((*u).f >= bags[i].f) break;

			if(bags[(*u).s].s < bags[i].f) return ret;

			minset.erase(u);

			maxset.insert( {bags[(*u).s].s, (*u).s} );

		}
		fmin = min(fmin, bags[i].f);
		if(!maxset.empty()){
			auto u = maxset.end(); u--;
			fmax = max(fmax, (*u).f);
		}

		ret = min(ret, (rmax - rmin) * (fmax - fmin));

	}
	return ret;
}

int main(){
	long long x, y;
	scanf("%d", &n);
	long long rmin = oo, rmax = -oo;
	long long bmin = oo, bmax = -oo;
	for(int i=1;i<=n;i++){
		scanf("%lld %lld", &x, &y);
		if(x > y) swap(x, y);
		rmin = min(rmin, x);
		rmax = max(rmax, x);
		bmin = min(bmin, y);
		bmax = max(bmax, y);
		bags.push_back({x, y});
	}
	sort(bags.begin(), bags.end());
	long long ret = (rmax - rmin) * (bmax - bmin);
	ret = min(ret, solve());
	cout << ret << endl;
	return 0;
}

