  // when rmax == ma, bmin == mi
  ll rmax = ma, rmin = ma, bmax = mi, bmin = mi;
  rep (i, n) {
    rmin = min(rmin, y[i]);
    bmax = max(bmax, x[i]);
  }
  ans = (rmax - rmin) * (bmax - bmin);
  rmax = ma; rmin = mi;
  bmax = -INF, bmin = INF;
  vector<bool> used(n);
  rep (i, n) {
    if (x[i] == mi && y[i] == ma) {
      return ans;
    }
    if (x[i] == mi) {
      bmax = max(bmax, y[i]);
      bmin = min(bmin, y[i]);
      used[i] = true;
    }
    if (y[i] == ma) {
      bmax = max(bmax, x[i]);
      bmin = min(bmin, x[i]);
      used[i] = true;
