	used[i] = true;
	cnt++;
	continue;
      }
      if (in(x[i], bmin, bmax + 1) || in(y[i], bmin, bmax + 1)) {
	used[i] = true;
	cnt++;
	continue;
      }
      else {
	if (bmax < x[i]) {
	  used[i] = true;
	  cnt++;
	  bmax = x[i];
	}
	else if (y[i] < bmin) {
	  used[i] = true;
	  cnt++;
	  bmin = y[i];
	}
      }
    }
  }
  rep (i, n) {
    if (!used[i]) {
      xy.push_back(pll(x[i], y[i]));
    }
  }
  sort(all(xy));
  rep (i, xy.size()) {
    ans2 = min(ans2, (rmax - rmin) * (bmax - xy[i].first));
    bmax = max(bmax, xy[i].second);
  }
  ans2 = min(ans2, (rmax - rmin) * (bmax - bmin)); 
  //cout << ans << " " << ans2 << endl << flush ;
  return min(ans, ans2);
}


