void Solve2(){
	int maxm=max(pmax,pmin),minm=min(pmax,pmin);
	sort(a+1,a+n+1,Cmp);
	for(int i=1;i<=n;i++){
		if(a[i].b<minm) minm=a[i].b,vis[i]=true;
		else if(maxm<a[i].r) maxm=a[i].r,vis[i]=true;
		else if(minm<=a[i].r && a[i].r<=maxm) vis[i]=true;
		else if(minm<=a[i].b && a[i].b<=maxm) vis[i]=true;
	}
	for(int i=1;i<=n;i++) if(!vis[i]) Ans=min((maxn-minn)*(a[i].b-a[i].r),Ans);
