#include <cstdio>
#include <algorithm>

using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)

typedef long long ll;
typedef pair<int, int> P;

const int N_MAX = 200000;

int N;
int x[N_MAX];
int y[N_MAX];
P z[N_MAX];

bool compare_fa_sd(const P& p1, const P& p2) {
  if (p1.first != p2.first) return p1.first < p2.first;
  return p1.second > p2.second;
}

bool compare_sd_fa(const P& p1, const P& p2) {
  if (p1.second != p2.second) return p1.second > p2.second;
  return p1.first < p2.first;
}

void solve() {
  REP(i, N) {
    int zi = min(x[i], y[i]);
    int zx = max(x[i], y[i]);
    x[i] = zi; y[i] = zx;
    z[i] = P(zi, zx);
  }
  sort(z, z + N, compare_fa_sd);
  int ai = z[0].first; int bi = z[0].second;
  sort(z, z + N, compare_sd_fa);
  int ax = z[0].second; int bx = z[0].first;
  // printf("ai: %d, ax: %d, bi: %d, bx: %d\n", ai, ax, bi, bx);
  int ci = bi, cx = bx;
  REP(i, N) {
    if (x[i] > cx) cx = x[i];
    if (y[i] < ci) ci = y[i];
  }
  // printf("ai: %d, ax: %d, ci: %d, cx: %d\n", ai, ax, ci, cx);
  ll ans = (ll) (ax - ci) * (cx - ai);
  if (bi != ax) {
    int ci = min(bi, bx), cx = max(bi, bx);
    REP(i, N) {
      int dx = max(cx, x[i]) - min(ci, x[i]);
      int dy = max(cx, y[i]) - min(ci, y[i]);
      if (dx < dy) {
        cx = max(cx, x[i]); ci = min(ci, x[i]);
      } else {
        cx = max(cx, y[i]); ci = min(ci, y[i]);
      }
    }
    // printf("ai: %d, ax: %d, ci: %d, cx: %d\n", ai, ax, ci, cx);
    ll ans2 = (ll) (ax - ai) * (cx - ci);
    ans = min(ans, ans2);
  }
  printf("%lld\n", ans);
}

void input() {
  scanf("%d", &N);
  REP(i, N) scanf("%d%d", x + i, y + i);
}

int main() {
  input();
  solve();
  return 0;
}

