        input[i] = P(x, y);
        chmax(maxe, y);
        chmin(mine, x);
    }
    bool flag = false;
    for(int i = 0; i < n; ++i){
        int x = input[i].first, y = input[i].second;
        if((maxe == x && mine != y) || (maxe != x && mine == y) || (mine == x && maxe != y) || (mine != x && maxe == y)){
            flag = true;
            break;
        }
    }

    ll res = 1e+18;
    // max と min が異なるグループ
    int rmin = INF, bmax = 0;
    for(int i = 0; i < n; ++i){
        int x = input[i].first, y = input[i].second;
        chmin(rmin, y);
