int same()
{
	for (int i = 1; i <= N; i++)
		if (p[i].x > p[i].y)
			std::swap(p[i].x, p[i].y);
	std::sort(p + 1, p + N + 1, [] (const point &a, const point &b) { return a.x < b.x; });
