const int MAX_N = 200010;
const int MAX_V = 100010;
const double eps = 1e-6;
const ll mod = 1000000007;
const int inf = 1 << 29;
const ll linf = 1LL << 60;
const double PI = 3.14159265358979323846;
///////////////////////////////////////////////////////////////////////////////////////////////////

int N;
ll X[MAX_N], Y[MAX_N];
vector<pl> vec;

void solve() {
	cin >> N;
	ll minv = linf, maxv = 0;
	int minat = -1, maxat = -1;
	rep(i, 0, N) {
		cin >> X[i] >> Y[i];
		if(X[i] < Y[i]) swap(X[i], Y[i]);
		if(X[i] > maxv) {
			maxat = i;
			maxv = X[i];
		}
		if(Y[i] < minv) {
			minat = i;
			minv = Y[i];
		}
	}
	rep(i, 0, N) {
		if(i != maxat && i != minat) vec.pb(pl(X[i], Y[i]));
	}
	sort(all(vec), greater<pl>());
	ll res = linf;
	ll bv = Y[maxat], rv = X[minat];
	// debug(bv, rv);
	rep(i, 0, sz(vec)) {
		MAX(bv, vec[i].sec); MIN(rv, vec[i].fst);
	}
	// debug(maxv, rv, bv, minv);
	MIN(res, (maxv - rv) * (bv - minv));
	if(minat != maxat) {
		multiset<ll> B;
		rep(i, 0, sz(vec)) {
			B.insert(vec[i].sec);
		}
		B.insert(X[minat]); B.insert(Y[maxat]);
		rep(i, 0, sz(vec)) {
			B.erase(B.lower_bound(vec[i].sec));
			// debug(vl(all(B)));
			MIN(res, (maxv - minv) * (max(Y[maxat], vec[i].fst) - min(X[minat], (*B.begin()))));
			B.insert(vec[i].sec);
		}
	}
	cout << res << "\n";
}

