#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll N = 4e5 + 100, inF = 1e16;

ll n, m, ans, x[N], y[N];
vector<ll> help, l[N], r[N];

int f(int a) {
	return lower_bound(help.begin(), help.end(), a) - help.begin();
}

int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> x[i] >> y[i];
		if(x[i] > y[i])
			swap(x[i], y[i]);
		help.push_back(x[i]);
		help.push_back(y[i]);
	}
	sort(help.begin(), help.end());
	help.resize(unique(help.begin(), help.end()) - help.begin());
	for (int i = 0; i < n; i++) {
		x[i] = f(x[i]);
		y[i] = f(y[i]);
		l[x[i]].push_back(y[i]);
		r[y[i]].push_back(x[i]);
	}

	m = help.size();
	if(m == 1) {
		cout << 0;
		return 0;
	}
	ll max_l = *max_element(x, x + n), min_r = *min_element(y, y + n);
	ans = (help[max_l] - help[0]) * (help[m - 1] - help[min_r]);

	if(l[0][0] != m - 1) {
		ll maxi = -inF;
		multiset<int> st;
		for (ll num: l[0])
			st.insert(num), maxi = max(maxi, num);
		for (ll num: r[m - 1])
			st.insert(num), maxi = max(maxi, num);
		for (int i = 0; i < n; i++)
			if(x[i] != 0 && y[i] != m - 1)
				st.insert(y[i]);
		for (ll R = m - 1; R >= maxi; R--) {
			for (int num: r[R + 1])
				st.insert(num);
			ans = min(ans, (help[m - 1] - help[0]) * max(0LL, (help[R] - help[*st.begin()])));
		}
	}
	cout << ans;
	return 0;
}

