			}
			else{
				B_max=max(b[n-3].first,BM[i-1]);
				B_min=min(b[i].first,bm[i-1]);
			}
			B_max=max(B_max,a[IM].first);
			B_min=min(B_min,a[im].second);
			res=min(res,(R_max-R_min)*(B_max-B_min));
		}
	}
	cout<<res<<endl;
}

