const ll INF = 2e18;

ll f(double m,ll& mx,ll& mn)
{
	double res = 0.0;
	mx = -INF;
	mn = INF;
	FOR(i,0,N){
		if(allMin == i){
			chmax(mx,A [i + N]);
			chmin(mn,A [i + N]);
			chmax(res,abs(A [i + N] - m));
			continue;
		}
		if(allMin == i + N){
			chmax(mx,A [i]);
			chmin(mn,A [i]);
			chmax(res,abs(A [i] - m));
			continue;
		}
		if(allMax == i){
			chmax(mx,A [i + N]);
			chmin(mn,A [i + N]);
			chmax(res,abs(A [i + N] - m));
			continue;
		}
		if(allMax == i + N){
			chmax(mx,A [i]);
			chmin(mn,A [i]);
			chmax(res,abs(A [i] - m));
			continue;
		}
		if(abs(A [i] - m) <= abs(A [i + N] - m)){
			chmax(mx,A [i]);
			chmin(mn,A [i]);
			chmax(res,abs(A [i] - m));
		}
		else{
			chmax(mx,A [i + N]);
			chmin(mn,A [i + N]);
			chmax(res,abs(A [i + N] - m));
		}
	}
	return res;
}

