			}
			else{
				lo = mid1;
			}
		}
		f((lo + hi) / 2,r,l);
		chmin(ans,(rMax - rMin) * (r - l));
	}
	{
		ll rMax = A [allMax],rMin = INF;
		ll bMax = -INF,bMin = A [allMin];
		FOR(i,0,N){
