	for (int i = 0; i < n; ++i)
	{
		cin >> x[i] >> y[i];
		sml = min(sml, x[i]);
		sml = min(sml, y[i]);
	}
	rmq_tree<LL> rmq(n, LLONG_MAX), lrmq(n, LLONG_MAX);
	rmq_tree<LL> rev(n, 12345678901234567ll), lrev(n, 12345678901234567ll);//maximumをとるので-1倍する
	vector<pair<LL, int>>lim;
	LL nowt = 0;
	for (int i = 0; i < n; ++i)
	{
		vec.push_back({ x[i] - sml,y[i] - sml });
		if (vec.back().first > vec.back().second)
		{
			swap(vec.back().first, vec.back().second);
		}
		nowt = max(nowt, vec.back().first);
	}
	sort(vec.begin(), vec.end());
	LL kij = vec[0].second;
	for (int i = 0; i < n; ++i)
	{
		if (vec[i].second <= nowt)
		{
			if (abs(kij - vec[i].second) > abs(kij - vec[i].first))
			{
				swap(vec[i].first, vec[i].second);
			}
		}
		lim.push_back({ vec[i].second,i });
