    for (int i=1; i <= N; i++)
    {
        cin >> G[i].fi >> G[i].se;
        if (G[i].fi > G[i].se) swap(G[i].fi, G[i].se);
        A[++M] = ii(G[i].fi, i);
        A[++M] = ii(G[i].se, i);
    }
    sort(A+1, A+M+1);
    long long rmin = A[1].fi, rmax = 0, bmin = 1e9, bmax = A[M].fi;
    for (int i=1; i <= N; i++)
    {
        if (i == A[1].se)
        {
            bmin = min(bmin, G[i].se);
            continue;
        }
        if (i == A[M].se)
        {
            rmax = max(rmax, G[i].fi);
            continue;
        }
        bmin = min(bmin, G[i].se);
        rmax = max(rmax, G[i].fi);
    }
    ans = (rmax - rmin) * (bmax - bmin);
    rmin = A[1].fi; rmax = A[M].fi;
    int t = A[1].se; dd[t] = 1;
    bmin = bmax = G[t].se;
    t = A[M].se; dd[t] = 1;
    bmin = min(bmin, G[t].fi);
    bmax = max(bmax, G[t].fi);
    t = N; N = 0;
    for (int i=1; i <= t; i++)
        if (!dd[i]) G[++N] = G[i];
    sort(G+1, G+N+1);
    for (int i=1; i <= N; i++) bmax = max(bmax, G[i].fi);
    int j = 1;
