void solve(){
	int N;
	cin >> N;
	vector< pair<LL,LL> > XY(N);
	vector< pair<LL,int> > A(2*N);
	for(int i=0;i<N;++i){
		cin >> XY[i].first >> XY[i].second;
		if( XY[i].first > XY[i].second ){
			swap(XY[i].first,XY[i].second);
		}
		A[2*i+0].first = XY[i].first;
		A[2*i+0].second = i;
		A[2*i+1].first = XY[i].second;
		A[2*i+1].second = i;
	}
	sort( XY.begin(), XY.end() );
	sort( A.begin(), A.end() );
	LL Rmax,Rmin,Bmax,Bmin;
	//全体のmax,minが別の色
	LL ans = -1;
	{
		int minPos = A[0].second;
		int maxPos = A[2*N-1].second;
		Rmax = A[2*N-1].first;
		Rmin = INF;
		Bmax = 0;
		Bmin = A[0].first;
		for(int i=0;i<N;++i){
			if( i == minPos ){
				Rmin = min(Rmin,XY[i].second);
			}else if( i == maxPos){
				Bmax = max(Bmax,XY[i].first);
			}else{
				Rmin = min(Rmin,XY[i].second);
				Bmax = max(Bmax,XY[i].first);
			}
		}
		ans = (Rmax-Rmin)*(Bmax-Bmin);
	}
	//全体のmax,minが同じ色
	if(A[0].second == A[2*N-1].second){//同じ箱だと同じ色に出来ない
		cout << ans << endl;
		return;
	}
	Rmin =A[0].first;
	Rmax =A[2*N-1].first;
	LL Rwide = Rmax-Rmin;

	vector< pair<LL,LL> > ZZ;
	for(int i=0;i<N;++i){
		if( i == A[0].second ) continue;
		if( i == A[2*N-1].second ) continue;
		ZZ.push_back(XY[i]);
	}

	int size = ZZ.size();
	vector< pair<LL,LL> > XX(size),YY(size);//min,max

	for(int i=0;i<size;++i){
		if( i == 0 ){
			YY[i].first = ZZ[i].second;
			YY[i].second = ZZ[i].second;
		}else{
			YY[i].first = min(YY[i-1].first,ZZ[i].second);
			YY[i].second = max(YY[i-1].second,ZZ[i].second);
		}
	}
	for(int i=size-1;i>=0;--i){
		if( i == size-1 ){
			XX[i].first = ZZ[i].first;
			XX[i].second = ZZ[i].first;
		}
		else{
			XX[i].first = min(XX[i+1].first,ZZ[i].first);
			XX[i].second = max(XX[i+1].second,ZZ[i].first);
		}
	}
	if( size == 0 ){
		LL MIN = min(XY[ A[0].second ].second,
			XY[ A[2*N-1].second ].first);
		LL MAX = max(XY[ A[0].second ].second,
			XY[ A[2*N-1].second ].first);
		LL res = Rwide*(MAX-MIN);
		ans = min(ans,res);
		cout << ans << endl;
		return;
	}
	for(int i=0;i<=size;++i){
		LL MIN = min(XY[ A[0].second ].second,
			XY[ A[2*N-1].second ].first);
		LL MAX = max(XY[ A[0].second ].second,
			XY[ A[2*N-1].second ].first);
		//片方を使う
		//YY[i]
		if(i==0){
			MIN = min(MIN,XX[i].first);
			MAX = max(MAX,XX[i].second);
		}else if(i==size){
			MIN = min(MIN,YY[i-1].first);
			MAX = max(MAX,YY[i-1].second);
		}else{
			MIN = min(MIN,XX[i].first);
			MAX = max(MAX,XX[i].second);
			MIN = min(MIN,YY[i-1].first);
			MAX = max(MAX,YY[i-1].second);
		}
		LL res = Rwide*(MAX-MIN);
		ans = min(ans,res);
	}
	cout << ans << endl;
}

