void solve()
{
	ll n;  cin >> n;
	vector<pair<ll, ll>> xy = cinv2<ll, ll>(n);
	each(e, xy){
		if (e.first<e.second) swap(e.first, e.second);
	}

	sort(ALL(xy));

	pll lm=xy.back();  xy.pop_back();

	ll xmn=xy.front().first;
	ll xmx=lm.first;

	sort(ALL(xy), [](pll &a, pll &b){return a.second<b.second; });
	ll ymn=xy.front().second;
	ll ymx=max(xy.back().second, lm.second);
	ll ans=(xmx-xmn)*(ymx-ymn);

	ll yend=lm.second;

	rep(i,0,sz(xy)-1){
		ll x,y;  tie(x,y) = xy[i];
		if (y>=yend)break;

		chmin(xmn, y);
		chmax(ymx, x);
		chmin(yend, x);

		ymn=yend;
		if (i+1<=sz(xy)-1){
			chmin(ymn, xy[i+1].second);
		}

		chmin(ans, (xmx-xmn)*(ymx-ymn));
	}
	cout << ans << '\n';
}


