#include <bits/stdc++.h>
using namespace std;
#define maxn 200000
#define INF 999999999000000001LL
#define int long long
int n, N, tot, ans = INF, LL, RR;
int mark[maxn];

int read()
{
	int x = 0, k = 1;
	char c; c = getchar();
	while(c < '0' || c > '9') { if(c == '-') k = -1; c = getchar(); }
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x * k;
}

struct node
{
	int x, rec, id;
	friend bool operator <(const node& a, const node& b)
	{ return a.x < b.x; }
}P[maxn];

void Work1(int LL, int RR)
{
	for(int i = N - 1, t = INF, l = LL; i >= RR; i --)
	{
		t = min(t, P[i].rec);
		while(l >= t) l --; int k = l;
		if(P[l].id == P[i].id) k = l - 1;
	//	cout << "____" << i << " " << k <<" " << t <<endl;
		ans = min(ans, (P[i].x - P[k].x) * (P[N].x - P[1].x));
	} 
}

void Work2(int LL, int RR)
{
	if(P[LL].id == P[N].id) LL --;
	if(P[RR].id == P[1].id) RR ++;
	ans = min(ans, (P[N].x - P[LL].x) * (P[RR].x - P[1].x));
}

signed main()
{
	n = read(); N = 2 * n;
	for(int i = 1; i <= n; i ++)
	{
		P[++ tot].x = read(), P[tot].id = i;
		P[++ tot].x = read(), P[tot].id = i; 
	}
	sort(P + 1, P + 1 + tot);

	for(int i = 1; i <= N; i ++)
	{
		if(mark[P[i].id]) P[i].rec = mark[P[i].id], P[P[i].rec].rec = i;
		else mark[P[i].id] = i;
	}
	LL = 0, RR = N + 1;
	for(int i = 1; i <= N; i ++) if(P[i].rec < i) { LL = i; break; }
	for(int i = N; i >= 1; i --) if(P[i].rec > i) { RR = i; break; } 

	//cout << LL << " " << RR <<endl;
	if(P[N].id != P[1].id) Work1(LL, RR);
	//cout <<ans << endl;
	Work2(LL, RR);
	//cout << ans << endl;
	if(LL - 1 >= n && RR + 1 <= n + 1) ans = min(ans, (P[n].x - P[1].x) * (P[N].x - P[n + 1].x));
	printf("%lld\n", ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int maxn=200010;
int a[maxn],b[maxn],v[maxn<<1],p[maxn<<1],pos[maxn<<1],t[maxn],Min=1e9,Max,Mi=1e9,Mx,ma,mb,m,n;
int cmp(int a,int b) {
	return v[a]<v[b];
}
int main() {
	long long ans=0;
	scanf("%d",&n);
	for(int i=1;i<=n;i++) {
		scanf("%d%d",a+i,b+i);
		if(a[i]>b[i])swap(a[i],b[i]);
		if(Min>a[i])Min=a[ma=i];
		if(Max<b[i])Max=b[mb=i];
		Mi=min(Mi,b[i]);
		Mx=max(Mx,a[i]);
	}
	ans=1ll*(Max-Mi)*(Mx-Min);
	if(ma==mb) {
		printf("%lld\n",ans);
		return 0;
	}
	for(int i=1;i<=n;i++)
		if(ma!=i&&mb!=i) {
			p[++m]=i;
			v[m]=a[i];
			p[++m]=i;
			v[m]=b[i];
		}
	for(int i=1;i<=m;i++)pos[i]=i;
	sort(pos+1,pos+1+m,cmp);
	for(int i=1,j=0,cnt=0;i<=m;i++) {
		while(j<m&&cnt<n-2) {
			if(!t[p[pos[++j]]])cnt++;
			t[p[pos[j]]]++;
		}
		Mi=min(v[pos[i]],min(b[ma],a[mb]));
		Mx=max(v[pos[j]],max(b[ma],a[mb]));
		ans=min(ans,1ll*(Max-Min)*(Mx-Mi));
		t[p[pos[i]]]--;
		if(!t[p[pos[i]]])cnt--;
	}
	printf("%lld\n",ans);
	return 0;
}

#include <bits/stdc++.h>
#define F(i, x, y) for (int i = (x); i <= (y); ++i)
#define Fr(i, x, y) for (int i = (x); i < (y); ++i)
using namespace std;
typedef long long ll;

const int N = 200000 + 5;
int n, a[N], b[N], nd[N];
struct node {
	int bmx, bmn, rmx, rmn;
	node() { bmx = rmx = 0xcfcfcfcf; bmn = rmn = 0x3f3f3f3f; }
	void reset() {  bmx = rmx = 0xcfcfcfcf; bmn = rmn = 0x3f3f3f3f; }
	void add(int x, int y) {
		bmx = max(bmx, x);
		bmn = min(bmn, x);
		rmx = max(rmx, y);
		rmn = min(rmn, y); 
	}
	ll get() { return (ll)(bmx - bmn) * (rmx - rmn); }
}chance[N][41];

ll solve() {
	F(i, 1, n) {
		for (int k = 1; k <= 5; ++k) chance[i][k].reset();
		int t =  nd[i];
		F(j, 1, 5) {
			node cp = chance[i - 1][j];
			cp.add(a[t], b[t]);
			for (int k = 5; k >= 1; --k)
				if (chance[i][k].get() > cp.get()) {
					for (int lst = 1; lst < k; ++lst) chance[i][lst] = chance[i][lst + 1];
					chance[i][k] = cp;
					break;
				}
			cp = chance[i - 1][j];
			cp.add(b[t], a[t]);
			for (int k = 5; k >= 1; --k)
				if (chance[i][k].get() > cp.get()) {
					for (int lst = 1; lst < k; ++lst) chance[i][lst] = chance[i][lst + 1];
					chance[i][k] = cp;
					break;
				}
		}
	}

	ll ans = 0x3f3f3f3f3f3f3f3fll;
	for (int i = 1; i <= 5; ++i) ans = min(ans, chance[n][i].get());
	return ans;
}
int main() {
	ios::sync_with_stdio(0);
	cin >> n;
	F(i, 1, n) {
		cin >> a[i] >> b[i];
		nd[i] = i;
	}
	ll ans = 0x3f3f3f3f3f3f3f3fll;
	F(k, 1, 30) {
		random_shuffle(nd + 1, nd + n + 1);
		ans = min(ans, solve());
	}
	cout << ans << '\n';
	return 0;
}

