int N;
int X[MAX_N], Y[MAX_N];
pi VX[MAX_N], VY[MAX_N];
vector<int> vec;

void solve() {
	cin >> N;
	if(N == 0) {
		cout << "0\n";
		return;
	}
	rep(i, 0, N) {
		cin >> X[i] >> Y[i];
		VX[i] = pi(X[i], i);
		VY[i] = pi(Y[i], i);
		if(VX[i] > VY[i]) swap(VX[i], VY[i]);
	}
	sort(VX, VX + N);
	sort(VY, VY + N);
	/*
	debug(vector<pi>(VX, VX + N));
	debug(vector<pi>(VY, VY + N));
	*/
	vec.push_back(VX[0].sec);
	vec.push_back(VX[1].sec);
	vec.push_back(VY[N - 1].sec);
	vec.push_back(VY[N - 2].sec);
	sort(all(vec));
	vec.erase(unique(all(vec)), vec.end());
	//debug(vec);
	int n = vec.size();
	ll res = inf;
	rep(i, 0, (1 << n)) {
		ll maxx = -1, minx = inf, maxy = -1, miny = inf;
		rep(k, 0, n) {
			ll x = X[k], y = Y[k];
			if(i & (1 << k)) swap(x, y);
			MAX(maxx, x);
			MIN(minx, x);
			MAX(maxy, y);
			MIN(miny, y);
		}
		MIN(res, (maxx - minx) * (maxy - miny));
		//debug(res, i);
	}
	cout << res << "\n";
}

