			if (xd > yd) swap(xd, yd);
			if (xd >= mn2) mx2 = max(mx2, xd);
			else if (yd <= mx2) mn2 = min(mn2, yd);
			else u.push_back(make_pair(xd, yd));

		}
		u.swap(v);
		if (u.size() == v.size())
			break;
	}
	int xdd, ydd;
	for (int i = 0; i < v.size(); ++i) {
		xd = v[i].X, yd = v[i].Y;

