  vector<int> min(N);
  vector<int> max(N);
  for (int i = 0; i < N; ++i) min[i] = max[i] = i;
  sort(min.begin(), min.end(), [&xy](int ai, int bi) {
    const auto a = xy[ai];
    const auto b = xy[bi];
    return std::min(a.first, a.second) < std::min(b.first, b.second);
  });
  sort(max.begin(), max.end(), [&xy](int ai, int bi) {
    const auto a = xy[ai];
    const auto b = xy[bi];
    return std::max(a.first, a.second) > std::max(b.first, b.second);
  });

  map<int, bool> selected_map;
  for (int i = 0; i < N; ++i) {
    selected_map[min[i]] = true;
    selected_map[max[i]] = true;
    if (selected_map.size() >= 4) break;
  }

