            y = temp;
        }
   bool operator < ( const Ball &right ) const {
       return x <= right.x;
   }
};

int n;

long long solve(Ball b[200001]){
    long long xmax = 0, ymax = 0, xmin = INF, ymin = INF;
    rep(i,n){
        xmin = min(b[i].x, xmin);
        xmax = max(b[i].x, xmax);
        ymin = min(b[i].y, ymin);
        ymax = max(b[i].y, ymax);
    }
    return (xmax - xmin) * (ymax - ymin);
}

