long long solve()
{
        int res = 1e9;
        vector < pair < int, int > > v;
        for(int i = 1; i <= n; i++){
                v.push_back({a[i].fi, i});
                v.push_back({a[i].se, i});
        }
        sort(v.begin(), v.end());
        multiset < int > S;
        int cnt = 0;
        for(auto p: v){
                if(cur[p.se]){
                        S.erase(S.find(cur[p.se]));
                } else{
                        cnt += 1;
                }
                cur[p.se] = p.fi;
                S.insert(p.fi);
                if(cnt == n){
                        res = min(res, p.fi - *S.begin());
                }
        }
        return res;
}

