// Returns a tuple of (l, u) s.t.
// - l is the minimum value s.t. is_upper_fn(l) is false.
// - r is the minimum value s.t. is_upper_fn(r) is true.
//
// Required:
// - is_upper_fn is a function s.t.
//   - There exists a constant c s.t. is_upper_fn(x) is true for x >= c and
//     is_upper_fn(x) is false for x < c.
// - is_upper_fn(min_value) is false.
// - is_upper_fn(max_value) is true.
//
// Verified: ABC144E
tuple<int64, int64> BinarySearch(function<bool(int64)> is_upper_fn, int64 l, int64 u) {
  while (u - l >= 2) {
    int64 m = (l + u) / 2;
    if (is_upper_fn(m)) u = m; else l = m;
  }
  return make_tuple(l, u);
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<int64> xs(n);
  vector<int64> ys(n);

  for (int i = 0; i < n; i++) {
    cin >> xs[i];
    cin >> ys[i];
  }

  auto solve_1_fn = [&]() -> int64 {
    vector<int64> rs;
    vector<int64> bs;
    for (int i = 0; i < n; i++) {
      if (xs[i] >= ys[i]) {
        rs.push_back(xs[i]);
        bs.push_back(ys[i]);
      } else {
        rs.push_back(ys[i]);
        bs.push_back(xs[i]);
      }
    }
    sort(rs.begin(), rs.end());
    sort(bs.begin(), bs.end());
    return (rs[n - 1] - rs[0]) * (bs[n - 1] - bs[0]);
  };

  auto solve_2_fn = [&]() -> int64 {
    vector<int64> zs;
    for (int64 x : xs) zs.push_back(x);
    for (int64 y : ys) zs.push_back(y);
    sort(zs.begin(), zs.end());
    int64 c1 = zs.back() - zs.front();

    auto w_fn = [&](int64 c) -> int64 {
      auto is_upper_fn = [&](int64 w) -> bool {
        for (int i = 0; i < n; i++) {
          if (abs(xs[i] - c) > w && abs(ys[i] - c) > w) {
            return false;
          }
        }
        return true;
      };
      if (is_upper_fn(0)) return 0;
      int64 l, u;
      tie(l, u) = BinarySearch(is_upper_fn, 0, 2E9);
      return u;
    };
    int64 c2 = min(w_fn(xs[0]), w_fn(ys[0]));
    return c1 * c2;
  };

  int64 ans1 = solve_1_fn();
  int64 ans2 = solve_2_fn();
  int64 ans = min(ans1, ans2);
  cout << ans << endl;
}

