		long long rm = (1LL << 40), rM = 0, bm = (1LL << 40), bM = 0;
		for(int i=0;i<N;i++){
			rm = min(rm, p[i].first);
			rM = max(rM, p[i].first);
			bm = min(bm, p[i].second);
			bM = max(bM, p[i].second);
		}
		long long res = (rM - rm) * (bM - bm);
		if(key[0].second != key.back().second){
			vector<int> use(N, 0);
			int cnt = 0;
			int low = 1, high = 1;
			use[key[1].second] = 1;
