                rb = get3Max(b,r1,r2) - get3Min(b,r1,r2);
                ll add = (ra < rb) ? a : b;
                r1 = get3Min(add,r1,r2), r2 = get3Max(add,r1,r2);
            }
        }
        ans = min(ans, (getMax(v[mxi]) - getMin(v[mni])) * (r2 - r1));
    }
