const ll MOD=1e9+7;

ll mM(vector<pll> ps){
  ll a=min(ps[0].X,ps[0].Y);
  ll b=max(ps[0].X,ps[0].Y);
  ll A=a,B=b;
  for(pll p:ps){
    MN(a,min(p.X,p.Y));
    MX(A,min(p.X,p.Y));
    MN(b,max(p.X,p.Y));
    MX(B,max(p.X,p.Y));
  }
  return (B-b)*(A-a);
}
ll srt(vector<pll> ps){
  multiset<ll> a,b;
  for(pll p:ps) a.insert(p.X), b.insert(p.Y);
  sort(all(ps),[](const pll &p,const pll &q){return p.X+p.Y<q.X+q.Y;});
  ll re=(*b.rbegin()-*b.begin())*(*a.rbegin()-*a.begin());
  for(pll p:ps){
    a.erase(a.find(p.X));
    b.erase(b.find(p.Y));
    a.insert(p.Y);
    b.insert(p.X);
    MN(re,(*b.rbegin()-*b.begin())*(*a.rbegin()-*a.begin()));
  }
  return re;
}

