                out.push_back(make_pair(x[i],y[i]));
        sort(out.begin(),out.end());
        int right=mxi;
        for (size_t i=0;i<out.size();++i)
        {
            ans=min(ans,(long long)(mx-mn)*(right-out[i].first));
            right=max(right,out[i].second);
        }
        ans=min(ans,(long long)(mx-mn)*(right-mni));
    }
    printf("%lld\n",ans);
    return 0;
}

