long trace(const vector<pair<int, int>>& xy, vector<pair<bool, bool>>& color, int i)
{
  if (i >= xy.size()) {
    long min[2] = {10000000000, 10000000000}, max[2] = {0, 0};
    for (int i = 0; i < color.size(); ++i) {
      if (color[i].first) {
        if (min[0] > xy[i].first) min[0] = xy[i].first;
        if (max[0] < xy[i].first) max[0] = xy[i].first;
      } else {
        if (min[1] > xy[i].first) min[1] = xy[i].first;
        if (max[1] < xy[i].first) max[1] = xy[i].first;
      }
      if (color[i].second) {
        if (min[0] > xy[i].second) min[0] = xy[i].second;
        if (max[0] < xy[i].second) max[0] = xy[i].second;
      } else {
        if (min[1] > xy[i].second) min[1] = xy[i].second;
        if (max[1] < xy[i].second) max[1] = xy[i].second;
      }
    }
    return (max[0] - min[0]) * (max[1] - min[1]);
  }

  color[i].first = true;
  color[i].second = false;
  long v0 = trace(xy, color, i + 1);

  color[i].first = false;
  color[i].second = true;
  long v1 = trace(xy, color, i + 1);

  return v0 < v1 ? v0 : v1;
}

int main()
{
  int N;
  cin >> N;
  vector<pair<int, int>> xy(N);
  for (int i = 0; i < N; ++i) cin >> xy[i].first >> xy[i].second;

  vector<int> min(N);
  vector<int> max(N);
  for (int i = 0; i < N; ++i) min[i] = max[i] = i;
  sort(min.begin(), min.end(), [&xy](int ai, int bi) {
    const auto a = xy[ai];
    const auto b = xy[bi];
    return
      (a.first < b.first and a.first < b.second) or
      (a.second < b.first and a.first < b.second);
  });
  sort(max.begin(), max.end(), [&xy](int ai, int bi) {
    const auto a = xy[ai];
    const auto b = xy[bi];
    return
      (a.first > b.first and a.first > b.second) or
      (a.second > b.first and a.first > b.second);
  });

  map<int, bool> selected_map;
  for (int i = 0; i < N; ++i) {
    selected_map[min[i]] = true;
    selected_map[max[i]] = true;
    if (selected_map.size() >= 8) break;
  }

  vector<pair<int, int>> selected;
  for (auto i: selected_map) selected.push_back(xy[i.first]);

  // for (auto i: selected) cout << i.first << ", " << i.second << endl;
  vector<pair<bool, bool>> color(selected.size());

  cout << trace(selected, color, 0) << endl;
  return 0;
}

