		if (ans[i] > mn)
			break;
		while (s.begin()->x<ans[i]) {
			auto x = *s.begin();
			s.erase(s.begin());
			if (x.y < ans[i])
				return res;
			swap(x.x, x.y);
			s.insert(x);
		}
		int L = ans[i];
		int R = max(mx, (--s.end())->x);
		R = max(R, L);
		res = min(res, (r - l)*(R - L));
	}
	return res;
}
