      if(X[i]>Y[i]) swap(X[i],Y[i]);
  }

  int mat=0,mit=0;
  for(int i=0;i<N;i++){
      if(X[mit]>X[i]) mit=i;
      if(Y[mat]<Y[i]) mat=i;
  }

  ll ans=INF;
  if(mit!=mat){
      ll R=Y[mat]-X[mit];
      vector<pair<ll,ll>> v;
      for(int i=0;i<N;i++){
          if(i!=mit&&i!=mat) v.push_back(mkp(X[i],Y[i]));
