              ll t=max(ma,max(yma,v[i].first));
              s=min(s,v.back().first);
              t=max(t,v.back().first);

              ans=min(ans,R*(t-s));
              yma=max(yma,v[i].second);
              ymi=min(ymi,v[i].second);
