          ll ls=mi,lt=ma;//all X
          for(int i=0;i<v.size();i++){
              ls=min(ls,v[i].first);
              lt=max(lt,v[i].first);
          }
          ans=min(ans,R*(lt-ls));

          ls=mi;lt=ma;// all Y
          for(int i=0;i<v.size();i++){
              ls=min(ls,v[i].second);
              lt=max(lt,v[i].second);
          }
          ans=min(ans,R*(lt-ls));
      }
  }

  ll rmi=Y[mit],bma=X[mat];
  for(int i=0;i<N;i++){
      if(i==mat||i==mit) continue;
      rmi=min(rmi,Y[i]);
      bma=max(bma,X[i]);
  }
  ans=min(ans,(Y[mat]-rmi)*(bma-X[mit]));
  cout<<ans<<endl;

  return 0;
}

