    }
    int rMIN = 1e12, rMAX = 0, bMIN = 1e12, bMAX = 0;
    rep(i, 0, n){
        chmax(rMAX, x[i]);
        chmin(rMIN, x[i]);
        chmax(bMAX, y[i]);
        chmin(bMIN, y[i]);
    }
    int ans = (rMAX - rMIN) * (bMAX - bMIN);
    // cout << rMAX << " " << rMIN << " " << bMAX << " " << bMIN << endl;
    rep(i, 1, n){
        rMIN = d[i].first;
