ll solve1() {
  for(int i=0;i < n;i++)
    d.emplace_back(x[i], i),
    d.emplace_back(y[i], i);
  sort(begin(d), end(d));
  int rmin = d[0].first, bmax = d[n*2-1].first;
  int bmin = y[d[0].second], rmax = x[d[n*2-1].second];
  for(int i = 0; i < n ; i++) {
