        if (ps.size() == 0) {
            ans = min(ans, (rmax - rmin) * (bmax - bmin));
        }

        sort(ps);

        priority_queue<int64_t> que;

        for (int i : rep(0, ps.size())) {
            bmin = ps[i].first;
            que.push(ps[i].second);

            bmax = que.top();

            ans = min(ans, (rmax - rmin) * (bmax - bmin));
        }
    }

    {
        int64_t rmin = x[j], rmax = x[k], bmin = y[j], bmax = y[k];

        for (int i : rep(0, n)) {
            if (i == j || i == k) {
                continue;
            }

            rmax = max(rmax, x[i]);
            bmin = min(bmin, y[i]);
        }

        ans = min(ans, (rmax - rmin) * (bmax - bmin));
    }

    out(ans);
