        minn1 = min(minn1, a[i]), minn2 = min(minn2, b[i]), maxx1 = max(maxx1, a[i]), maxx2 = max(maxx2, b[i]);
        if(minn1 == a[i]) sum1++, pl1 = i;
        if(maxx2 == b[i]) sum2++, pl2 = i;
    }
    if(n <= 2){
        if(n == 1) printf("0");
        else printf("%lld", min(1ll * abs(a[2]-a[1]) * abs(b[2]-b[1]), 1ll * abs(b[2]-a[1]) * abs(b[1]-a[2])));
