    sort(s + 1, s + cnt + 1, cmp); t[cnt] = s[cnt].minn;
    per(i, cnt - 1, 1) t[i] = max(t[i + 1], s[cnt].minn);
    if(cnt == 0) ans = min(ans, 1ll * (maxx1 - minn2) * (maxx2 - minn1));
