	cin >> n;
	vector<pll> v(n);
	ll cmax = -1, cmin = INF, pmax = 0, pmin = 0;
	REP(i, n)cin >> v[i].first >> v[i].second;
	REP(i, n) {
		if (cmax < max(v[i].first, v[i].second)) {
			pmax = i;
			cmax = max(v[i].first, v[i].second);
		}
		if (cmin > min(v[i].first, v[i].second)) {
			pmin = i;
			cmin = min(v[i].first, v[i].second);
		}
	}
	//cmaxとcminがおなじ
	ll ans = INF*INF;
	if (pmin != pmax){

		auto s = v;
		ll c = INF*INF;
		REP(i, n) {
			if (i != pmin&&s[i].first > s[i].second)swap(s[i].first, s[i].second);
			else if (i == pmin&&s[i].first == cmin)swap(s[i].first, s[i].second);
		}
		sort(ALL(s));
		c = min(c, s[s.size() - 1].first - s[0].first);
		ll f = s[s.size() - 1].first;
		REP(i, n-1) {
			s[i].first = s[i].second;
			f = max(f, s[i].first);
			c = min(c,f-s[i+1].first);
