using namespace std;

struct St
{
	int small;
	int big;
	bool operator < (const St &st) const
	{
		if (st.small == small)
		{
			return st.big > big;
		}
		return st.small > small;
	}
};


int N;
St st[200000];

int func1()
{
	int max = INT_MIN;
	int max_i;
	for (int i = 0; i < N; i++)
	{
		if (max < st[i].big)
		{
			max = st[i].big;
			max_i = i;
		}
	}
	int min = INT_MAX;
	int min_i;
	for (int i = 0; i < N; i++)
	{
		if (i == max_i) continue;
		if (min > st[i].small)
		{
			min = st[i].small;
			min_i = i;
		}
	}

	int min_b = MIN(st[max_i].small, st[min_i].big);
	int max_b = MAX(st[max_i].small, st[min_i].big);
	int threshold = min_b;
	for (int i = 0; i < N; i++)
	{
		if (i == max_i || i == min_i) continue;
		min_b = MIN(min_b, st[i].small);
		max_b = MAX(max_b, st[i].small);
	}

	int min_val = (max - min) * (max_b - min_b);
	for (int i = 0; i < N; i++)
	{
		if (i == max_i || i == min_i) continue;
		if (st[i].big >= min_b)  break;

		min_b = MIN(threshold, st[i + 1].small);
		max_b = MAX(max_b, st[i].big);
		threshold = MIN(threshold, st[i].big);

		min_val = MIN(min_val, (max - min) * (max_b - min_b));
	}

	return min_val;
}

int func2()
{
	int min = st[0].small;
	int max = INT_MIN;
	int max_i;
	for (int i = 0; i < N; i++)
	{
		if (max < st[i].big)
		{
			max = st[i].big;
			max_i = i;
		}
	}
	int min_r = st[0].big;
	int max_b = st[max_i].small;
	for (int i = 1; i < N; i++)
	{
		if (i == max_i) continue;
		min_r = MIN(st[i].big, min_r);
		max_b = MAX(st[i].small, max_b);
	}
	return (max - min_r) * (max_b - min);
}

signed main()
{
	cin >> N;
	for (int i = 0; i < N; i++)
	{
		int x, y;
		cin >> x >> y;
		int max = MAX(x, y);
		int min = MIN(x, y);
		st[i].small = min;
		st[i].big = max;
	}
	ARY_SORT(st, N);

	if (N == 1)
	{
		return 0;
	}

	int val = MIN(func1(), func2());

	cout << val << endl;
}

