#define MAX_N   (200000)                  // 10^5
#define BASE    (1000000000 + 7)          // 10^9 + 7
#define INFI    (1000000000 + 7)          // 10^9 + 7
#define INFL    (1000000000000000000 + 7) // 10^18 + 7

int N;
ll X[MAX_N], Y[MAX_N];

ll score(range r) {
  return (r.rr - r.rl) * (r.br - r.bl);
}

class Compare {
public:
    bool operator () (const range &r1, const range &r2) {
      return score(r1) > score(r2);
    }
};

void solve() {
  priority_queue<range, vector<range>, Compare> pque[2];
  range rng = {X[0], X[0], Y[0], Y[0]};
  pque[0].push(rng);
  for (int i = 1; i < N; i++) {
    int x = (i - 1) % 2, y = i % 2;
    while (!pque[x].empty()) {
      rng = pque[x].top(); pque[x].pop();
      range rngs[2];
      rngs[0] = {min(X[i], rng.rl), max(X[i], rng.rr), min(Y[i], rng.bl), max(Y[i], rng.br)};
      rngs[1] = {min(Y[i], rng.rl), max(Y[i], rng.rr), min(X[i], rng.bl), max(X[i], rng.br)};
      pque[y].push(rngs[0]);
      pque[y].push(rngs[1]);
    }
  }

  cout << score(pque[(N - 1) % 2].top()) << endl;
}

int main() {
  cin >> N;
  for (int i = 0; i < N; i++) cin >> X[i] >> Y[i];

  solve();

  return 0;
}

