#define mod 1000000007

int main()
{
	int n;
	cin >> n;
	long long int amax = 0, amin = mod;
	long long int bmax = 0, bmin = mod;
	long long int x[200001], y[200001];
	for(int i = 0; i < n; i++){
		cin >> x[i] >> y[i];
		if(x[i] > amax){
			amax = x[i];
			bmax = bmin = y[i];
		}
		if(y[i] > amax){
			amax = y[i];
			bmax = bmin = x[i];
		}
		if(x[i] < amin){
			amin = x[i];
			bmax = bmin = y[i];
		}
		if(y[i] < amin){
			amin = y[i];
			bmax = bmin = x[i];
		}
	}
	for(int i = 0; i < n; i++){
		if(max(bmax, x[i]) - min(bmin, x[i]) < max(bmax, y[i]) - min(bmin, y[i])){
			bmax = max(bmax, x[i]);
			bmin = min(bmin, x[i]);
		} else {
			bmax = max(bmax, y[i]);
			bmin = min(bmin, y[i]);
		}
	}
	long long int ans = (amax - amin) * (bmax - bmin);
	bmin = amin;
	amin = mod;
	bmax = 0;
	for(int i = 0; i < n; i++){
		amin = min(amin, max(x[i], y[i]));
		bmax = max(bmax, min(x[i], y[i]));
	}
	ans = min(ans, (amax - amin) * (bmax - bmin));
	cout << ans << endl;
	return 0;
}

