            x.first ^= (v[x.second*2]^v[x.second*2+1]);
            S.erase(*S.rbegin()); S.insert(x);
            ans = min(ans,
                max(maxv, S.rbegin()->first) - min(minv, S.begin()->first));
        }
    }
