		scanf("%lld%lld",&A [i],&A [i + N]);
		B [i] = make_pair(A [i],i);
		B [i + N] = make_pair(A [i + N],i + N);
	}
	sort(B.begin(),B.end());
	allMax = max_element(A.begin(),A.end()) - A.begin();
	allMin = min_element(A.begin(),A.end()) - A.begin();

	ll ans = INF;
	if(allMax != allMin){
		ll rMax = A [allMax],rMin = A [allMin];
		ll lo = 0,hi = N * 2,mid1,mid2;
		while(hi - lo > 100){
			mid1 = (lo + lo + hi) / 3;
			mid2 = (lo + hi + hi) / 3;
			if(f(mid1) <= f(mid2)){
				hi = mid2;
			}
			else{
				lo = mid1;
			}
		}
		for(ll i = lo;i <= hi;i++){
			chmin(ans,(rMax - rMin) * f(lo));
			chmin(ans,(rMax - rMin) * f(hi));
		}
	}
	{
		ll rMax = A [allMax],rMin = INF;
		ll bMax = -INF,bMin = A [allMin];
		FOR(i,0,N){
			if(A [i] >= A [i + N]){
				chmax(rMax,A [i]);
				chmin(rMin,A [i]);
				chmax(bMax,A [i + N]);
				chmin(bMin,A [i + N]);
			}
			else{
				chmax(rMax,A [i + N]);
				chmin(rMin,A [i + N]);
				chmax(bMax,A [i]);
				chmin(bMin,A [i]);
			}
		}
		chmin(ans,(rMax - rMin) * (bMax - bMin));
	}

	printf("%lld\n",ans);

	return 0;
}

