	static class TaskE {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int[] x = new int[n];
			int[] y = new int[n];
			int maxPos = 0;
			for (int i = 0; i < n; i++) {
				x[i] = in.nextInt();
				y[i] = in.nextInt();
				if (x[i] < y[i]) {
					int t = x[i];
					x[i] = y[i];
					y[i] = t;
				}
				if (x[maxPos] < x[i]) {
					maxPos = i;
				}
			}

			{
				int t;
				t = x[maxPos];
				x[maxPos] = x[0];
				x[0] = t;
				t = y[maxPos];
				y[maxPos] = y[0];
				y[0] = t;
			}

			long ans = Long.MAX_VALUE / 2;
			for (int step = 0; step < 2; step++) {
				long rmax = x[0];
				long rmin = x[0];
				long bmax = y[0];
				long bmin = y[0];
				for (int i = 1; i < n; i++) {
