					bmax = Math.max(bmax, x[i]);
					bmin = Math.min(bmin, x[i]);
					int t;
					t = x[i];
					x[i] = y[i];
					y[i] = t;
				}
				ans = Math.min(ans, (rmax - rmin) * (bmax - bmin));
			}
			out.println(ans);
		}

