import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

	public static void main(String args[]) {
		FastScanner cin = new FastScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	private static void solve(FastScanner cin, PrintWriter cout) {
		assert solve(3, new int[][] { { 1, 2 }, { 3, 4 }, { 5, 6 } }) == 15;
		assert solve(3, new int[][] { { 1010, 10 }, { 1000, 1 }, { 20, 1020 } }) == 380;
		assert solve(2, new int[][] { { 1, 1 }, { 1000000000, 1000000000 } }) == 999999998000000001L;
		int n = cin.nextInt();
		int[][] xys = new int[n][];
		for (int i = 0; i < n; i++)
			xys[i] = new int[] { cin.nextInt(), cin.nextInt() };
		long ans = -1;
		ans = solve(n, xys);
		cout.println(ans);
	}

	private static long solve(int n, int[][] xys) {
		if (n == 1)
			return 0;
		int[][] balls = new int[2 * n][];
		for (int i = 0; i < n; i++) {
			balls[2 * i] = new int[] { xys[i][0], i };
			balls[2 * i + 1] = new int[] { xys[i][1], i };
		}
		Arrays.sort(balls, (ball1, ball2) -> Integer.compare(ball1[0], ball2[0]));

		int[] notFound = new int[n];
		int toFind = 0;

		long[] maxOfMin = new long[2];
		for (int j = 0; j < 2; j++) {
			Arrays.fill(notFound, 1);
			toFind = n;
			for (int i = j; i < balls.length; i++) {
				if (toFind == 0)
					break;
				toFind -= notFound[balls[i][1]];
				notFound[balls[i][1]] = 0;
				maxOfMin[j] = balls[i][0];
			}
		}

		long[] minOfMax = new long[2];
		for (int j = 0; j < 2; j++) {
			Arrays.fill(notFound, 1);
			toFind = n;
			for (int i = balls.length - 1 - j; i >= 0; i--) {
				if (toFind == 0)
					break;
				toFind -= notFound[balls[i][1]];
				notFound[balls[i][1]] = 0;
				minOfMax[j] = balls[i][0];
			}
		}

		long ans = Long.MAX_VALUE;
		// min-allpairs, max-allpairs
		ans = Math.min(ans, (maxOfMin[0] - balls[0][0]) * (balls[balls.length - 1][0] - minOfMax[0]));
		// min-max, 2ndlargest-allpairs
		ans = Math.min(ans, (balls[balls.length - 1][0] - balls[0][0]) * (balls[balls.length - 2][0] - minOfMax[1]));
		// min-max, 2ndsmallest-allpairas
		ans = Math.min(ans, (balls[balls.length - 1][0] - balls[0][0]) * (maxOfMin[1] - balls[1][0]));
		return ans;
	}

	/**
	 * How to read input in Java — tutorial <br />
	 * By Flatfoot<br />
	 * http://codeforces.com/blog/entry/7018
	 */
	static class FastScanner {
		private BufferedReader br;
		private StringTokenizer st;

		FastScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements())
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new IllegalStateException(e);
				}
			return st.nextToken();
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				throw new IllegalStateException(e);
			}
			return str;
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
    static InputStream is;
    static PrintWriter out;
    static String INPUT = "";

    int n;
    long[] x, y;

    void solve() {
        n = ni();
        x = new long[n];
        y = new long[n];
        for (int i = 0; i < n; ++i) {
            x[i] = nl();
            y[i] = nl();
            if (x[i] > y[i]) {
                long t = x[i];
                x[i] = y[i];
                y[i] = t;
            }
        }
        long q;
        {
            long ra = 0, ri = Long.MAX_VALUE;
            long ba = 0, bi = Long.MAX_VALUE;
            for (int i = 0; i < n; ++i) {
                ra = Math.max(ra, x[i]);
                ri = Math.min(ri, x[i]);
                ba = Math.max(ba, y[i]);
                bi = Math.min(bi, y[i]);
            }
            q = (ra - ri) * (ba - bi);
        }
        long ri = 0;
        long li = Long.MAX_VALUE / 2;
        while (li - ri > 10) {
            long ai = ri + (li - ri) / 3;
            long av = calc(ai);
            long bi = ai + (li - ai) / 2;
            long bv = calc(bi);
            if (av > bv) {
                ri = ai;
            } else {
                li = bi;
            }
        }
        for (long i = ri; i <= li; ++i) {
            q = Math.min(q, calc(i));
        }
        out.println(q);
    }

    long calc(long a) {
        long ra = 0, ri = Long.MAX_VALUE;
        long ba = 0, bi = Long.MAX_VALUE;
        for (int i = 0; i < n; ++i) {
            if (Math.abs(a - x[i]) < Math.abs(a - y[i])) {
                ra = Math.max(ra, x[i]);
                ri = Math.min(ri, x[i]);
                ba = Math.max(ba, y[i]);
                bi = Math.min(bi, y[i]);
            } else {
                ra = Math.max(ra, y[i]);
                ri = Math.min(ri, y[i]);
                ba = Math.max(ba, x[i]);
                bi = Math.min(bi, x[i]);
            }
        }
        return (ra - ri) * (ba - bi);
    }

    public static void main(String[] args) throws Exception {
        long S = System.currentTimeMillis();
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);

        new Main().solve();
        out.flush();
        long G = System.currentTimeMillis();
        tr(G - S + "ms");
    }

    private static boolean eof() {
        if (lenbuf == -1) return true;
        int lptr = ptrbuf;
        while (lptr < lenbuf)
            if (!isSpaceChar(inbuf[lptr++])) return false;

        try {
            is.mark(1000);
            while (true) {
                int b = is.read();
                if (b == -1) {
                    is.reset();
                    return true;
                } else if (!isSpaceChar(b)) {
                    is.reset();
                    return false;
                }
            }
        } catch (IOException e) {
            return true;
        }
    }

    private static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    private static int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = is.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    private static boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private static int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b))
            ;
        return b;
    }

    private static double nd() {
        return Double.parseDouble(ns());
    }

    private static char nc() {
        return (char) skip();
    }

    private static String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != ' ')
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private static char[] ns(int n) {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n && !(isSpaceChar(b))) {
            buf[p++] = (char) b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private static char[][] nm(int n, int m) {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++)
            map[i] = ns(m);
        return map;
    }

    private static int[] na(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = ni();
        return a;
    }

    private static int ni() {
        int num = 0, b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
            ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static long nl() {
        long num = 0;
        int b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
            ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) {
        if (INPUT.length() != 0) System.out.println(Arrays.deepToString(o));
    }

    private static void debug(Object... o) {
        System.out.println(Arrays.deepToString(o));
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.Arrays;
import java.io.IOException;
import java.util.Random;
import java.util.TreeSet;
import java.io.UncheckedIOException;
import java.io.Closeable;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author daltao
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "daltao", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            TaskE solver = new TaskE();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class TaskE {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();

            int[][] balls = new int[n][2];
            int rMax = 0;
            int bMax = 0;
            int rMin = (int) 1e9;
            int bMin = rMin;
            for (int i = 0; i < n; i++) {
                int a = in.readInt();
                int b = in.readInt();
                if (a > b) {
                    int tmp = a;
                    a = b;
                    b = tmp;
                }
                balls[i][0] = a;
                balls[i][1] = b;
                rMax = Math.max(rMax, a);
                rMin = Math.min(rMin, a);
                bMax = Math.max(bMax, b);
                bMin = Math.min(bMin, b);
            }

            long ans = (long) (rMax - rMin) * (bMax - bMin);

            rMin = Math.min(rMin, bMin);
            rMax = Math.max(rMax, bMax);
            TreeSet<int[]> orderByMin = new TreeSet<>((a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);
            TreeSet<int[]> orderByMax = new TreeSet<>((a, b) -> a[1] == b[1] ? a[0] - b[0] : a[1] - b[1]);
            for (int[] ball : balls) {
                orderByMin.add(ball);
            }

            IntList seq = new IntList(n * 2);
            for (int i = 0; i < n; i++) {
                seq.add(balls[i][0]);
                seq.add(balls[i][1]);
            }
            seq.unique();
            for (int i = 0; i < seq.size(); i++) {
                int v = seq.get(i);
                while (!orderByMin.isEmpty() && orderByMin.first()[0] < v) {
                    int[] ball = orderByMin.pollFirst();
                    orderByMax.add(ball);
                }
                if (!orderByMax.isEmpty() && orderByMax.first()[1] < v) {
                    break;
                }
                int mx = 0;
                if (!orderByMin.isEmpty()) {
                    mx = Math.max(mx, orderByMin.last()[0]);
                }
                if (!orderByMax.isEmpty()) {
                    mx = Math.max(mx, orderByMax.last()[1]);
                }

                ans = Math.min(ans, (long) (rMax - rMin) * (mx - v));
            }

            out.println(ans);
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }

    static class Randomized {
        static Random random = new Random();

        public static void randomizedArray(int[] data, int from, int to) {
            to--;
            for (int i = from; i <= to; i++) {
                int s = nextInt(i, to);
                int tmp = data[i];
                data[i] = data[s];
                data[s] = tmp;
            }
        }

        public static int nextInt(int l, int r) {
            return random.nextInt(r - l + 1) + l;
        }

    }

    static class FastOutput implements AutoCloseable, Closeable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput println(long c) {
            cache.append(c).append('\n');
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

    }

    static class IntList {
        private int size;
        private int cap;
        private int[] data;
        private static final int[] EMPTY = new int[0];

        public IntList(int cap) {
            this.cap = cap;
            if (cap == 0) {
                data = EMPTY;
            } else {
                data = new int[cap];
            }
        }

        public IntList(IntList list) {
            this.size = list.size;
            this.cap = list.cap;
            this.data = Arrays.copyOf(list.data, size);
        }

        public IntList() {
            this(0);
        }

        private void ensureSpace(int need) {
            int req = size + need;
            if (req > cap) {
                while (cap < req) {
                    cap = Math.max(cap + 10, 2 * cap);
                }
                data = Arrays.copyOf(data, cap);
            }
        }

        private void checkRange(int i) {
            if (i < 0 || i >= size) {
                throw new ArrayIndexOutOfBoundsException();
            }
        }

        public int get(int i) {
            checkRange(i);
            return data[i];
        }

        public void add(int x) {
            ensureSpace(1);
            data[size++] = x;
        }

        public void sort() {
            if (size <= 1) {
                return;
            }
            Randomized.randomizedArray(data, 0, size);
            Arrays.sort(data, 0, size);
        }

        public void unique() {
            if (size <= 1) {
                return;
            }

            sort();
            int wpos = 1;
            for (int i = 1; i < size; i++) {
                if (data[i] != data[wpos - 1]) {
                    data[wpos++] = data[i];
                }
            }
            size = wpos;
        }

        public int size() {
            return size;
        }

        public int[] toArray() {
            return Arrays.copyOf(data, size);
        }

        public String toString() {
            return Arrays.toString(toArray());
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    static int N;
    static Box[] B;

    public static void main(String[] args) {
        FastScanner fc = new FastScanner(System.in);
        N = fc.nextInt();
        B = new Box[N];
        for (int i = 0; i < N; i++) {
            int x = fc.nextInt();
            int y = fc.nextInt();
            B[i] = new Box(i, x, y);
            B[i].reset();
        }
        System.out.println(solve());
    }

    static long solve() {
        if( N == 1 ) {
            return (long)(B[0].y - B[0].x) * (B[0].y - B[0].x);
        };

        // x < yに並べてあるのでそれを前提にしている
        int min = Integer.MAX_VALUE;
        int max = -1;

        for (int i = 0; i < N; i++) {
            if( min > B[i].x ) {
                min = B[i].x;
            }
            if( max < B[i].y ) {
                max = B[i].y;
            }
        }

        return Math.min(caseMinMaxIsOtherSize(min, max), caseMinMaxIsSameSide(min, max));
    }

    static long caseMinMaxIsSameSide(int min, int max) {
        // min, max どちらも片方に存在する場合
        // もう片側(はいい感じに選択して幅を最小にすることを目指すことができる

        Arrays.sort(B, Comparator.comparing(b -> b.x));

        long ans = (long)(B[N-1].x - B[0].x) * (max - min);
        int ymin = Integer.MAX_VALUE;
        int ymax = -1;
        for (int i = 0; i < N-1; i++) {
            Box box = B[i];

            ymax = Math.max(ymax, box.y);
            ymin = Math.min(ymin, box.y);

            ans = Math.min((long)(Math.max(B[N-1].x, ymax) - Math.min(B[i+1].x, ymin)) * (max - min), ans);
        }
        ymax = Math.max(ymax, B[N-1].y);
        ymin = Math.min(ymin, B[N-1].y);
        ans = Math.min((long)(ymax - ymin) * (max - min), ans);

        return ans;
    }

    static long caseMinMaxIsOtherSize(int min, int max) {
        int rmin = min;
        int rmax = -1;
        int bmin = Integer.MAX_VALUE;
        int bmax = max;

        for (Box b : B) {
            // boxの中身は x < y になってるはずだけどまぁ
            b.reset();

            rmax = Math.max(b.x, rmax);
            bmin = Math.min(b.y, bmin);
        }

        // System.out.println("(" + rmax + " - " + rmin + ") * (" + bmax + " - " +  bmin + ")");
        return (long)(rmax - rmin) * (bmax - bmin);
    }

    static class Box {
        int i, x, y;

        public Box(int i, int x, int y) {
            this.i = i;
            this.x = x;
            this.y = y;
        }

        void flip() {
            int t = x;
            x = y;
            y = t;
        }

        void reset() {
            if( x > y ) flip();
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

