      int y = ni();
      xs[i] = x;
      ys[i] = y;
    }
    long min = Long.MAX_VALUE;
    min = Math.min(min, left(n, xs, ys));
    min = Math.min(min, right(n, xs, ys));
    System.out.println(min);
  }

