    public static void solve() throws Exception {
        //longを忘れるなオーバーフローするぞ
        N = ni();
        int[] x = niah(N, 2);
        int[] y = niah(N, 2);
        PriorityQueue<Integer> rmax = new PriorityQueue<>(Comparator.reverseOrder());
        PriorityQueue<Integer> bmax = new PriorityQueue<>(Comparator.reverseOrder());
        PriorityQueue<Integer> rmin = new PriorityQueue<>();
        PriorityQueue<Integer> bmin = new PriorityQueue<>();
        rmax.add(x[0]);
        rmin.add(x[0]);
        bmax.add(y[0]);
        bmin.add(y[0]);
        for (int i = 1; i < N; i++) {
            long vx;
            {
                long rma = max(x[i], rmax.peek());
                long rmi = min(x[i], rmin.peek());
                long bma = max(y[i], bmax.peek());
                long bmi = min(y[i], bmin.peek());
                vx = (rma - rmi) * (bma - bmi);
            }
            long vy;
            {
                long rma = max(y[i], rmax.peek());
                long rmi = min(y[i], rmin.peek());
                long bma = max(x[i], bmax.peek());
                long bmi = min(x[i], bmin.peek());
                vy = (rma - rmi) * (bma - bmi);
            }
            if (vx < vy) {
                rmax.add(x[i]);
                rmin.add(x[i]);
                bmax.add(y[i]);
                bmin.add(y[i]);
            } else {
                rmax.add(y[i]);
                rmin.add(y[i]);
                bmax.add(x[i]);
                bmin.add(x[i]);
            }
        }
        long rma = rmax.peek();
        long rmi = rmin.peek();
        long bma = bmax.peek();
        long bmi = bmin.peek();
        long res = (rma - rmi) * (bma - bmi);
        System.out.println(res);
    }


