import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
    static InputStream is;
    static PrintWriter out;
    static String INPUT = "";

    int n;
    long[] x, y;

    void solve() {
        n = ni();
        x = new long[n];
        y = new long[n];
        for (int i = 0; i < n; ++i) {
            x[i] = nl();
            y[i] = nl();
            if (x[i] > y[i]) {
                long t = x[i];
                x[i] = y[i];
                y[i] = t;
            }
        }
        long q = Long.MAX_VALUE;
        {
            long ra = 0, ri = Long.MAX_VALUE;
            long ba = 0, bi = Long.MAX_VALUE;
            for (int i = 0; i < n; ++i) {
                ra = Math.max(ra, x[i]);
                ri = Math.min(ri, x[i]);
                ba = Math.max(ba, y[i]);
                bi = Math.min(bi, y[i]);
            }
            q = (ra - ri) * (ba - bi);
        }
        q = Math.min(q, calc(x[0] + 0));
        q = Math.min(q, calc(x[0] - 1));
        q = Math.min(q, calc(x[0] + 1));
        q = Math.min(q, calc(y[0] + 0));
        q = Math.min(q, calc(y[0] - 1));
        q = Math.min(q, calc(y[0] + 1));
        out.println(q);
    }

    long calc(long a) {
        long ra = 0, ri = Long.MAX_VALUE;
        long ba = 0, bi = Long.MAX_VALUE;
        for (int i = 0; i < n; ++i) {
            if (Math.abs(a - x[i]) < Math.abs(a - y[i])) {
                ra = Math.max(ra, x[i]);
                ri = Math.min(ri, x[i]);
                ba = Math.max(ba, y[i]);
                bi = Math.min(bi, y[i]);
            } else {
                ra = Math.max(ra, y[i]);
                ri = Math.min(ri, y[i]);
                ba = Math.max(ba, x[i]);
                bi = Math.min(bi, x[i]);
            }
        }
        return (ra - ri) * (ba - bi);
    }

    public static void main(String[] args) throws Exception {
        long S = System.currentTimeMillis();
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);

        new Main().solve();
        out.flush();
        long G = System.currentTimeMillis();
        tr(G - S + "ms");
    }

    private static boolean eof() {
        if (lenbuf == -1) return true;
        int lptr = ptrbuf;
        while (lptr < lenbuf)
            if (!isSpaceChar(inbuf[lptr++])) return false;

        try {
            is.mark(1000);
            while (true) {
                int b = is.read();
                if (b == -1) {
                    is.reset();
                    return true;
                } else if (!isSpaceChar(b)) {
                    is.reset();
                    return false;
                }
            }
        } catch (IOException e) {
            return true;
        }
    }

    private static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    private static int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = is.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    private static boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private static int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b))
            ;
        return b;
    }

    private static double nd() {
        return Double.parseDouble(ns());
    }

    private static char nc() {
        return (char) skip();
    }

    private static String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != ' ')
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private static char[] ns(int n) {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n && !(isSpaceChar(b))) {
            buf[p++] = (char) b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private static char[][] nm(int n, int m) {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++)
            map[i] = ns(m);
