    static class SegmentTree {
        int[] originalData;
        int[] mins;
        int[] maxs;
        long[] sums;

        int N;

        int INT_MAX = Integer.MAX_VALUE / 2;

        SegmentTree(int n) {
            N = 1;
            while (N < n) N *= 2;
            mins = new int[N * 2];
            maxs = new int[N * 2];
            sums = new long[N * 2];
            Arrays.fill(mins, INT_MAX);
        }


        SegmentTree(int[] nums) {
            N = 1;
            while (N < nums.length) N *= 2;
            mins = new int[N * 2];
            maxs = new int[N * 2];
            sums = new long[N * 2];
            Arrays.fill(mins, INT_MAX);
            originalData = nums.clone();
            //初期値をセット
            for (int i = 0; i < originalData.length; i++) {
                mins[i + N - 1] = originalData[i];
                maxs[i + N - 1] = originalData[i];
                sums[i + N - 1] = originalData[i];
            }

            //初期値を計算
            //下から2段目右端から左へ、上へ
            for (int i = N - 2; i >= 0; i--) {
                mins[i] = Math.min(mins[i * 2 + 1], mins[i * 2 + 2]);
                maxs[i] = Math.max(maxs[i * 2 + 1], maxs[i * 2 + 2]);
                sums[i] = sums[i * 2 + 1] + sums[i * 2 + 2];
            }
        }


        public void update(int i, int v) {
            i = N + i - 1;
            mins[i] = v;
            maxs[i] = v;
            sums[i] = v;

            while (i > 0) {
                i = (i - 1) / 2;
                mins[i] = Math.min(mins[i * 2 + 1], mins[i * 2 + 2]);
                maxs[i] = Math.max(maxs[i * 2 + 1], maxs[i * 2 + 2]);
                sums[i] = sums[i * 2 + 1] + sums[i * 2 + 2];
            }
        }

        public long sum(int start, int end) {
            return sum(start, end, 0, 0, N);
        }

        private long sum(int a, int b, int k, int l, int r) {
            if (b <= l || r <= a) return 0;

            if (a <= l && r <= b) return sums[k];
            else {
                long lv = sum(a, b, 2 * k + 1, l, (l + r) / 2);
                long rv = sum(a, b, 2 * k + 2, (l + r) / 2, r);
                return lv + rv;
            }
        }

        public int min(int start, int end) {
            return min(start, end, 0, 0, N);
        }

        private int min(int a, int b, int k, int l, int r) {
            if (b <= l || r <= a) return INT_MAX;
            if (a <= l && r <= b) return mins[k];
            else {
                int lv = min(a, b, 2 * k + 1, l, (l + r) / 2);
                int rv = min(a, b, 2 * k + 2, (l + r) / 2, r);
                return Math.min(lv, rv);
            }
        }

        public int max(int start, int end) {
            return max(start, end, 0, 0, N);
        }

        private int max(int a, int b, int k, int l, int r) {
            if (b <= l || r <= a) return MINF;
            if (a <= l && r <= b) return maxs[k];
            else {
                int lv = max(a, b, 2 * k + 1, l, (l + r) / 2);
                int rv = max(a, b, 2 * k + 2, (l + r) / 2, r);
                return Math.max(lv, rv);
            }
        }

    }

