public class Main {

	final long INF = 1001001001;
	void solve() {
		int N = sc.nextInt();
		int[][] p = new int[N][2];
		for (int i = 0; i < N; i++) {
			int x = sc.nextInt();
			int y = sc.nextInt();
			p[i][0] = Math.min(x, y);
			p[i][1] = Math.max(x, y);
		}
		sort(p, new Comparator<int[]>(){
			@Override
			public int compare(int[] a, int[] b) {
				if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
				return Integer.compare(a[1], b[1]);
			}
		});
		long Rmax = 0, Bmax = 0;
		long Rmin = INF, Bmin = INF;
		for (int i = 0; i < N; i++) {
			Rmax = max(Rmax, p[i][0]);
			Rmin = min(Rmin, p[i][0]);

			Bmax = max(Bmax, p[i][1]);
			Bmin = min(Bmin, p[i][1]);
		}
		long ans = (Rmax - Rmin) * (Bmax - Bmin);
		long Gmax = max(Rmax, Bmax);
		long Gmin = min(Rmin, Bmin);

		long c1 = INF, c2 = 0;
		for (int i = 0; i < N; i++) {
			if (p[i][0] == Gmin) {
				c1 = min(c1, p[i][1]);
				c2 = max(c2, p[i][1]);
			}
			if (p[i][1] == Gmax) {
				c1 = min(c1, p[i][0]);
				c2 = max(c2, p[i][0]);
			}
		}

		ans = min(ans, (Gmax - Gmin) * f(p, c1));
		ans = min(ans, (Gmax - Gmin) * f(p, c2));
		ans = min(ans, (Gmax - Gmin) * f(p, (c1 + c2)/2));
		out.println(ans);
	}

	long f(int[][]p, long c) {
		long max = 0;
		long min = INF;
		for (int i = 0; i < p.length; i++) {
			int k = abs(p[i][0] - c) < abs(p[i][1] - c) ? p[i][0] : p[i][1];
			max = max(max, k);
			min = min(min, k);
		}
		return max - min;
	}

