    long min = Integer.MAX_VALUE;

    long max2 = 0;
    long min2 = Integer.MAX_VALUE;

    for (int i = 0; i < N; i ++) {
      if (v[i][0] > v[i][1]) {
        long tmp = v[i][0];
        v[i][0] = v[i][1];
        v[i][1] = tmp;
      }
      max = Math.max(max, v[i][1]);
      min = Math.min(min, v[i][0]);

      max2 = Math.max(max2, v[i][0]);
      min2 = Math.min(min2, v[i][1]);
    }

    long ans = (max - min2) * (max2 - min);

