import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;
	static boolean debug = false;

	static void solve() {
		int n = ir.nextInt();
		long[][] a = new long[n][];
		for (int i = 0; i < n; i++) {
			a[i] = ir.nextLongArray(2);
			if (a[i][0] < a[i][1]) {
				long t = a[i][0];
				a[i][0] = a[i][1];
				a[i][1] = t;
			}
		}
		long[] ma = new long[2];
		long[] mi = new long[2];
		int[] idx = new int[2];
		Arrays.fill(mi, (long) 1e9 + 7);
		Arrays.sort(a, new Comparator<long[]>() {
			public int compare(long[] A, long[] B) {
				return Long.compare(A[0], B[0]);
			}
		});
		for (int i = 0; i < n; i++)
			for (int j = 0; j < 2; j++) {
				if ((j == 1 && mi[j] >= a[i][j])) {
					idx[j] = i;
				}
				ma[j] = Math.max(ma[j], a[i][j]);
				mi[j] = Math.min(mi[j], a[i][j]);
			}
		long res = (ma[0] - mi[0]) * (ma[1] - mi[1]);
		if (idx[0] != idx[1]) {
			long max = Math.max(a[idx[0]][1], a[idx[1]][0]);
			long min = Math.min(a[idx[0]][1], a[idx[1]][0]);
			long[][] b = new long[n - 2][];
			int p = 0;
			for (int i = 0; i < n; i++) {
				if (i != idx[0] && i != idx[1])
					b[p++] = a[i];
			}
			Arrays.sort(b, new Comparator<long[]>() {
				public int compare(long[] A, long[] B) {
					return Long.compare(B[0], A[0]);
				}
			});
			for (int i = 0; i < n - 2; i++) {
				res = Math.min(res, (ma[0] - mi[1]) * (Math.max(b[i][0], max) - Math.min(a[n - 3][0], min)));
				max = Math.max(max, a[i][1]);
				min = Math.min(min, a[i][1]);
			}
			res = Math.min(res, (ma[0] - mi[1]) * (max - min));
		}
		out.println(res);
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
