    readonly int mod = 1000000007;
    readonly string alfa = "abcdefghijklmnopqrstuvwxyz";

    int N;

    void Solve()
    {
        N = cin.Nextint;
        var X = new int[N];
        var Y = new int[N];


        var R = new int[N];
        var B = new int[N];

        var W = new Pair[N];
        for (int i = 0; i < N; i++)
        {
            X[i] = cin.Nextint;
            Y[i] = cin.Nextint;
            R[i] = Math.Min(X[i], Y[i]);
            B[i] = Math.Max(X[i], Y[i]);
            W[i] = new Pair(R[i], B[i]);
        }

        Array.Sort(R);Array.Sort(B);

        long ans = (long)(R[N - 1] - R[0]) * (B[N - 1] - B[0]);
       // WriteLine(ans);
        var J = new SortedSet<int>();
        W = W.OrderBy(i => i.Key).ToArray();
        int min = W[0].Key;
        int max = W[N - 1].Key;
        int diff = max - min;
       // WriteLine(diff);

        for (int i = 0; i < N; i++)
        {
            J.Add(W[i].Key);
        }

        for (int i = 0; i < N; i++)
        {
            J.Remove(W[0].Key);
            J.Add(W[0].Value);
            diff = Math.Min(diff, J.Last() - J.First());
        }
        long d = Math.Max(R[N - 1], B[N - 1]) - Math.Min(R[0], B[0]);

        ans = Math.Min(ans, d * diff);
        WriteLine(ans);

    }

