        }
        Array.Sort(X,Y);
        long count = (X[N-1]-X[0])*(maxY-minY);
        long M = X[N-1];
        long m = Y[0];
        for(int i=0;i<N;i++){
            count = Math.Min(count,(maxY-X[0])*(M-Math.Min(X[i],m)));
            m = Math.Min(m,Y[i]);
            M = Math.Max(M,Y[i]);
        }
        sb.Append(count+"\n");
    }
}

