	internal class Template
	{

		private void Solve()
		{
			var n = cin.NextLong();
			var a = new Tuple<int, int>[n];
			var tree1 = new Treap<int>();
			var tree2 = new Treap<int>();
			tree1.Min = tree2.Min = int.MaxValue;
			tree1.Max = tree2.Max = int.MinValue;
			for (var i = 0; i < n; i++)
			{
				var x = cin.NextInt();
				var y = cin.NextInt();
				a[i] = Tuple.Create(x, y);
				tree1.Add(a[i].Item1);
				tree2.Add(a[i].Item2);
			}
			a = a.OrderBy(x => x.Item1 - x.Item2).ToArray();
			var res = 1L * (tree1.Max - tree1.Min)*(tree2.Max - tree2.Min);
			for (var i = 0; i < a.Length; i++)
			{
				tree1.Remove(a[i].Item1);
				tree1.Add(a[i].Item2);
				tree2.Remove(a[i].Item2);
				tree2.Add(a[i].Item1);
				res = Math.Min(res, 1L * (tree1.Max - tree1.Min)*(tree2.Max - tree2.Min));
			}
			Console.WriteLine(res);
		}

		public class Treap<T>
		{
			private static Random rnd = new Random(13);

			public T Max, Min;

			public class Node
			{
				public readonly T Value;
				public readonly int Priority;
				public Node Left, Right;
				public Node(T value)
				{
					Value = value;
					Priority = rnd.Next();
				}
			}

			private class NodePair
			{
				public Node Left, Right;
				public NodePair(Node left, Node right)
				{
					Left = left;
					Right = right;
				}
			}

			private Node root;
			private readonly Comparison<T> compare;

			public Treap()
				: this(Comparer<T>.Default.Compare)
			{
			}

			public Treap(Comparison<T> compare)
			{
				this.compare = compare;
			}

			public void Add(T value)
			{
				NodePair pair = Split(root, value);
				root = Merge(Merge(pair.Left, new Node(value)), pair.Right);
				if (compare(Max, value) < 0)
					Max = value;
				if (compare(Min, value) > 0)
					Min = value;
			}

			public void Remove(T value)
			{
				root = Remove(root, value);
				if (compare(Min, value) == 0)
					Min = pMin(root);
				if (compare(Max, value) == 0)
					Max = pMax(root);
			}

			private NodePair Split(Node node, T value)
			{
				if (node == null)
					return new NodePair(null, null);
				if (compare(node.Value, value) >= 0)
				{
					NodePair leftSplit = Split(node.Left, value);
					node.Left = leftSplit.Right;
					leftSplit.Right = node;
					return leftSplit;
				}
				else
				{
					NodePair rightSplit = Split(node.Right, value);
					node.Right = rightSplit.Left;
					rightSplit.Left = node;
					return rightSplit;
				}
			}

			private Node Remove(Node node, T value)
			{
				if (node == null)
					return null;
				if (compare(value, node.Value) < 0)
				{
					node.Left = Remove(node.Left, value);
					return node;
				}
				if (compare(value, node.Value) > 0)
				{
					node.Right = Remove(node.Right, value);
					return node;
				}
				return Merge(node.Left, node.Right);
			}

			private static Node Merge(Node left, Node right)
			{
				if (left == null)
					return right;
				if (right == null)
					return left;
				if (left.Priority > right.Priority)
				{
					left.Right = Merge(left.Right, right);
					return left;
				}
				else
				{
					right.Left = Merge(left, right.Left);
					return right;
				}
			}

			private T pMin(Node node)
			{
				if (node.Left != null)
					return pMin(node.Left);
				return node.Value;
			}

			private T pMax(Node node)
			{
				if (node.Right != null)
					return pMax(node.Right);
				return node.Value;
			}
		}

		private static readonly Scanner cin = new Scanner();

		private static void Main()
