public class Solver
{
    public class Treap<T>
    {
        private static Random rnd = new Random(13);

        public class Node
        {
            public readonly T Value;
            public readonly int Priority;
            public Node Left, Right;
            public Node(T value)
            {
                Value = value;
                Priority = rnd.Next();
            }
        }

        private class NodePair
        {
            public Node Left, Right;
            public NodePair(Node left, Node right)
            {
                Left = left;
                Right = right;
            }
        }

        private Node root;
        private readonly Comparison<T> compare;

        public Treap()
            : this(Comparer<T>.Default.Compare)
        {
        }

        public Treap(Comparison<T> compare)
        {
            this.compare = compare;
        }

        public void Add(T value)
        {
            NodePair pair = Split(root, value);
            root = Merge(Merge(pair.Left, new Node(value)), pair.Right);
        }

        public void Remove(T value)
        {
            root = Remove(root, value);
        }

        private NodePair Split(Node node, T value)
        {
            if (node == null)
                return new NodePair(null, null);
            if (compare(node.Value, value) >= 0)
            {
                NodePair leftSplit = Split(node.Left, value);
                node.Left = leftSplit.Right;
                leftSplit.Right = node;
                return leftSplit;
            }
            else
            {
                NodePair rightSplit = Split(node.Right, value);
                node.Right = rightSplit.Left;
                rightSplit.Left = node;
                return rightSplit;
            }
        }

        private Node Remove(Node node, T value)
        {
            if (node == null)
                return null;
            if (compare(value, node.Value) < 0)
            {
                node.Left = Remove(node.Left, value);
                return node;
            }
            if (compare(value, node.Value) > 0)
            {
                node.Right = Remove(node.Right, value);
                return node;
            }
            return Merge(node.Left, node.Right);
        }

        private static Node Merge(Node left, Node right)
        {
            if (left == null)
                return right;
            if (right == null)
                return left;
            if (left.Priority > right.Priority)
            {
                left.Right = Merge(left.Right, right);
                return left;
            }
            else
            {
                right.Left = Merge(left, right.Left);
                return right;
            }
        }

        public T Min()
        {
            return Min(root);
        }

        private T Min(Node node)
        {
            if (node.Left != null)
                return Min(node.Left);
            return node.Value;
        }

        public T Max()
        {
            return Max(root);
        }

        private T Max(Node node)
        {
            if (node.Right != null)
                return Max(node.Right);
            return node.Value;
        }
    }

