	{
		if (unif[node] != 0)
		{
			seg[node] += unif[node];
			if (node < N2 - 1) { unif[2 * node + 1] += unif[node]; unif[2 * node + 2] += unif[node]; }
			unif[node] = 0;
		}
	}
