public class Solver
{
    public void Solve()
    {
        int n = ReadInt();
        var a = ReadIntMatrix(n);

        for (int i = 0; i < n; i++)
        {
            if (a[i][0] > a[i][1])
            {
                int t = a[i][0];
                a[i][0] = a[i][1];
                a[i][1] = t;
            }
        }

        Array.Sort(a, (a1, a2) => a1[0].CompareTo(a2[0]));
        var tr1 = new SortedSet<Tuple<int, int>>();
        var tr2 = new SortedSet<Tuple<int, int>>();
        for (int i = 0; i < n; i++)
        {
            tr1.Add(Tuple.Create(a[i][0], i));
            tr2.Add(Tuple.Create(a[i][1], i));
        }

        long ans = 1L * (tr1.Max.Item1 - tr1.Min.Item1) * (tr2.Max.Item1 - tr2.Min.Item1);
        for (int i = 0; i < n; i++)
        {
            tr1.Remove(Tuple.Create(a[i][0], i));
            tr1.Add(Tuple.Create(a[i][1], i));
            tr2.Remove(Tuple.Create(a[i][1], i));
            tr2.Add(Tuple.Create(a[i][0], i));
            ans = Math.Min(ans, 1L * (tr1.Max.Item1 - tr1.Min.Item1) * (tr2.Max.Item1 - tr2.Min.Item1));
        }

        Write(ans);
    }

    #region Main

    protected static TextReader reader;
    protected static TextWriter writer;
