                    minR = y[i];
                }
                if (x[i] < minB)
                {
                    minB = x[i];
                    index_minB = i;
                }
                if (maxB < x[i])
                {
                    maxB = x[i];
                }
            }
            long rv1 = (long)(maxR - minR) * (maxB - minB);
            long rv2 = int.MaxValue;
            if (minB <= maxR)
            {
                maxR = maxR;
                minR = minB;
                maxB = Math.Max(Math.Min(x[index_maxR], y[index_maxR]), Math.Max(x[index_minB], y[index_minB]));
                minB = Math.Min(Math.Min(x[index_maxR], y[index_maxR]), Math.Max(x[index_minB], y[index_minB]));
                for (int i = 0; i < N; ++i)
                {
                    if ((i != index_maxR )||(i != index_minB))
                    {
                        if (maxB < x[i])
                        {
                            maxB = x[i];
                        }
                        else if (maxB < y[i])
                        {
                            maxB = y[i];
                        }
                        if (y[i] < minB)
                        {
                            minB = y[i];
                        }
                        else if (x[i] < minB)
                        {
                            minB = x[i];
                        }
                    }
                }
                rv2 = (long)(maxR - minR) * (maxB - minB);
            }
            io.WriteLine(Math.Min(rv1, rv2).ToString());
        }
    }
