    void Solve()
    {
        N = cin.Nextint;
        var X = new int[N];
        var Y = new int[N];


        var R = new int[N];
        var B = new int[N];

        var W = new Pair[N];
        var J = new SortedSet<int>();
        for (int i = 0; i < N; i++)
        {
            X[i] = cin.Nextint;
            Y[i] = cin.Nextint;
            R[i] = Math.Min(X[i], Y[i]);
            B[i] = Math.Max(X[i], Y[i]);
            W[i] = new Pair(R[i], B[i]);
            J.Add(R[i]);
        }

        Array.Sort(R);Array.Sort(B);

        long ans = (long)(R[N - 1] - R[0]) * (B[N - 1] - B[0]);
       // WriteLine(ans);


        W = W.OrderBy(i => i.Key).ThenBy(i => i.Value).ToArray();
        int min = W[0].Key;
