        {
            if (J.First() < W[i].Key) break;
            J.Remove(W[i].Key);
            J.Add(W[i].Value);
            diff = Math.Min(J.Last() - J.First(), diff);

        }

        long d = Math.Max(R[N - 1], B[N - 1]) - Math.Min(R[0], B[0]);

        ans = Math.Min(ans, d * diff);
        WriteLine(ans);

    }

}

