        var B = new int[N];

        for (int i = 0; i < N; i++)
        {
            int x = cin.Nextint;
            int y = cin.Nextint;
            int r = Math.Min(x, y);
            rmax = Math.Max(rmax, r);
            rmin = Math.Min(rmin, r);
            int b = Math.Max(x, y);
            bmax = Math.Max(bmax, b);
            bmin = Math.Max(bmin, b);

            R[i] = r;
            B[i] = b;
        }

        Array.Sort(R, B);
        long ans = (long)(rmax - rmin) * (bmax - bmin);

        long diff = R[N - 1] - R[0];

