        for (int i = 0; i < N; i++)
        {
            m = Math.Min(m, B[i]);
            M = Math.Max(M, B[i]);
            diff = Math.Min(diff, M - m);
        }
        ans = Math.Min(ans, diff * (bmax - rmin));



    }

