        int M = R[N - 1];//Bの中に入っていた交換した中で一番大きいもの
        for (int i = 0; i < N; i++)
        {
            diff = Math.Min(diff, M - Math.Min(m, R[i]));
            m = Math.Min(m, B[i]);
            M = Math.Max(M, B[i]);

            //WriteLine($"m={m} M={M} diff={diff}");
        }
        ans = Math.Min(ans, diff * (bmax - rmin));
