        long lma = -1, lmi = M, sma = -1, smi = M;
        for (int i = 0; i < n; i++)
        {
            sc.Multi(out l[i], out s[i]);
            if (l[i] < s[i]) {
                swap(ref l[i], ref s[i]);
            }
