namespace Codeforces
{
	internal class Template
	{

		private void Solve()
		{
			var n = cin.NextLong();
			var a = new Tuple<long, long>[n];
			var tree1 = new SortedSet<long>();
			var tree2 = new SortedSet<long>();
			for (var i = 0; i < n; i++)
			{
				var x = cin.NextLong();
				var y = cin.NextLong();
				a[i] = Tuple.Create(x, y);
				tree1.Add(a[i].Item1);
				tree2.Add(a[i].Item2);
			}
			a = a.OrderBy(x => x.Item1 - x.Item2).ToArray();
			var res = (tree1.Max - tree1.Min)*(tree2.Max - tree2.Min);
			for (var i = 0; i < a.Length; i++)
			{
				tree1.Remove(a[i].Item1);
				tree1.Add(a[i].Item2);
				tree2.Remove(a[i].Item2);
				tree2.Add(a[i].Item1);
				res = Math.Min(res, (tree1.Max - tree1.Min)*(tree2.Max - tree2.Min));
			}
			Console.WriteLine(res);
		}

		private static readonly Scanner cin = new Scanner();

		private static void Main()
		{
#if DEBUG
			var inputText = File.ReadAllText(@"..\..\input.txt");
