        {
            io.Read();
            int N = io.Int();
            List<Item> items = new List<Item>();
            for (int i = 0; i < N; ++i)
            {
                io.ReadSplit();
                Item item = new Item();
                item.x = io.Int();
                item.y = io.Int();
                if (item.y < item.x)
                {
                    int tmp = item.x;
                    item.x = item.y;
                    item.y = tmp;
                }
                items.Add(item);
            }
            items = items.OrderBy(item => item.x).ToList();

            int maxR = int.MinValue;
            int minR = int.MaxValue;
            int maxB = items[items.Count - 1].x;
            int minB = items[0].x;
            for (int i = 0; i < N; ++i)
            {
                Item item = items[i];
                if (maxR < item.y)
                {
                    maxR = item.y;
                }
                if (item.y < minR)
                {
                    minR = item.y;
                }
            }
            long solution1 = (long)(maxR - minR) * (maxB - minB);

            long solution2 = long.MaxValue;
            minR = minB;
            int min_difference_maxBminB = int.MaxValue;
            for (int i = 0; i < items.Count - 1; ++i)
            {
                maxB = Math.Max(maxB, items[i].y);
                if (items[i].x == minB)
                {
                    minB = Math.Min(items[i + 1].x, items[i].y);
                }
                else
                {
                    minB = Math.Min(minB, items[i].y);
                }
                min_difference_maxBminB = Math.Min(min_difference_maxBminB, maxB - minB);
            }
            solution2 = (long)(maxR - minR) * min_difference_maxBminB;

            io.WriteLine(Math.Min(solution1, solution2).ToString());
