type Evaluator func(a, b interface{}) interface{}
func Max(a, b interface{}) interface{} {
  if a.([]int)[0] < b.([]int)[0] { return b }
  return a
}
func Min(a, b interface{}) interface{} {
  if a.([]int)[0] < b.([]int)[0] { return a }
  return b
}
type SegmentTree struct {
  size  int
  data  []interface{}
  inf   interface{}
  eval  Evaluator
}
func InitSegmentTree(N int, inf interface{}, eval Evaluator) *SegmentTree {
  size := 1
  for size < N {
    size *= 2
  }
  S := make([]interface{}, size * 2)
  for i := range S {
    S[i] = inf
  }
  return &SegmentTree{
    size: size,
    data: S,
    inf:  inf,
    eval: eval,
  }
}
func (ST *SegmentTree) Update(index int, value interface{}) {
  idx := ST.size + index
  ST.data[idx] = value
  for idx > 1 {
    parent := idx / 2
    ST.data[parent] = ST.eval(ST.data[2 * parent], ST.data[2 * parent + 1])
    idx = parent
  }
}
func (ST *SegmentTree) Get(from, to, index, left, right int) interface{} {
  // get [from, to)
  if to <= left || right <= from { return ST.inf }
  if from <= left && right <= to { return ST.data[index] }
  m := (left + right) / 2
  lval := ST.Get(from, to, 2 * index, left, m)
  rval := ST.Get(from, to, 2 * index + 1, m, right)
  return ST.eval(lval, rval)
}
func (ST *SegmentTree) Query(from, to int) interface{} {
  return ST.Get(from, to, 1, 0, ST.size)
}

func Solve() {
  var N, x, y int
  NextInt(&N)
  Rmax := InitSegmentTree(N, []int{0, 0}, Max)
  Rmin := InitSegmentTree(N, []int{1000000007, 0}, Min)
  Bmax := InitSegmentTree(N, []int{0, 0}, Max)
  Bmin := InitSegmentTree(N, []int{1000000007, 0}, Min)
  R := make([]int, N)
  B := make([]int, N)
  for i := 0; i < N; i++ {
    NextInt(&x, &y)
    if x < y { x, y = y, x }
    Rmax.Update(i, []int{x, i})
    Rmin.Update(i, []int{x, i})
    Bmax.Update(i, []int{y, i})
    Bmin.Update(i, []int{y, i})
    R[i], B[i] = x, y
  }
  A := func() int { return (Rmax.Query(0, N).([]int)[0] - Rmin.Query(0, N).([]int)[0]) * (Bmax.Query(0, N).([]int)[0] - Bmin.Query(0, N).([]int)[0]) }
  ans := A()
  for i := 0; i < N; i++ {
    j := Bmin.Query(0, N).([]int)[1]
    if R[j] <= B[j] { break }
    R[j], B[j] = B[j], R[j]
    Rmax.Update(j, []int{R[j], j})
    Rmin.Update(j, []int{R[j], i})
    Bmax.Update(j, []int{B[j], j})
    Bmin.Update(j, []int{B[j], j})
    ans = MinInt(A(), ans)
  }
  Write(ans)
}

func main() {
  Solve()
  Output()
}

