	{ //red red || blue blue
		li := Pairs(make([]Pair, N))
		for i := 0; i < N; i++ {
			li[i] = Pair{int64(min(a[i], b[i])), int64(max(a[i], b[i]))}
		}
		sort.Sort(li)

		Mi_ := li[0].second
		Ma_ := li[N - 1].first

		Min_ := Ma_ - li[0].first
		for i := 0; i < N - 1; i++ {
			Mi_ = minInt64(Mi_, li[i].second)
			Ma_ = maxInt64(Ma_, li[i].second)

			Min_ = Ma_ - minInt64(Mi_, li[i + 1].first)
		}

