			BMax, BMin = BMin, BMax
		}

		for i := 0; i < N; i++ {
			lower := min(a[i], b[i])
			upper := max(a[i], b[i])

			BMin = min(BMin, upper)
			RMax = max(RMax, lower)
		}

		mi = minInt64(mi, int64(RMax - RMin) * int64(BMax - BMin))
	}

	fmt.Println(mi)
