	a, b := make([]int, N), make([]int, N)
	Mi, Ma := 0, 0
	for i := 0; i < N; i++ {
		a[i], b[i] = next.Int(), next.Int()

		if max(a[Ma], b[Ma]) <= max(a[i], b[i]) {
			Ma = i
		}

		if min(a[i], b[i]) <= min(a[Mi], b[Mi]) {
			Mi = i
		}
	}

	var mi int64 = int64(1e18)
	{ //red red || blue blue
		Ma_ := max(min(a[Ma], b[Ma]), max(a[Mi], b[Mi]))
		Mi_ := min(min(a[Ma], b[Ma]), max(a[Mi], b[Mi]))
		for i := 0; i < N; i++ {
			if Mi_ <= a[i] && a[i] <= Ma_ {
				continue
			}

			if Mi_ <= b[i] && b[i] <= Ma_ {
				continue
			}

			A := min(abs(Ma_ - a[i]), abs(Mi_ - a[i]))
			B := min(abs(Ma_ - b[i]), abs(Mi_ - b[i]))
			if A < B {
				if abs(Ma_ - a[i]) < abs(Mi_ - a[i]) {
					Ma_ = a[i]
				} else {
					Mi_ = a[i]
				}
			} else {
				if abs(Ma_ - b[i]) < abs(Mi_ - b[i]) {
					Ma_ = b[i]
				} else {
					Mi_ = b[i]
				}	
			}
		}

		mi = int64(Ma_ - Mi_) * int64(max(a[Ma], b[Ma]) - min(a[Mi], b[Mi]))
	}

	{ //blue red || red blue
		RMax := min(a[Ma], b[Ma])
		RMin := min(a[Mi], b[Mi])
		BMax := max(a[Ma], b[Ma])
		BMin := max(a[Mi], b[Mi])
		if RMax < RMin {
			RMax, RMin = RMin, RMax
		}

		if BMax < BMin {
			BMax, BMin = BMin, BMax
		}

		for i := 0; i < N; i++ {
			lower := min(a[i], b[i])
			upper := max(a[i], b[i])

			BMin = min(BMin, upper)
			RMax = max(RMax, lower)
		}

		mi = minInt64(mi, int64(RMax - RMin) * int64(BMax - BMin))
	}

