  eval  Evaluator
}
func InitSegmentTree(N int, inf interface{}, eval Evaluator) *SegmentTree {
  size := 1
  for size < N {
    size *= 2
  }
  S := make([]interface{}, size * 2)
  for i := range S {
    S[i] = inf
  }
  return &SegmentTree{
    size: size,
    data: S,
    inf:  inf,
    eval: eval,
  }
}
func (ST *SegmentTree) Update(index int, value interface{}) {
  idx := ST.size + index
  ST.data[idx] = value
  for idx > 1 {
    parent := idx / 2
    ST.data[parent] = ST.eval(ST.data[2 * parent], ST.data[2 * parent + 1])
    idx = parent
  }
}
func (ST *SegmentTree) Get(from, to, index, left, right int) interface{} {
  // get [from, to)
  if to <= left || right <= from { return ST.inf }
  if from <= left && right <= to { return ST.data[index] }
  m := (left + right) / 2
  lval := ST.Get(from, to, 2 * index, left, m)
  rval := ST.Get(from, to, 2 * index + 1, m, right)
  return ST.eval(lval, rval)
}
func (ST *SegmentTree) Query(from, to int) interface{} {
  return ST.Get(from, to, 1, 0, ST.size)
}

func Solve() {
  var N, x, y int
  NextInt(&N)
  XY := make([][]int, N)
  for i := 0; i < N; i++ {
    NextInt(&x, &y)
    if x > y { x, y = y, x }
    XY[i] = []int{x, y}
  }
  sort.Sort(Balls(XY))
  R := make([]int, N)
  B := make([]int, N)
  for i, xy := range XY { R[i], B[i] = xy[0], xy[1] }
  ans := (MaxInt(R...) - MinInt(R...)) * (MaxInt(B...) - MinInt(B...))
  max := 0
  for i, b := range B {
    if B[max] < b { max = i }
  }
  if max != 0 {
    if max != 1 {
      R[max], R[1] = R[1], R[max]
      B[max], B[1] = B[1], B[max]
    }
    R[1], B[1] = B[1], R[1]
    r := R[1] - R[0]
    min := MinInt(B...)
    T := InitSegmentTree(N, []int{0, 0}, Eval)
    for i, b := range B { T.Update(i, []int{b, i}) }
    for i := 0; i < N; i++ {
      j := T.Query(0, N).([]int)[1]
      ans = MinInt(r * (B[j] - min), ans)
      if R[j] >= B[j] { break }
      R[j], B[j] = B[j], R[j]
      min = MinInt(B[j], min)
      T.Update(j, []int{B[j], j})
    }
  }
  Write(ans)
}

func main() {
  Solve()
  Output()
}

