def solve(N, x, y):
    state = [x[0], x[0], y[0], y[0]]
    for i in range(1, N):
        state_1 = [max(state[0], x[i]), min(state[1], x[i]), max(state[2], y[i]), min(state[3], y[i])]
        state_2 = [max(state[0], y[i]), min(state[1], y[i]), max(state[2], x[i]), min(state[3], x[i])]

        dif_1 = (state_1[0] - state_1[1]) * (state_1[2] - state_1[3])
        dif_2 = (state_2[0] - state_2[1]) * (state_2[2] - state_2[3])

        if dif_1 > dif_2:
            state = state_2
        else:
            state = state_1

    ans = (state[0] - state[1]) * (state[2] - state[3])
    return ans


