fn solve() {
    input!{
        n:usize,
        xy:[(i64,i64);n]
    }

    let mut z = vec![];
    for i in 0..n {
        let (x,y) = xy[i];
        z.push((x,i));
        z.push((y,i));
    }
    z.sort();

    let mut h = HashSet::new();

    for i in 0..min(z.len(),8) {
        h.insert(z[i].1);
    }
    z.reverse();
    for i in 0..min(z.len(),8) {
        h.insert(z[i].1);
    }

    let mut z: Vec<usize> = h.into_iter().collect();
    z.sort();
    let m = z.len();

    let mut minv = std::i64::MAX;
    for bit in 0..(1<<m) {
        let mut R = vec![];
        let mut B = vec![];
        for j in 0..m {
            let (x,y) = xy[z[j]];
            if (bit & (1<<j)) > 0 {
                R.push(x);
                B.push(y);
            } else {
                R.push(y);
                B.push(x);
            }
        }
        R.sort();
        let rmax = R[m-1];
        let rmin = R[0];
        B.sort();
