#[derive(Clone, Debug)]
pub struct QueueAggregation<M: Monoid> {
    front_stack: Vec<(M::T, M::T)>,
    back_stack: Vec<(M::T, M::T)>,
    monoid: M,
}
impl<M: Monoid> QueueAggregation<M> {
    pub fn new(monoid: M) -> Self {
        QueueAggregation {
            front_stack: Vec::new(),
            back_stack: Vec::new(),
            monoid: monoid,
        }
    }
    #[inline]
    pub fn len(&self) -> usize {
        self.front_stack.len() + self.back_stack.len()
    }
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.front_stack.is_empty() && self.back_stack.is_empty()
    }
    #[inline]
    pub fn fold_all(&self) -> M::T {
        self.monoid.operate(
            self.front_stack
                .last()
                .map(|t| &t.0)
                .unwrap_or(&self.monoid.unit()),
            self.back_stack
                .last()
                .map(|t| &t.0)
                .unwrap_or(&self.monoid.unit()),
        )
    }
    #[inline]
    pub fn last(&self) -> Option<&M::T> {
        self.back_stack
            .last()
            .or(self.front_stack.first())
            .map(|t| &t.1)
    }
    #[inline]
    pub fn push(&mut self, value: M::T) {
        let x = self.monoid.operate(
            self.back_stack
                .last()
                .map(|t| &t.0)
                .unwrap_or(&self.monoid.unit()),
            &value,
        );
        self.back_stack.push((x, value));
    }
    #[inline]
    fn push_front(&mut self, value: M::T) {
        let x = self.monoid.operate(
            &value,
            self.front_stack
                .last()
                .map(|t| &t.0)
                .unwrap_or(&self.monoid.unit()),
        );
        self.front_stack.push((x, value));
    }
    #[inline]
    pub fn pop(&mut self) -> Option<M::T> {
        if self.front_stack.is_empty() {
            let v = self
                .back_stack
                .drain(..)
                .map(|t| t.1)
                .rev()
                .collect::<Vec<_>>();
            for x in v.into_iter() {
                self.push_front(x)
            }
        }
        self.front_stack.pop().map(|t| t.1)
    }
}
use std::cmp::{max, min};
fn main() {
    input! { n, xy: [(i64, i64); n] };
    let mut ans = 0i64;
    let ab = xy
        .iter()
        .map(|&(x, y)| (min(x, y), max(x, y)))
        .collect::<Vec<_>>();
    if n > 1 {
        ans = std::i64::MAX;
        let (mut mx, mut mn) = ((0, 0), (1_000_000_001, n));
        for i in 0..n {
            mx = max(mx, (ab[i].1, i));
            mn = min(mn, (ab[i].0, i));
        }
        if mx.1 != mn.1 {
            let mut seg = (min(ab[mx.1].0, ab[mn.1].1), max(ab[mx.1].0, ab[mn.1].1));
            let mut idx = (0..n)
                .filter(|&i| i != mx.1 && i != mn.1)
                .collect::<Vec<_>>();
            idx.sort_by_key(|&i| ab[i].0);
            let mut que = QueueAggregation::new(CartesianOperation::new(
                MinOperation::new(1_000_000_001),
                MaxOperation::new(0),
            ));
            if idx.len() > 0 {
                for &i in idx.iter() {
                    que.push((ab[i].0, ab[i].0));
                }
                for &i in idx.iter() {
                    let (mi, ma) = que.fold_all();
                    ans = min(ans, (max(seg.1, ma) - min(seg.0, mi)) * (mx.0 - mn.0));
                    que.pop();
                    seg.0 = max(seg.0, ab[i].1);
                    seg.1 = min(seg.1, ab[i].1);
                }
            } else {
                ans = min(ans, (seg.1 - seg.0) * (mx.0 - mn.0));
            }
        }
        let mut seg = (ab[mx.1].0, ab[mn.1].1);
        for i in 0..n {
            seg.0 = max(seg.0, ab[i].0);
            seg.1 = min(seg.1, ab[i].1);
        }
        ans = min(ans, (mx.0 - seg.1) * (seg.0 - mn.0));
    }
    println!("{}", ans);
}

