    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let xy = (0..n)
        .map(|_| (sc.read::<i64>(), sc.read::<i64>()))
        .collect::<Vec<_>>();
    let mut r_max = 0;
    let mut r_min = 1 << 50;
    let mut b_max = 0;
    let mut b_min = 1 << 50;
    for &(x, y) in xy.iter() {
        let (r, b) = if x < y { (x, y) } else { (y, x) };
        r_max = max(r, r_max);
        r_min = min(r, r_min);
        b_max = max(b, b_max);
        b_min = min(b, b_min);
    }

    let ans = (r_max - r_min) * (b_max - b_min);
    let mut xy = xy
        .into_iter()
        .map(|(x, y)| (min(x, y), max(x, y)))
        .collect::<Vec<_>>();
    xy.sort();

    let mut cur_max = xy.iter().map(|t| t.0).max().unwrap();
    let mut ans1 = cur_max - xy.iter().map(|t| t.0).min().unwrap();
    let mut store_min = 1 << 50;
    for i in 0..(n - 1) {
        cur_max = max(cur_max, xy[i].1);
        store_min = min(store_min, xy[i].1);
        let cur_min = min(xy[i + 1].0, store_min);
        ans1 = min(ans1, cur_max - cur_min);
    }

    let min0 = xy.iter().map(|t| t.0).min().unwrap();
    let max1 = xy.iter().map(|t| t.1).max().unwrap();
    let ans2 = ans1 * (max1 - min0);
