fn main() {
    let input = read_string();
    let mut sc = Scanner::new(&input);
    let n: usize = sc.next();
    let mut v: Vec<Vec<i64>> = sc.next_mat(2, n);
    for i in 0..n {
        if v[i][0] > v[i][1] {
            let t = v[i][0];
            v[i][0] = v[i][1];
            v[i][1] = t;
        }
    }
    let mut mini = 0;
    let mut maxi = 0;
    for i in 1..n {
        if v[mini][0] > v[i][0] {
            mini = i;
        }
        if v[maxi][1] < v[i][1] {
            maxi = i;
        }
    }
    let min2 = v.iter().min_by_key(|x| x[1]).unwrap()[1];
    let max1 = v.iter().max_by_key(|x| x[0]).unwrap()[0];
    let mut ans = (max1 - v[mini][0]) * (v[maxi][1] - min2);
    if maxi != mini {
        let r = v[maxi][1] - v[mini][0];
        let mut map: BTreeMap<i64,usize> = BTreeMap::new();
        for i in 0..n {
            let c = map.entry(v[i][0]).or_insert(0);
            *c += 1;
        }
        v.sort_by_key(|x| x[0]);
        let mut ans_t = max1 - v[0][0];
        for i in 0..n {
            {
                let &x = map.get(&v[i][0]).unwrap();
                if x == 1 {
                    map.remove(&v[i][0]);
                } else {
                    map.insert(v[i][0],x-1);
                }
            }
            {
                let mut x = map.entry(v[i][1]).or_insert(0);
                *x += 1;
            }
            ans_t = cmp::min(ans_t, map.keys().last().unwrap() - *map.keys().nth(0).unwrap());
        }

        ans = cmp::min(ans, r * ans_t);
    }
    println!("{}",ans);
}

