use std::cmp::{max, min};
fn main() {
    input! { n, xy: [(i64, i64); n] };
    let mut ans = 0i64;
    let ab = xy
        .iter()
        .map(|&(x, y)| (min(x, y), max(x, y)))
        .collect::<Vec<_>>();
    if n > 1 {
        ans = std::i64::MAX;
        let (mut mx, mut mn) = ((0, 0), (1_000_000_001, n));
        for i in 0..n {
            mx = max(mx, (ab[i].1, i));
            mn = min(mn, (ab[i].0, i));
        }
        if mx.1 != mn.1 {
            let mut used = vec![false; n];
            used[mx.1] = true;
            used[mn.1] = true;
            let mut seg = (min(ab[mx.1].0, ab[mn.1].1), max(ab[mx.1].0, ab[mn.1].1));
            let mut v = vec![];
            for i in 0..n {
                if ab[i].0 < seg.0 && ab[i].1 < seg.0 {
                    seg.0 = ab[i].1;
                    used[i] = true;
                }
                if ab[i].0 > seg.1 && ab[i].1 > seg.1 {
                    seg.1 = ab[i].0;
                    used[i] = true;
                }
                if seg.0 <= ab[i].0 && ab[i].0 <= seg.1 || seg.0 <= ab[i].1 && ab[i].1 <= seg.1 {
                    used[i] = true;
                }
                if !used[i] {
                    v.push(ab[i]);
                }
            }
            v.push(seg);
            v.sort_by_key(|&(_a, b)| b);
            for i in 0..v.len() - 1 {
                v[i + 1].0 = min(v[i + 1].0, v[i].0);
            }
            for &(a, b) in &v {
                if b >= seg.1 {
                    ans = min(ans, (mx.0 - mn.0) * (b - a));
                }
            }
        }
        let mut seg = (ab[mx.1].0, ab[mn.1].1);
        for i in 0..n {
            seg.0 = max(seg.0, ab[i].0);
            seg.1 = min(seg.1, ab[i].1);
        }
        ans = min(ans, (mx.0 - seg.1) * (seg.0 - mn.0));
    }
    println!("{}", ans);
}

