fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let mut xy: Vec<(u64, u64)> = (0..n)
        .map(|_| {
            let x: u64 = sc.read();
            let y: u64 = sc.read();
            (cmp::min(x, y), cmp::max(x, y))
        })
        .collect();

    let global_min = xy.iter().map(|&(x, _)| x).min().unwrap();
    let global_max = xy.iter().map(|&(_, y)| y).max().unwrap();

    let max_x = xy.iter().map(|&(x, _)| x).max().unwrap();
    let min_y = xy.iter().map(|&(_, y)| y).min().unwrap();
    let ans1 = (max_x - global_min) * (global_max - min_y);

    xy.sort();

    let mut ans2 = (xy[n - 1].0 - xy[0].0) * (global_max - global_min);
    let mut cur_y_min = global_max;
    let mut cur_y_max = global_min;
    for i in 0..n {
        let added_y = xy[i].1;
        cur_y_min = cmp::min(cur_y_min, added_y);
        cur_y_max = cmp::max(cur_y_max, added_y);

        let mut min = cur_y_min;
        if i + 1 < n {
            min = cmp::min(min, xy[i + 1].0);
        }

        let mut max = cur_y_max;
        if i < n - 1 {
            max = cmp::max(max, xy[n - 1].0);
        }

        ans2 = cmp::min(ans2, (global_max - global_min) * (max - min));
    }

    println!("{}", cmp::min(ans1, ans2));
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

