fn run() {
    input! {
        n: usize,
        p: [(i64, i64); n],
    }
    let mut p = p;
    for p in &mut p {
        if p.0 > p.1 {
            std::mem::swap(&mut p.0, &mut p.1);
        }
    }
    p.sort();
    let mut max = 0;
    for i in 1..n {
        if p[i].1 >= p[max].1 {
            max = i;
        }
    }
    let mut r = [p[0].0, p[max].0];
    let mut b = [p[0].1, p[max].1];
    for i in 1..n {
        r[1] = std::cmp::max(r[1], p[i].0);
        b[0] = std::cmp::min(b[0], p[i].1);
    }
    let mut ans = (r[1] - r[0]) * (b[1] - b[0]);
    if max != 0 {
        let mut bmax = std::cmp::max(p[max].0, p[0].1);
        let bmin = std::cmp::min(p[max].0, p[0].1);
        let mut local = bmin;
        let mut h = std::collections::BinaryHeap::new();
        for i in 1..n {
            if i == max {
                continue;
            }
            h.push((-p[i].0, i));
            bmax = std::cmp::max(bmax, p[i].0);
            local = std::cmp::min(local, p[i].0);
        }
        ans = std::cmp::min(ans, (p[max].1 - p[0].0) * (bmax - local));
        while let Some((_, k)) = h.pop() {
            bmax = std::cmp::max(bmax, p[k].1);
            if let Some(&(u, _)) = h.peek() {
                ans = std::cmp::min(ans, (p[max].1 - p[0].0) * (bmax - std::cmp::min(bmin, -u)));
            } else {
                break;
            }
        }
    }
    println!("{}", ans);
}

fn main() {
    run();
}

