fn main() {
    let n: usize = util::get();
    let xy: Vec<(usize, usize)> = (0..n)
        .map(|_| {
            let t = util::get2();
            (min(t.0, t.1), max(t.0, t.1))
        })
        .collect();

    let g_min = xy.iter()
        .flat_map(|t| vec![t.0, t.1].into_iter())
        .min()
        .unwrap();
    let g_max = xy.iter()
        .flat_map(|t| vec![t.0, t.1].into_iter())
        .max()
        .unwrap();

    let r_min_b_max = {
        let mut r = (xy[0].0, xy[0].0);
        let mut b = (xy[0].1, xy[0].1);

        for &(x, y) in xy[1..].iter() {
            r = (min(r.0, x), max(r.1, x));
            b = (min(b.0, y), max(b.1, y));
        }
        (r.1 - r.0) * (b.1 - b.0)
    };

    let r_min_r_max = {
        let mut b = BinaryHeap::from_iter(xy.iter().map(|&(x, y)| (y, x)));

        loop {
            let (x, y) = b.peek().cloned().unwrap();
            if y < x && y != g_min {
                b.pop();
                b.push((y, x));
            } else {
                break;
            }
        }

        let v = b.into_vec();
        let b_min = v.iter().map(|t| t.0).min().unwrap();
        let b_max = v.iter().map(|t| t.0).max().unwrap();
        let r_min = v.iter().map(|t| t.1).min().unwrap();
        let r_max = v.iter().map(|t| t.1).max().unwrap();

        (b_max - b_min) * (r_max - r_min)
    };

    println!("{}", min(r_min_r_max, r_min_b_max));

}

