#[derive(Clone, Debug, Copy)]
struct I64(i64);

impl Monoid for I64 {
    fn mul(&self, other: Self) -> Self {
        if self.0 < other.0 { I64(other.0) } else { I64(self.0) }
    }

    fn one() -> Self { I64(0) }
}

