fn solve0(xy: &Vec<(i64, i64)>) -> i64 {
    // fix rmin and bmax

    let n = xy.len();
    if n == 1 {
        return 0
    }

    let mut rmin = xy[0].0;
    let mut rmax = xy[0].0;
    let mut bmin = xy[0].1;
    let mut bmax = xy[0].1;

    let mut bi = 0;
    for i in 0..n {
        if bmax <= xy[i].1 {
            bmax = xy[i].1;
            bi = i;
        }
    }
    rmin = min(rmin, xy[bi].0);
    rmax = max(rmax, xy[bi].0);

    for i in 0..n {
        if i == 0 || i == bi {
            continue
        }
        bmin = min(bmin, xy[i].1);
        rmax = max(rmax, xy[i].0);
    }

    (rmax - rmin) * (bmax - bmin)
}

fn solve1(xy: &Vec<(i64, i64)>) -> i64 {
    // fix rmin and rmax
    let n = xy.len();
    if n == 1 {
        return 0
    }

    let mut rmin = xy[0].0;
    let mut rmax = xy[0].0;
    let mut bmin = xy[0].1;
    let mut bmax = xy[0].1;

    let mut bi = 0;
    for i in 1..n {
        if rmax <= xy[i].1 {
            rmax = xy[i].1;
            bi = i;
        }
    }
    bmin = min(bmin, xy[bi].0);
    bmax = max(bmax, xy[bi].0);

    if n == 2 {
        return (rmax - rmin) * (bmax - bmin)
    }

    let mut pairs = vec![];
    for i in 0..n {
        if i != 0 && i != bi {
            pairs.push(xy[i]);
        }
    }

    let pn = pairs.len();
    let mut r = SegmentTree::new(n+10, I64::one());
    for i in 0..pn {
        r.change(i, I64(pairs[i].1));
    }

    let mut best_blue = (0, 1e11 as i64);
    for i in 0..pn {
        let bmin = min(bmin, pairs[i].0);
        let bmax = max(bmax, r.range(0, i).0);

        if best_blue.1 - best_blue.0 >= bmax - bmin {
            best_blue = (bmin, bmax);
        }
    }

    (rmax - rmin) * (best_blue.1 - best_blue.0)
}

fn main() {
    let n: usize = read();
    let mut xy: Vec<(i64, i64)> = readn(n);

    for i in 0..n {
        if xy[i].1 < xy[i].0 {
            xy[i] = (xy[i].1, xy[i].0);
        }
    }
    xy.sort();

    // println!("{:?}", xy);
    println!("{}", min(solve0(&xy), solve1(&xy)));
}

use io::*;
use std::cmp;
use std::collections::BinaryHeap;

fn main() {
    let input = read_string();
    let mut sc = Scanner::new(&input);
    let n: usize = sc.next();
    let mut v: Vec<Vec<usize>> = sc.next_mat(2, n);
    for i in 0..n {
        if v[i][0] > v[i][1] {
            let t = v[i][0];
            v[i][0] = v[i][1];
            v[i][1] = t;
        }
    }
    let mut mini = 0;
    let mut maxi = 0;
    for i in 1..n {
        if v[mini][0] > v[i][0] {
            mini = i;
        }
        if v[maxi][1] < v[i][1] {
            maxi = i;
        }
    }
    let min1 = v[mini][0];
    let min2 = v.iter().min_by_key(|x| x[1]).unwrap()[1];
    let max1 = v.iter().max_by_key(|x| x[0]).unwrap()[0];
    let max2 = v[maxi][1];
    let mut ans = (max1 - min1) * (max2 - min2);

    if maxi != mini {
        let mut bh: BinaryHeap<(usize,usize)> = BinaryHeap::new();
        for i in 0..n {
            bh.push((v[i][1],v[i][0]));
        }
        loop {
            let (a,b) = bh.pop().unwrap();
            if a > b && b != min1 {
                bh.push((b,a));
            } else {
                bh.push((a,b));
                break;
            }
        }
        let bv = bh.into_vec();
        let r = bv.iter().map(|x| x.0).max().unwrap() - bv.iter().map(|x| x.0).min().unwrap();
        ans = cmp::min(ans, (max2 - min1) * r);
    }
    println!("{}",ans);
}

pub mod io {
    use std;
    use std::str::FromStr;

    pub struct Scanner<'a> {
        iter: std::str::SplitWhitespace<'a>,
    }

    impl<'a> Scanner<'a> {
        pub fn new(s: &'a str) -> Scanner<'a> {
            Scanner {
                iter: s.split_whitespace(),
            }
        }

        pub fn next<T: FromStr>(&mut self) -> T {
            let s = self.iter.next().unwrap();
            if let Ok(v) = s.parse::<T>() {
                v
            } else {
                panic!("Parse error")
            }
        }

        pub fn next_vec_len<T: FromStr>(&mut self) -> Vec<T> {
            let n: usize = self.next();
            self.next_vec(n)
        }

        pub fn next_vec<T: FromStr>(&mut self, n: usize) -> Vec<T> {
            (0..n).map(|_| self.next()).collect()
        }

        pub fn next_mat<T: FromStr>(&mut self, w: usize, h: usize) -> Vec<Vec<T>> {
            (0..h).map(|_| self.next_vec(w)).collect()
        }

        pub fn next_vec_char(&mut self) -> Vec<char> {
            self.next::<String>().chars().collect()
        }

        pub fn next_mat_char(&mut self, n: usize) -> Vec<Vec<char>> {
            (0..n).map(|_| self.next_vec_char()).collect()
        }
    }

    pub fn read_string() -> String {
        use std::io::Read;

        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).unwrap();
        s
    }

    pub fn read_line() -> String {
        let mut s = String::new();
        std::io::stdin().read_line(&mut s).unwrap();
        s.trim_right().to_owned()
    }
}
